e val revealedPhoneNumbers: Flow<Set<String>> = userDataStore.data        .map { it[REVEALED_PHONE_NUMBERS] ?: emptySet() }    suspend fun addRevealedPhoneNumber(userNumberOrGroupId: String) {        userDataStore.edit { prefs ->            val current = prefs[REVEALED_PHONE_NUMBERS] ?: emptySet()            prefs[REVEALED_PHONE_NUMBERS] = current + userNumberOrGroupId        }    }    suspend fun isPhoneNumberRevealed(userNumberOrGroupId: String): Boolean {        return revealedPhoneNumbers.first().contains(userNumberOrGroupId)    }    fun getSelectableSosContacts(): Flow<List<Upbhogta>> =        upbhogtaDao.getAllUpbhogtas()    // ✅ Check    fun isCallAlreadyEnded(roomId: String): Boolean {        return activeCalls.contains(roomId)    }    // ✅ Set (mark active)    fun setCallAlreadyEnded(roomId: String): Boolean {        return activeCalls.add(roomId) // returns false if already exists    }    fun handleTypingReceived(userNumber: String) {        coroutineScope.launch {            val isTypingEnabled = settingFlow(                SettingPrefKeys.CHAT_MESSAGE_TYPING_INDICATORS,                false            ).first()            if (!isTypingEnabled) {                DLog.i("🙈 Typing indicators disabled — ignoring incoming typing from $userNumber")                return@launch            }            TypingManager.startTyping(                TypingState(                    userNumber = userNumber,                    isTyping = true                )            )        }    }    //region websocket    fun logDebugSafe(        level: String,        tag: String,        message: String,        msgId: String? = null,        userId: String? = null,        sessionId: String? = null    ) {        coroutineScope.launch {            loggingMutex.withLock {                try {                    val currentTime = System.currentTimeMillis()                    val readableTime = SimpleDateFormat(                        "yyyy-MM-dd HH:mm:ss",                        Locale.getDefault()                    ).format(Date(currentTime))                    debugLogDao.insert(                        DebugLogEntity(                            timestamp = currentTime,                            readableTime = readableTime,                            level = level,                            tag = tag,                            message = message,                            msgId = msgId,                            userId = userId,                            sessionId = sessionId                        )                    )                } catch (e: Exception) {                    Log.e("DB_LOG", "Failed to insert debug log", e)                }            }        }    }    fun startMessageSync() {        val workRequest = PeriodicWorkRequestBuilder<MessageSyncWorker>(            25, TimeUnit.MINUTES        )            .setConstraints(                Constraints.Builder()                    .setRequiredNetworkType(NetworkType.CONNECTED)                    .build()            )            .build()        WorkManager.getInstance(context).enqueueUniquePeriodicWork(            "message_sync_worker",            ExistingPeriodicWorkPolicy.KEEP,            workRequest        )    }    private fun isUsingMobileData(): Boolean {        val connectivityManager =            context.getSystemService(Context.CONNECTIVITY_SERVICE) as ConnectivityManager        val activeNetwork = connectivityManager.activeNetwork ?: return false        val capabilities = connectivityManager.getNetworkCapabilities(activeNetwork) ?: return false        return capabilities.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR)    }        private fun observeSocket() {            coroutineScope.launch {                SocketManager.events.collect { event ->                    when (event) {                        is ConnectionEvent.Open -> {                            isOnMobileData = isUsingMobileData()                            DLog.i("✅ Connected")                        }                        is ConnectionEvent.Closed -> {                            isParmaan = false                            _connectionStatus.value = false  // disconnected                            DLog.i("🔒 Closed: ${event.code} / ${event.reason}")                        }                        is ConnectionEvent.Failure -> {                            isParmaan = false                            _connectionStatus.value = false  // disconnected                            DLog.e("❌ Failed", event.throwable) // full stack trace                        }                        is ConnectionEvent.Message -> {                            val text = event.text                            coroutineScope.launch {                                messageReceivedMutex.withLock {                                    DLog.i("Received: $text")                                    val sizeBytes = text.toByteArray(Charsets.UTF_8).size                                    val sizeKB = sizeBytes / 1024.0                                    DLog.i("Received message size: $sizeBytes bytes (${sizeKB} KB)")                                    handleReceivedMessage(text)                                }                            }                        }                    }                }            }        }    fun sendCurrentToken() {        //todo        FirebaseMessaging.getInstance().token.addOnCompleteListener { task ->            if (!task.isSuccessful) {                Log.e("FCM", "Failed to get FCM token", task.exception)                return@addOnCompleteListener            }            val token = task.result            if (token != null) {                sendToken(token) // Pass to your server API function            }        }    }    //endregion    // Method to get the current registerStatus    fun getRegisterStatus(): RegisterStatus? {        return registerStatus    }    // Method to reset registerStatus to its default values    fun resetRegisterStatus() {        registerStatus = RegisterStatus() // Resets all values to default        DLog.i("RegisterStatus has been reset: $registerStatus")    }    private fun updateSandeshStithiTime(        userNumber: String,        sandeshId: String,        stithi: SandeshStithi,        time: Long,        upbhogtaToo: Boolean = false    ) {        coroutineScope.launch {            updateStithi.withLock {            }            updateSandeshStithiTimePass(userNumber, sandeshId, stithi, time, upbhogtaToo)        }    }    private suspend fun updateSandeshStithiTimePass(        userNumber: String,        sandeshId: String,        stithi: SandeshStithi,        time: Long,        upbhogtaToo: Boolean = false    ) {        DLog.i("UPDATING TIME now ")        // Fetch existing JSON from the database        val existingJson = sandeshStatusDao.getStatusJson(userNumber, sandeshId)        val jsonObject = if (existingJson != null) Gson().fromJson(            existingJson,            JsonObject::class.java        ) else JsonObject()        // Update the JSON        jsonObject.addProperty(stithi.value.toString(), time)        // Store the updated JSON as a string        val updatedStatus = SandeshStatus(            sandeshId = sandeshId,            userNumber = userNumber,            statusJson = jsonObject.toString()        )        DLog.i("existing $existingJson new $jsonObject updated $updatedStatus")        sandeshStatusDao.insertOrUpdateStatus(updatedStatus)        sandeshDao.updateStithiIfForwardProgress(            sandeshId,            userNumber,            stithi.value        )        if (upbhogtaToo) {            upbhogtaDao.updateStithiUpbhogtaIfForwardProgress(                sandeshId,                userNumber,                stithi.value            )        }    }    suspend fun ensureGroupSandeshStatusExists(        sandeshId: String,        groupId: String,    ) {        val existing = sandeshStatusDao.getStatusJson(groupId, sandeshId)        if (existing != null) return        val members = groupDao.getAllMembersInGroup(groupId)//            .filter { it.userNumber != senderNumber }        val samarpit = JsonObject()        val dhrist = JsonObject()        for (member in members) {            samarpit.add(member.userNumber, JsonNull.INSTANCE)            dhrist.add(member.userNumber, JsonNull.INSTANCE)        }        val statusJson = JsonObject().apply {            add(SandeshStithi.SAMARPIT.value.toString(), samarpit)  // "2"            add(SandeshStithi.DHRIST.value.toString(), dhrist)      // "3"            add(SandeshStithi.LIKHIT.value.toString(), JsonNull.INSTANCE)     // "0"            add(SandeshStithi.PREKSHIT.value.toString(), JsonNull.INSTANCE)   // "1"        }        val entity = SandeshStatus(            sandeshId = sandeshId,            userNumber = groupId,            statusJson = statusJson.toString()        )        sandeshStatusDao.insertOrUpdateStatus(entity)    }    fun updateGroupSandeshStithiTime(        groupId: String,        sandeshId: String,        stithi: SandeshStithi,        memberUserNumber: String,        time: Long,        upbhogtaToo: Boolean = false    ) {        coroutineScope.launch {            updateStithi.withLock {            }            updateGroupSandeshStithiTimePass(                groupId,                sandeshId,                stithi,                memberUserNumber,                time,                upbhogtaToo            )        }    }    suspend fun updateGroupSandeshStithiTimePass(        groupId: String,        sandeshId: String,        stithi: SandeshStithi,        memberUserNumber: String,        time: Long,        upbhogtaToo: Boolean = false    ) {        userNumberKhud.firstOrNull()?.let { selfNumber ->            // 👇 Ensure status JSON exists before updating            ensureGroupSandeshStatusExists(                sandeshId = sandeshId,                groupId = groupId,            )            DLog.i("📬 Updating group stithi for $sandeshId | member: $memberUserNumber  | stithi : $stithi")            val existingJson = sandeshStatusDao.getStatusJson(groupId, sandeshId)            DLog.i("📥 Loaded existing status JSON: $existingJson")            val rootJson = existingJson?.let {                Gson().fromJson(it, JsonObject::class.java)            } ?: JsonObject()            val stithiKey = stithi.value.toString()            when (stithi) {                SandeshStithi.SAMARPIT, SandeshStithi.DHRIST -> {                    val nestedMap = rootJson.getAsJsonObject(stithiKey)                        ?: JsonObject().also {                            DLog.i("📦 Creating new nested map for $stithiKey")                            rootJson.add(stithiKey, it)                        }                    DLog.i("🧩 Before update: $stithiKey -> $nestedMap")                    nestedMap.addProperty(memberUserNumber, time)                    DLog.i("✅ After update: $stithiKey -> $nestedMap")                }                else -> {                    DLog.i("🖋 Updating flat value for $stithiKey to $time")                    rootJson.addProperty(stithiKey, time)                }            }            DLog.i("📤 Final status JSON to save: $rootJson")            val updatedStatus = SandeshStatus(                sandeshId = sandeshId,                userNumber = groupId, // using groupId as key                statusJson = rootJson.toString()            )            sandeshStatusDao.insertOrUpdateStatus(updatedStatus)            // 🔍 Check if promotion is possible            if (stithi == SandeshStithi.SAMARPIT || stithi == SandeshStithi.DHRIST) {                val members = groupDao.getAllMembersInGroup(groupId)                val otherUserNumbers = members.map { it.userNumber }.filter { it != selfNumber }                val stithiMap = rootJson.getAsJsonObject(stithiKey)                val allOthersReached = stithiMap != null &&                        otherUserNumbers.all { stithiMap.has(it) }                if (allOthersReached) {                    DLog.i("✅ All other members reached $stithi, promoting group stithi ")                    groupDao.updateStithiGroupSandeshIfForwardProgress(                        messageId = sandeshId,                        groupId = groupId,                        newStithi = stithi.value                    )                    if (upbhogtaToo) {                        groupDao.updateStithiGroupEntityIfForwardProgress(                            sandeshId,                            groupId,                            stithi.value                        )                    }                } else {                    DLog.i("⏳ Waiting for more members to reach $stithi")                }            } else if (stithi == SandeshStithi.PREKSHIT) {                DLog.i("VALUE IS PREKSHIT")                groupDao.updateStithiGroupSandeshIfForwardProgress(                    messageId = sandeshId,                    groupId = groupId,                    newStithi = stithi.value                )                if (upbhogtaToo) {                    groupDao.updateStithiGroupEntityIfForwardProgress(                        sandeshId,                        groupId,                        stithi.value                    )                }            }        }    }    private fun saveImagePreview(base64Image: String): String {        val previewDir = File(context.filesDir, "preview")        if (!previewDir.exists() && !previewDir.mkdirs()) {            DLog.i("❌ Failed to create preview directory")            return ""        }        val fileName = "preview_${System.currentTimeMillis()}.webp"        val imageFile = File(previewDir, fileName)        return try {            // Decode Base64 to Bitmap            val decodedBytes = Base64.decode(base64Image, Base64.DEFAULT)            val originalBitmap = BitmapFactory.decodeByteArray(decodedBytes, 0, decodedBytes.size)            // Always use WebP format (lossless for API 30+)            val format = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {                Bitmap.CompressFormat.WEBP_LOSSLESS            } else {                Bitmap.CompressFormat.WEBP            }            // Save the image            FileOutputStream(imageFile).use { outputStream ->                val success = originalBitmap.compress(format, 100, outputStream)                if (!success) {                    DLog.i("❌ Failed to save image")                    return ""                }            }            // ✅ Return file path if saved successfully            DLog.i("✅ Image saved at: ${imageFile.absolutePath}")            imageFile.absolutePath        } catch (e: IOException) {            e.printStackTrace()            ""        }    }    private val recoveryBuffer = ConcurrentHashMap<String, MutableSet<String>>()    private val recoveryJobMap = ConcurrentHashMap<String, Job>()    private suspend fun handleEncryptErrorRecoveryAskAgain(        sender: String,        messageId: String,        jsonMessageString: String,        exception: Exception    ) {        // ✅ Add messageId to buffer        val set = recoveryBuffer.computeIfAbsent(sender) { mutableSetOf() }        set.add(messageId)        // optional logging        handleMalformedJsonDelivery(jsonMessageString, exception)        DLog.i("📥 Added to recovery buffer [$sender]: $messageId")        // ❗ If already scheduled → don't reschedule        if (recoveryJobMap.containsKey(sender)) return        // ✅ Schedule batch send after deZlay        val job = CoroutineScope(Dispatchers.IO).launch {            delay(4000.milliseconds)            val messageIds = recoveryBuffer.remove(sender)?.toList() ?: emptyList()            recoveryJobMap.remove(sender)            if (messageIds.isEmpty()) return@launch            DLog.i("🚀 Sending batched askAgain for $sender → $messageIds")            val revealReceiverNumber = try {                val original = JsonParser.parseString(jsonMessageString).asJsonObject                val sandesh = JsonParser.parseString(                    original.get(JsonKeys.SANDESH).asString                ).asJsonObject                sandesh.get(JsonKeys.REVEAL_RECEIVER_NUMBER)?.asBoolean ?: true            } catch (_: Exception) {                false            }            val json = JsonObject().apply {                add(JsonKeys.MESSAGE_IDS, gson.toJsonTree(messageIds))                addProperty(DootawasMessage.ASK_AGAIN, true)                addProperty(                    JsonKeys.REVEAL_RECEIVER_NUMBER,                    revealReceiverNumber                )            }            val unsentSandesh = UnsentSandesh(                messId = createMessageID(),                receiver = sender,                message = json.toString(),                dataType = DataType.ASK_AGAIN            )            insertUnsentData(unsentSandesh)            sendUnsentMessages(false)        }        recoveryJobMap[sender] = job    }    private suspend fun processGroup(        finalJsonObject: JsonObject,        sandeshType: GroupSandeshType,        sender: String,        jsonMessage: JsonObject,        messageId: String,        sendNotification: Boolean,        groupId: String    ) {        var messagePass = "Added to Group"        when (sandeshType) {            GroupSandeshType.DELETE -> {                val deleteListJson = finalJsonObject.getAsJsonArray(DootawasMessage.PAATH)                val deleteList = deleteListJson.map { it.asString }.toMutableList()                DLog.i("Deleting messages: $deleteList")                deleteGroupListMessage(deleteList, groupId,sender)                val notificationId = sender.hashCode()                NotificationManagerCompat.from(context).cancel(notificationId)                messagingStyleMap.remove(sender) // 💡 This clears the old messages                addDeletedMessageIdToDataStore(messageId)                val confirmationJson = JSONObject().apply {                    put(JsonKeys.SENT_DATA_TYPE, 0)                    put(JsonKeys.GROUP_ID, groupId)                    put(JsonKeys.DATA, jsonMessage.get(JsonKeys.TIME_STAMP).asString)                    put(JsonKeys.STORAGE_TYPE, jsonMessage.get(JsonKeys.STORAGE_TYPE).asInt)                    put(JsonKeys.MESSAGE_ID, messageId)                }                sendDeliveryConfirmation(messageId, sender, confirmationJson.toString(), DataType.DELIVERY_CONFIRMATION,null, isGroupZ = true)//                val unsentSandesh = UnsentSandesh(//                    messId = messageId,//                    receiver = sender,//                    message = confirmationJson.toString(),//                    dataType = DataType.DELIVERY_CONFIRMATION,//                    isGroup = true//                )////                insertUnsentData(unsentSandesh)//                sendUnsentMessages(false)                return            }            GroupSandeshType.REACTION -> {                if (finalJsonObject.has(DootawasMessage.ORIGINAL_MESSAGE_ID)) {                    val originalSandeshId =                        finalJsonObject.get(DootawasMessage.ORIGINAL_MESSAGE_ID).asString                    val reaction = finalJsonObject.get(DootawasMessage.REACTION).asString                    storeReaction(originalSandeshId, reaction, true, groupId, sender)                }                //todo add here notification too like (user reacted ) should show on notification                val confirmationJson = JSONObject().apply {                    put(JsonKeys.SENT_DATA_TYPE, 0)                    put(JsonKeys.DATA, jsonMessage.get(JsonKeys.TIME_STAMP).asString)                    put(JsonKeys.STORAGE_TYPE, jsonMessage.get(JsonKeys.STORAGE_TYPE).asInt)                    put(JsonKeys.MESSAGE_ID, messageId)                }                sendDeliveryConfirmation(messageId, sender, confirmationJson.toString(), DataType.DELIVERY_CONFIRMATION,null, isGroupZ = true)//                val unsentSandesh = UnsentSandesh(//                    messId = messageId,//                    receiver = sender,//                    message = confirmationJson.toString(),//                    dataType = DataType.DELIVERY_CONFIRMATION,//                    isGroup = true//                )////                insertUnsentData(unsentSandesh)                sendUnsentMessages(false)                return            }            GroupSandeshType.MESSAGE, GroupSandeshType.REPLY_MESSAGE -> {                if (finalJsonObject.has(DootawasMessage.ORIGINAL_MESSAGE)) {                    val originalMessageObject =                        finalJsonObject.getAsJsonObject(DootawasMessage.ORIGINAL_MESSAGE)                    if (originalMessageObject.has(DootawasMessage.ORIGINAL_SAMAGRI)) {                        val originalSamagriString =                            originalMessageObject.get(DootawasMessage.ORIGINAL_SAMAGRI).asString                        try {                            // Parse the originalSamagri string into a JsonObject                            val originalSamagriObject =                                Gson().fromJson(originalSamagriString, JsonObject::class.java)                            if (originalSamagriObject.has(DootawasMessage.ORIGINAL_URI)) {                                DLog.i("Key exists in originalSamagri!")                                val originalSandeshId =                                    originalMessageObject.get(DootawasMessage.ORIGINAL_MESSAGE_ID).asString                                // Get sandesh from DB                                DLog.i(originalSandeshId)                                val sandesh = sandeshDao.getSandeshByIdAndUser(                                    originalSandeshId,                                    sender                                )                                val jsonObjectFromDatabase = try {                                    Gson().fromJson(sandesh?.samagri ?: "", JsonObject::class.java)                                        ?: JsonObject()                                } catch (e: Exception) {                                    JsonObject() // Return an empty object on failure                                }                                // Check if `savedFileUri` exists in DB and update it in `originalSamagri`                                if (jsonObjectFromDatabase.has(DootawasMessage.ORIGINAL_URI)) {                                    val newSavedUri =                                        jsonObjectFromDatabase.get(DootawasMessage.ORIGINAL_URI).asString                                    originalSamagriObject.addProperty(                                        DootawasMessage.ORIGINAL_URI,                                        newSavedUri                                    )                                    // ✅ Convert updated JsonObject back to String and store it                                    originalMessageObject.addProperty(                                        DootawasMessage.ORIGINAL_SAMAGRI,                                        originalSamagriObject.toString()                                    )                                    DLog.i("Updated originalSamagri with new savedUri: $newSavedUri")                                } else {                                    DLog.i("No savedUri found in database.")                                }                            } else {                          