                  }                    return                }            }            GroupSandeshType.REPLY_LIST -> TODO()            GroupSandeshType.GROUP_KEY_PACKAGE -> TODO()            GroupSandeshType.EPOCH_COMMIT -> TODO()            GroupSandeshType.ACTION_DELETE_PROFILE -> TODO()            GroupSandeshType.ACTION_DELETE_GROUP -> TODO()            GroupSandeshType.ACTION_ADD_MEMBERS -> TODO()            GroupSandeshType.ACTION_INVITE_MEMBER -> TODO()            GroupSandeshType.ACTION_REMOVE_MEMBER -> TODO()            GroupSandeshType.ACTION_LEAVE_GROUP -> TODO()            GroupSandeshType.ACTION_RESTORE -> TODO()            GroupSandeshType.ACTION_GET_GROUPS -> TODO()            GroupSandeshType.ACTION_GET_GROUP -> TODO()            GroupSandeshType.ACTION_GET_ALL_MEMBERS_ADDED -> TODO()            GroupSandeshType.ACTION_GET_ALL_MEMBERS_REINSTALLED -> TODO()            GroupSandeshType.ACTION_GET_MEMBERS -> TODO()            GroupSandeshType.ACTION_MEMBER_UPDATED -> TODO()            GroupSandeshType.ACTION_GROUP_UPDATED -> TODO()            GroupSandeshType.ACTION_MEMBER_PERMISSION_UPDATED -> TODO()            GroupSandeshType.ACTION_ERROR -> TODO()        }        finalJsonObject.remove(DootawasMessage.SANDESH_TYPE)        finalJsonObject.remove(JsonKeys.TIME_STAMP)        val newSandesh = GroupSandesh(            sandeshId = messageId,            userNumber = sender,            groupId = groupId,            samagri = finalJsonObject.toString(),            isSelf = false,            time = jsonMessage.get(JsonKeys.TIME_STAMP).asLong,            sandeshType = sandeshType.value,            sandeshStithi = SandeshStithi.SAMARPIT        )        insertGroupWithCheck(            newSandesh,            messagePass,            sendNotification,            jsonMessage.get(JsonKeys.STORAGE_TYPE).asInt        )        if (sandeshType in listOf(                GroupSandeshType.LOCATION,                GroupSandeshType.REPLY_LOCATION            )        ) {            downloadFileGroup(messageId, groupId)            return        }        val key = when (sandeshType) {            GroupSandeshType.IMAGE, GroupSandeshType.REPLY_IMAGE ->                SettingPrefKeys.CHAT_MEDIA_AUTO_DOWNLOAD_PHOTOS            GroupSandeshType.VIDEO, GroupSandeshType.REPLY_VIDEO ->                SettingPrefKeys.CHAT_MEDIA_AUTO_DOWNLOAD_VIDEOS            GroupSandeshType.AUDIO, GroupSandeshType.REPLY_AUDIO ->                SettingPrefKeys.CHAT_MEDIA_AUTO_DOWNLOAD_VOICE            GroupSandeshType.DOCUMENT, GroupSandeshType.REPLY_DOCUMENT ->                SettingPrefKeys.CHAT_MEDIA_AUTO_DOWNLOAD_FILES            else -> return        }        val autoDownloadEnabled = settingFlow(key, false).first()        if (autoDownloadEnabled) {            downloadFileGroup(messageId, groupId)        }    }    private suspend fun processMessage(        finalJsonObject: JsonObject,        sandeshType: SandeshType,        sender: String,        jsonMessage: JsonObject,        messageId: String,        sendNotification: Boolean,        youAreRevealedToSender: Boolean    ) {        DLog.i("MESSAGE RECEIVED with SandeshType: $sandeshType  $jsonMessage")        DLog.i("Final json Decrypted: $finalJsonObject")        var messagePass = "new message"        when (sandeshType) {            SandeshType.DELETE -> {                val deleteListJson = finalJsonObject.getAsJsonArray(DootawasMessage.PAATH)                val deleteList = deleteListJson.map { it.asString }.toMutableList()                DLog.i("Deleting messages: $deleteList")                deleteUserListMessage(deleteList, sender)                val notificationId = sender.hashCode()                NotificationManagerCompat.from(context).cancel(notificationId)                messagingStyleMap.remove(sender) // 💡 This clears the old messages                addDeletedMessageIdToDataStore(messageId)     