_MESSAGE)) {                    val originalMessageObject =                        finalJsonObject.getAsJsonObject(DootawasMessage.ORIGINAL_MESSAGE)                    if (originalMessageObject.has(DootawasMessage.ORIGINAL_SAMAGRI)) {                        val originalSamagriString =                            originalMessageObject.get(DootawasMessage.ORIGINAL_SAMAGRI).asString                        try {                            // Parse the originalSamagri string into a JsonObject                            val originalSamagriObject =                                Gson().fromJson(originalSamagriString, JsonObject::class.java)                            if (originalSamagriObject.has(DootawasMessage.ORIGINAL_URI)) {                                val originalSandeshId =                                    originalMessageObject.get(DootawasMessage.ORIGINAL_MESSAGE_ID).asString                                // Get sandesh from DB                                DLog.i(originalSandeshId)                                val sandesh = sandeshDao.getSandeshByIdAndUser(                                    originalSandeshId,                                    sender                                )                                val jsonObjectFromDatabase = try {                                    Gson().fromJson(sandesh?.samagri ?: "", JsonObject::class.java)                                        ?: JsonObject()                                } catch (e: Exception) {                                    JsonObject() // Return an empty object on failure                                }                                // Check if `savedFileUri` exists in DB and update it in `originalSamagri`                                if (jsonObjectFromDatabase.has(DootawasMessage.ORIGINAL_URI)) {                                    val newSavedUri =                                        jsonObjectFromDatabase.get(DootawasMessage.ORIGINAL_URI).asString                                    originalSamagriObject.addProperty(                                        DootawasMessage.ORIGINAL_URI,                                        newSavedUri                                    )                                    // ✅ Convert updated JsonObject back to String and store it                                    originalMessageObject.addProperty(                                        DootawasMessage.ORIGINAL_SAMAGRI,                                        originalSamagriObject.toString()                                    )                                }                            }                        } catch (e: Exception) {                        }                    }                }                updateSandeshStithiTime(                    sender,                    messageId,                    SandeshStithi.LIKHIT,                    finalJsonObject.get(JsonKeys.TIME_STAMP).asLong                )                updateSandeshStithiTime(                    sender,                    messageId,                    SandeshStithi.PREKSHIT,                    jsonMessage.get(JsonKeys.TIME_STAMP).asLong                )                // Checking if PAATH key exists in JSON                if (finalJsonObject.has(DootawasMessage.PAATH)) {                    try {                        val decryptedMessage = finalJsonObject.get(DootawasMessage.PAATH).asString                        // Sanitize and clean decrypted message                        val safeMessage = decryptedMessage                            .replace(Regex("<[^>]*>"), "")   // Remove all HTML tags                            .replace(Regex("&[^;]+;"), " ") // Remove &nbsp;, &lt;, etc.                            .trim()                         // Trim only start/end                        finalJsonObject.addProperty(DootawasMessage.PAATH, safeMessage)                        val duration = finalJsonObject.get(DootawasMessage.DISAPPEAR_DURATION).asInt                        messagePass = if (duration != 0) "new message" else decryptedMessage                        if (finalJsonObject.get(DootawasMessage.IS_LINK)?.asBoolean == true) {                            // cleaner                            storeMessagePreview(finalJsonObject, messageId, false)                        }                    } catch (e: Exception) {                        Log.e("WebSocket", "Error sanitizing message: ${e.message}")                        messagePass = ""                    }                } else {                    DLog.i("❌ PAATH key not found in sandeshJsonObject")                    messagePass = ""                }                DLog.i("GG1")            }            SandeshType.IMAGE -> {                updateSandeshStithiTime(                    sender,                    messageId,                    SandeshStithi.LIKHIT,                    finalJsonObject.get(JsonKeys.TIME_STAMP).asLong                )                updateSandeshStithiTime(                    sender,                    messageId,                    SandeshStithi.PREKSHIT,                    jsonMessage.get(JsonKeys.TIME_STAMP).asLong                )                if (finalJsonObject.has(DootawasMessage.IMAGE_PREVIEW)) {                    val imagePreview = if (finalJsonObject.has(DootawasMessage.IMAGE_PREVIEW)) {                        val element = finalJsonObject.get(DootawasMessage.IMAGE_PREVIEW)                        if (!element.isJsonNull) element.asString.trim() else ""                    } else {                        ""                    }                    val savedUri = if (imagePreview.isNotEmpty()) {                        // Save valid preview                        saveImagePreview(imagePreview)                    } else {                        // Store empty if null or blank                        ""                    }                    // Store URI in `duplicateUri` field                    finalJsonObject.addProperty(DootawasMessage.BLUR_URI, savedUri)                    // Remove base64 preview after saving                    finalJsonObject.remove(DootawasMessage.IMAGE_PREVIEW)                    // 🔥 Add `DOWNLOAD_PERCENT` with initial value `0`                    finalJsonObject.addProperty(DootawasMessage.DOWNLOAD_PERCENT, 0)                    messagePass = "Image"                }            }            SandeshType.REPLY_IMAGE -> {                updateSandeshStithiTime(                    sender,                    messageId,                    SandeshStithi.LIKHIT,                    finalJsonObject.get(JsonKeys.TIME_STAMP).asLong                )                updateSandeshStithiTime(                    sender,                    messageId,                    SandeshStithi.PREKSHIT,                    jsonMessage.get(JsonKeys.TIME_STAMP).asLong                )                if (finalJsonObject.has(DootawasMessage.ORIGINAL_MESSAGE)) {                    val originalMessageObject =                        finalJsonObject.getAsJsonObject(DootawasMessage.ORIGINAL_MESSAGE)                    if (originalMessageObject.has(DootawasMessage.ORIGINAL_SAMAGRI)) {                        val originalSamagriString =                            originalMessageObject.get(DootawasMessage.ORIGINAL_SAMAGRI).asString                        try {                            // Parse the originalSamagri string into a JsonObject                            val originalSamagriObject =                                Gson().fromJson(originalSamagriString, JsonObject::class.java)                            if (originalSamagriObject.has(DootawasMessage.ORIGINAL_URI)) {                                DLog.i("Key exists in originalSamagri!")                                val originalSandeshId =                                    originalMessageObject.get(DootawasMessage.ORIGINAL_MESSAGE_ID).asString                                // Get sandesh from DB                                DLog.i(originalSandeshId)                                val sandesh = sandeshDao.getSandeshByIdAndUser(                                    originalSandeshId,                                    sender                                )                                val jsonObjectFromDatabase = try {                                    Gson().fromJson(sandesh?.samagri ?: "", JsonObject::class.java)                                        ?: JsonObject()                                } catch (e: Exception) {                                    JsonObject() // Return an empty object on failure                                }                                // Check if `savedFileUri` exists in DB and update it in `originalSamagri`                                if (jsonObjectFromDatabase.has(DootawasMessage.ORIGINAL_URI)) {                                    val newSavedUri =                                        jsonObjectFromDatabase.get(DootawasMessage.ORIGINAL_URI).asString                                    originalSamagriObject.addProperty(                                        DootawasMessage.ORIGINAL_URI,                                        newSavedUri                                    )                                    // ✅ Convert updated JsonObject back to String and store it                                    originalMessageObject.addProperty(                                        DootawasMessage.ORIGINAL_SAMAGRI,                                        originalSamagriObject.toString()                                    )                                    DLog.i("Updated originalSamagri with new savedUri: $newSavedUri")                                } else {                                    DLog.i("No savedUri found in database.")                                }                            } else {                                DLog.i("Key 'savedUri' does not exist in originalSamagri.")                            }                        } catch (e: Exception) {                            DLog.i("Failed to parse originalSamagri: ${e.message}")                        }                    } else {                        DLog.i("originalSamagri does not exist in originalMessage.")                    }                } else {                    DLog.i("originalMessage does not exist in sandeshJsonObject.")                }                if (finalJsonObject.has(DootawasMessage.IMAGE_PREVIEW)) {                    val imagePreview = finalJsonObject.get(DootawasMessage.IMAGE_PREVIEW).asString                    val mimeType =                        finalJsonObject.get(DootawasMessage.MIME_TYPE)?.asString ?: "image/jpeg"                    // Save image preview to personal storage and get URI                    val savedUri = if (imagePreview.isNotEmpty()) {                        // Save valid preview                        saveImagePreview(imagePreview)                    } else {                        // Store empty if null or blank                        ""                    }                    // Store URI in `duplicateUri` field                    finalJsonObject.addProperty(DootawasMessage.BLUR_URI, savedUri)                    // Remove base64 preview after saving                    finalJsonObject.remove(DootawasMessage.IMAGE_PREVIEW)                    // 🔥 Add `DOWNLOAD_PERCENT` with initial value `0`                    finalJsonObject.addProperty(DootawasMessage.DOWNLOAD_PERCENT, 0)                    messagePass = "Image"                }                // Additional logic specific to REPLY_IMAGE                // (Add whatever extra processing REPLY_IMAGE needs here)            }            SandeshType.VIDEO -> {                updateSandeshStithiTime(                    sender,                    messageId,    