perty(DootawasMessage.BLUR_URI, savedUri)                    // Remove base64 preview after saving                    finalJsonObject.remove(DootawasMessage.IMAGE_PREVIEW)                    // 🔥 Add `DOWNLOAD_PERCENT` with initial value `0`                    finalJsonObject.addProperty(DootawasMessage.DOWNLOAD_PERCENT, 0)                    messagePass = "📍 Location"                }            }            SandeshType.REPLY_LOCATION -> {                updateSandeshStithiTime(                    sender,                    messageId,                    SandeshStithi.LIKHIT,                    finalJsonObject.get(JsonKeys.TIME_STAMP).asLong                )                updateSandeshStithiTime(                    sender,                    messageId,                    SandeshStithi.PREKSHIT,                    jsonMessage.get(JsonKeys.TIME_STAMP).asLong                )                if (finalJsonObject.has(DootawasMessage.IMAGE_PREVIEW)) {                    val imagePreview = finalJsonObject.get(DootawasMessage.IMAGE_PREVIEW).asString                    val mimeType =                        finalJsonObject.get(DootawasMessage.MIME_TYPE)?.asString ?: "image/jpeg"                    // Save image preview to personal storage and get URI                    val savedUri = if (imagePreview.isNotEmpty()) {                        // Save valid preview                        saveImagePreview(imagePreview)                    } else {                        // Store empty if null or blank                        ""                    }                    // Store URI in `duplicateUri` field                    finalJsonObject.addProperty(DootawasMessage.BLUR_URI, savedUri)                    // Remove base64 preview after saving                    finalJsonObject.remove(DootawasMessage.IMAGE_PREVIEW)                    // 🔥 Add `DOWNLOAD_PERCENT` with initial value `0`                    finalJsonObject.addProperty(DootawasMessage.