sonObject.get(DootawasMessage.LONGITUDE)?.asDouble ?: 0.0                val isStopped = finalJsonObject.get(DootawasMessage.IS_STOPPED)?.asBoolean ?: false                val sandesh =                    sandeshDao.getSandeshByIdAndUser(                        originalMessageId,                        sender                    ) ?: return                val samagriJson = try {                    JsonParser.parseString(                        sandesh.samagri                    ).asJsonObject                } catch (e: Exception) {                    return                }                samagriJson.addProperty(                    DootawasMessage.LATITUDE,                    latitude                )                samagriJson.addProperty(                    DootawasMessage.LONGITUDE,                    longitude                )                samagriJson.addProperty(                    DootawasMessage.IS_STOPPED,                    isStopped                )                sandeshDao.updateSamagri(                    sandeshId = originalMessageId,                    userNumber = sender,                    samagri = samagriJson.toString()                )                if (isStopped){                    NotificationManagerCompat                        .from(context)                        .cancel(sender.hashCode())                }else{                    notifier.showOrUpdateLiveLocationNotification(                        sender = sender,                        text = "Live location update"                    )                }                return            }            SandeshType.SCREEN_COLORS -> {                val confirmationJson = JSONObject().apply {                    put(JsonKeys.SENT_DATA_TYPE, 0)                    put(JsonKeys.DATA, jsonMessage.get(JsonKeys.TIME_STAMP).asLong)                    put(JsonKeys.STORAGE_TYPE, jsonMessage.get(JsonKeys.STORAGE_TYPE).asInt)                    put(Js