oroutineScope.launch {                            val original = sandeshDao.getSandeshByIdAndUser(refId, sender)                            if (original != null) {                                val originalJson = try {                                    JsonParser.parseString(original.samagri).asJsonObject                                } catch (e: Exception) { null }                                if (originalJson != null) {                                    originalJson.addProperty(DootawasMessage.LEDGER_STATUS, status.value)                                    // --- ADVANCED OVERPAYMENT & BALANCE CALCULATION LAYER ---                                    var finalType = LedgerType.fromInt(originalJson.get(DootawasMessage.LEDGER_TYPE)?.asInt ?: 0)                                    var finalAmount = originalJson.get(DootawasMessage.LEDGER_AMOUNT)?.asDouble ?: 0.0                                    if (finalType == LedgerType.BILL && originalJson.has(                                            DootawasMessage.LEDGER_DATA)) {                                        try {                                            val ledgerData = originalJson.getAsJsonObject(DootawasMessage.LEDGER_DATA)                                            if (ledgerData != null && ledgerData.has(DootawasMessage.BILL_AMOUNT_PAID)) {                                                val amountPaid = ledgerData.get(DootawasMessage.BILL_AMOUNT_PAID).asDouble                                                // Net calculation: Bill Total - Amount Paid                                                val pendingAmount = finalAmount - amountPaid                                                if (pendingAmount >= 0.0) {                                                    // Scenario A: Standard partial payment or exact match                                                    finalAmount = pendingAmount                                                    finalType = LedgerType.CREDIT // or keep as BILL depending on direction layout                                                } else {                                                    // Scenario B: Overpayment! The receiver paid extra.                                                    // Absorb the inverted negative value as a positive absolute balance displacement                                                    finalAmount = abs(pendingAmount)                                                    finalType = LedgerType.DEBIT // Direction flips because they are now owed money back                                                }                                                // Sync calculations back to json payload metadata tracking parameters                                                originalJson.addProperty(DootawasMessage.LEDGER_AMOUNT, finalAmount)//                                                originalJson.addProperty(DootawasMessage.LEDGER_TYPE, finalType.value)                                            }                                        } catch (e: Exception) {                                        }                                    }                                    // --- END OF CALCULATION LAYER ---                                    // Apply the calculated balance difference cleanly to the engine                                    val resolvedBalance = updateLedgerStatusAndBalance(                                        sandeshId  = refId,                                        userNumber = sender,                                        status     = status,                                        ledgerType = finalType,                                        amount     = finalAmount                                    )                                    if (resolvedBalance != null) {                                        originalJson.addProperty(DootawasMessage.LEDGER_RESOLVED_BALANCE, resolvedBalance)                               