                // Safely read any update that is already pending.                                    val existingUpdateJson = existingJson.get(keyUpdated)                                        ?.takeIf { it.isJsonObject }                                        ?.asJsonObject                                    val pendingVersion = existingUpdateJson                                        ?.get(keyVersion)                                        ?.takeIf { it.isJsonPrimitive }                                        ?.asLong ?: 0L                                    // Use the highest version we already know about.                                    val highestKnownVersion = maxOf(                                        currentJsonVersion,                                        currentVersion,                                        pendingVersion                                    )                                    if (incomingVersion > highestKnownVersion) {                                        existingJson.addProperty(                                            keyMessageType,                                            ListMessageType.UPDATE.name                                        )                                        // Store the newest update as pending.                                        existingJson.add(                                            keyUpdated,                                            newIncomingDataJson                                        )                                        sandeshDao.updateSamagri(                                            sandeshId = targetListId,                                            samagri = existingJson.toString()                                        )                                    } else {                                    }                                }                            } catch (e: Exception) {                                e.printStackTrace()                            }                        }                        updateSandeshStithiTime(                            sender,                            messageId,                            SandeshStithi.LIKHIT,                            finalJsonObject.get(JsonKeys.TIME_STAMP).asLong                        )                        updateSandeshStithiTime(                            sender,                            messageId,                            SandeshStithi.PREKSHIT,                            jsonMessage.get(JsonKeys.TIME_STAMP).asLong                        )                    }                    return                }            }            SandeshType.REPLY_LIST -> {}            SandeshType.GROUP_KEY_REQUEST,            SandeshType.GROUP_KEY_RESPONSE -> {                finalJsonObject.addProperty(                    DootawasMessage.IS_KEY_REQUEST,                    sandeshType == SandeshType.GROUP_KEY_REQUEST                )                handleGroupKeyPackage(                    finalJsonObject,                    sender,                    messageId                )                val confirmationJson = JSONObject().apply {                    put(JsonKeys.SENT_DATA_TYPE, 0)                    put(JsonKeys.DATA, jsonMessage.get(JsonKeys.TIME_STAMP).asLong)                    put(JsonKeys.STORAGE_TYPE, jsonMessage.get(JsonKeys.STORAGE_TYPE).asInt)                    put(JsonKeys.MESSAGE_ID, messageId)                }                sendDeliveryConfirmation(                    messageId, sender, confirmationJson.toString(), DataType.DELIVERY_CONFIRMATION,                    jsonMessage.get(JsonKeys.TIME_STAMP).asString                )                return            }            SandeshType.EPOCH_COMMIT -> {                handleEpochCommit(finalJsonObject)                val confirmationJson = JSONObject().apply {                    put(JsonKeys.SENT_DATA_TYPE, 0)                    put(JsonKeys.DATA, jsonMessage.get(JsonKeys.TIME_STAMP).asLong)                    put(JsonKeys.STORAGE_TYPE, jsonMessage.get(JsonKeys.STORAGE_TYPE).asInt)                    put(JsonKeys.MESSAGE_ID, messageId)                }                sendDeliveryConfirmation(                    messageId, sender, confirmationJson.toString(), DataType.DELIVERY_CONFIRMATION,                    jsonMessage.get(JsonKeys.TIME_STAMP).asString                )                return            }            SandeshType.GROUP_KEY_SETUP -> {                handleGroupKeySetup(finalJsonObject, sender, messageId)                val confirmationJson = JSONObject().apply {                    put(JsonKeys.SENT_DATA_TYPE, 0)                    put(JsonKeys.DATA, jsonMessage.get(JsonKeys.TIME_STAMP).asLong)                    put(JsonKeys.STORAGE_TYPE, jsonMessage.get(JsonKeys.STORAGE_TYPE).asInt)                    put(JsonKeys.MESSAGE_ID, messageId)                }                sendDeliveryConfirmation(                    messageId,                    sender,                    confirmationJson.toString(),                    DataType.DELIVERY_CONFIRMATION,                    jsonMessage.get(JsonKeys.TIME_STAMP).asString                )                return            }            SandeshType.AI_MESSAGE -> {}        }        finalJsonObject.remove(DootawasMessage.SANDESH_TYPE)        finalJsonObject.remove(JsonKeys.TIME_STAMP)        val newSandesh = Sandesh(            messageId,            sender,            finalJsonObject.toString(),            false,            jsonMessage.get(JsonKeys.TIME_STAMP).asLong,            sandeshType.value,            SandeshStithi.SAMARPIT        )        DLog.i("GG3")        insertSandeshWithCheck(            newSandesh,            messagePass,            sendNotification,            jsonMessage.get(JsonKeys.STORAGE_TYPE).asInt,            youAreRevealedToSender        )        if (sandeshType in listOf(                SandeshType.LOCATION,                SandeshType.REPLY_LOCATION            )        ) {            downloadFile(messageId, sender)            return        }        val key = when (sandeshType) {            SandeshType.IMAGE, SandeshType.REPLY_IMAGE ->                SettingPrefKeys.CHAT_MEDIA_AUTO_DOWNLOAD_PHOTOS            SandeshType.VIDEO, SandeshType.REPLY_VIDEO ->                SettingPrefKeys.CHAT_MEDIA_AUTO_DOWNLOAD_VIDEOS            SandeshType.AUDIO, SandeshType.REPLY_AUDIO ->                SettingPrefKeys.CHAT_MEDIA_AUTO_DOWNLOAD_VOICE            SandeshType.DOCUMENT, SandeshType.REPLY_DOCUMENT ->                SettingPrefKeys.CHAT_MEDIA_AUTO_DOWNLOAD_FILES            else -> return // Skip other types        }        val autoDownloadEnabled = settingFlow(key, false).first()        if (autoDownloadEnabled) {            downloadFile(messageId, sender)        }    }    suspend fun sendSettingToServer(        users: String,        settingType: UserSettingType,        value: String    ) {        try {            val requestJson = JsonObject().apply {                addProperty(JsonKeys.RECEIVER, users)                addProperty(JsonKeys.USER_SETTING, settingType.value)                addProperty(JsonKeys.DATA, value)            }            val unsentSandesh = UnsentSandesh(                messId = createMessageID(),                receiver = users,                message = requestJson.toString(),                dataType = DataType.UPDATE_USER_SETTINGS            )            insertUnsentData(unsentSandesh)            DLog.i("Setting synced to server: $settingType -> $value for $users")        } catch (e: Exception) {            DLog.e("Failed to sync setting to server: ${e.message}")            // consider queuing for retry if this fails, since server sync isn't guaranteed to succeed inline        }    }    private suspend fun handleInternalMessage(jsonMessage: JsonObject, sendNotification: Boolean) {        DLog.i("MESSAGE InTERNAl $jsonMessage")        val sender = jsonMessage.get(JsonKeys.SENDER).asString        val messageId = jsonMessage.get(JsonKeys.MESSAGE_ID).asString        // Extract 'sandesh' field as JSON string and parse it        val sandeshJsonString = jsonMessage.get(JsonKeys.SANDESH).asString        val parsed = JsonParser.parseString(sandeshJsonString)        if (!parsed.isJsonObject) {            handleMalformedJsonDelivery(                jsonMessage.toString(),                IllegalStateException("Sandesh string is not a JSON object")            )            return        }        val sandeshJsonObject = parsed.asJsonObject        if (sandeshJsonObject.has(DootawasMessage.ASK_AGAIN)) {            val messageIdElement = sandeshJsonObject.get(JsonKeys.MESSAGE_IDS)            if (messageIdElement == null || !messageIdElement.isJsonArray) {                handleMalformedJsonDelivery(                    jsonMessage.toString(),                    IllegalStateException("ASK_AGAIN missing MESSAGE_ID array")                )                return            }            val messageIds = gson.fromJson(                messageIdElement,                Array<String>::class.java            ).toList()            val confirmationJson = JSONObject().apply {                put(JsonKeys.SENT_DATA_TYPE, DataType.MESSAGE.value)                put(JsonKeys.STORAGE_TYPE, jsonMessage.get(JsonKeys.STORAGE_TYPE).asInt)                put(JsonKeys.MESSAGE_ID, messageId)            }            sendDeliveryConfirmation(                messageId,                sender,                confirmationJson.toString(),                DataType.DELIVERY_DELIVERED,                jsonMessage.get(JsonKeys.TIME_STAMP).asString            )                DLog.i("🔥 Resetting session for $sender")                logDebugSafe(                    level = "DEBUG",                    tag = "ASK AGAIN",                    message = "Force Resetting from=$sender messageId=$messageIds",                    msgId = messageId,                    userId = sender                )                val userSessionId = sender                val address = SignalProtocolAddress(userSessionId, 1)                roomSignalStore.deleteSession(address)                delay(50.milliseconds)            messageIds.forEach { messID ->                DLog.i("🔄 Ask again for: $messID from $sender")                unsentSandeshDao.markDataSentFalse(messID, sender)            }            return        }        val isGroupElement = sandeshJsonObject.get(JsonKeys.IS_GROUP)        if (isGroupElement == null || !isGroupElement.isJsonPrimitive || !isGroupElement.asJsonPrimitive.isBoolean) {            handleMalformedJsonDelivery(                jsonMessage.toString(),                IllegalStateException("IS_GROUP missing or not boolean")            )            return        }        val isGroup = isGroupElement.asBoolean        var groupId = ""        if (isGroup) {            val groupIdElement = sandeshJsonObject.get(JsonKeys.GROUP_ID)            val protocolVersionElement = sandeshJsonObject.get(DootawasMessage.GROUP_CRYPTO_PROTOCOL_VERSION)            val epochElement = sandeshJsonObject.get(DootawasMessage.GROUP_EPOCH)            val senderIdElement = sandeshJsonObject.get(DootawasMessage.GROUP_SENDER_ID)            val senderDeviceIdElement = sandeshJsonObject.get(DootawasMessage.GROUP_SENDER_DEVICE_ID)            val messageIdElement = sandeshJsonObject.get(JsonKeys.MESSAGE_ID)            val messageNumberElement = sandeshJsonObject.get(DootawasMessage.GROUP_MESSAGE_NUMBER)            val nonceElement = sandeshJsonObject.get(DootawasMessage.GROUP_NONCE)            val messageElement = sandeshJsonObject.get(JsonKeys.SANDESH)            if (                groupIdElement == null ||                !groupIdElement.isJsonPrimitive ||                !groupIdElement.asJsonPrimitive.isString ||                protocolVersionElement == null ||                !protocolVersionElement.isJsonPrimitive ||                !protocolVersionElement.asJsonPrimitive.isNumber ||                epochElement == null ||                !epochElement.isJsonPrimitive ||                !epochElement.asJsonPrimitive.isNumber ||                senderIdElement == null ||                !senderIdElement.isJsonPrimitive ||                !senderIdElement.asJsonPrimitive.isString ||                senderDeviceIdElement == null ||                !senderDeviceIdElement.isJsonPrimitive ||                !senderDeviceIdElement.asJsonPrimitive.isString ||                messageIdElement == null ||                !messageIdElement.isJsonPrimitive ||                !messageIdElement.asJsonPrimitive.isString ||                messageNumberElement == null ||                !messageNumberElement.isJsonPrimitive ||                !messageNumberElement.asJsonPrimitive.isNumber ||                nonceElement == null ||                !nonceElement.isJsonPrimitive ||                !nonceElement.asJsonPrimitive.isString ||                messageElement == null ||                !messageElement.isJsonPrimitive ||                !messageElement.asJsonPrimitive.isString            ) {                handleMalformedJsonDelivery(                    jsonMessage.toString(),                    IllegalStateException(                        "Group message missing or has invalid crypto elements"                    )                )                return            }            groupId = groupIdElement.asString        } else {            val type = sandeshJsonObject.get(DootawasMessage.CIPHER_MESSAGE_TYPE)            val cipherText = sandeshJsonObject.get(DootawasMessage.CIPHER_MESSAGE)            val revealReceiver = sandeshJsonObject.get(JsonKeys.REVEAL_RECEIVER_NUMBER)            val senderUsernameId = sandeshJsonObject.get(JsonKeys.USER_NAME_ID)            if (                type == null ||                !type.isJsonPrimitive ||                !type.asJsonPrimitive.isString ||                cipherText == null ||                !cipherText.isJsonPrimitive ||                !cipherText.asJsonPrimitive.isString ||                revealReceiver == null ||                !revealReceiver.isJsonPrimitive ||                !revealReceiver.asJsonPrimitive.isBoolean ||                senderUsernameId == null ||                !senderUsernameId.isJsonPrimitive ||                !senderUsernameId.asJsonPrimitive.isString            ) {                handleMalformedJsonDelivery(                    jsonMessage.toString(),                    IllegalStateException("Private message missing required elements")                )                return            }        }        val finalJsonObject = if (isGroup) {            try {                // Call the new AES-GCM epoch-based decryption helper                val decryptedJson = decryptGroupJsonObject( sandeshJsonObject)                // Check if decryption resulted in an error object                if (decryptedJson.has("error")) {                    throw IllegalStateException(decryptedJson.get("error").asString)                }                decryptedJson            } catch (e: Exception) {                DLog.e("Failed to decrypt group message: ${e.message}")                DLog.e("The Message which Failed Is : ${e.message}")//                showFallbackNotification(groupId,"Setting up Group")                notifier.showGroupFallback(groupId, "", "Setting up Group")                handleMalformedJsonDelivery(                    jsonMessage.toString(),                    IllegalStateException("Failed to decrypt group message", e)                )                val groupId = sandeshJsonObject                    .get(JsonKeys.GROUP_ID)                    ?.asString                    ?: throw IllegalArgumentException("Missing group ID")                groupId.let { id ->                    val myNumber = userNumberKhud.firstOrNull()                        ?: return@let                    val myMember = groupDao.getAGroupMemberByNumber(                        groupId = id,                        userNumber = myNumber                    ) ?: throw IllegalStateException(                        "Local member not found after reinstall: group=$id"                    )                    if (myMember.isSwami) {                        setupReinstalledOwnerGroup(id)                    } else {                        setupReinstalledMemberGroup(id)                    }                }                return            }        } else {            decryptJsonObject(sender, messageId,sandeshJsonObject)        }        DLog.i("Json After Decrypt Process $finalJsonObject")        if (finalJsonObject.has("duplicate") && finalJsonObject.get("duplicate").asBoolean) {            DLog.i("✅ Skipping duplicate message — just sending delivery confirmation.")//            showFallbackNotification(sender, "Duplicate Msg Ignoring")//            notifier.showFallback(sender, "Duplicate Msg Ignoring")            val confirmationJson = JSONObject().apply {                put(JsonKeys.SENT_DATA_TYPE, DataType.MESSAGE.value)                put(JsonKeys.DATA, jsonMessage.get(JsonKeys.TIME_STAMP).asString)                put(JsonKeys.STORAGE_TYPE, jsonMessage.get(JsonKeys.STORAGE_TYPE).asInt)                put(JsonKeys.MESSAGE_ID, messageId)            }            sendDeliveryConfirmation(                messageId,                sender,                confirmationJson.toString(),                DataType.DELIVERY_CONFIRMATION,                getSandeshStithiTime(sender, messageId, SandeshStithi.SAMARPIT)            )            return        }        if (finalJsonObject.has("error")) {            val errorType = finalJsonObject.get("error").asString            DLog.i("⚠️ Decrypt error: $errorType from $sender")            when (errorType) {                "ASK_KEY" -> {//                    showFallbackNotification(sender,"Setting Up Keys")                    notifier.showFallback(sender, "Setting Up Keys")                    handleEncryptErrorRecoveryAskAgain(                        sender, messageId, jsonMessage.toString(),                        IllegalStateException("DECRYPT FAILED ASKING AGAIN")                    )                }                "SKIP" -> {                    DLog.i("⏭️ Skipping unrecoverable message from $sender")//                    showFallbackNotification(sender,"Setting Up Keys")                    notifier.showFallback(sender, "Setting Up Keys")                    val confirmationJson = JsonObject().apply {                        addProperty(JsonKeys.SENT_DATA_TYPE, DataType.MESSAGE.value)                        addProperty(JsonKeys.DATA, jsonMessage.get(JsonKeys.TIME_STAMP).asString)                        addProperty(JsonKeys.STORAGE_TYPE, jsonMessage.get(JsonKeys.STORAGE_TYPE).asInt)                        addProperty(JsonKeys.MESSAGE_ID, messageId)                    }                    sendDeliveryConfirmation(                        messageId,                        sender,                        confirmationJson.toString(),                        DataType.DELIVERY_CONFIRMATION,                        getSandeshStithiTime(sender, messageId, SandeshStithi.SAMARPIT)                    )                }            }            return        }        if (isGroup){            val sandeshTypeInt = finalJsonObject.get(DootawasMessage.SANDESH_TYPE).asInt            val sandeshType = GroupSandeshType.fromInt(sandeshTypeInt)            finalJsonObject.remove(JsonKeys.IS_GROUP)            processGroup(                finalJsonObject, sandeshType = sandeshType, sender, jsonMessage,                messageId, sendNotification, groupId            )        }else {            val sandeshTypeInt = finalJsonObject.get(DootawasMessage.SANDESH_TYPE).asInt            val senderUsernameIdValue = sandeshJsonObject.get(JsonKeys.USER_NAME_ID)?.asString            val isGroupCryptoControlMessage =                sandeshTypeInt == SandeshType.CREATE_GROUP.value ||                        sandeshTypeInt == SandeshType.GROUP_KEY_SETUP.value ||                        sandeshTypeInt == SandeshType.GROUP_KEY_REQUEST.value ||                        sandeshTypeInt == SandeshType.GROUP_KEY_RESPONSE.value ||                        sandeshTypeInt == SandeshType.EPOCH_COMMIT.value            if (!isGroupCryptoControlMessage &&                !senderUsernameIdValue.isNullOrBlank() &&                sender != senderUsernameIdValue            ) {                roomSignalStore.updateUser(                    oldUser = senderUsernameIdValue,                    newUser = sender                )            }            val sandeshType = SandeshType.fromInt(sandeshTypeInt)            finalJsonObject.remove(JsonKeys.IS_GROUP)            if (!SandeshValidator.isValid(sandeshType, finalJsonObject)) {                DLog.i("❌ Invalid Sandesh JSON for $sandeshType")                DLog.i(SandeshValidator.debugInvalidKeys(sandeshType, finalJsonObject))                handleMalformedJsonDelivery(                    jsonMessage.toString(),                    IllegalStateException("Fallback is not a valid JSON object")                )                return            }            processMessage(                finalJsonObject, sandeshType = sandeshType, sender, jsonMessage,                messageId, sendNotification,sandeshJsonObject                    .get(JsonKeys.REVEAL_RECEIVER_NUMBER)                    .asBoolean            )        }    }    // Handle received message    suspend fun addToMediaReceivedUsage(bytes: Int, isMobileData: Boolean) {        val key = if (isMobileData) SettingPrefKeys.DATA_USAGE_MOBILE_MEDIA_RECEIVED        else SettingPrefKeys.DATA_USAGE_WIFI_MEDIA_RECEIVED        dataUsageMutex.withLock {            settingStore.edit { prefs ->                val current = prefs[key] ?: 0                prefs[key] = current + bytes            }        }    }    suspend fun addToMediaSentUsage(bytes: Int, isMobileData: Boolean) {        val key = if (isMobileData) SettingPrefKeys.DATA_USAGE_MOBILE_MEDIA_SENT        else SettingPrefKeys.DATA_USAGE_WIFI_MEDIA_SENT        dataUsageMutex.withLock {            settingStore.edit { prefs ->                val current = prefs[key] ?: 0                prefs[key] = current + bytes            }        }    }    suspend fun addToMessageReceivedUsage(bytes: Int, isMobileData: Boolean) {        val key = if (isMobileData) SettingPrefKeys.DATA_USAGE_MOBILE_MESSAGE_RECEIVED else            SettingPrefKeys.DATA_USAGE_WIFI_MESSAGE_RECEIVED        dataUsageMutex.withLock {            settingStore.edit { prefs ->                val current = prefs[key] ?: 0                prefs[key] = current + bytes            }        }    }    suspend fun deleteMemberFromGroup(        deniedMembers: MutableList<String>,        groupId: String    ) {        if (deniedMembers.isNotEmpty()) {            groupDao.deleteMembersFromGroup(groupId, deniedMembers)            DLog.i("🗑️ Removed denied members from local DB: $deniedMembers")        }    }    private suspend fun handleReceivedMessage(message: String) {        try {            val sizeInBytes = message.toByteArray(Charsets.UTF_8).size            addToMessageReceivedUsage(sizeInBytes, isOnMobileData)            val jsonMessage: JsonObject = JsonParser.parseString(message).asJsonObject            val retrievedValue: Int = jsonMessage.get(JsonKeys.DATA_TYPE).asInt            val dataType: DataType = DataType.fromInt(retrievedValue)            DLog.i(dataType.toString())            when (dataType) {                DataType.TYPING -> handleTypingReceived(jsonMessage.get(JsonKeys.SENDER).asString)                DataType.ASK_FOR_TOKEN -> {                    val senderAB: String = jsonMessage.get(JsonKeys.SENDER).asString                    val messageIdAB: String = jsonMessage.get(JsonKeys.MESSAGE_ID).asString                    val timeStampB: String = jsonMessage.get(JsonKeys.TIME_STAMP).asString                    val confirmationJson = JSONObject().apply {                        put(JsonKeys.SENT_DATA_TYPE, DataType.ASK_FOR_TOKEN.value)                        put(JsonKeys.STORAGE_TYPE, jsonMessage.get(JsonKeys.STORAGE_TYPE).asInt)                        put(JsonKeys.MESSAGE_ID, messageIdAB)                    }                    sendDeliveryConfirmation(                        messageIdAB,                        senderAB,                        confirmationJson.toString(),                        DataType.DELIVERY_DELIVERED,                        timeStampB                    )                    sendCurrentToken()                }                DataType.MORE_KEYS_NEEDED -> {                    val senderAB: String = jsonMessage.get(JsonKeys.SENDER).asString                    val messageIdAB: String = jsonMessage.get(JsonKeys.MESSAGE_ID).asString                    val timeStampB: String = jsonMessage.get(JsonKeys.TIME_STAMP).asString                    val confirmationJson = JSONObject().apply {                        put(JsonKeys.SENT_DATA_TYPE, DataType.MORE_KEYS_NEEDED.value)                        put(JsonKeys.STORAGE_TYPE, jsonMessage.get(JsonKeys.STORAGE_TYPE).asInt)                        put(JsonKeys.MESSAGE_ID, messageIdAB)                    }                    sendDeliveryConfirmation(                        messageIdAB,                        senderAB,                        confirmationJson.toString(),                        DataType.DELIVERY_DELIVERED,                        timeStampB                    )                    sendNextKeys()                    sendNextKuberKeys()                    sendNextKeys()                    sendNextKuberKeys()                }                DataType.CONTACT_PROFILE_STATUS -> {                    val userList: JsonArray = jsonMessage.getAsJsonArray(JsonKeys.LIST)                    DLog.i(userList.toString())                    processContactProfileStatus(userList)                }                DataType.ASK_KEY -> {                    handleAskKey(jsonMessage)                    notifyResponseReceived(jsonMessage.get(JsonKeys.ACK_ID).asString)                }                DataType.CHECK_USER_EXISTENCE -> {                    notifyResponseReceived(jsonMessage.get(JsonKeys.ACK_ID).asString)                    // Extract the user list (JsonArray)                    val userList: JsonArray = jsonMessage.getAsJsonArray(JsonKeys.LIST)                    processExistenceStatus(userList)                }                DataType.CHECK_USER_EXISTENCE_QR -> {                    val ackId = jsonMessage.get(JsonKeys.ACK_ID).asString                    notifyResponseReceived(ackId)                    val exists = jsonMessage.get("exists")?.asBoolean ?: false                    val phone = jsonMessage.get(JsonKeys.USER_NUMBER)?.asString ?: return                    val name = jsonMessage.get("userName")                        ?.takeIf { !it.isJsonNull }                        ?.asString                    val profilePhoto = jsonMessage.get("profile_photo")                        ?.takeIf { !it.isJsonNull }                        ?.asString                    //todo later get profie pic from the server and show                    val state = if (exists) {                        val contact = contactDao.getUserContactByNumber(phone)                        if (contact?.buttonState == ContactButtonState.ADDED) {                            ContactState.AlreadyAdded                        }else{                            ContactState.Exists                        }                    } else {                        ContactState.NotFound                    }                    val result = CheckedContact(                        phone = phone,                        state = state,                        displayName = name,                        profileUri = ""                    )                    // 🔥 Emit to flow                    CoroutineScope(Dispatchers.IO).launch {                        _contactResultFlow.emit(result)                    }                }                DataType.ASK_SINGLE_PROFILE_STATUS -> {                    notifyResponseReceived(jsonMessage.get(JsonKeys.ACK_ID).asString)                    processSingleProfileStatus(jsonMessage)                }                DataType.HOME_PROFILE_STATUS -> {                    notifyResponseReceived(jsonMessage.get(JsonKeys.ACK_ID).asString)                    val profiles = jsonMessage.getAsJsonArray(JsonKeys.LIST) ?: return                    val stories = jsonMessage.getAsJsonArray(JsonKeys.STORIES) ?: JsonArray()                    processHomeProfilesList(profiles)                    processHomeStoriesList(stories)                }                DataType.GET_DELIVERY_TOKEN -> {                    saveDeliveryToken(jsonMessage.get(JsonKeys.TOKEN).asString)                }                DataType.GROUP_HOME_PROFILE -> {                    notifyResponseReceived(jsonMessage.get(JsonKeys.ACK_ID).asString)                    val profiles = jsonMessage.getAsJsonArray(JsonKeys.LIST) ?: return                    processGroupHomeProfilesList(profiles)                }                DataType.GROUP_MEMBER_PROFILE -> {                    notifyResponseReceived(jsonMessage.get(JsonKeys.ACK_ID).asString)                    val profiles = jsonMessage.getAsJsonArray(JsonKeys.LIST) ?: return                    processGroupMembersProfilesList(profiles)                }                DataType.FORWARD_IMAGE -> {}                DataType.DELIVERY_CONFIRMATION -> {                    val sender = jsonMessage[JsonKeys.SENDER].asString                    val messageId = jsonMessage[JsonKeys.MESSAGE_ID].asString                    val timeStamp = jsonMessage[JsonKeys.TIME_STAMP].asString                    // sandesh is a JSON string, not an object                    val sandeshJsonString = jsonMessage[JsonKeys.SANDESH].asString                    val sandeshObject = JsonParser.parseString(sandeshJsonString).asJsonObject                    val isGroup = sandeshObject.get(JsonKeys.IS_GROUP)?.asBoolean ?: false                    val groupId = if (isGroup && sandeshObject.has(JsonKeys.GROUP_ID)) {                        sandeshObject[JsonKeys.GROUP_ID].asString                    } else null                    if (isGroup && groupId != null) {                        DLog.i("updating confirmation")                        updateGroupSandeshStithiTime(                            groupId, messageId, SandeshStithi.SAMARPIT,                            sender, timeStamp.toLong(), true                        )                    } else {                        updateSandeshStithiTime(                            sender, messageId, SandeshStithi.SAMARPIT,                            timeStamp.toLong(), true                        )                    }                    val confirmationJson = JSONObject().apply {                        put(JsonKeys.SENT_DATA_TYPE, DataType.DELIVERY_CONFIRMATION.value)                        put(JsonKeys.STORAGE_TYPE, jsonMessage.get(JsonKeys.STORAGE_TYPE).asInt)                        put(JsonKeys.MESSAGE_ID, messageId)                    }                    sendDeliveryConfirmation(                        messageId,                        sender,                        confirmationJson.toString(),                        DataType.DELIVERY_DELIVERED,                        timeStamp                    )                }                DataType.DATA_VERIFIED -> {                    DLog.i("VERIFIED TYPE DATA $jsonMessage")                    val sentDataType = jsonMessage.get(JsonKeys.SENT_DATA_TYPE)?.asInt                    val isMessageType = sentDataType == DataType.MESSAGE.value                    if (isMessageType) {                        DLog.i("➡️ SENT_DATA_TYPE found and is MESSAGE")                        timePrekshit = jsonMessage.get(JsonKeys.TIME_STAMP)?.asLong ?: run {                            DLog.i("⚠️ TIME_STAMP not found, using default -1")                            -1L                        }                    } else {                        DLog.i("❌ SENT_DATA_TYPE is missing or not MESSAGE")                    }                    DLog.i("📦 dataTypeAck: ${dataTypeAck?.value}, sentDataType: $sentDataType")                    if (dataTypeAck?.value == sentDataType) {                        DLog.i("✅ dataTypeAck matches SENT_DATA_TYPE, notifying...")                        notifyResponseReceived(jsonMessage.get(JsonKeys.ACK_ID).asString)                    } else {                        DLog.i("🚫 dataTypeAck does NOT match SENT_DATA_TYPE")                    }                }                DataType.AUTH_RESPONSE -> {                    if (dataTypeAck?.value == DataType.LOGIN.value) {                        notifyResponseReceivedWithoutID()                    }                    val isAuth = jsonMessage.get(JsonKeys.DATA_BOOLEAN).asBoolean                    val messageAuth = jsonMessage.get(JsonKeys.SANDESH).asString                    val versionString = jsonMessage.get(JsonKeys.VERSION)?.asString ?: "0.0.1"                    val minVersionFromServer =                        versionString.trim().split("|").getOrNull(1)?.trim() ?: "0.0.1"                    val latestVersionFromServer =                        versionString.trim().split("|").getOrNull(0)?.trim() ?: minVersionFromServer                    val currentVersion = BuildConfig.VERSION_NAME                    DLog.i("📦 App Version: $currentVersion | Minimum Required: $minVersionFromServer | Latest: $latestVersionFromServer")                    // Force update if below minimum                    if (isVersionOlderThan(currentVersion, minVersionFromServer)) {                        DLog.i("❌ Version too old. Forcing update...")                        onForceUpdateRequired?.invoke(minVersionFromServer, currentVersion)                        SocketManager.setConnectionAllowed(false)                        return                    }                    if (isVersionOlderThan(currentVersion, latestVersionFromServer)) {                        val lastShownVersion = settingFlow(                            SettingPrefKeys.OPTIONAL_UPDATE_SHOWN_VERSION,                            ""                        ).first()                        if (lastShownVersion != latestVersionFromServer) {                            DLog.i("⚠️ Optional update available: $latestVersionFromServer")                            onOptionalUpdateAvailable?.invoke(                                latestVersionFromServer,                                currentVersion                            )                        }                    }                    if (isAuth) {                        saveFileToken(jsonMessage.get(JsonKeys.TOKEN).asString)                        sessionToken = jsonMessage.get(JsonKeys.SAMABHASH_TOKEN).asString                        isParmaan = true                        checkAndHandleDeliveryToken()                        if (reason == ConnectReason.SendDataOnly) {                            sendUnsentMessages(true)                        } else {                            _connectionStatus.value = true                            sendUnsentMessages(false)                            sendUnsentFiles()          