mber = senderSeen,                                time = timeStampSeen.toLong(),                                true                            )                            // group disappearing not handled yet — see note below                        } else {                            DLog.i("? single Seen ? $originalId")                            updateSandeshStithiTime(                                userNumber = senderSeen,                                sandeshId = originalId,                                stithi = SandeshStithi.DHRIST,                                time = timeStampSeen.toLong(),                                true                            )                            singleChatSeenIds.add(originalId) // 👈 track for scheduling                        }                    }                    // 👇 schedule disappear timers for your own sent messages now confirmed seen                    if (singleChatSeenIds.isNotEmpty()) {                        scheduleDisappearForBatch(senderSeen, singleChatSeenIds, timeStampSeen.toLong())                    }                    val confirmationJson = JSONObject().apply {                        put(JsonKeys.SENT_DATA_TYPE, DataType.SEEN_STATUS.value)                        put(JsonKeys.STORAGE_TYPE, jsonMessage.get(JsonKeys.STORAGE_TYPE).asInt)                        put(JsonKeys.MESSAGE_ID, messageIdSeen)                    }                    sendDeliveryConfirmation(                        messageIdSeen,                        senderSeen,                        confirmationJson.toString(),                        DataType.SEEN_DELIVERED,                        timeStampSeen                    )                }                DataType.DELIVERY_DELIVERED -> {                    // Handle DELIVERY_DELIVERED                    val senderDelivered: String = jsonMessage.get(JsonKeys.SENDER).asString                    val messageIdDelivered: String = jsonMessage.ge