ck?.value == DataType.ASK_REGISTER_KEY.value) {                        notifyResponseReceivedWithoutID()                    }                }                DataType.CALL_DATA -> {                    DLog.i("CALL DATA gson $jsonMessage")                    try {                        val callData = gson.fromJson(jsonMessage, CallData::class.java)                        callDataCallback?.invoke(callData)                    } catch (e: Exception) {                        DLog.e("Failed to parse CALL_DATA: ${e.message}", e)                    }                }                DataType.REGISTRATION_RESPONSE -> {                    handleRegistrationResponse(jsonMessage)                }                DataType.GROUP_ACTION -> {                    if (dataTypeAck?.value == DataType.GROUP_ACTION.value) {                        DLog.i("✅ dataTypeAck matches SENT_DATA_TYPE, notifying...")                        notifyResponseReceived(jsonMessage.get(JsonKeys.ACK_ID).asString)                    } else {                        DLog.i("🚫 dataTypeAck does NOT match SENT_DATA_TYPE")                    }                    handleGroupAction(jsonMessage)                }                DataType.INVALID_DATA -> {                    DLog.i("INVALID DATA")                    notifyResponseReceivedWithoutID()                }                DataType.SEND_OTP -> {                    val success = jsonMessage.get("dataBoolean")?.asBoolean == true                    val reason = jsonMessage.get("reason")?.asString ?: "Unknown error"                    if (!success) {                        Handler(Looper.getMainLooper()).post {                            Toast.makeText(context, " $reason", Toast.LENGTH_LONG).show()                        }                    }                }                DataType.MEMBER_RESPONSE -> {                }                DataType.REQUEST_MEMBER -> {                    val sandeshArray = jsonMessage.getAs