pdatedSet                        )                        val sentDataType = jsonMessage.get(JsonKeys.SENT_DATA_TYPE)?.asInt                        if (dataTypeAck?.value == sentDataType) {                            DLog.i("✅ dataTypeAck matches SENT_DATA_TYPE, notifying...")                            notifyResponseReceived(jsonMessage.get(JsonKeys.ACK_ID).asString)                        } else {                            DLog.i("🚫 dataTypeAck does NOT match SENT_DATA_TYPE")                        }                    }                }                DataType.GET_PRIVACY_SETTINGS -> {                    DLog.i("This need to store in data store privacy $jsonMessage")                    DLog.i("📥 Received privacy settings: $jsonMessage")                    val dataObject = jsonMessage.getAsJsonObject("data")                    if (dataObject != null) {                        val lastSeenLabel =                            dataObject.get("LAST_SEEN").asInt                        val onlineStatusLabel =                            dataObject.get("ONLINE_STATUS").asInt                        val profilePhotoLabel =                            dataObject.get("PROFILE_PHOTO").asInt                        val bioLabel =                            dataObject.get("BIO").asInt                        val messagesLabel =                            dataObject.get("MESSAGES").asInt                        val groupInvitesLabel =                            dataObject.get("GROUP_INVITES").asInt                        val callsLabel =                            dataObject.get("CALLS").asInt                        DLog.i("🔒 Converted labels:")                        DLog.i("LAST_SEEN = $lastSeenLabel")                        DLog.i("ONLINE_STATUS = $onlineStatusLabel")                        DLog.i("PROFILE_PHOTO = $profilePhotoLabel")                        DLog.i("BIO = $bioLabel")                        DLog.i("MESSAGES = $messagesLabel")                        DLog.i("GROUP_INVITES = $groupInvitesLabel")                        DLog.i("CALLS = $callsLabel")                        // 🔥 Save to DataStore (String-based)                        updateIntSetting(                            SettingPrefKeys.PRIVACY_LAST_SEEN,                            lastSeenLabel                        )                        updateIntSetting(                            SettingPrefKeys.PRIVACY_ONLINE_STATUS,                            onlineStatusLabel                        )                        updateIntSetting(                            SettingPrefKeys.PRIVACY_PROFILE_PHOTO,                            profilePhotoLabel                        )                        updateIntSetting(                            SettingPrefKeys.PRIVACY_BIO,                            bioLabel                        )                        updateIntSetting(                            SettingPrefKeys.PRIVACY_MESSAGES,                            messagesLabel                        )                        updateIntSetting(                            SettingPrefKeys.PRIVACY_GROUP_INVITES,                            groupInvitesLabel                        )                        updateIntSetting(                            SettingPrefKeys.CALL_ALLOW_FROM,                            callsLabel                        )                        DLog.i("✅ Privacy settings saved to DataStore")                    }                    val sentDataType = jsonMessage.get(JsonKeys.SENT_DATA_TYPE)?.asInt                    if (dataTypeAck?.value == sentDataType) {                        DLog.i("✅ dataTypeAck matches SENT_DATA_TYPE, notifying...")                        notifyResponseReceived(jsonMessage.get(JsonKeys.ACK_ID).asString)                    } else {                        DLog.i("🚫 dataTypeAck does NOT match SENT_DATA_TYPE")                    }                }                