                  userNumber = counterpartyUser,//                                        wallpaperId = it//                                    )//                                }                                upbhogtaDao.updateAutoDisappearDuration(                                    userNumber = counterpartyUser,                                    duration = disappearingDuration                                )                                DLog.i("? Local settings synchronization complete for $counterpartyUser: balance=$balance, theme=$theme, wallpaper=$wallpaper, disappearing=$disappearingDuration")                            }                        } else {                            DLog.w("?? User settings fetch returned a failure status or null counterparty.")                        }                    } catch (e: Exception) {                        DLog.e("? Failed to parse or persist backend user settings payload: ${e.message}")                    }                }                DataType.FILE_PROCESS -> {                    DLog.d("responsefile $jsonMessage")                    if (dataTypeAck?.value == DataType.FILE_PROCESS.value) {                        DLog.i("✅ dataTypeAck matches SENT_DATA_TYPE, notifying...")                        notifyResponseReceived(jsonMessage.get(JsonKeys.MESSAGE_ID).asString)                    } else {                        DLog.i("🚫 dataTypeAck does NOT match SENT_DATA_TYPE")                    }                    val generated =                        jsonMessage.get(JsonKeys.DATA_BOOLEAN)?.asBoolean ?: true                    if (!generated) {                        return                    }                    when (jsonMessage.get(JsonKeys.FILE_TOKEN_TYPE)?.asInt) {                        FileDataTypeToken.FILE_UPLOAD_REQUEST.value -> {                            val response = gson.fromJson(                                jsonMessage,                                FileUploadResponse::class.java                            )                            pendingUploadRequests                                .remove(response.messageId)                                ?.complete(response)                        }                        FileDataTypeToken.STORY_UPLOAD_REQUEST.value -> {                            val response = gson.fromJson(                                jsonMessage,                                FileUploadResponse::class.java                            )                            pendingStoryUploadRequests                                .remove(response.messageId)                                ?.complete(response)                        }                        FileDataTypeToken.FILE_DOWNLOAD_REQUEST.value -> {                            val response = gson.fromJson(                                jsonMessage,                                FileDownloadResponse::class.java                            )                            pendingDownloadRequests                                .remove(response.messageId)                                ?.complete(response)                        }                        FileDataTypeToken.PROFILE_UPLOAD_REQUEST.value -> {                            val response = gson.fromJson(                                jsonMessage,                                ProfileUploadResponse::class.java                            )                            pendingProfileUploadRequests                                .remove(response.messageId)                                ?.complete(response)                        }                        FileDataTypeToken.PROFILE_DOWNLOAD_REQUEST.value -> {                            val response = gson.fromJson(                                jsonMessage,                                ProfileDownloadResponse::class.java                            )                            pendingProfileDownloadRequests                                .remove(response.messageId)                                ?.complete(response)                        }                        FileDataTypeToken.STORY_DOWNLOAD_REQUEST.value -> {                            val messageId = jsonMessage.get(JsonKeys.MESSAGE_ID)                                ?.takeUnless { it.isJsonNull }                                ?.asString                            val stories = jsonMessage.getAsJsonArray(JsonKeys.STORIES)                            if (stories == null || stories.isEmpty) {                                DLog.i("STORY DOWNLOAD: no stories returned")                                return                            }                            DLog.i(                                "STORY DOWNLOAD: received ${stories.size()} download URLs messageId=$messageId"                            )                            processStoryDownloadUrls(stories)                        }                    }                }                DataType.CHECK_USERNAME_ID -> {                    DLog.d("response USERNAME $jsonMessage")                    if (dataTypeAck?.value == DataType.CHECK_USERNAME_ID.value) {                        DLog.i("✅ dataTypeAck matches SENT_DATA_TYPE, notifying...")                        notifyResponseReceived(jsonMessage.get(JsonKeys.MESSAGE_ID).asString)                    } else {                        DLog.i("🚫 dataTypeAck does NOT match SENT_DATA_TYPE")                    }                    DLog.d("response USERNAME $jsonMessage")                    val messId = jsonMessage.get(JsonKeys.MESSAGE_ID)?.asString                    val isAvailable = jsonMessage.get(JsonKeys.DATA_BOOLEAN)?.asBoolean                    if (messId == null || isAvailable == null) {                        DLog.w("⚠️ Malformed CHECK_USERNAME_ID response: $jsonMessage")                        return // or `return` depending on enclosing function shape                    }                    val deferred = pendingUsernameChecks[messId]                    if (deferred != null) {                        deferred.complete(isAvailable)                        DLog.i("✅ Completed username check for messId=$messId -> available=$isAvailable")                    } else {                        // response arrived after timeout, or check was superseded by a newer keystroke — safe to ignore                        DLog.i("🚫 No pending check for messId=$messId (likely timed out or superseded)")                    }                }                DataType.UPDATE_USERNAME_ID -> {                    val messId = jsonMessage.get(JsonKeys.MESSAGE_ID)?.asString                    val success = jsonMessage.get(JsonKeys.DATA_BOOLEAN)?.asBoolean                    val reason = jsonMessage.get(JsonKeys.REASON)?.asString // e.g. "TAKEN" | "COOLDOWN" | "SUCCESS" | error text                    if (dataTypeAck?.value == DataType.UPDATE_USERNAME_ID.value) {                        DLog.i("✅ dataTypeAck matches SENT_DATA_TYPE, notifying...")                        notifyResponseReceived(jsonMessage.get(JsonKeys.MESSAGE_ID).asString)                    } else {                        DLog.i("🚫 dataTypeAck does NOT match SENT_DATA_TYPE")                    }                    if (messId == null || success == null) {                        DLog.w("⚠️ Malformed UPDATE_USERNAME_ID response: $jsonMessage")                        return                    }                    val deferred = pendingUsernameUpdates[messId]                    if (deferred != null) {                        val result = when {                            success -> UpdateUserNameIdResult.Success                            reason == "TAKEN" -> UpdateUserNameIdResult.Taken                            reason == "COOLDOWN" -> UpdateUserNameIdResult.CooldownActive(0L) // server can send exact epoch if needed                            else -> UpdateUserNameIdResult.Failed(reason ?: "Update failed")                        }                        deferred.complete(result)                    } else {                        DLog.i("🚫 No pending update for messId=$messId")                    }                }                DataType.STORY_MP3_LINK_GENERATE -> {                    val messId = jsonMessage.get(JsonKeys.MESSAGE_ID)?.asString                    val success = jsonMessage.get(JsonKeys.DATA_BOOLEAN)?.asBoolean ?: false                    if (messId != null && dataTypeAck?.value == DataType.STORY_MP3_LINK_GENERATE.value) {                        notifyResponseReceived(messId)                    }                    // Remove from pending map so memory is freed once completed                    val deferred = messId?.let { pendingStoryMusicRequests.remove(it) } ?: return                    if (!success) {                        val errorMsg = jsonMessage.get(JsonKeys.SANDESH)?.asString ?: "Failed to fetch music"                        DLog.w("STORY_MP3_LINK_GENERATE error: $errorMsg")                        deferred.complete(emptyList())                        return                    }                    val tracksArray = jsonMessage.getAsJsonArray(JsonKeys.TRACKS)                    val trackList = mutableListOf<AudioTrackItem>()                    tracksArray?.forEach { element ->                        val item = element.asJsonObject                        val streamUrl = item.get(JsonKeys.STREAM_URL)?.asString ?: ""                        if (streamUrl.isNotBlank()) {                            trackList.add(                                AudioTrackItem(                                    id = item.get(JsonKeys.ID)?.asString ?: "",                                    title = item.get(JsonKeys.TITLE)?.asString ?: "Unknown Track",                                    artist = item.get(JsonKeys.ARTIST)?.asString ?: "Royalty Free",                                    uri = Uri.parse(streamUrl),                                    durationMs = item.get(JsonKeys.DURATION_MS)?.asLong ?: 120000L                                )                            )                        }                    }                    deferred.complete(trackList)                }                DataType.STORY_ACTION -> {                    DLog.i("STORY ACTION RESPONSE: $jsonMessage")                    val messageId = jsonMessage                        .get(JsonKeys.MESSAGE_ID)                        ?.takeUnless { it.isJsonNull }                        ?.asString                    // Notify only once after the complete STORY_ACTION response is processed.                    messageId?.let {                        notifyResponseReceived(it)                    }                    val data = jsonMessage                        .get(JsonKeys.DATA)                        ?.takeUnless { it.isJsonNull }                        ?.asJsonObject                    if (data == null) {                        DLog.e("STORY ACTION: missing response data")                        return                    }                    val actionValue = data                        .get(JsonKeys.STORY_ACTION)                        ?.takeUnless { it.isJsonNull }                        ?.asInt                    if (actionValue == null) {                        DLog.e("STORY ACTION: missing story action")                        return                    }                    val action = try {                        StoryAction.fromValue(actionValue)                    } catch (e: Exception) {                        DLog.e(                            "STORY ACTION: unknown action=$actionValue",                            e                        )                        return                    }                    when (action) {                        StoryAction.DELETE_STORY,                        StoryAction.SET_COMMENT_PRIVATE,                        StoryAction.ADD_COMMENT,                        StoryAction.DELETE_COMMENT,                        StoryAction.LIKE_STORY,                        StoryAction.UNLIKE_STORY,                        StoryAction.VIEW_STORY,                        StoryAction.SET_VISIBILITY -> {                            DLog.i(                                "STORY ACTION: ${action.name} completed"                            )                        }                        StoryAction.GET_STORY_DETAILS -> {                            DLog.i(                                "STORY ACTION: GET_STORY_DETAILS response"                            )                            val comments = data.get(JsonKeys.COMMENTS)                                ?.takeUnless { it.isJsonNull }                                ?.asJsonArray                            val likes = data.get(JsonKeys.LIKES)                                ?.takeUnless { it.isJsonNull }                                ?.asJsonArray                            val views = data.get(JsonKeys.VIEWS)                                ?.takeUnless { it.isJsonNull }                                ?.asJsonArray                            val likeCount = data.get(JsonKeys.LIKE_COUNT)                                ?.takeUnless { it.isJsonNull }                                ?.asInt                            val commentCount = data.get(JsonKeys.COMMENT_COUNT)                                ?.takeUnless { it.isJsonNull }                                ?.asInt                            val viewCount = data.get(JsonKeys.VIEW_COUNT)                                ?.takeUnless { it.isJsonNull }                                ?.asInt                            val commentPrivate = data.get(JsonKeys.COMMENT_PRIVATE)                                ?.takeUnless { it.isJsonNull }                                ?.asBoolean                            val detailsData = data.get(JsonKeys.DATA)                                ?.takeUnless { it.isJsonNull }                                ?.asJsonObject                            val storyId = detailsData                                ?.get(DootawasMessage.STORY_ID)                                ?.takeUnless { it.isJsonNull }                                ?.asString                                ?.takeIf { it.isNotBlank() }                            if (storyId == null) {                                DLog.e("STORY DETAILS: missing storyId")                                return                            }                            comments?.let {                                processStoryComments(storyId, it)                            }                            likes?.let {                                processStoryLikes(storyId, it)                            }                            views?.let {                                processStoryViews(storyId, it)                            }                            DLog.i(                                "STORY DETAILS: comments=${comments?.size() ?: 0}, " +                                        "likes=${likes?.size() ?: 0}, " +                                        "views=${views?.size() ?: 0}, " +                                        "likeCount=$likeCount, " +                                        "commentCount=$commentCount, " +                                        "viewCount=$viewCount, " +                                        "commentPrivate=$commentPrivate"                            )                            if (!storyId.isNullOrBlank()) {                                coroutineScope.launch {                                    likeCount?.let {                                        storyDao.setLikeCount(                                            storyId = storyId,                                            likeCount = it                                        )                                    }                                    commentCount?.let {                                        storyDao.setCommentCount(                                            storyId = storyId,                                            commentCount = it                                        )                                    }                                    viewCount?.let {                                        storyDao.setViewCount(                                            storyId = storyId,                                            viewCount = it                                        )                                    }                                    commentPrivate?.let {                                        storyDao.setCommentsPrivate(                                            storyId = storyId,                                            isPrivate = it                                        )                                    }                                }                            }                        }                    }                }                DataType.GET_QUICK_TIPS_DATA -> {                    DLog.i("Received User QuickTipsData: $jsonMessage")                    try {                        if (dataTypeAck?.value == DataType.GET_QUICK_TIPS_DATA.value) {                            val ackId = jsonMessage.get(JsonKeys.ACK_ID).asString                            notifyResponseReceived(ackId)                            val dataArray = jsonMessage.getAsJsonArray("data")                            val userNumber = "+919999912345"                            // IDs currently present on server                            val receivedIds = dataArray.map { element ->                                element.asJsonObject.get("fileId").asString                            }.toSet()                            // Existing records for this user                            val existingMessages =                                sandeshDao.getReceivedMessagesForUser(userNumber)                            val idsToDelete = existingMessages                                .map { it.sandeshId }                                .filter { it !in receivedIds }                            if (idsToDelete.isNotEmpty()) {                                sandeshDeleter.deleteMessages(                                    sandeshIds = idsToDelete,                                    userNumber = userNumber                                )                            }                            // Add only records that don't already exist                            dataArray.forEach { element ->                                val json = element.asJsonObject                                val fileId = json.get("fileId").asString                                if (!sandeshDao.existsById(fileId)) {                                    val time = json.get("time").asLong                                    val sandeshType = json.get("sandeshType").asInt                                    val sandesh = Sandesh(                                        sandeshId = fileId,                                        userNumber = userNumber,                                        samagri = json.toString(),                                        isSelf = false,                                        time = time,                                        sandeshType = sandeshType,                                        sandeshStithi = SandeshStithi.DHRIST                                    )                                    sandeshDao.insertMessage(sandesh)                                    downloadFile(fileId,userNumber)                                }                            }                        }                    } catch (e: Exception) {                        DLog.e("Failed to parse or persist QuickTipsData: ${e.message}")                    }                }                DataType.AI_MESSAGE -> {                    handleAiResponse(jsonMessage)                }                DataType.FETCH_AI_TOKENS -> {                    val amount = jsonMessage.get(JsonKeys.AMOUNT).asLong                   updateAiWalletBalance(amount)                }                else -> DLog.i("Unknown message type: $dataType")            }        } catch (e: Exception) {            handleMalformedJsonDelivery(message, e)            Log.e("Knotx", "Error malformed JSON", e)  // ✅ full details with stack trace        }    }    val aiWalletBalanceFlow: Flow<AiWalletBalance> =        settingStore.data.map { preferences ->            preferences[PrefKeys.AI_WALLET_BALANCE]?.let {                runCatching {                    gson.fromJson(it, AiWalletBalance::class.java)                }.getOrNull()            } ?: AiWalletBalance()        }.distinctUntilChanged()    suspend fun saveAiWalletBalance(balance: AiWalletBalance) {        settingStore.edit { preferences ->            preferences[PrefKeys.AI_WALLET_BALANCE] = gson.toJson(balance)        }    }    private suspend fun sendAiMessageAck(messageId: String) {        val sender = userNumberKhud.firstOrNull()        if (sender.isNullOrBlank()) {            DLog.e("Cannot send AI message ACK: sender ID unavailable")            return        }        val json = JsonObject().apply {            addProperty(JsonKeys.DATA_TYPE, DataType.AI_ACK.value)            addProperty(JsonKeys.SENDER, sender)            addProperty(JsonKeys.MESSAGE_ID, messageId)        }        SocketManager.send(json.toString())    }    suspend fun updateAiWalletBalance(balance: Long) {        settingStore.edit { preferences ->            val current = preferences[PrefKeys.AI_WALLET_BALANCE]                ?.let { runCatching { gson.fromJson(it, AiWalletBalance::class.java) }.getOrNull() }            val updated = (current ?: AiWalletBalance(                balance = 0L,                freeMonthlyTarget = 0L            )).copy(                balance = balance            )            preferences[PrefKeys.AI_WALLET_BALANCE] = gson.toJson(updated)        }    }    suspend fun fetchAiTokens(){        val sender = userNumberKhud.firstOrNull()        if (sender.isNullOrBlank()) {            DLog.e("Cannot send AI message ACK: sender ID unavailable")            return        }        val json = JsonObject().apply {            addProperty(JsonKeys.DATA_TYPE, DataType.FETCH_AI_TOKENS.value)            addProperty(JsonKeys.SENDER, sender)            addProperty(JsonKeys.SAMABHASH_TOKEN, sessionToken)        }        SocketManager.send(json.toString())    }    private suspend fun handleAiResponse(jsonMessage: JsonObject) {        // Always use the original server-generated ID        val messageId = jsonMessage.get(JsonKeys.MESSAGE_ID).asString        val receiver = jsonMessage.get(JsonKeys.RECEIVER).asString        val replyTo = jsonMessage.get(JsonKeys.REPLY_TO).asString        TypingManager.clearTyping(            TypingState(                userNumber = receiver,                isTyping = false,                isAi = true            )        )        // Duplicate protection        if (sandeshDao.existsById(messageId)) {            DLog.d("Duplicate AI response: $messageId")            sendAiMessageAck(messageId)            return        }        // Mark the message being replied to as seen        sandeshDao.updateStithiIfForwardProgress(            replyTo,            receiver,            SandeshStithi.DHRIST.value        )        val dID = upbhogtaDao.getAutoDisappearDuration(receiver)        val dataJson = JsonParser.parseString(            jsonMessage.get(JsonKeys.DATA).asString        ).asJsonObject        // Update local AI wallet balance        dataJson.getAsJsonObject("balance")?.let { balanceJson ->            runCatching {                saveAiWalletBalance(                    AiWalletBalance(                        balance = balanceJson.get("balance").asLong,                        freeMonthlyTarget = balanceJson.get("freeMonthlyTarget").asLong                    )                )            }.onFailure {                DLog.e("Failed to update AI wallet balance: ${it.message}")            }        }        val fullText = dataJson.get("paath").asString        val blocks = dataJson.remove("blocks")        dataJson.remove("balance")        dataJson.addProperty("diD", dID)        val time = System.currentTimeMillis()        val chunks = Regex("\\S+\\s*")            .findAll(fullText.trim())            .map { it.value }            .toList()            .chunked(5)        val sandesh = Sandesh(            sandeshId = messageId,            userNumber = receiver,            samagri = dataJson.toString(),            isSelf = false,            time = time,            sandeshType = SandeshType.AI_MESSAGE.value,            sandeshStithi = SandeshStithi.DHRIST        )        val displayedText = StringBuilder()        displayedText.append(chunks.firstOrNull()?.joinToString("") ?: "")        dataJson.addProperty("paath", displayedText.toString())        sandeshDao.insertMessage(            sandesh.copy(samagri = dataJson.toString())        )        try {            for (chunk in chunks.drop(1)) {                delay(180)                displayedText.append(chunk.joinToString(""))                dataJson.addProperty("paath", displayedText.toString())                sandeshDao.updateSamagri(messageId, dataJson.toString())            }        } finally {            withContext(NonCancellable) {                dataJson.addProperty("paath", fullText)                if (blocks != null) {                    dataJson.add("blocks", blocks)                }                sandeshDao.updateSamagri(messageId, dataJson.toString())            }        }        // ACK only after the complete message is persisted        sendAiMessageAck(messageId)    }    private fun processStoryComments(        storyId: String,        comments: JsonArray    ) {        CoroutineScope(Dispatchers.IO).launch {            try {                val entities = mutableListOf<StoryCommentEntity>()                comments.forEach { element ->                    if (!element.isJsonObject) return@forEach                    val comment = element.asJsonObject                    val commentId = comment.get(JsonKeys.COMMENT_ID)                        ?.takeUnless { it.isJsonNull }                        ?.asString                        ?.takeIf { it.isNotBlank() }                        ?: return@forEach                    val userId = comment.get(JsonKeys.USER_NUMBER)                        ?.takeUnless { it.isJsonNull }                        ?.asString                        ?.takeIf { it.isNotBlank() }                        ?: return@forEach                    val text = comment.get(JsonKeys.COMMENT)                        ?.takeUnless { it.isJsonNull }                        ?.asString                        ?: return@forEach                    val createdAt = comment.get(JsonKeys.TIME_STAMP)                        ?.takeUnless { it.isJsonNull }                        ?.asLong                        ?: return@forEach                    entities.add(                        StoryCommentEntity(                            id = commentId,                            storyId = storyId,                            userId = userId,                            text = text,                            createdAt = createdAt,                            pendingSync = false                        )                    )                }                if (entities.isNotEmpty()) {                    storyCommentDao.upsertAll(entities)                }                DLog.i(                    "STORY DETAILS: stored ${entities.size} comments for story=$storyId"                )            } catch (e: Exception) {                DLog.e(                    "STORY DETAILS: failed storing comments: ${e.message}",                    e                )            }        }    }    private fun processStoryLikes(        storyId: String,        likes: JsonArray    ) {        CoroutineScope(Dispatchers.IO).launch {            try {                val entities = mutableListOf<StoryLikeEntity>()                likes.forEach { element ->                    if (!element.isJsonObject) return@forEach                    val like = element.asJsonObject                    val userId = like.get(JsonKeys.USER_NUMBER)                        ?.takeUnless { it.isJsonNull }                        ?.asString                        ?.takeIf { it.isNotBlank() }                        ?: return@forEach                    val likedAt = like.get(JsonKeys.TIME_STAMP)                        ?.takeUnless { it.isJsonNull }                        ?.asLong                        ?: return@forEach                    entities.add(                        StoryLikeEntity(                            storyId = storyId,                            userId = userId,                            likedAt = likedAt                        )                    )                }                if (entities.isNotEmpty()) {                    storyLikeDao.upsertAll(entities)                }                DLog.i(                    "STORY DETAILS: stored ${entities.size} likes for story=$storyId"                )            } catch (e: Exception) {                DLog.e(                    "STORY DETAILS: failed storing likes: ${e.message}",                    e                )            }        }    }    private fun processStoryViews(        storyId: String,        views: JsonArray    ) {        CoroutineScope(Dispatchers.IO).launch {            try {                val entities = mutableListOf<StoryViewEntity>()                views.forEach { element ->                    if (!element.isJsonObject) return@forEach                    val view = element.asJsonObject                    val viewerId = view.get(JsonKeys.USER_NUMBER)                        ?.takeUnless { it.isJsonNull }                        ?.asString                        ?.takeIf { it.isNotBlank() }                        ?: return@forEach                    val viewedAt = view.get(JsonKeys.TIME_STAMP)                        ?.takeUnless { it.isJsonNull }                        ?.asLong                        ?: return@forEach                    entities.add(                        StoryViewEntity(                            storyId = storyId,                            viewerId = viewerId,                            viewedAt = viewedAt                        )                    )                }                if (entities.isNotEmpty()) {                    storyViewDao.upsertAll(entities)                }                DLog.i(                    "STORY DETAILS: stored ${entities.size} views for story=$storyId"                )            } catch (e: Exception) {                DLog.e(                    "STORY DETAILS: failed storing views: ${e.message}",                    e                )            }        }    }    private val pendingUploadRequests =        ConcurrentHashMap<String, CompletableDeferred<FileUploadResponse>>()    private val pendingDownloadRequests =        ConcurrentHashMap<String, CompletableDeferred<FileDownloadResponse>>()    private val pendingProfileUploadRequests =        ConcurrentHashMap<String, CompletableDeferred<ProfileUploadResponse>>()    private val pendingProfileDownloadRequests =        ConcurrentHashMap<String, CompletableDeferred<ProfileDownloadResponse>>()    suspend fun requestProfileDownloadUrl(        messageId: String,        profileId: String,        isGroup: Boolean    ): ProfileDownloadResponse {        val deferred = CompletableDeferred<ProfileDownloadResponse>()        pendingProfileDownloadRequests[messageId] = deferred        val request = JsonObject().apply {            addProperty(JsonKeys.FILE_TOKEN_TYPE, FileDataTypeToken.PROFILE_DOWNLOAD_REQUEST.value)            addProperty(JsonKeys.MESSAGE_ID, messageId)            addProperty(JsonKeys.DATA_BOOLEAN, isGroup)            if (isGroup) {                addProperty(JsonKeys.RECEIVER, profileId)            }        }        sendMessage(            UnsentSandesh(                messId = messageId,                receiver = profileId,                message = request.toString(),                dataType = DataType.FILE_PROCESS            )        )        return deferred.await()    }    suspend fun requestProfileUploadUrl(        messageId: String,        receiver: String?,        pass: String,        isGroup: Boolean    ): ProfileUploadResponse {        val deferred = CompletableDeferred<ProfileUploadResponse>()        pendingProfileUploadRequests[messageId] = deferred        val request = JsonObject().apply {            addProperty(                JsonKeys.FILE_TOKEN_TYPE,                FileDataTypeToken.PROFILE_UPLOAD_REQUEST.value            )            addProperty(JsonKeys.MESSAGE_ID, messageId)            addProperty(JsonKeys.DATA, pass)            addProperty(JsonKeys.DATA_BOOLEAN, isGroup)            if (isGroup) {                addProperty(JsonKeys.RECEIVER, receiver)            }        }        val unsentSandesh = UnsentSandesh(            messId = messageId,            receiver = receiver ?: "",            message = request.toString(),            dataType = DataType.FILE_PROCESS        )        sendMessage(unsentSandesh)        return deferred.await()    }    suspend fun requestUploadUrl(        messageId: String,        receivers: List<String>    ): FileUploadResponse {        val deferred = CompletableDeferred<FileUploadResponse>()        pendingUploadRequests[messageId] = deferred        val request = JsonObject().apply {            addProperty(                JsonKeys.FILE_TOKEN_TYPE,                FileDataTypeToken.FILE_UPLOAD_REQUEST.value            )            val array = JsonArray()            receivers.forEach(array::add)            add(JsonKeys.RECEIVERS, array)        }        val unsentSandesh = UnsentSandesh(            messId = messageId,            receiver = receivers.first(),            message = request.toString(),            dataType = DataType.FILE_PROCESS        )        sendMessage(unsentSandesh)        return deferred.await()    }    private val pendingStoryUploadRequests =        ConcurrentHashMap<String, CompletableDeferred<FileUploadResponse>>()    suspend fun requestStoryUploadUrl(        storyId: String    ): FileUploadResponse {        val deferred = CompletableDeferred<FileUploadResponse>()        pendingStoryUploadRequests[storyId] = deferred        val request = JsonObject().apply {            addProperty(                JsonKeys.FILE_TOKEN_TYPE,                FileDataTypeToken.STORY_UPLOAD_REQUEST.value            )            addProperty(                JsonKeys.MESSAGE_ID,                storyId            )        }        val unsentSandesh = UnsentSandesh(            messId = storyId,            receiver = storyId,            message = request.toString(),            dataType = DataType.FILE_PROCESS        )        sendMessage(unsentSandesh)        return deferred.await()    }    // Map to track pending story music requests by messageId    private val pendingStoryMusicRequests = ConcurrentHashMap<String, CompletableDeferred<List<AudioTrackItem>>>()    suspend fun requestStoryMp3Links(        category: String = "all"    ): List<AudioTrackItem> {        val messageId = UUID.randomUUID().toString()        val deferred = CompletableDeferred<List<AudioTrackItem>>()        pendingStoryMusicRequests[messageId] = deferred        val request = JsonObject().apply {            addProperty(JsonKeys.MESSAGE_ID, messageId)            addProperty(JsonKeys.CATEGORY, category)        }        sendMessage(            UnsentSandesh(                messId = messageId,                receiver = "pixabey",                message = request.toString(),                dataType = DataType.STORY_MP3_LINK_GENERATE            )        )        return try {            deferred.await()        } finally {            pendingStoryMusicRequests.remove(messageId)        }    }    suspend fun requestDownloadUrl(        sender: String,        messageId: String    ): FileDownloadResponse {        val deferred = CompletableDeferred<FileDownloadResponse>()        pendingDownloadRequests[messageId] = deferred        val request = JsonObject().apply {            addProperty(                JsonKeys.FILE_TOKEN_TYPE,                FileDataTypeToken.FILE_DOWNLOAD_REQUEST.value            )            addProperty(                JsonKeys.SENDER,                sender            )        }        val unsentSandesh = UnsentSandesh(            messId = messageId,            receiver = sender,            message = request.toString(),            dataType = DataType.FILE_PROCESS        )        sendMessage(unsentSandesh)        return deferred.await()    }    private val _liveRouteFlow = MutableSharedFlow<Pair<String, String>>()    val liveRouteFlow = _liveRouteFlow.asSharedFlow()    fun setLatestAvailable(latest: String){        coroutineScope.launch {            context.settingStore.edit {                it[SettingPrefKeys.OPTIONAL_UPDATE_SHOWN_VERSION] =                    latest            }        }    }    fun privacyLabelFromValue(value: Int): String {        return when (value) {            0 -> "Everyone"            1 -> "Contact