nchIntentForPackage(context.packageName)            ?.apply {                addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK)            }        if (intent != null) {            context.startActivity(intent)            Process.killProcess(Process.myPid())        }    }    fun deleteAccount() {        coroutineScope.launch {            writeMessageMutex.withLock {                _isProcessing.value = true                //todo before delete account leave from all groups                val unsentSandesh = UnsentSandesh(                    messId = createMessageID(),                    receiver = "delete_account",   // server route / handler key                    message = "delete_user_account",   // 🔥 Gson JSON as String                    dataType = DataType.DELETE_ACCOUNT,                    isGroup = false                )                // 📦 store locally (offline-safe)                insertUnsentData(unsentSandesh)                // 🚀 trigger sender if idle                sendUnsentMessages(false)            }        }    }    suspend fun ensureIdentity(): Pair<IdentityKeyPair, Int> {        val existing = signalDao.getIdentity()        if (existing != null) {            val identityPair = IdentityKeyPair(existing.identityKeyPair)            return identityPair to existing.registrationId        }        // Generate new identity        val identityKeyPair = IdentityKeyPair.generate()        val registrationId = KeyHelper.generateRegistrationId(false)        val entity = IdentityEntity(            id = 1,            identityKeyPair = identityKeyPair.serialize(),            registrationId = registrationId        )        signalDao.saveIdentity(entity)        return identityKeyPair to registrationId    }    private val base64 = java.util.Base64.getDecoder()    suspend fun handleAskKey(        jsonMessage: JsonObject,        onNewIdentity: suspend (String, IdentityKey) -> Boolean = { _, _ -> true },    ) = withContext(Dispatchers.IO) {        try {            DLog.i("handleAskKey: Received ASK_KEY message → $jsonMessage")            val receiver = jsonMessage.get(JsonKeys.RECEIVER)?.asString?.takeIf { it.isNotBlank() }                ?: return@withContext DLog.i("❌ Missing receiver in ASK_KEY")            val sandeshRaw = jsonMessage.get(JsonKeys.SANDESH)?.asString?.takeIf { it.isNotBlank() }                ?: return@withContext DLog.i("❌ Missing sandesh payload")            val sandeshJson = JsonParser.parseString(sandeshRaw).asJsonObject            val identityBundle = sandeshJson.getAsJsonObject(JsonKeys.IDENTITY_BUNDLE)                ?: return@withContext DLog.i("❌ Missing identityBundle in ASK_KEY")            val ecPreKey = sandeshJson.getAsJsonObject(JsonKeys.EC_PREKEY)                ?: return@withContext DLog.i("❌ Missing ecPreKey in ASK_KEY")            val kyberPreKey = sandeshJson.getAsJsonObject(JsonKeys.KYBER_PREKEY)                ?: return@withContext DLog.i("❌ Missing kyberPreKey in ASK_KEY")            val userSessionId = receiver            // 3️⃣ Decode Identity            val identityKey = IdentityKey(base64.decode(identityBundle[JsonKeys.IDENTITY_KEY].asString))            val registrationId = identityBundle[JsonKeys.REGISTRATION_ID].asInt            val signedPreKeyId = identityBundle[JsonKeys.SIGNED_PREKEY_ID].asInt            val signedPreKeyPublic =                ECPublicKey(base64.decode(identityBundle[JsonKeys.SIGNED_PREKEY_PUBLIC].asString))            val signedPreKeySignature =                base64.decode(identityBundle[JsonKeys.SIGNED_PREKEY_SIGNATURE].asString)            val ecPreKeyId = ecPreKey[JsonKeys.PREKEY_ID].asInt            val ecPreKeyPublic = ECPublicKey(base64.decode(ecPreKey[JsonKeys.PREKEY_PUBLIC].asString))            val kyberPreKeyId = kyberPreKey[JsonKeys.KYBER_PREKEY_ID].asInt            val kyberPreKeyPublic =                KEMPublicKey(base64.decode(kyberPreKey[JsonKeys.KYBER_PREKEY_PUBLIC].asString))            val kyberPreKeySignature = base64.decode(kyberPreKey[JsonKeys.KYBER_PREKEY_SIGNATURE].asString)            DLog.i("📦 Parsed ASK_KEY bundle → regId=$registrationId EC=$ecPreKeyId Kyber=$kyberPreKeyId")            // 4️⃣ Validate & Trust Identity            val address = SignalProtocolAddress(userSessionId, 1)            if (roomSignalStore.containsSession(address)) {                DLog.i("🧹 Clearing old session before ASK_KEY")                roomSignalStore.deleteSession(address)                logDebugSafe(                    level = "DEBUG",                    tag = "DELETE Session",                    message = "Clearing old session before ASK_KEY",                    msgId = createMessageID(),                    userId = userSessionId                )                delay(100.milliseconds)            }            val idStore = roomSignalStore as? IdentityKeyStore                ?: return@withContext DLog.i("❌ Missing IdentityKeyStore")            if (!idStore.isTrustedIdentity(                    address,                    identityKey,                    IdentityKeyStore.Direction.RECEIVING                )            ) {                DLog.i("⚠️ New identity for $receiver")                if (!onNewIdentity(userSessionId, identityKey)) {                    return@withContext DLog.i("🚫 User rejected new identity")                }                idStore.saveIdentity(address, identityKey)                DLog.i("✅ New identity trusted and stored")            }            // 5️⃣ Build PQXDH PreKeyBundle            val bundle = PreKeyBundle(                registrationId = registrationId,                deviceId = 1,                preKeyId = ecPreKeyId,                preKeyPublic = ecPreKeyPublic,                signedPreKeyId = signedPreKeyId,                signedPreKeyPublic = signedPreKeyPublic,                signedPreKeySignature = signedPreKeySignature,                identityKey = identityKey,                kyberPreKeyId = kyberPreKeyId,                kyberPreKeyPublic = kyberPreKeyPublic,                kyberPreKeySignature = kyberPreKeySignature            )            // 6️⃣ Establish PQXDH session            SessionBuilder(roomSignalStore, address).process(bundle)            DLog.i("✅ PQXDH session established with $receiver")            unsentSandeshDao.restoreHeldMessagesForUser(receiver)        } catch (e: Exception) {            DLog.i("❌ handleAskKey error: ${e.message}")            e.printStackTrace()        }    }    private suspend fun handleMalformedJsonDelivery(message: String, exception: Exception) {        val stackTrace = Thread.currentThread().stackTrace        // 0 = getStackTrace        // 1 = current method (handleMalformedJsonDelivery)        // 2 = direct caller (the one you want)        val caller = exception.stackTrace.firstOrNull()        DLog.i("🔥 Crash at ${caller?.className}:${caller?.lineNumber} -> ${caller?.methodName}()")        DLog.i("🔥 Problem JSON: $message")        val jsonMessage = try {            JsonParser.parseString(message).asJsonObject        } catch (e: Exception) {            DLog.i("THE BITCH AGAIN CRASHED")            JsonObject() // fallback empty object        }        jsonMessage.remove("sandesh")        DLog.i("🔥 Problem JSON: $jsonMessage")        val senderDelivered = jsonMessage.get(JsonKeys.SENDER)            ?.takeIf { it !is JsonNull }            ?.asString ?: "unknown"        val messageIdDelivered = jsonMessage.get(JsonKeys.MESSAGE_ID)            ?.takeIf { it !is JsonNull }            ?.asString ?: UUID.randomUUID().toString()        val timeStampDelivered = jsonMessage.get(JsonKeys.TIME_STAMP)            ?.takeIf { it !is JsonNull }            ?.asString ?: System.currentTimeMillis().toString()        val dataType = jsonMessage.get(JsonKeys.DATA_TYPE)            ?.takeIf { it !is JsonNull }            ?.asInt ?: DataType.INVALID_DATA.value        val storageType = jsonMessage.get(JsonKeys.STORAGE_TYPE)            ?.takeIf { it !is JsonNull }            ?.asInt ?: 0        // default 0        val confirmationJson = JSONObject().apply {            put(JsonKeys.SENT_DATA_TYPE, dataType)            put(JsonKeys.STORAGE_TYPE, storageType)            put(JsonKeys.MESSAGE_ID, messageIdDelivered)        }        sendDeliveryConfirmation(            messageIdDelivered,            senderDelivered,            confirmationJson.toString(),            DataType.MALFUNCTION_JSON,            timeStampDelivered        )        Log.e(            "Knotx",            "Error while processing malformed JSON",            exception        )  // ✅ full details with stack trace    }    fun forceUpdateNow(context: Context) {        try {            val updateIntent = Intent(Intent.ACTION_VIEW).apply {                data =                    "https://play.google.com/store/apps/details?id=${BuildConfig.APPLICATION_ID}".toUri()                flags = Intent.FLAG_ACTIVITY_NEW_TASK            }            context.startActivity(updateIntent)        } catch (e: Exception) {            e.printStackTrace()        }    }    fun hasSecureSession(roomSignalStore: RoomSignalStore, userNumber: String): Boolean {        val address = SignalProtocolAddress(userNumber, 1)        return roomSignalStore.containsSession(address)    }    // Keep this global or class-level (outside the function)//    private val deletedOnceUsers = mutableSetOf<String>()    fun isVersionOlderThan(current: String, required: String): Boolean {        val cur = current.split("-", ignoreCase = true)[0].split(".").map { it.toIntOrNull() ?: 0 }        val req = required.split(".").map { it.toIntOrNull() ?: 0 }        for (i in 0..2) {            if (cur.getOrElse(i) { 0 } < req.getOrElse(i) { 0 }) return true            if (cur.getOrElse(i) { 0 } > req.getOrElse(i) { 0 }) return false        }        return false    }    fun sendToIntent(json: String) = CoroutineScope(Dispatchers.Default).launch {        CallIntentBus.emit(json)    }    fun sendToSignal(json: String) = CoroutineScope(Dispatchers.Default).launch {        CallSignalBus.emit(json)    }    @Synchronized    fun getValidFileToken(): String? {        val currentTime = System.currentTimeMillis()        val isExpired = (currentTime - tokenTime) > TOKEN_VALIDITY_MS        DLog.i("🔍 [getValidFileToken] Thread=${Thread.currentThread().name}")        return if (!fileToken.isNullOrEmpty() && !isExpired) {            DLog.i("✅ Token valid, returning existing token.")            fileToken        } else {            DLog.i("⚠️ Token missing or expired. Clearing.")            fileToken = null            tokenTime = 0L            null        }    }    private val _otpResult = MutableSharedFlow<String>(extraBufferCapacity = 1)    val otpResult = _otpResult.asSharedFlow()    private suspend fun handleRegistrationResponse(jsonMessage: JsonObject) {        val message = jsonMessage.get(JsonKeys.SANDESH)?.asString ?: OtpResult.ERROR        DLog.i("OTP Response: $message")        if (message == OtpResult.SUCCESS) {            val profilePhoto = jsonMessage.get(JsonKeys.PROFILE_PHOTO)                ?.takeIf { !it.isJsonNull }?.asString            val userNumber = jsonMessage.get(JsonKeys.USER_NUMBER)                ?.takeIf { !it.isJsonNull }?.asString            userDataStore.edit { prefs ->                userNumber?.let {                    prefs[PrefKeys.USER_NUMBER] = it // 👈 NEW — save this FIRST, everything else depends on it                }                jsonMessage.get(JsonKeys.USER_NAME)?.takeIf { !it.isJsonNull }?.asString?.let {                    prefs[PrefKeys.USER_NAME] = it                }                jsonMessage.get(JsonKeys.USER_NAME_ID)?.takeIf { !it.isJsonNull }?.asString?.let {                    prefs[PrefKeys.USER_NAME_ID] = it                }                jsonMessage.get(JsonKeys.USERNAME_UPDATE_TIME)?.takeIf { !it.isJsonNull }?.asLong?.let {                    prefs[PrefKeys.USER_NAME_ID_UPDATE_TIME] = it                }                jsonMessage.get(JsonKeys.PROFILE_TIME)?.takeIf { !it.isJsonNull }?.asLong?.let {                    prefs[PrefKeys.PROFILE_TIME] = it                }                profilePhoto?.let {                    prefs[PrefKeys.PROFILE_IMAGE] = it                }                jsonMessage.get(JsonKeys.ABOUT)?.takeIf { !it.isJsonNull }?.asString?.let {                    prefs[PrefKeys.USER_ABOUT] = it                }            }            // 🔥 If a profile photo reference came back, fetch the actual image file            if (!profilePhoto.isNullOrBlank()) {                // use the number we JUST resolved above — don't re-read from the flow,                // since DataStore's write may not have propagated through userNumberKhud yet                val selfNumber = userNumber ?: userNumberKhud.firstOrNull()                if (!selfNumber.isNullOrBlank()) {                    DLog.i("Requesting profile pic for self after registration")                    val unsentFiles = UnsentFiles(                        messageId = createMessageID(),                        receiver = selfNumber,                        data = profilePhoto,                        dataType = FileDataType.GET_PROFILE_PIC                    )                    insertSendData(unsentFiles)                    if (!sendingFileInProgress) sendUnsentFiles()                } else {                    DLog.i("⚠ Could not fetch profile pic — no self number available yet")                }            }            firstThing()        }        _otpResult.tryEmit(message)    }    private suspend fun firstThing() {        getAllGroup()        getPrivacyFromServer()        getContactsFromServer()        getBlocklistFromServer()        sendCurrentToken()        getContributionsFromServer()        sendNextKeys()        sendNextKuberKeys()        loginDootawas()    }    private suspend fun getAllGroup() {        val jsonObject = JsonObject().apply {            addProperty(DootawasMessage.SANDESH_TYPE, GroupSandeshType.ACTION_GET_GROUPS.value)        }        val unsentSandesh = UnsentSandesh(            messId = createMessageID(),            receiver = userNumberKhud.firstOrNull().toString(),            message = jsonObject.toString(),            dataType = DataType.GROUP_ACTION        )        insertUnsentData(unsentSandesh)        sendUnsentMessages(false)    }    //todo delete this later    suspend fun resetGroupForReinstallTest(groupId: String) {        try {            // 1. Clear all local members            groupDao.deleteAllMembersInGroup(groupId)            // 2. Clear pending key packages            groupDao.deletePrivateKeyByGroupId(groupId)            // 3. Clear local epoch            groupDao.deleteEpochByGroupId(groupId)            // 4. Clear local private keys            groupDao.deletePrivateKeyByGroupId(groupId)            DLog.i("Temporary reinstall test cleanup completed: group=$groupId")            // 5. Request members again as a reinstalled user            getAllGroupMembers(                groupId = groupId,                isReinstalled = true            )        } catch (e: Exception) {            DLog.e(                "Temporary reinstall test failed: group=$groupId error=${e.message}",                e            )        }    }    private suspend fun getAllGroupMembers(groupId: String, isReinstalled: Boolean) {        val jsonObject = JsonObject().apply {            addProperty(                DootawasMessage.SANDESH_TYPE,                if (isReinstalled) GroupSandeshType.ACTION_GET_ALL_MEMBERS_REINSTALLED.value                else GroupSandeshType.ACTION_GET_ALL_MEMBERS_ADDED.value            )            addProperty(JsonKeys.GROUP_ID, groupId)        }        val unsentSandesh = UnsentSandesh(            messId = createMessageID(),            receiver = userNumberKhud.firstOrNull().toString(),            message = jsonObject.toString(),            dataType = DataType.GROUP_ACTION        )        insertUnsentData(unsentSandesh)    }    private suspend fun getGroupMembers(jsonObject: JsonObject) {        jsonObject.addProperty(DootawasMessage.SANDESH_TYPE, GroupSandeshType.ACTION_GET_MEMBERS.value)        val unsentSandesh = UnsentSandesh(            messId = createMessageID(),            receiver = userNumberKhud.firstOrNull().toString(),            message = jsonObject.toString(),            dataType = DataType.GROUP_ACTION        )        insertUnsentData(unsentSandesh)    }    private suspend fun getPrivacyFromServer() {        val unsentSandesh = UnsentSandesh(            messId = createMessageID(),            receiver = userNumberKhud.firstOrNull().toString(),            message = "getPrivacySetting",            dataType = DataType.GET_PRIVACY_SETTINGS        )        insertUnsentData(unsentSandesh)        sendUnsentMessages(false)    }    private suspend fun getContactsFromServer() {        val unsentSandesh = UnsentSandesh(            messId = createMessageID(),            receiver = userNumberKhud.firstOrNull().toString(),            message = "getServerContacts",            dataType = DataType.GET_SERVER_CONTACTS        )        insertUnsentData(unsentSandesh)        sendUnsentMessages(false)    }    private suspend fun getBlocklistFromServer() {        val unsentSandesh = UnsentSandesh(            messId = createMessageID(),            receiver = userNumberKhud.firstOrNull().toString(),            message = "getServerBlocklist",            dataType = DataType.GET_SERVER_BLOCKLIST        )        insertUnsentData(unsentSandesh)        sendUnsentMessages(false)    }    fun getContributionsFromServer() {        coroutineScope.launch {            val unsentSandesh = UnsentSandesh(                messId = createMessageID(),                receiver = userNumberKhud.firstOrNull().toString(),                message = "getMyContribution",                dataType = DataType.GET_MY_CONTRIBUTIONS            )            insertUnsentData(unsentSandesh)            sendUnsentMessages(false)        }    }    fun fetchUserSettingsFromServer(userNumber: String) {        coroutineScope.launch {            val unsentSandesh = UnsentSandesh(                messId = createMessageID(),                receiver = userNumber,                message = "fetchUserSettings",                dataType = DataType.FETCH_USER_SETTINGS            )            insertUnsentData(unsentSandesh)            sendUnsentMessages(false)        }    }    private suspend fun handleGroupAction(json: JsonObject) {        val sentType = json.get(JsonKeys.SENT_DATA_TYPE).asInt        when (sentType) {            GroupSandeshType.ACTION_GET_GROUPS.value ->                handleGetGroups(json)            GroupSandeshType.ACTION_GET_GROUP.value ->                handleGetGroupDetails(json)            GroupSandeshType.ACTION_GET_ALL_MEMBERS_ADDED.value ->                handleGetAllGroupMembers(json)            GroupSandeshType.ACTION_GET_ALL_MEMBERS_REINSTALLED.value ->                handleGetAllGroupMembersReInstalled(json)            GroupSandeshType.ACTION_GET_MEMBERS.value ->                handleGetGroupMembers(json)            GroupSandeshType.ACTION_ADD_MEMBERS.value ->                handleAddMembers(json)            GroupSandeshType.ACTION_REMOVE_MEMBER.value -> {                val groupId = json.get(JsonKeys.GROUP_ID)?.asString                    ?: throw IllegalArgumentException("Missing groupId")                val removedUserNumber = json.get(JsonKeys.USER_NUMBER)?.asString                    ?: throw IllegalArgumentException("Missing removed userNumber")                // Remove first so the user cannot receive the new epoch.                groupDao.deleteMembersFromGroup(                    groupId = groupId,                    userNumbers = listOf(removedUserNumber)                )                // Add universal "member removed" message.                val data = JsonObject().apply {                    val arr = JsonArray()                    arr.add(removedUserNumber)                    add(JsonKeys.MEMBERS, arr)                }                insertUniversalGroupMessage(                    UniversalType.MEMBER_REMOVED,                    data,                    groupId                )                // Now rotate the epoch using the updated roster.                checkAndRotateGroupEpoch(groupId)            }        }    }    private suspend fun handleGetAllGroupMembers(json: JsonObject) {            val membersJson = json.getAsJsonArray(JsonKeys.MEMBERS)            val myNumber = userNumberKhud.firstOrNull()            val members = mutableListOf<GroupMemberEntity>()            var groupId: String? = null            membersJson.forEach { element ->                val obj = element.asJsonObject                groupId = obj.get(JsonKeys.GROUP_ID).asString                val userNumber = obj.get(JsonKeys.USER_NUMBER).asString                val colors = generateUserColors()                val isLocalMember = userNumber == myNumber                val member = GroupMemberEntity(                    groupId = groupId,                    userNumber = userNumber,                    contactName = getNameByNumberFromContactOnly(userNumber),                    onlineName = null,                    userDarkColor = colors.darkModeColor,                    userLightColor = colors.lightModeColor,                    joinedAt = obj.get(JsonKeys.GROUP_JOINED_AT)?.asLong ?: 0L,                    isSwami = obj.get(JsonKeys.IS_SWAMI).asBoolean,                    canMessage = obj.get(JsonKeys.CAN_MESSAGE).asBoolean,                    canUpdateProfile = obj.get(JsonKeys.CAN_UPDATE_PROFILE).asBoolean,                    canModifyMembers = obj.get(JsonKeys.CAN_MODIFY_MEMBERS).asBoolean,                    canStartCall = obj.get(JsonKeys.CAN_START_CALL).asBoolean,                    profileTime = 0L,                    profileUrl = "",                    publicKey = "",                    memberInstanceId = if (isLocalMember) UUID.randomUUID().toString() else "",                    deviceId = if (isLocalMember) "1" else "",                    keyGeneration = if (isLocalMember) 1L else 0L,                    isCryptoActive = isLocalMember                )                members.add(member)            }                groupDao.insertMembers(members)                groupId?.let { id ->                    processPendingGroupKeyPackages(id)                }    }    private suspend fun handleGetAllGroupMembersReInstalled(json: JsonObject) {            val membersJson = json.getAsJsonArray(JsonKeys.MEMBERS)            val myNumber = userNumberKhud.firstOrNull()            val members = mutableListOf<GroupMemberEntity>()            var groupId: String? = null            membersJson.forEach { element ->                val obj = element.asJsonObject                groupId = obj.get(JsonKeys.GROUP_ID).asString                val userNumber = obj.get(JsonKeys.USER_NUMBER).asString                val colors = generateUserColors()                val isLocalMember = userNumber == myNumber                val member = GroupMemberEntity(                    groupId = groupId,                    userNumber = userNumber,                    contactName = getNameByNumberFromContactOnly(userNumber),                    onlineName = null,                    userDarkColor = colors.darkModeColor,                    userLightColor = colors.lightModeColor,                    joinedAt = obj.get(JsonKeys.GROUP_JOINED_AT)?.asLong ?: 0L,                    isSwami = obj.get(JsonKeys.IS_SWAMI).asBoolean,                    canMessage = obj.get(JsonKeys.CAN_MESSAGE).asBoolean,                    canUpdateProfile = obj.get(JsonKeys.CAN_UPDATE_PROFILE).asBoolean,                    canModifyMembers = obj.get(JsonKeys.CAN_MODIFY_MEMBERS).asBoolean,                    canStartCall = obj.get(JsonKeys.CAN_START_CALL).asBoolean,                    profileTime = 0L,                    profileUrl = "",                    publicKey = "",                    memberInstanceId = if (isLocalMember) UUID.randomUUID().toString() else "",                    deviceId = if (isLocalMember) "1" else "",                    keyGeneration = if (isLocalMember) 1L else 0L,                    isCryptoActive = true //todo change that thing to true                )                members.add(member)            }        groupDao.insertMembers(members)        groupId?.let { id ->            val myNumber = userNumberKhud.firstOrNull()                ?: return@let            val myMember = groupDao.getAGroupMemberByNumber(                groupId = id,                userNumber = myNumber            ) ?: throw IllegalStateException(                "Local member not found after reinstall: group=$id"            )            if (myMember.isSwami) {                setupReinstalledOwnerGroup(id)            } else {                setupReinstalledMemberGroup(id)            }        }    }    private suspend fun setupReinstalledMemberGroup(groupId: String) {        val myNumber = userNumberKhud.firstOrNull()            ?: throw IllegalStateException("Local user number missing.")        val myMember = groupDao.getAGroupMemberByNumber(            groupId = groupId,            userNumber = myNumber        ) ?: throw IllegalStateException(            "Local member not found after reinstall: group=$groupId"        )        if (myMember.isSwami) {            DLog.i(                "Skipping member reinstall setup: local user is owner group=$groupId"            )            return        }        val admins = groupDao.getAllMembersInGroup(groupId)            .filter {                it.isSwami || it.canModifyMembers            }            .filter {                it.userNumber != myNumber            }        if (admins.isEmpty()) {            DLog.i(                "No admins available for reinstall setup: group=$groupId"            )            return        }        // Unique value for this reinstall/setup attempt.        val setupId = UUID.randomUUID().toString()        admins.forEach { admin ->            val setupJson = JsonObject().apply {                addProperty(                    JsonKeys.GROUP_ID,                    groupId                )                addProperty(                    DootawasMessage.SANDESH_TYPE,                    SandeshType.GROUP_KEY_SETUP.value                )                addProperty(                    DootawasMessage.SETUP_ID,                    setupId                )                addProperty(                    JsonKeys.USER_NUMBER,                    myNumber                )                addProperty(                    JsonKeys.TIME_STAMP,                    System.currentTimeMillis()                )            }            insertUnsentData(                UnsentSandesh(                    messId = UUID.randomUUID().toString(),                    receiver = admin.userNumber,                    message = setupJson.toString(),                    dataType = DataType.MESSAGE                )            )            DLog.i(                "Queued GROUP_KEY_SETUP: " +                        "group=$groupId " +                        "from=$myNumber " +                        "to=${admin.userNumber} " +                        "setupId=$setupId"            )        }        sendUnsentMessages(false)        DLog.i(            "Reinstalled member setup requests sent to " +                    "${admins.size} admin(s): group=$groupId setupId=$setupId"        )    }    private suspend fun setupReinstalledOwnerGroup(groupId: String) {        val myNumber = userNumberKhud.firstOrNull()            ?: throw IllegalStateException("Local user number missing.")        val myMember = groupDao.getAGroupMemberByNumber(            groupId = groupId,            userNumber = myNumber        ) ?: throw IllegalStateException(            "Local member not found after reinstall: group=$groupId"        )        if (!myMember.isSwami) {            DLog.i(                "Skipping owner reinstall setup: local user is not owner group=$groupId"            )            return        }        val allMembers = groupDao.getAllMembersInGroup(groupId)        if (allMembers.isEmpty()) {            DLog.i(                "Skipping owner reinstall setup: no members found group=$groupId"            )            return        }        if (myMember.memberInstanceId.isBlank()) {            throw IllegalStateException(                "Local memberInstanceId missing: group=$groupId"            )        }        val localKeys = groupCryptoManager.getOrCreateLocalGroupKeys(            groupId = groupId,            memberInstanceId = myMember.memberInstanceId        )        groupDao.updateGroupCryptoState(            groupId = groupId,            currentEpoch = 0L,            currentCommitHash = ByteArray(0),            rosterVersion = 0L,            protocolVersion = 1        )        groupCryptoManager.createInitialEpoch(groupId)        DLog.i(            "Initial group epoch created for reinstalled owner: group=$groupId"        )        // One setupId identifies this entire reinstall synchronization.        val setupId = UUID.randomUUID().toString()        allMembers.forEach { member ->            if (member.userNumber == myNumber) return@forEach            sendGroupBootstrap(                groupId = groupId,                userNumber = member.userNumber            )            val keyRequestJson = JsonObject().apply {                addProperty(                    JsonKeys.GROUP_ID,                    groupId                )                addProperty(                    DootawasMessage.SANDESH_TYPE,                    SandeshType.GROUP_KEY_REQUEST.value                )                addProperty(                    DootawasMessage.SETUP_ID,                    setupId                )                addProperty(                    JsonKeys.USER_NUMBER,                    myNumber                )                addProperty(                    DootawasMessage.GROUP_MEMBER_INSTANCE_ID,                    myMember.memberInstanceId                )                addProperty(                    DootawasMessage.GROUP_DEVICE_ID,                    myMember.deviceId                )                addProperty(                    DootawasMessage.GROUP_KEY_GENERATION,                    myMember.keyGeneration                )                addProperty(                    DootawasMessage.GROUP_X25519_PUBLIC_KEY,                    Base64.encodeToString(                        localKeys.x25519PublicKey.encoded,                        Base64.NO_WRAP                    )                )                addProperty(                    DootawasMessage.GROUP_ML_KEM_PUBLIC_KEY,                    Base64.encodeToString(                        localKeys.mlKemPublicKey.encoded,                        Base64.NO_WRAP                    )                )                addProperty(                    DootawasMessage.GROUP_ED25519_PUBLIC_KEY,                    Base64.encodeToString(                        localKeys.ed25519PublicKey.encoded,                        Base64.NO_WRAP                    )                )            }            insertUnsentData(                UnsentSandesh(                    messId = UUID.randomUUID().toString(),                    receiver = member.userNumber,                    message = keyRequestJson.toString(),                    dataType = DataType.MESSAGE                )            )            DLog.i(                "Queued reinstalled owner GROUP_KEY_REQUEST: " +                        "group=$groupId " +                        "receiver=${member.userNumber} " +                        "setupId=$setupId"            )        }        sendUnsentMessages(false)        DLog.i(            "Reinstalled owner setup completed: " +                    "group=$groupId " +                    "members=${allMembers.size - 1} " +                    "setupId=$setupId"        )    }    private fun handleGetGroupMembers(json: JsonObject) {        coroutineScope.launch {            val membersJson = json.getAsJsonArray(JsonKeys.MEMBERS)            val groupId = json                .asJsonObject                ?.get(JsonKeys.GROUP_ID)                ?.asString ?: return@launch            coroutineScope.launch(Dispatchers.IO) {                try {                    val userNumberKhud = userNumberKhud.firstOrNull()                    // ✅ 1. Local DB                    val localMembers = groupDao.getAllMembersInGroup(groupId)                    val localMap = localMembers.associateBy { it.userNumber }                    val toInsert = mutableListOf<GroupMemberEntity>()                    val toUpdate = mutableListOf<GroupMemberEntity>()                    val toDelete = mutableListOf<String>()                    // 🔥 Track changes (IMPORTANT)                    val addedMembers = mutableListOf<String>()                    val removedMembers = mutableListOf<String>()                    var iWasAdded = false                    var iWasRemoved = false                    // ✅ 2. Process server                    membersJson.forEach { element ->                        val obj = element.asJsonObject                        val userNumber = obj.get(JsonKeys.USER_NUMBER).asString                        val isExist = obj.get("isExist").asBoolean                        val local = localMap[userNumber]                        if (!isExist) {                            if (local != null) {                                toDelete.add(userNumber)                                if (userNumber == userNumberKhud) {                                    iWasRemoved = true                                } else {                                    removedMembers.add(userNumber)                                }                            }                            return@forEach                        }                        // ✅ Exists → build member                        val colors = generateUserColors()                        val member = GroupMemberEntity(                            groupId = groupId,                            userNumber = userNumber,                            contactName = getNameByNumberFromContactOnly(userNumber),                            onlineName = null,                            userDarkColor = colors.darkModeColor,                            userLightColor = colors.lightModeColor,                            joinedAt = obj.get(JsonKeys.GROUP_JOINED_AT)?.asLong ?: 0L,                            isSwami = obj.get(JsonKeys.IS_SWAMI).asBoolean,                            canMessage = obj.get(JsonKeys.CAN_MESSAGE).asBoolean,                            canUpdateProfile = obj.get(JsonKeys.CAN_UPDATE_PROFILE).asBoolean,                            canModifyMembers = obj.get(JsonKeys.CAN_MODIFY_MEMBERS).asBoolean,                            canStartCall = obj.get(JsonKeys.CAN_START_CALL).asBoolean,                            profileTime = 0L,                            profileUrl = "",                            publicKey = ""                        )                        if (local == null) {                            toInsert.add(member)                            if (userNumber == userNumberKhud) {                                iWasAdded = true                            } else {                                addedMembers.add(userNumber)                            }                        } else {                            toUpdate.add(member)                        }                    }                    // ✅ 3. Apply DB changes                    if (toInsert.isNotEmpty()) groupDao.insertMembers(toInsert)                    if (toUpdate.isNotEmpty()) groupDao.insertMembers(toUpdate)                    if (toDelete.isNotEmpty()) groupDao.deleteMembersFromGroup(groupId, toDelete)                    // 🔥 5. INSERT UNIVERSAL MESSAGES (FINAL LOGIC)                    // 👤 YOU ADDED                    if (iWasAdded) {                        insertUniversalGroupMessage(                            UniversalType.YOU_ADDED,                            JsonObject(),                            groupId                        )                    }                    // 🚫 YOU REMOVED                    if (iWasRemoved) {                        insertUniversalGroupMessage(                            UniversalType.YOU_REMOVED,                            JsonObject(),                            groupId                        )                    }                    // 👥 MEMBERS ADDED (batched)                    if (addedMembers.isNotEmpty()) {                        val data = JsonObject().apply {                            val arr = JsonArray()                            addedMembers.forEach { arr.add(it) }                            add(JsonKeys.MEMBERS, arr)                        }                        insertUniversalGroupMessage(                            UniversalType.MEMBER_ADDED,                            data,                            groupId                        )                    }                    // ❌ MEMBERS REMOVED (batched)                    if (removedMembers.isNotEmpty()) {                        val data = JsonObject().apply {                            val arr = JsonArray()                            removedMembers.forEach { arr.add(it) }                            add(JsonKeys.MEMBERS, arr)                        }                        insertUniversalGroupMessage(                            UniversalType.MEMBER_REMOVED,                            data,                            groupId                        )                    }                } catch (e: Exception) {                }            }        }    }    fun insertUniversalMessage(        type: String,        data: JsonObject,        userNumber: String,        isSelf: Boolean = false    ) {        coroutineScope.launch {            val currentTime = Instant.now().toEpochMilli()            val jsonObject = JsonObject().apply {                addProperty(DootawasMessage.UNIVERSAL_TYPE, type)                add("data", data)                addProperty("time", currentTime)            }            val newSandesh = Sandesh(                sandeshId = createMessageID(),                userNumber = userNumber,                samagri = jsonObject.toString(),                isSelf = isSelf,                time = currentTime,                sandeshType = SandeshType.UNIVERSAL_MESSAGE.value,                sandeshStithi = SandeshStithi.LIKHIT            )            sandeshDao.insertMessage(newSandesh)        }    }    fun insertUniversalGroupMessage(        type: String,        data: JsonObject,        groupId: String    ) {        coroutineScope.launch {            val currentTime = Instant.now().toEpochMilli()            val jsonObject = JsonObject().apply {                addProperty(DootawasMessage.UNIVERSAL_TYPE, type)                add("data", data)                addProperty("time", currentTime)            }            val newSandesh = GroupSandesh(                sandeshId = createMessageID(),                userNumber = "",                samagri = jsonObject.toString(),                isSelf = false,                time = currentTime,                sandeshType = SandeshType.UNIVERSAL_MESSAGE.value,                sandeshStithi = SandeshStithi.LIKHIT,                groupId = groupId            )            groupDao.insertMessage(newSandesh)        }    }    private fun handleAddMembers(jsonMessage: JsonObject) {        coroutineScope.launch {            try {                val membersObj = jsonMessage.getAsJsonObject(JsonKeys.MEMBERS)                    ?: throw IllegalArgumentException("Missing members object.")                if (membersObj.has("error")) {                    DLog.e("AddMembers failed: ${membersObj.get("error").asString}")                    return@launch                }                val sandeshArray = membersObj.getAsJsonArray(JsonKeys.SANDESH)                    ?: throw IllegalArgumentException("Missing members sandesh.")                val groupId = jsonMessage.get(JsonKeys.GROUP_ID)?.asString                    ?: throw IllegalArgumentException("Missing groupId.")                val myNumber = userNumberKhud.firstOrNull()                    ?: throw IllegalStateException("Local user number missing.")                val deniedMembers = mutableListOf<String>()                val approvedMembers = mutableListOf<String>()                sandeshArray.forEach { element ->                    val memberObj = element.asJsonObject                    val userNumber = memberObj.get(JsonKeys.USER_NUMBER)?.asString                        ?: return@forEach                    val added = memberObj.get(JsonKeys.DATA_BOOLEAN)?.asBoolean                        ?: return@forEach                    if (added) {                        approvedMembers.add(userNumber)                        DLog.i("Member confirmed: $userNumber")                    } else {                        deniedMembers.add(userNumber)                        DLog.i("Member denied: $userNumber")                    }                }                // Remove members that the server rejected.                if (deniedMembers.isNotEmpty()) {                    deleteMemberFromGroup(                        deniedMembers,                        groupId                    )                }                if (approvedMembers.isEmpty()) {                    DLog.i("No members approved for group=$groupId")                    return@launch                }                val group = groupDao.getGroupById(groupId)                    ?: throw IllegalStateException("Group not found: $groupId")                val myMember = groupDao.getAGroupMemberByNumber(                    groupId = groupId,                    userNumber = myNumber                ) ?: throw IllegalStateException(                    "Local member not found in group=$groupId"                )                // Only Swami or a member with modify permission can distribute                // the group key package after member changes.                if (!myMember.isSwami && !myMember.canModifyMembers) {                    DLog.e(                        "Not authorized to distribute group keys: " +                                "group=$groupId"                    )                    return@launch                }                if (myMember.memberInstanceId.isBlank()) {                    throw IllegalStateException(                        "Local memberInstanceId missing: group=$groupId"                    )                }                // Make sure our local public/private key package exists.                val localKeys = groupCryptoManager.getOrCreateLocalGroupKeys(                    groupId = groupId,                    memberInstanceId = myMember.memberInstanceId                )                // Send OUR public key package to every newly approved member.                val setupId = UUID.randomUUID().toString()                approvedMembers.forEach { approvedNumber ->                    if (approvedNumber == myNumber) return@forEach                    sendGroupBootstrap(                        groupId = groupId,                        userNumber = approvedNumber                    )                    val keyRequestJson = JsonObject().apply {                        addProperty(                            JsonKeys.GROUP_ID,                            groupId                        )                        addProperty(                            DootawasMessage.SANDESH_TYPE,                            SandeshType.GROUP_KEY_REQUEST.value                        )                        addProperty(                            DootawasMessage.SETUP_ID,                            setupId                        )                        addProperty(                            JsonKeys.USER_NUMBER,                            myNumber                        )                        addProperty(                            DootawasMessage.GROUP_MEMBER_INSTANCE_ID,                            myMember.memberInstanceId                        )                        addProperty(                            DootawasMessage.GROUP_DEVICE_ID,                            myMember.deviceId                        )                        addProperty(                            DootawasMessage.GROUP_KEY_GENERATION,                            myMember.keyGeneration                        )                        addProperty(                            DootawasMessage.GROUP_X25519_PUBLIC_KEY,                            Base64.encodeToString(                                localKeys.x25519PublicKey.encoded,                                Base64.NO_WRAP                            )                        )                        addProperty(                            DootawasMessage.GROUP_ML_KEM_PUBLIC_KEY,                            Base64.encodeToString(                                localKeys.mlKemPublicKey.encoded,                                Base64.NO_WRAP                            )                        )                        addProperty(                            DootawasMessage.GROUP_ED25519_PUBLIC_KEY,                            Base64.encodeToString(                                localKeys.ed25519PublicKey.encoded,                                Base64.NO_WRAP                            )                        )                    }                    insertUnsentData(                        UnsentSandesh(                            messId = UUID.randomUUID().toString(),                            receiver = approvedNumber,                            message = keyRequestJson.toString(),                            dataType = DataType.MESSAGE                        )                    )                    DLog.i(                        "Queued GROUP_KEY_REQUEST: " +                                "group=$groupId " +                                "receiver=$approvedNumber " +                                "setupId=$setupId"                    )                }                // Send all key packages together.                sendUnsentMessages(false)                // Save universal system message.                val data = JsonObject().apply {                    val arr = JsonArray()                    approvedMembers.forEach { member ->                        arr.add(member)                    }                    add(JsonKeys.MEMBERS, arr)                }                insertUniversalGroupMessage(                    UniversalType.MEMBER_ADDED,                    data,                    groupId                )                DLog.i(                    "Member addition processed successfully: " +                            "group=$groupId approved=${approvedMembers.size}"                )            } catch (e: Exception) {                DLog.e(                    "Failed to handle AddMembers: ${e.message}",                    e                )            }        }    }    suspend fun whatUserNameInGroup(groupId: String): String? {        val isRevealed = groupDao.getRevealSender(groupId) ?: false        return if (isRevealed) {            userNumberKhud.firstOrNull()        } else {            userNameIdKhud.firstOrNull()        }    }    suspend fun sendGroupBootstrap(groupId: String, userNumber: String){                try {                    val group = groupDao.getGroupById(groupId)                        ?: throw IllegalStateException("Group not found: $groupId")                    val epochSecret = groupCryptoManager.getEpochSecret(                        groupId = groupId,                        epoch = group.currentEpoch                    )                    val groupJson = JsonObject().apply {                        addProperty(JsonKeys.GROUP_ID, group.groupId)                        addProperty(JsonKeys.GROUP_NAME, group.groupName)                        addProperty(JsonKeys.GROUP_DEC, group.groupDescription ?: "")                        addProperty(JsonKeys.GROUP_CREATOR, group.createdBy)                        addProperty(JsonKeys.GROUP_CREATED_AT, group.createdAt)                        addProperty(JsonKeys.GROUP_ADDED_BY, whatUserNameInGroup(groupId))                        addProperty(DootawasMessage.SANDESH_TYPE, SandeshType.CREATE_GROUP.value)                        addProperty(                            DootawasMessage.GROUP_CURRENT_EPOCH,                            group.currentEpoch                        )                        addProperty(                            DootawasMessage.GROUP_BOOTSTRAP_EPOCH_SECRET,                            Base64.encodeToString(epochSecret, Base64.NO_WRAP)                        )                        addProperty(                            DootawasMessage.GROUP_ROSTER_VERSION,                            group.rosterVersion                        )                        group.currentCommitHash?.let {                            addProperty(                                DootawasMessage.GROUP_CURRENT_COMMIT_HASH,                                Base64.encodeToString(it, Base64.NO_WRAP)                            )                        }                    }                    val unsentSandesh = UnsentSandesh(                        messId = UUID.randomUUID().toString(),                        receiver = userNumber,                        message = groupJson.toString(),                        dataType = DataType.MESSAGE                    )                    insertUnsentData(unsentSandesh)                    DLog.i(                        "Queued group bootstrap: " +                                "group=$groupId receiver=$userNumber"                    )                    sendUnsentMessages(false)                } catch (e: Exception) {                    DLog.e(                        "Failed to send group bootstrap: group=$groupId receiver=$userNumber",                        e                    )                }        }    private suspend fun sendEpochCommitToGroupMembers(        groupId: String,        commit: EpochCommit    ) {        try {            val myNumber = userNumberKhud.firstOrNull()                ?: throw IllegalStateException(                    "Local user number missing."                )            val members = groupDao.getAllMembersInGroup(groupId)            val activeMembers = members.filter {                it.isCryptoActive &&                        it.userNumber != myNumber            }            if (activeMembers.isEmpty()) {                DLog.i(                    "No other crypto-active members to send EpochCommit: " +                            "group=$groupId"                )                return            }            // Same signed path-hash list is sent to every recipient.            val pathHashesJson = JsonArray().apply {                commit.pathHashes                    .sortedBy { it.recipientLeafId }                    .forEach { pathHash ->                        add(                            JsonObject().apply {                                addProperty(                                    DootawasMessage.GROUP_RECIPIENT_LEAF_ID,                                    pathHash.recipientLeafId                                )                                addProperty(                                    DootawasMessage.GROUP_PATH_HASH,                                    Base64.encodeToString(                                        pathHash.pathHash,                                        Base64.NO_WRAP                                    )                                )                            }                        )                    }            }            activeMembers.forEach { member ->                val recipientLeafId = member.memberInstanceId                if (recipientLeafId.isBlank()) {                    DLog.e(                        "Skipping EpochCommit for member=${member.userNumber}: " +                                "memberInstanceId missing."                    )                    return@forEach                }                val recipientPath = commit.encryptedPaths.find {                    it.recipientLeafId == recipientLeafId                }                if (recipientPath == null) {                    DLog.e(                        "No encrypted path found for member=${member.userNumber} " +                                "group=$groupId"                    )                    return@forEach                }                // This member receives only its own actual encrypted path.                val pathJson = JsonObject().apply {                    addProperty(                        DootawasMessage.GROUP_RECIPIENT_LEAF_ID,                        recipientPath.recipientLeafId                    )                    addProperty(                        DootawasMessage.GROUP_EPHEMERAL_X25519_PUBLIC,                        Base64.encodeToString(                            recipientPath.ephemeralX25519Public,                            Base64.NO_WRAP                        )                    )                    addProperty(                        DootawasMessage.GROUP_ML_KEM_CIPHERTEXT,                        Base64.encodeToString(                            recipientPath.mlKemCiphertext,                            Base64.NO_WRAP                        )                    )                    addProperty(                        DootawasMessage.GROUP_ENCRYPTED_PATH_SEED,                        Base64.encodeToString(                            recipientPath.encryptedPathSeed,                            Base64.NO_WRAP                        )                    )                    addProperty(                        DootawasMessage.GROUP_PATH_NONCE,                        Base64.encodeToString(                            recipientPath.nonce,                            Base64.NO_WRAP                        )                    )                }                val commitJson = JsonObject().apply {                    addProperty(                        DootawasMessage.SANDESH_TYPE,                        SandeshType.EPOCH_COMMIT.value                    )                    addProperty(                        JsonKeys.GROUP_ID,                        commit.groupId                    )                    addProperty(                        DootawasMessage.GROUP_CRYPTO_PROTOCOL_VERSION,                        commit.protocolVersion                    )                    addProperty(                        DootawasMessage.GROUP_PARENT_EPOCH,                        commit.parentEpoch                    )                    addProperty(                        DootawasMessage.GROUP_NEW_EPOCH,                        commit.newEpoch                    )                    addProperty(                        DootawasMessage.GROUP_ROSTER_VERSION,                        commit.rosterVersion                    )                    addProperty(                        DootawasMessage.GROUP_COMMIT_ID,                        commit.commitId                    )                    if (commit.parentCommitHash != null) {                        addProperty(                            DootawasMessage.GROUP_PARENT_COMMIT_HASH,                            Base64.encodeToString(                                commit.parentCommitHash,                                Base64.NO_WRAP                            )                        )                    }                    addProperty(                        DootawasMessage.GROUP_COMMITTER_MEMBER_ID,                        commit.committerMemberId                    )                    addProperty(                        DootawasMessage.GROUP_COMMITTER_DEVICE_ID,                        commit.committerDeviceId                    )                    // All signed path hashes.                    add(                        DootawasMessage.GROUP_PATH_HASHES,                        pathHashesJson                    )                    // Only this receiver's actual encrypted path.                    add(                        DootawasMessage.GROUP_ENCRYPTED_PATH,                        pathJson                    )                    addProperty(                        DootawasMessage.GROUP_COMMIT_SIGNATURE,                        Base64.encodeToString(                            commit.signature,                            Base64.NO_WRAP                        )                    )                }                val unsentSandesh = UnsentSandesh(                    messId = UUID.randomUUID().toString(),                    receiver = member.userNumber,                    message = commitJson.toString(),                    dataType = DataType.MESSAGE                )                insertUnsentData(unsentSandesh)                DLog.i(                    "Queued EpochCommit: " +                            "group=$groupId " +                            "epoch=${commit.newEpoch} " +                            "receiver=${member.userNumber}"                )            }            sendUnsentMessages(false)        } catch (e: Exception) {            DLog.e(                "Failed to send EpochCommit for group=$groupId",                e            )            throw e        }    }    private fun handleEpochCommit(jsonMessage: JsonObject) {        coroutineScope.launch {            try {                // =========================================================                // 1. READ REQUIRED COMMIT FIELDS                // =========================================================                val groupId = jsonMessage.get(JsonKeys.GROUP_ID)?.asString                    ?: throw IllegalArgumentException("Missing groupId.")                val protocolVersion = jsonMessage                    .get(DootawasMessage.GROUP_CRYPTO_PROTOCOL_VERSION)                    ?.asInt                    ?: throw IllegalArgumentException(                        "Missing group crypto protocol version."                    )                val parentEpoch = jsonMessage                    .get(DootawasMessage.GROUP_PARENT_EPOCH)                    ?.asLong                    ?: throw IllegalArgumentException("Missing parent epoch.")                val newEpoch = jsonMessage                    .get(DootawasMessage.GROUP_NEW_EPOCH)                    ?.asLong                    ?: throw IllegalArgumentException("Missing new epoch.")                val rosterVersion = jsonMessage                    .get(DootawasMessage.GROUP_ROSTER_VERSION)                    ?.asLong                    ?: throw IllegalArgumentException(                        "Missing roster version."                    )                val commitId = jsonMessage                    .get(DootawasMessage.GROUP_COMMIT_ID)                    ?.asString                    ?.takeIf { it.isNotBlank() }                    ?: throw IllegalArgumentException("Missing commit ID.")                val committerMemberId = jsonMessage                    .get(DootawasMessage.GROUP_COMMITTER_MEMBER_ID)                    ?.asString                    ?.takeIf { it.isNotBlank() }                    ?: throw IllegalArgumentException(                        "Missing committer member ID."                    )                val committerDeviceId = jsonMessage                    .get(DootawasMessage.GROUP_COMMITTER_DEVICE_ID)                    ?.asString                    ?.takeIf { it.isNotBlank() }                    ?: throw IllegalArgumentException(                        "Missing committer device ID."                    )                // =========================================================                // 2. OPTIONAL PARENT COMMIT HASH                // =========================================================                val parentCommitHashString = jsonMessage                    .get(DootawasMessage.GROUP_PARENT_COMMIT_HASH)                    ?.asString                val parentCommitHash =                    if (parentCommitHashString.isNullOrBlank()) {                        null                    } else {                        Base64.decode(                            parentCommitHashString,                            Base64.NO_WRAP                        )                    }                // =========================================================                // 3. READ ALL SIGNED PATH HASHES                // =========================================================                val pathHashesJson = jsonMessage.getAsJsonArray(                    DootawasMessage.GROUP_PATH_HASHES                ) ?: throw IllegalArgumentException(                    "Missing group path hashes."                )                if (pathHashesJson.size() == 0) {                    throw SecurityException(                        "EpochCommit contains no path hashes."                    )                }                val pathHashes = pathHashesJson.map { element ->                    val pathHashJson = element.asJsonObject                    val leafId = pathHashJson                        .get(DootawasMessage.GROUP_RECIPIENT_LEAF_ID)                        ?.asString                        ?.takeIf { it.isNotBlank() }                        ?: throw IllegalArgumentException(                            "Path hash is missing recipient leaf ID."                        )                    val hashString = pathHashJson                        .get(DootawasMessage.GROUP_PATH_HASH)                        ?.asString                        ?.takeIf { it.isNotBlank() }                        ?: throw IllegalArgumentException(                            "Path hash is missing hash value."                        )                    EpochPathHash(                        recipientLeafId = leafId,                        pathHash = Base64.decode(                            hashString,                            Base64.NO_WRAP                        )                    )                }.sortedBy {                    it.recipientLeafId                }                // Prevent duplicate leaf IDs.                if (pathHashes.map { it.recipientLeafId }.toSet().size != pathHashes.size) {                    throw SecurityException(                        "EpochCommit contains duplicate path hashes."                    )                }                // =========================================================                // 4. READ THIS RECEIVER'S SINGLE ENCRYPTED PATH                // =========================================================                val pathJson = jsonMessage                    .getAsJsonObject(                        DootawasMessage.GROUP_ENCRYPTED_PATH                    ) ?: throw IllegalArgumentException(                    "Missing encrypted recipient path."                )                val recipientLeafId = pathJson                    .get(DootawasMessage.GROUP_RECIPIENT_LEAF_ID)                    ?.asString                    ?.takeIf { it.isNotBlank() }                    ?: throw IllegalArgumentException(                        "Missing recipient leaf ID."                    )                val ephemeralX25519Public = Base64.decode(                    pathJson                        .get(                            DootawasMessage.GROUP_EPHEMERAL_X25519_PUBLIC                        )                        ?.asString                        ?: throw IllegalArgumentException(                            "Missing ephemeral X25519 public key."                        ),                    Base64.NO_WRAP                )                val mlKemCiphertext = Base64.decode(                    pathJson                        .get(                            DootawasMessage.GROUP_ML_KEM_CIPHERTEXT                        )                        ?.asString                        ?: throw IllegalArgumentException(                            "Missing ML-KEM ciphertext."                        ),                    Base64.NO_WRAP                )                val encryptedPathSeed = Base64.decode(                    pathJson                        .get(                            DootawasMessage.GROUP_ENCRYPTED_PATH_SEED                        )                        ?.asString                        ?: throw IllegalArgumentException(                            "Missing encrypted path seed."                        ),                    Base64.NO_WRAP                )                val pathNonce = Base64.decode(                    pathJson                        .get(DootawasMessage.GROUP_PATH_NONCE)                        ?.asString                        ?: throw IllegalArgumentException(                            "Missing path nonce."                        ),                    Base64.NO_WRAP                )                val encryptedPath = HybridEncapsulatedPayload(                    recipientLeafId = recipientLeafId,                    ephemeralX25519Public = ephemeralX25519Public,                    mlKemCiphertext = mlKemCiphertext,                    encryptedPathSeed = encryptedPathSeed,                    nonce = pathNonce                )                // =========================================================                // 5. READ COMMIT SIGNATURE                // =========================================================                val signature = Base64.decode(                    jsonMessage                        .get(DootawasMessage.GROUP_COMMIT_SIGNATURE)                        ?.asString                        ?: throw IllegalArgumentException(                            "Missing commit signature."                        ),                    Base64.NO_WRAP                )                if (signature.isEmpty()) {                    throw SecurityException("Commit signature is empty.")                }                // =========================================================                // 6. FIND LOCAL GROUP MEMBER                // =========================================================                val myNumber = userNumberKhud.firstOrNull()                    ?: throw IllegalStateException(                        "Local user number missing."                    )                val myMember = groupDao.getAGroupMemberByNumber(                    groupId = groupId,                    userNumber = myNumber                ) ?: throw IllegalStateException(                    "Local member not found in group=$groupId"                )                if (myMember.memberInstanceId.isBlank()) {                    throw SecurityException(                        "Local memberInstanceId is missing."                    )                }                // Ensure this encrypted path belongs to us.                if (recipientLeafId != myMember.memberInstanceId) {                    DLog.e(                        "err check EpochCommit mismatch: myNumber=$myNumber " +                                "myMember.memberInstanceId=${myMember.memberInstanceId} " +                                "expectedFromPath=$recipientLeafId " +                                "committerMemberId=$committerMemberId groupId=$groupId"                    )                    throw SecurityException("EpochCommit path is not addressed to this member.")                }                // =========================================================                // 7. VERIFY OUR ENCRYPTED PATH MATCHES SIGNED HASH                // =========================================================                val expectedPathHash = pathHashes.find {                    it.recipientLeafId == myMember.memberInstanceId                } ?: throw SecurityException(                    "No signed path hash found for this member."                )                val actualPathHash = groupCryptoManager.hashEncryptedPath(                    encryptedPath                )                if (!actualPathHash.contentEquals(expectedPathHash.pathHash)) {                    throw SecurityException(                        "Encrypted path does not match its signed path hash."                    )                }                // =========================================================                // 8. RECONSTRUCT EPOCH COMMIT                // =========================================================                val commit = EpochCommit(                    protocolVersion = protocolVersion,                    groupId = groupId,                    parentEpoch = parentEpoch,                    newEpoch = newEpoch,                    rosterVersion = rosterVersion,                    commitId = commitId,                    parentCommitHash = parentCommitHash,                    committerMemberId = committerMemberId,                    committerDeviceId = committerDeviceId,                    pathHashes = pathHashes,                    encryptedPaths = listOf(encryptedPath),                    signature = signature                )                // =========================================================                // 9. LOAD LOCAL PRIVATE KEYS                // =========================================================                val localKeys =                    groupCryptoManager.getOrCreateLocalGroupKeys(                        groupId = groupId,                        memberInstanceId = myMember.memberInstanceId                    )                // =========================================================                // 10. VERIFY, DECAPSULATE AND SAVE NEW EPOCH                // =========================================================                groupCryptoManager.receiveEpochCommit(                    commit = commit,                    myX25519Private = localKeys.x25519PrivateKey,                    myMlKemPrivate = localKeys.mlKemPrivateKey                )                DLog.i(                    "EpochCommit successfully processed: " +                            "group=$groupId epoch=$newEpoch " +                            "commit=$commitId"                )            } catch (e: Exception) {                DLog.e(                    "Failed to handle EpochCommit: ${e.message}",                    e                )            }        }    }    private fun handleGroupKeySetup(        jsonMessage: JsonObject,        sender: String,        messageId: String    ) {        coroutineScope.launch {            try {                val groupId = jsonMessage.get(JsonKeys.GROUP_ID)?.asString                    ?: throw IllegalArgumentException("Missing groupId.")                val setupId = jsonMessage.get(DootawasMessage.SETUP_ID)?.asString                    ?.takeIf { it.isNotBlank() }                    ?: throw IllegalArgumentException("Missing setupId.")                val userNumber = jsonMessage.get(JsonKeys.USER_NUMBER)?.asString                    ?.takeIf { it.isNotBlank() }                    ?: throw IllegalArgumentException("Missing userNumber.")                val myNumber = userNumberKhud.firstOrNull()                    ?: throw IllegalStateException("Local user number missing.")                if (userNumber != sender) {                    throw SecurityException(                        "GROUP_KEY_SETUP sender mismatch: sender=$sender userNumber=$userNumber"                    )                }                val myMember = groupDao.getAGroupMemberByNumber(                    groupId = groupId,                    userNumber = myNumber                ) ?: throw IllegalStateException(                    "Local member not found: group=$groupId"                )                if (!myMember.isSwami && !myMember.canModifyMembers) {                    DLog.i(                        "Ignoring GROUP_KEY_SETUP: local member is not authorized " +                                "to handle group key setup. group=$groupId"                    )                    return@launch                }                DLog.i(                    "Received GROUP_KEY_SETUP: " +                            "group=$groupId " +                            "user=$userNumber " +                            "setupId=$setupId"                )                // Generate/load THIS admin's current group keys.                val localKeys = groupCryptoManager.getOrCreateLocalGroupKeys(                    groupId = groupId,                    memberInstanceId = myMember.memberInstanceId                )                val requestJson = JsonObject().apply {                    addProperty(                        JsonKeys.GROUP_ID,                        groupId                    )                    addProperty(                        DootawasMessage.SANDESH_TYPE,                        SandeshType.GROUP_KEY_REQUEST.value                    )                    addProperty(                        DootawasMessage.SETUP_ID,                        setupId                    )                    addProperty(                        JsonKeys.USER_NUMBER,                        myNumber                    )                    addProperty(                        DootawasMessage.GROUP_MEMBER_INSTANCE_ID,                        myMember.memberInstanceId                    )                    addProperty(                        DootawasMessage.GROUP_DEVICE_ID,                        myMember.deviceId                    )                    addProperty(                        DootawasMessage.GROUP_KEY_GENERATION,                        myMember.keyGeneration                    )                    addProperty(                        DootawasMessage.GROUP_X25519_PUBLIC_KEY,                        Base64.encodeToString(                            localKeys.x25519PublicKey.encoded,                            Base64.NO_WRAP                        )                    )                    addProperty(                        DootawasMessage.GROUP_ML_KEM_PUBLIC_KEY,                        Base64.encodeToString(                            localKeys.mlKemPublicKey.encoded,                            Base64.NO_WRAP                        )                    )                    addProperty(                        DootawasMessage.GROUP_ED25519_PUBLIC_KEY,                        Base64.encodeToString(                            localKeys.ed25519PublicKey.encoded,                            Base64.NO_WRAP                        )                    )                    addProperty(                        JsonKeys.TIME_STAMP,                        System.currentTimeMillis()                    )                }                insertUnsentData(                    UnsentSandesh(                        messId = UUID.randomUUID().toString(),                        receiver = sender,                        message = requestJson.toString(),                        dataType = DataType.MESSAGE                    )                )                DLog.i(                    "Queued GROUP_KEY_REQUEST: " +                            "group=$groupId " +                            "receiver=$sender " +                            "setupId=$setupId"                )                sendUnsentMessages(false)            } catch (e: Exception) {                DLog.e(                    "Failed to handle GROUP_KEY_SETUP: ${e.message}",                    e                )            }        }    }    private fun handleGroupKeyPackage(        jsonMessage: JsonObject,        sender: String,        messageId: String,    ){        coroutineScope.launch {            try {                val groupId = jsonMessage.get(JsonKeys.GROUP_ID)?.asString                    ?: throw IllegalArgumentException("Missing groupId.")                val timestamp = jsonMessage.get(JsonKeys.TIME_STAMP)?.asLong                    ?: throw IllegalArgumentException("Missing timestamp.")                val existing = groupDao.getPendingGroupKeyPackage(                    groupId = groupId,                    userNumber = sender                )                if (existing == null || timestamp > existing.createdAt) {                    groupDao.insertPendingGroupKeyPackage(                        PendingGroupKeyPackageEntity(                            groupId = groupId,                            userNumber = sender,                            messageJson = jsonMessage.toString(),                            createdAt = timestamp                        )                    )                    DLog.i(                        "Stored newer GROUP_KEY_PACKAGE: " +                                "messageId=$messageId user=$sender group=$groupId timestamp=$timestamp"                    )                } else {                    DLog.i(                        "Ignored older GROUP_KEY_PACKAGE: " +                                "messageId=$messageId user=$sender group=$groupId timestamp=$timestamp"                    )                }                // Try immediately. If member is not in roster yet, it stays pending.                processPendingGroupKeyPackages(groupId)            } catch (e: Exception) {                DLog.e("Failed to handle GROUP_KEY_PACKAGE: ${e.message}", e)            }        }    }    private suspend fun processGroupKeyPackage(        jsonMessage: JsonObject,        sender: String    ) {        val groupId = jsonMessage.get(JsonKeys.GROUP_ID)?.asString            ?: throw IllegalArgumentException("Missing groupId.")        val userNumber = jsonMessage.get(JsonKeys.USER_NUMBER)?.asString            ?: throw IllegalArgumentException("Missing userNumber.")        val memberInstanceId = jsonMessage            .get(DootawasMessage.GROUP_MEMBER_INSTANCE_ID)            ?.asString            ?.takeIf { it.isNotBlank() }            ?: throw IllegalArgumentException("Missing memberInstanceId.")        val deviceId = jsonMessage            .get(DootawasMessage.GROUP_DEVICE_ID)            ?.asString            ?.takeIf { it.isNotBlank() }            ?: throw IllegalArgumentException("Missing deviceId.")        val keyGeneration = jsonMessage            .get(DootawasMessage.GROUP_KEY_GENERATION)            ?.asLong            ?: throw IllegalArgumentException("Missing keyGeneration.")        val x25519PublicKey = Base64.decode(            jsonMessage.get(DootawasMessage.GROUP_X25519_PUBLIC_KEY)?.asString                ?: throw IllegalArgumentException("Missing X25519 public key."),            Base64.NO_WRAP        )        val mlKemPublicKey = Base64.decode(            jsonMessage.get(DootawasMessage.GROUP_ML_KEM_PUBLIC_KEY)?.asString                ?: throw IllegalArgumentException("Missing ML-KEM public key."),            Base64.NO_WRAP        )        val ed25519PublicKey = Base64.decode(            jsonMessage.get(DootawasMessage.GROUP_ED25519_PUBLIC_KEY)?.asString                ?: throw IllegalArgumentException("Missing Ed25519 public key."),            Base64.NO_WRAP        )        if (x25519PublicKey.isEmpty() || mlKemPublicKey.isEmpty() || ed25519PublicKey.isEmpty()) {            throw IllegalArgumentException("Received empty group public key.")        }        // Caller must only call this after confirming the member exists.        val member = groupDao.getAGroupMemberByNumber(            groupId = groupId,            userNumber = userNumber        ) ?: throw IllegalStateException(            "Member not found while processing GROUP_KEY_PACKAGE: user=$userNumber group=$groupId"        )        val instanceChanged = member.memberInstanceId != memberInstanceId        if (            !instanceChanged &&            member.keyGeneration > keyGeneration &&            member.x25519PublicKey.isNotEmpty() &&            member.mlKemPublicKey.isNotEmpty() &&            member.ed25519PublicKey.isNotEmpty()        ) {            DLog.i(                "Ignoring stale GROUP_KEY_PACKAGE: user=$userNumber group=$groupId " +                        "incomingGeneration=$keyGeneration storedGeneration=${member.keyGeneration}"            )            return        }        groupDao.insertMember(            member.copy(                memberInstanceId = memberInstanceId,                deviceId = deviceId,                keyGeneration = keyGeneration,                x25519PublicKey = x25519PublicKey,                mlKemPublicKey = mlKemPublicKey,                ed25519PublicKey = ed25519PublicKey,                isCryptoActive = true            )        )        DLog.i("Saved GROUP_KEY_PACKAGE: user=$userNumber group=$groupId generation=$keyGeneration")        unsentSandeshDao.restoreHeldMessagesForUser(groupId)        val myNumber = userNumberKhud.firstOrNull()            ?: throw IllegalStateException("Local user number missing.")        val myMember = groupDao.getAGroupMemberByNumber(            groupId = groupId,            userNumber = myNumber        ) ?: throw IllegalStateException("Local member not found in group=$groupId")        val isKeyRequest = jsonMessage            .get(DootawasMessage.IS_KEY_REQUEST)            ?.asBoolean            ?: throw IllegalArgumentException("Missing isKeyRequest.")        if (isKeyRequest) {            DLog.i(                "Received GROUP_KEY_REQUEST. " +                        "Sending GROUP_KEY_RESPONSE: " +                        "group=$groupId receiver=$sender"            )            sendGroupKeyResponse(                groupId = groupId, sender            )        } else {            DLog.i(                "Received GROUP_KEY_RESPONSE. " +                        "Checking epoch rotation: " +                        "group=$groupId sender=$sender"            )            checkAndRotateGroupEpoch(groupId)        }    }    private suspend fun processPendingGroupKeyPackages(        groupId: String    ) {        val pendingPackages = groupDao.getPendingGroupKeyPackages(groupId)        if (pendingPackages.isEmpty()) return        DLog.i(            "Checking ${pendingPackages.size} pending GROUP_KEY_PACKAGE(s): group=$groupId"        )        pendingPackages.forEach { pending ->            try {                val member = groupDao.getAGroupMemberByNumber(                    groupId = groupId,                    userNumber = pending.userNumber                )                if (member == null) {                    DLog.i(                        "Keeping GROUP_KEY_PACKAGE pending: " +                                "user=${pending.userNumber} group=$groupId"                    )                    return@forEach                }                val jsonMessage = JsonParser                    .parseString(pending.messageJson)                    .asJsonObject                processGroupKeyPackage(                    jsonMessage = jsonMessage,                    sender = pending.userNumber                )                // Delete only after successful processing.                groupDao.deletePendingGroupKeyPackage(                    groupId = groupId,                    userNumber = pending.userNumber                )                DLog.i(                    "Processed and deleted pending GROUP_KEY_PACKAGE: " +                            "user=${pending.userNumber} group=$groupId"                )            } catch (e: Exception) {                DLog.e(                    "Failed to process pending GROUP_KEY_PACKAGE: " +                            "user=${pending.userNumber} group=$groupId error=${e.message}",                    e                )            }        }    }    suspend fun checkAndRotateGroupEpoch(        groupId: String,        forceAfterTimeout: Boolean = false    ) {        rotationMutexFor(groupId).withLock {            DLog.i(                "checkAndRotateGroupEpoch RUNNING (lock acquired): " +                        "group=$groupId forceAfterTimeout=$forceAfterTimeout"            )            try {                val group = groupDao.getGroupById(groupId)                    ?: throw IllegalStateException(                        "Group $groupId not found."                    )                val myNumber = userNumberKhud.firstOrNull()                    ?: throw IllegalStateException(                        "Local user number missing."                    )                val myMember = groupDao.getAGroupMemberByNumber(                    groupId = groupId,                    userNumber = myNumber                ) ?: throw IllegalStateException(                    "Local member not found in group: $groupId"                )                if (!myMember.isSwami && !myMember.canModifyMembers) {                    DLog.i(                        "Local member is not authorized to rotate epoch: " +                                "group=$groupId"                    )                    return                }                val members = groupDao.getAllMembersInGroup(groupId)                val activeMembers = members.filter {                    it.isCryptoActive                }                if (activeMembers.isEmpty()) {                    DLog.i(                        "No crypto-active members in group: $groupId"                    )                    return                }                val membersWithoutKeys = activeMembers.filter {                    it.memberInstanceId.isBlank() ||                            it.deviceId.isBlank() ||                            it.x25519PublicKey.isEmpty() ||                            it.mlKemPublicKey.isEmpty() ||                            it.ed25519PublicKey.isEmpty()                }// Normal mode: wait for missing key packages.                if (                    membersWithoutKeys.isNotEmpty() &&                    !forceAfterTimeout                ) {                    DLog.i(                        "⏳ ROTATION WAITING: " +                                "group=$groupId missing=${membersWithoutKeys.size}"                    )                    scheduleGroupEpochRotation(groupId)                    DLog.i(                        "⏳ ROTATION WAIT SCHEDULED: " +                                "group=$groupId missing=${membersWithoutKeys.size}"                    )                    return                } else {                    DLog.i(                        "🔎 ROTATION CONDITION FALSE: " +                                "group=$groupId " +                                "membersWithoutKeys=${membersWithoutKeys.size} " +                                "forceAfterTimeout=$forceAfterTimeout"                    )                }                if (                    forceAfterTimeout &&                    membersWithoutKeys.isNotEmpty()                ) {                    DLog.i(                        "Epoch rotation timeout reached. Marking " +                                "${membersWithoutKeys.size} member(s) as " +                                "crypto-inactive: group=$groupId"                    )                    membersWithoutKeys.forEach { member ->                        groupDao.insertMember(                            member.copy(                                isCryptoActive = false                            )                        )                        DLog.i(                            "Marked crypto-inactive: " +                                    "user=${member.userNumber} group=$groupId"                        )                    }                } else {                    DLog.i(                        "Epoch rotation timeout condition FALSE: " +                                "group=$groupId " +                                "forceAfterTimeout=$forceAfterTimeout " +                                "membersWithoutKeys=${membersWithoutKeys.size}"                    )                }                val updatedMembers = groupDao.getAllMembersInGroup(groupId)                val finalActiveMembers = updatedMembers.filter {                    it.isCryptoActive &&                            it.memberInstanceId.isNotBlank() &&                            it.deviceId.isNotBlank() &&                            it.x25519PublicKey.isNotEmpty() &&                            it.mlKemPublicKey.isNotEmpty() &&                            it.ed25519PublicKey.isNotEmpty()                }                if (finalActiveMembers.isEmpty()) {                    DLog.i(                        "No members with complete crypto keys available: " +                                "group=$groupId"                    )                    return                }                val finalMyMember = finalActiveMembers.find {                    it.userNumber == myNumber                } ?: throw SecurityException(                    "Local member is not part of the final crypto-active roster."                )                val rosterVersion = group.rosterVersion + 1L                val localKeys = groupCryptoManager.getOrCreateLocalGroupKeys(                    groupId = groupId,                    memberInstanceId = finalMyMember.memberInstanceId                )                DLog.i(                    "🚨 ABOUT TO CREATE EPOCH COMMIT: " +                            "group=$groupId " +                            "forceAfterTimeout=$forceAfterTimeout " +                            "currentEpoch=${group.currentEpoch} " +                            "rosterVersion=${group.rosterVersion} " +                            "finalActiveMembers=${finalActiveMembers.size}"                )                val commit = groupCryptoManager.createEpochCommit(                    groupId = groupId,                    commitId = UUID.randomUUID().toString(),                    rosterVersion = rosterVersion,                    privateX25519 = localKeys.x25519PrivateKey,                    privateMlKem = localKeys.mlKemPrivateKey,                    privateEd25519 = localKeys.ed25519PrivateKey                )                DLog.i(                    "🔥 EPOCH COMMIT CREATED: " +                            "group=$groupId " +                            "commitId=${commit.commitId} " +                            "parentEpoch=${commit.parentEpoch} " +                            "newEpoch=${commit.newEpoch} " +                            "rosterVersion=${commit.rosterVersion}"                )                commit.encryptedPaths.forEach { path ->                    val recipientMember =                        activeMembers.find { it.memberInstanceId == path.recipientLeafId }                    DLog.i(                        "EpochCommit fanout: sending path for recipientLeafId=${path.recipientLeafId} " +                                "to phoneNumber=${recipientMember?.userNumber ?: "NOT FOUND"} " +                                "group=$groupId newEpoch=${commit.newEpoch}"                    )                    // ... existing code that builds the per-recipient JSON and sends it ...                }                sendEpochCommitToGroupMembers(                    groupId = groupId,                    commit = commit                )                // Rotation completed, so the timeout must not trigger later.                WorkManager                    .getInstance(context)                    .cancelUniqueWork(                        GroupEpochRotationWorker.uniqueWorkName(groupId)                    )                DLog.i(                    "Cancelled epoch rotation timeout: group=$groupId"                )            } catch (e: Exception) {                DLog.e(                    "Failed to check/rotate group epoch for group=$groupId",                    e                )            }        }    }    private fun scheduleGroupEpochRotation(        groupId: String    ) {        val inputData = workDataOf(            GroupEpochRotationWorker.KEY_GROUP_ID to groupId        )        val request =            OneTimeWorkRequestBuilder<GroupEpochRotationWorker>()                .setInitialDelay(                    1,                    TimeUnit.MINUTES                )                .setInputData(inputData)                .build()        WorkManager            .getInstance(context)            .enqueueUniqueWork(                GroupEpochRotationWorker.uniqueWorkName(groupId),                ExistingWorkPolicy.KEEP,                request            )        DLog.i(            "Scheduled epoch rotation timeout: " +                    "group=$groupId delay=60 seconds"        )    }    private suspend fun ensureLocalGroupCryptoIdentity(        groupId: String    ): GroupMemberEntity {        val myNumber = userNumberKhud.firstOrNull()            ?: throw IllegalStateException("Local user number missing.")        // Fast path: no lock needed if identity already exists.        val existing = groupDao.getAGroupMemberByNumber(            groupId = groupId,            userNumber = myNumber        ) ?: throw IllegalStateException(            "Local member not found in group: $groupId"        )        if (existing.memberInstanceId.isNotBlank()) {            return existing        }        // Slow path: identity missing — serialize so only one caller        // can generate/persist it, even under concurrent invocation.        return mutexFor(groupId).withLock {            // Re-check AFTER acquiring the lock — another coroutine may            // have already created it while we were waiting.            val recheck = groupDao.getAGroupMemberByNumber(                groupId = groupId,                userNumber = myNumber            ) ?: throw IllegalStateException(                "Local member not found in group: $groupId"            )            if (recheck.memberInstanceId.isNotBlank()) {                DLog.i(                    "ensureLocalGroupCryptoIdentity: another caller already " +                            "created identity=${recheck.memberInstanceId} for group=$groupId"                )                return@withLock recheck            }            val memberInstanceId = UUID.randomUUID().toString()            val deviceId = recheck.deviceId                .takeIf { it.isNotBlank() } ?: CURRENT_DEVICE_ID            val keyGeneration = if (recheck.keyGeneration > 0L) recheck.keyGeneration else 1L            val updated = recheck.copy(                memberInstanceId = memberInstanceId,                deviceId = deviceId,                keyGeneration = keyGeneration            )            groupDao.insertMember(updated)            DLog.i(                "ensureLocalGroupCryptoIdentity: generated NEW identity=" +                        "$memberInstanceId for group=$groupId"            )            updated        }    }    private suspend fun sendGroupKeyResponse(        groupId: String,        requesterNumber: String    ) {        try {            val myNumber = userNumberKhud.firstOrNull()                ?: throw IllegalStateException(                    "Local user number missing."                )            val myMember = ensureLocalGroupCryptoIdentity(                groupId = groupId            )            val localKeys = groupCryptoManager.getOrCreateLocalGroupKeys(                groupId = groupId,                memberInstanceId = myMember.memberInstanceId            )            val keyResponseJson = JsonObject().apply {                addProperty(                    JsonKeys.GROUP_ID,                    groupId                )                addProperty(                    DootawasMessage.SANDESH_TYPE,                    SandeshType.GROUP_KEY_RESPONSE.value                )                addProperty(                    JsonKeys.USER_NUMBER,                    myNumber                )                addProperty(                    DootawasMessage.GROUP_MEMBER_INSTANCE_ID,                    myMember.memberInstanceId                )                addProperty(                    DootawasMessage.GROUP_DEVICE_ID,                    myMember.deviceId                )                addProperty(                    DootawasMessage.GROUP_KEY_GENERATION,                    myMember.keyGeneration                )                addProperty(                    DootawasMessage.GROUP_X25519_PUBLIC_KEY,                    Base64.encodeToString(                        localKeys.x25519PublicKey.encoded,                        Base64.NO_WRAP                    )                )                addProperty(                    DootawasMessage.GROUP_ML_KEM_PUBLIC_KEY,                    Base64.encodeToString(                        localKeys.mlKemPublicKey.encoded,                        Base64.NO_WRAP                    )                )                addProperty(                    DootawasMessage.GROUP_ED25519_PUBLIC_KEY,                    Base64.encodeToString(                        localKeys.ed25519PublicKey.encoded,                        Base64.NO_WRAP                    )                )            }            val unsentSandesh = UnsentSandesh(                messId = UUID.randomUUID().toString(),                receiver = requesterNumber,                message = keyResponseJson.toString(),                dataType = DataType.MESSAGE            )            insertUnsentData(unsentSandesh)            DLog.i(                "Sending GROUP_KEY_RESPONSE: " +                        "group=$groupId " +                        "from=$myNumber " +                        "to=$requesterNumber " +                        "memberInstanceId=${myMember.memberInstanceId} " +                        "generation=${myMember.keyGeneration}"            )            sendUnsentMessages(false)        } catch (e: Exception) {            DLog.e(                "Failed to send GROUP_KEY_RESPONSE for group=$groupId",                e            )        }    }    private fun handleGetGroupDetails(json: JsonObject) {        val groupObj = json.getAsJsonObject(JsonKeys.DATA)        val groupId = groupObj.get(JsonKeys.GROUP_ID).asString        val groupName = groupObj.get(JsonKeys.GROUP_NAME).asString        val creator = groupObj.get(JsonKeys.GROUP_CREATOR).asString        val createdAt = groupObj.get(JsonKeys.GROUP_CREATED_AT).asLong        val description = groupObj.get(JsonKeys.GROUP_DEC).asString        val isActive = groupObj.get(JsonKeys.GROUP_IS_ACTIVE).asBoolean        val lastActivity = groupObj.get(JsonKeys.GROUP_LAST_ACTIVITY_AT).asLong        val membersJson = groupObj.getAsJsonArray(JsonKeys.GROUP_MEMBERS)        CoroutineScope(Dispatchers.IO).launch {            // ⭐ Load local group            val oldGroup = groupDao.getGroupById(groupId)            // ⭐ Merge new + old (keep local fields that server does NOT send)            val groupEntity = GroupEntity(                groupId = groupId,                groupName = groupName,                groupDescription = description,                groupImageUrl = oldGroup?.groupImageUrl,              // keep existing                lastMessage = oldGroup?.lastMessage ?: "Added To Group",                totalUnread = oldGroup?.totalUnread ?: 0,                createdBy = creator,                createdAt = createdAt,                imageTime = oldGroup?.imageTime ?: 0,                isMuted = oldGroup?.isMuted ?: false,                lastMessageTime = lastActivity,                wallpaperImage = oldGroup?.wallpaperImage,                sandeshStithi = oldGroup?.sandeshStithi ?: SandeshStithi.LIKHIT,                lastMessageId = oldGroup?.lastMessageId ?: "",                isGroupSuspended = !isActive,                backgroundColor = RandomColorGenerator.getRandomColor(),                isGroupActive = isActive            )            // Save group entity            groupDao.insertGroupEntity(groupEntity)            // ⭐ Load existing local members for merging            val oldMembers = groupDao.getAllMembersInGroup(groupId)                .associateBy { it.userNumber }            val finalList = mutableListOf<GroupMemberEntity>()            // ⭐ Build merged list            for (element in membersJson) {                val m = element.asJsonObject                val userNumber = m.get(JsonKeys.USER_NUMBER).asString                val old = oldMembers[userNumber]                val colors = generateUserColors()                val merged = GroupMemberEntity(                    groupId = groupId,                    userNumber = userNumber,                    contactName = m.get(JsonKeys.USER_NAME).asString,                    userDarkColor = colors.darkModeColor,                    userLightColor = colors.lightModeColor,                    joinedAt = m.get(JsonKeys.GROUP_JOINED_AT).asLong,                    isSwami = m.get(JsonKeys.IS_SWAMI).asBoolean,                    canMessage = m.get(JsonKeys.CAN_MESSAGE).asBoolean,                    canUpdateProfile = m.get(JsonKeys.CAN_UPDATE_PROFILE).asBoolean,                    canModifyMembers = m.get(JsonKeys.CAN_MODIFY_MEMBERS).asBoolean,                    canStartCall = m.get(JsonKeys.CAN_START_CALL).asBoolean,                    // ⭐ KEEP LOCAL FIELDS (server does NOT send)                    profileTime = old?.profileTime ?: 0L,                    profileUrl = old?.profileUrl ?: "",                    publicKey = old?.publicKey ?: ""                )                finalList.add(merged)            }            // ⭐ Delete members no longer in server response            val serverUserNumbers = finalList.map { it.userNumber }.toSet()            groupDao.deleteMembersNotIn(groupId, serverUserNumbers)            // ⭐ Insert merged members            groupDao.insertMembers(finalList)            DLog.i("✔ Synced group $groupName (${finalList.size} members)")        }    }    private fun handleGetGroups(json: JsonObject) {        val groupsJson = json.getAsJsonArray(JsonKeys.GROUPS)        val groups = mutableListOf<GroupEntity>()        val groupIds = mutableListOf<String>()        groupsJson.forEach { element ->            val obj = element.asJsonObject            val groupId = obj.get(JsonKeys.GROUP_ID).asString            groupIds.add(groupId)            val group = GroupEntity(                groupId = groupId,                groupName = obj.get(JsonKeys.GROUP_NAME).asString,                groupDescription = obj.get(JsonKeys.GROUP_DEC)?.asString,                groupImageUrl = null,                lastMessage = null,                totalUnread = 0,                createdBy = obj.get(JsonKeys.GROUP_CREATOR).asString,                createdAt = obj.get(JsonKeys.GROUP_CREATED_AT)?.asLong ?: 0,                imageTime = obj.get(JsonKeys.GROUP_PROFILE_TIME)?.asLong ?: 0,                isMuted = false,                lastMessageTime = obj.get(JsonKeys.GROUP_LAST_ACTIVITY_AT)?.asLong ?: 0,                wallpaperImage = null,                sandeshStithi = SandeshStithi.LIKHIT,                lastMessageId = "",                backgroundColor = 0,                // ===== GROUP E2EE STATE =====                currentEpoch = 0L,                currentCommitHash = null,                rosterVersion = 0L,                groupCryptoProtocolVersion = 1            )            groups.add(group)        }        CoroutineScope(Dispatchers.IO).launch {            groupDao.insertAllGroups(groups)            // Now fetch members sequentially            for (groupId in groupIds) {                getAllGroupMembers(groupId,true)                delay(30.milliseconds) // small throttle            }        }    }    private suspend fun getGroup(groupId: String) {        val jsonObject = JsonObject().apply {            addProperty(DootawasMessage.SANDESH_TYPE, GroupSandeshType.ACTION_GET_GROUP.value)            addProperty(JsonKeys.GROUP_ID, groupId)        }        val unsentSandesh = UnsentSandesh(            messId = createMessageID(),            receiver = userNumberKhud.firstOrNull().toString(),            message = jsonObject.toString(),            dataType = DataType.GROUP_ACTION        )        insertUnsentData(unsentSandesh)        sendUnsentMessages(false)    }    private suspend fun sendNextKeys() {        val nextKeys: JsonObject = roomSignalStore.generateNextPreKeysBatch()        val unsentSandesh = UnsentSandesh(            messId = createMessageID(),            receiver = "noNeed",            message = nextKeys.toString(),            dataType = DataType.PUBLIC_KEY        )        DLog.i("Sending KEY: $unsentSandesh")        insertUnsentData(unsentSandesh)        sendUnsentMessages(false)    }    private suspend fun sendNextKuberKeys() {        val nextKeys: JsonObject = roomSignalStore.generateNextKyberKeysBatch()        val unsentSandesh = UnsentSandesh(            messId = createMessageID(),            receiver = "storekyber",            message = nextKeys.toString(),            dataType = DataType.PUBLIC_KEY        )        DLog.i("Sending KEY: $unsentSandesh")        insertUnsentData(unsentSandesh)        sendUnsentMessages(false)    }    private fun testDataBeforeSend(jsonObject: JsonObject): Boolean {        // Validate required fields        if (!jsonObject.has(JsonKeys.DATA_TYPE) ||            !jsonObject.has(JsonKeys.MESSAGE_ID)        ) {            return false // Missing essential fields        }        // Validate `dataType` (should be an integer)        if (!jsonObject.get("dataType").isJsonPrimitive || !jsonObject.get("dataType").asJsonPrimitive.isNumber) {            return false        }        // Validate `sender` (should be a non-empty string)        if (!jsonObject.get("sender").isJsonPrimitive || jsonObject.get("sender").asString.isEmpty()) {            return false        }        // Validate `sandesh` (should be a valid JSON string)        try {            val sandeshObj: JsonObject =                JsonParser.parseString(jsonObject.get("sandesh").asString).asJsonObject            // Validate `originalMessage` inside `sandesh`            if (sandeshObj.has("originalMessage")) {                val originalMessage: JsonObject = sandeshObj.getAsJsonObject("originalMessage")                if (!originalMessage.has("mimeType") ||                    !originalMessage.has("savedUri") ||                    !originalMessage.has("fileName")                ) {                    return false // `originalMessage` is missing fields                }            }        } catch (e: Exception) {            return false // `sandesh` is not valid JSON        }        return true // Data is valid    }    private fun processContactProfileStatus(userList: JsonArray) {        CoroutineScope(Dispatchers.IO).launch {            statusAndProfileMutex.withLock {                for (element in userList) {                    val userObject = element.asJsonObject                    val userNumber = userObject.get(JsonKeys.USER_NUMBER)                        ?.takeUnless { it.isJsonNull }                        ?.asString ?: continue                    val userName = userObject.get(JsonKeys.USER_NAME)                        ?.takeUnless { it.isJsonNull }                        ?.asString                    val newProfileTime = userObject.get(JsonKeys.TIME_STAMP)                        ?.takeUnless { it.isJsonNull }                        ?.asLong ?: 0L                    val profilePass = userObject.get(JsonKeys.DATA)                        ?.takeUnless { it.isJsonNull }                        ?.asString ?: ""                    DLog.i("Processing User: $userNumber")                    val existingUser = contactDao.getUserContactByNumber(userNumber)                    DLog.i(existingUser.toString())                    if (existingUser != null) {                        val newState =                            if (existingUser.buttonState == ContactButtonState.INVITE || existingUser.buttonState == ContactButtonState.INVITED) {                                ContactButtonState.ADD                            } else {                                existingUser.buttonState                            }                        contactDao.update(                            existingUser.copy(                                isInstalled = true,                                buttonState = newState                            )                        )                        if (newProfileTime == 0L && existingUser.imageTime > 0L) {                            DLog.i("🗑 Profile removed for $userNumber")                            // Remove locally                            upbhogtaDao.updateImageTimeByNumber(userNumber, 0L)                            contactDao.updateImageTimeByNumber(userNumber, 0L)                            groupDao.updateProfileTimeForUser(userNumber, 0L)                            replaceUri(userNumber, null)                            return@launch                        }                        // 💡 Check profile image time                        if (newProfileTime != existingUser.imageTime && newProfileTime != 0L) {                            val upbhogtaUser = upbhogtaDao.getUserByNumber(userNumber)                            if (upbhogtaUser != null) {                                upbhogtaDao.updateImageTimeByNumber(                                    upbhogtaUser.userNumber,                                    newImageTime = newProfileTime                                )                            }                            groupDao.updateProfileTimeForUser(userNumber, newProfileTime)                            contactDao.updateImageTimeByNumber(existingUser.number, newProfileTime)                            DLog.i("New profile image detected for $userNumber")                            val unsentFiles = UnsentFiles(                                createMessageID(),                                userNumber,                                profilePass,                                FileDataType.GET_PROFILE_PIC                            )                            insertSendData(unsentFiles)                            if (!sendingFileInProgress) {                                sendUnsentFiles()                            }                        }                    } else {                        DLog.i("User not found, skipping: $userNumber")                    }                }            }        }    }    private fun processExistenceStatus(userList: JsonArray) {        CoroutineScope(Dispatchers.IO).launch {  // Run in background thread            statusAndProfileMutex.withLock {                for (element in userList) {                    val userObject = element.asJsonObject                    val userNumber = userObject.get(JsonKeys.USER_NUMBER).asString                    val userExists = userObject.get("userExists").asBoolean                    DLog.i("Processing User: $userNumber")                    val existingUser = contactDao.getUserContactByNumber(userNumber)                    DLog.i(existingUser.toString())                    if (existingUser != null) {                        // Check if `isInstalled` status has changed                        if (existingUser.isInstalled != userExists) {                            val newState = if (userExists &&                                (existingUser.buttonState == ContactButtonState.INVITE || existingUser.buttonState == ContactButtonState.INVITED)                            ) {                                ContactButtonState.ADD                            } else {                                existingUser.buttonState                            }                            contactDao.update(                                existingUser.copy(                                    isInstalled = userExists, buttonState =                                        newState                                )                            )                            DLog.i("Updated installation status and button state for $userNumber")                        }                    } else {                        DLog.i("User not found, skipping insert: $userNumber")                    }                }            }        }    }    private val _presenceMap =        MutableStateFlow<Map<String, Boolean?>>(emptyMap())    val presenceMap: StateFlow<Map<String, Boolean?>> =        _presenceMap    fun onPresenceReceived(userNumber: String, isOnline: Boolean?) {        _presenceMap.update { current ->            current.toMutableMap().apply {                put(userNumber, isOnline)            }        }    }    private fun processSingleProfileStatus(userObject: JsonObject?) {        if (userObject == null || !userObject.has(JsonKeys.USER_NUMBER)) return        CoroutineScope(Dispatchers.IO).launch {            statusAndProfileMutex.withLock {                val userNumber = userObject.get(JsonKeys.USER_NUMBER)                    ?.takeIf { it.isJsonPrimitive }?.asString ?: return@launch                val userName = userObject.get(JsonKeys.USER_NAME)                    ?.takeIf { it.isJsonPrimitive && !it.isJsonNull }                    ?.asString                val about = userObject.get(JsonKeys.ABOUT)                    ?.takeIf { it.isJsonPrimitive && !it.isJsonNull }                    ?.asString                val newProfileTime = userObject.get("profile_time")                    ?.takeIf { it.isJsonPrimitive }                    ?.asLong ?: 0L                val profileData = userObject.get(JsonKeys.DATA)                    ?.takeIf { it.isJsonPrimitive && !it.isJsonNull }                    ?.asString                val lastSeen = userObject.get("last_seen")                    ?.takeIf { it.isJsonPrimitive }                    ?.asLong ?: 0L                // isOnline can be: null, false, true                val isOnline =                    if (userObject.has("isOnline") && !userObject.get("isOnline").isJsonNull) {                        userObject.get("isOnline").asBoolean                    } else null                onPresenceReceived(userNumber, isOnline)                val upbhogtaUser = upbhogtaDao.getUserByNumber(userNumber)                upbhogtaDao.updateLastOnlineByNumber(lastSeen, userNumber)                if (upbhogtaUser != null) {                    // Update username and about                    upbhogtaDao.updateOnlineNameAndAboutByNumber(                        userNumber = userNumber,                        onlineName = userName,                        about = about                    )                    // ----------------------------------------                    // ? CASE 1: Profile Removed                    // ----------------------------------------                    if (newProfileTime == 0L && upbhogtaUser.imageTime > 0L) {                        DLog.i("? Profile removed for $userNumber")                        // Remove locally                        upbhogtaDao.updateImageTimeByNumber(userNumber, 0L)                        contactDao.updateImageTimeByNumber(userNumber, 0L)                        groupDao.updateProfileTimeForUser(userNumber, 0L)                        replaceUri(userNumber, null)                        return@launch                    }                    if (newProfileTime != upbhogtaUser.imageTime && newProfileTime > 0) {                        DLog.i("? New profile image for $userNumber")                        val existingUser = contactDao.getUserContactByNumber(userNumber)                        if (existingUser != null) {                            contactDao.updateImageTimeByNumber(existingUser.number, newProfileTime)                        }                        upbhogtaDao.updateImageTimeByNumber(userNumber, newProfileTime)                        groupDao.updateProfileTimeForUser(userNumber, newProfileTime)                        // Send request for profile image                        val unsentFiles = UnsentFiles(                            messageId = createMessageID(),                            receiver = userNumber,                            data = profileData ?: "",                            dataType = FileDataType.GET_PROFILE_PIC                        )                        insertSendData(unsentFiles)                        if (!sendingFileInProgress) sendUnsentFiles()                    }                } else {                    DLog.i("?? User not found in upbhogta table, skipping update: $userNumber")                }            }        }    }    private val storyMutex = Mutex()    fun processHomeStoriesList(stories: JsonArray) {        CoroutineScope(Dispatchers.IO).launch {            storyMutex.withLock {                try {                    DLog.i("STORY HOME: stories=${stories.size()}")                    val serverStoriesByOwner =                        mutableMapOf<String, MutableList<JsonObject>>()                    stories.forEach { element ->                        if (!element.isJsonObject) return@forEach                        val story = element.asJsonObject                        val ownerId = story.get(JsonKeys.USER_NUMBER)                            ?.takeUnless { it.isJsonNull }                            ?.asString                            ?.takeIf { it.isNotBlank() }                            ?: return@forEach                        serverStoriesByOwner                            .getOrPut(ownerId) { mutableListOf() }                            .add(story)                    }                    val storiesToDownload = mutableListOf<Pair<String, String>>()                    for ((ownerId, serverStories) in serverStoriesByOwner) {                        val actualServerStories = serverStories.filter {                            it.get(DootawasMessage.STORY_ID)                                ?.takeUnless { value -> value.isJsonNull }                                ?.asString                                ?.isNotBlank() == true                        }                        val serverStoryIds = actualServerStories                            .mapNotNull {                                it.get(DootawasMessage.STORY_ID)                                    ?.takeUnless { value -> value.isJsonNull }                                    ?.asString                            }                            .toSet()                        val localStories = storyDao.getStoriesByOwner(ownerId)                        DLog.i(                            "STORY HOME: owner=$ownerId local=${localStories.size} server=${actualServerStories.size}"                        )                        // -------------------------------------------------                        // USER HAS NO STORIES                        // -------------------------------------------------                        if (actualServerStories.isEmpty()) {                            if (localStories.isNotEmpty()) {                                DLog.i(                                    "STORY HOME: removing ${localStories.size} old stories from $ownerId"                                )                                storyDao.deleteByOwner(ownerId)                            }                            continue                        }                        // -------------------------------------------------                        // DELETE STORIES REMOVED FROM SERVER                        // -------------------------------------------------                        val deletedStories = localStories.filter {                            it.id !in serverStoryIds                        }                        for (deletedStory in deletedStories) {                            DLog.i(                                "STORY HOME: deleting removed story=${deletedStory.id} owner=$ownerId"                            )                            storyDao.deleteById(deletedStory.id)                        }                        // -------------------------------------------------                        // ADD / CHECK STORIES                        // -------------------------------------------------                        for (story in actualServerStories) {                            val storyId = story.get(DootawasMessage.STORY_ID)                                ?.takeUnless { it.isJsonNull }                                ?.asString                                ?.takeIf { it.isNotBlank() }                                ?: continue                            val storyPass = story.get(DootawasMessage.STORY_PASS)                                ?.takeUnless { it.isJsonNull }                                ?.asString                                ?.takeIf { it.isNotBlank() }                            val existingStory = storyDao.getById(storyId)                            // -------------------------------------------------                            // STORY ALREADY EXISTS                            // -------------------------------------------------                            if (existingStory != null) {                                if (!storyPass.isNullOrBlank() &&                                    existingStory.storyPass != storyPass                                ) {                                    DLog.i(                                        "STORY HOME: updating pass for story=$storyId"                                    )                                    storyDao.updateStoryPass(                                        storyId = storyId,                                        storyPass = storyPass                                    )                                }                                if (!existingStory.isStoryDownloaded) {                                    DLog.i(                                        "STORY HOME: story=$storyId exists but is NOT downloaded -> request download"                                    )                                    storiesToDownload.add(                                        storyId to ownerId                                    )                                } else {                                    DLog.i(                                        "STORY HOME: story=$storyId already downloaded -> skip"                                    )                                }                                continue                            }                            // -------------------------------------------------                            // NEW STORY                            // -------------------------------------------------                            val mediaType = story.get(DootawasMessage.MEDIA_TYPE)                                ?.takeUnless { it.isJsonNull }                                ?.asString                                ?: continue                            val durationMs = story.get(DootawasMessage.DURATION)                                ?.takeUnless { it.isJsonNull }                                ?.asLong                            val createdAt = story.get(JsonKeys.TIME_STAMP)                                ?.takeUnless { it.isJsonNull }                                ?.asLong                                ?: 0L                            val storyEntity = StoryEntity(                                id = storyId,                                ownerId = ownerId,                                mediaUrl = null,                                thumbnailUrl = null,                                localPath = null,                                mediaType = StoryMediaType.valueOf(mediaType),                                visibility = StoryVisibility.EVERYONE,                                allowedContactIds = emptyList(),                                durationMs = durationMs,                                createdAt = createdAt,                                expiresAt = createdAt + 24 * 60 * 60 * 1000L,                                isStoryDownloaded = false,                                storyPass = storyPass                            )                            storyDao.upsert(storyEntity)                            storiesToDownload.add(                                storyId to ownerId                            )                            DLog.i(                                "STORY HOME: new story=$storyId owner=$ownerId -> download required"                            )                        }                    }                    // -----------------------------------------------------                    // REMOVE DUPLICATES                    // -----------------------------------------------------                    val uniqueStoriesToDownload =                        storiesToDownload.distinct()                    // -----------------------------------------------------                    // ONE REQUEST FOR ALL STORIES NEEDING DOWNLOAD                    // -----------------------------------------------------                    if (uniqueStoriesToDownload.isNotEmpty()) {                        DLog.i(                            "STORY HOME: requesting R2 URLs for ${uniqueStoriesToDownload.size} stories: $uniqueStoriesToDownload"                        )                        requestStoryDownloads(uniqueStoriesToDownload)                    } else {                        DLog.i(                            "STORY HOME: no stories require download"                        )                    }                } catch (e: Exception) {                    DLog.e(                        "STORY HOME: failed to process stories: ${e.message}",                        e                    )                }            }        }    }    private suspend fun processStoryDownloadUrls(        stories: JsonArray    ) = withContext(Dispatchers.IO) {        for (element in stories) {            if (!element.isJsonObject) continue            val story = element.asJsonObject            val storyId = story.get(DootawasMessage.STORY_ID)                ?.takeUnless { it.isJsonNull }                ?.asString                ?.takeIf { it.isNotBlank() }                ?: continue            val downloadUrl = story.get(JsonKeys.DOWNLOAD_URL)                ?.takeUnless { it.isJsonNull }                ?.asString                ?.takeIf { it.isNotBlank() }                ?: continue            try {                // -----------------------------------------                // Get story from local DB                // -----------------------------------------                val entity = storyDao.getById(storyId)                if (entity == null) {                    DLog.e("STORY: local story not found $storyId")                    continue                }                if (entity.isStoryDownloaded) {                    DLog.i("STORY: already downloaded $storyId")                    continue                }                // -----------------------------------------                // Password comes from local DB                // -----------------------------------------                val storyPass = entity.storyPass                    ?.takeIf { it.isNotBlank() }                if (storyPass == null) {                    DLog.e(                        "STORY: story password not found in DB $storyId"                    )                    continue                }                // -----------------------------------------                // Download encrypted ZIP from R2                // -----------------------------------------                val encryptedPath = downloadStoryFromR2(                    storyId = storyId,                    downloadUrl = downloadUrl                )                // -----------------------------------------                // Decrypt using stored story password                // -----------------------------------------                val decryptedPath = decryptStory(                    encryptedPath = encryptedPath,                    storyPass = storyPass,                    storyId = storyId,                    mediaType = entity.mediaType                )                // -----------------------------------------                // Mark story as downloaded                // -----------------------------------------                storyDao.markStoryDownloaded(                    storyId = storyId,                    localPath = decryptedPath                )                // -----------------------------------------                // Delete encrypted temporary ZIP                // -----------------------------------------                File(encryptedPath).delete()                DLog.i(                    "STORY: downloaded + decrypted story=$storyId owner=${entity.ownerId}"                )            } catch (e: Exception) {                DLog.e(                    "STORY: failed processing story=$storyId: ${e.message}",                    e                )            }        }    }    private suspend fun decryptStory(        encryptedPath: String,        storyPass: String,        storyId: String,        mediaType: StoryMediaType    ): String = withContext(Dispatchers.IO) {        val encryptedFile = File(encryptedPath)        if (!encryptedFile.exists()) {            throw IOException("Encrypted story file does not exist")        }        val storyDir = File(            context.filesDir,            "stories"        )        if (!storyDir.exists()) {            storyDir.mkdirs()        }        File(storyDir, ".nomedia").apply {            if (!exists()) createNewFile()        }        val extension = when (mediaType) {            StoryMediaType.IMAGE -> "jpg"            StoryMediaType.VIDEO -> "mp4"            StoryMediaType.TEXT -> TODO()        }        val outputFile = File(            storyDir,            "${storyId}.$extension"        )        val zipFile = ZipFile(            encryptedFile,            storyPass.toCharArray()        )        if (!zipFile.isValidZipFile) {            throw IOException("Invalid encrypted story ZIP")        }        val files = zipFile.fileHeaders        if (files.isEmpty()) {            throw IOException("Story ZIP is empty")        }        val fileHeader = files.first()        if (fileHeader.isDirectory) {            throw IOException("Story ZIP contains only a directory")        }        zipFile.extractFile(            fileHeader,            storyDir.absolutePath        )        val extractedFile = File(            storyDir,            fileHeader.fileName        )        if (!extractedFile.exists()) {            throw IOException("Story extraction failed")        }        if (outputFile.exists()) {            outputFile.delete()        }        if (!extractedFile.renameTo(outputFile)) {            extractedFile.copyTo(                outputFile,                overwrite = true            )            extractedFile.delete()        }        outputFile.absolutePath    }    private suspend fun downloadStoryFromR2(        storyId: String,        downloadUrl: String    ): String = withContext(Dispatchers.IO) {        val storiesDir = File(            context.filesDir,            "stories"        )        if (!storiesDir.exists()) {            storiesDir.mkdirs()        }        val destination = File(            storiesDir,            "$storyId"        )        val request = Request.Builder()            .url(downloadUrl)            .get()            .build()        okHttpClient.newCall(request).execute().use { response ->            if (!response.isSuccessful) {                throw IOException(                    "R2 download failed: HTTP ${response.code}"                )            }            val body = response.body                ?: throw IOException("R2 response body is empty")            body.byteStream().use { input ->                destination.outputStream().use { output ->                    input.copyTo(output)                }            }        }        destination.absolutePath    }    suspend fun sendStoryAction(        storyOwner: String,        request: JsonObject    ) {        try {            if (storyOwner.isBlank()) {                DLog.e("STORY ACTION: story owner is empty")                return            }            DLog.i(                "STORY ACTION: receiver=$storyOwner request=$request"            )            val unsentSandesh = UnsentSandesh(                messId = UUID.randomUUID().toString(),                receiver = storyOwner,                message = request.toString(),                dataType = DataType.STORY_ACTION,                isGroup = false            )            insertUnsentData(unsentSandesh)            sendUnsentMessages(false)            if (!sendingFileInProgress) {                sendUnsentFiles()            }        } catch (e: Exception) {            DLog.e(                "STORY ACTION: failed receiver=$storyOwner: ${e.message}",                e            )        }    }    private suspend fun requestStoryDownloads(        stories: List<Pair<String, String>>    ) {        if (stories.isEmpty()) return        try {            val request = JsonObject().apply {                addProperty(                    JsonKeys.FILE_TOKEN_TYPE,                    FileDataTypeToken.STORY_DOWNLOAD_REQUEST.value                )                val storiesArray = JsonArray()                stories.forEach { (storyId, ownerId) ->                    storiesArray.add(                        JsonObject().apply {                            addProperty(                                DootawasMessage.STORY_ID,                                storyId                            )                            addProperty(                                JsonKeys.USER_NUMBER,                                ownerId                            )                        }                    )                }                add(                    JsonKeys.STORIES,                    storiesArray                )            }            DLog.i(                "STORY: requesting R2 download URLs for ${stories.size} stories: $request"            )            val unsentSandesh = UnsentSandesh(                messId = UUID.randomUUID().toString(),                receiver = "server",                message = request.toString(),                dataType = DataType.FILE_PROCESS,                isGroup = false            )            insertUnsentData(unsentSandesh)            sendUnsentMessages(false)            if (!sendingFileInProgress) {                sendUnsentFiles()            }        } catch (e: Exception) {            DLog.e(                "STORY: failed to request R2 download URLs: ${e.message}",                e            )        }    }    fun processHomeProfilesList(profiles: JsonArray) {        CoroutineScope(Dispatchers.IO).launch {            statusAndProfileMutex.withLock {                profiles.forEach { jsonElement ->                    if (!jsonElement.isJsonObject) return@forEach                    val profile = jsonElement.asJsonObject                    val userNumber = profile.get(JsonKeys.USER_NUMBER)                        ?.takeUnless { it.isJsonNull }                        ?.asString ?: return@forEach                    val userName = profile.get(JsonKeys.USER_NAME)                        ?.takeUnless { it.isJsonNull }                        ?.asString                    val newProfileTime = profile.get(JsonKeys.TIME_STAMP)                        ?.takeUnless { it.isJsonNull }                        ?.asLong ?: 0L                    val profilePass = profile.get(JsonKeys.DATA)                        ?.takeUnless { it.isJsonNull }                        ?.asString ?: ""                    DLog.i("🔄 Processing $userNumber")                    val upbhogtaUser = upbhogtaDao.getUserByNumber(userNumber)                    if (upbhogtaUser != null) {                        if (newProfileTime == 0L && upbhogtaUser.imageTime > 0L) {                            DLog.i("🗑 Profile removed for $userNumber")                            // Remove locally                            upbhogtaDao.updateImageTimeByNumber(userNumber, 0L)                            contactDao.updateImageTimeByNumber(userNumber, 0L)                            groupDao.updateProfileTimeForUser(userNumber, 0L)                            replaceUri(userNumber, null)                            return@launch                        }                        if (newProfileTime != upbhogtaUser.imageTime && newProfileTime > 0) {                            DLog.i("🆕 New profile image for $userNumber")                            val existingUser = contactDao.getUserContactByNumber(userNumber)                            if (existingUser != null) {                                contactDao.updateImageTimeByNumber(                                    existingUser.number,                                    newProfileTime                                )                            }                            upbhogtaDao.updateImageTimeByNumber(userNumber, newProfileTime)                            groupDao.updateProfileTimeForUser(userNumber, newProfileTime)                            // Send request for profile image                            val unsentFiles = UnsentFiles(                                messageId = createMessageID(),                                receiver = userNumber,                                data = profilePass,                                dataType = FileDataType.GET_PROFILE_PIC                            )                            insertSendData(unsentFiles)                            if (!sendingFileInProgress) sendUnsentFiles()                        }                    } else {                        DLog.i("⚠️ User not found in upbhogta table, skipping update: $userNumber")                    }                }            }        }    }    fun processGroupMembersProfilesList(profiles: JsonArray) {        CoroutineScope(Dispatchers.IO).launch {            statusAndProfileMutex.withLock {                profiles.forEach { jsonElement ->                    if (!jsonElement.isJsonObject) return@forEach                    val profile = jsonElement.asJsonObject                    val userNumber = profile.get(JsonKeys.USER_NUMBER)                        ?.takeUnless { it.isJsonNull }                        ?.asString ?: return@forEach                    val userName = profile.get(JsonKeys.USER_NAME)                        ?.takeUnless { it.isJsonNull }                        ?.asString ?: ""                    val newProfileTime = profile.get(JsonKeys.TIME_STAMP)                        ?.takeUnless { it.isJsonNull }                        ?.asLong ?: 0L                    val profilePass = profile.get(JsonKeys.DATA)                        ?.takeUnless { it.isJsonNull }                        ?.asString ?: ""                    DLog.i("🔄 Processing $userNumber")                    // ✅ NEW: Update group_members table too                    val existingGroupMember = groupDao.getAnyGroupMemberByNumber(userNumber)                    if (existingGroupMember != null) {                        if (newProfileTime == 0L && existingGroupMember.profileTime > 0L) {                            DLog.i("🗑 Profile removed for $userNumber")                            // Remove locally                            upbhogtaDao.updateImageTimeByNumber(userNumber, 0L)                            contactDao.updateImageTimeByNumber(userNumber, 0L)                            groupDao.updateProfileTimeForUser(userNumber, 0L)                            replaceUri(userNumber, null)                            return@launch                        }                        if (newProfileTime != existingGroupMember.profileTime && newProfileTime > 0) {                            val existingUser = contactDao.getUserContactByNumber(userNumber)                            if (existingUser != null) {                                contactDao.updateImageTimeByNumber(                                    existingUser.number,                                    newProfileTime                                )                            }                            groupDao.updateProfileTimeForUser(userNumber, newProfileTime)                            val upbhogtaUser = upbhogtaDao.getUserByNumber(userNumber)                            if (upbhogtaUser != null) {                                upbhogtaDao.updateImageTimeByNumber(userNumber, newProfileTime)                            }                            // Send request for profile image                            val unsentFiles = UnsentFiles(                                messageId = createMessageID(),                                receiver = userNumber,                                data = profilePass,                                dataType = FileDataType.GET_PROFILE_PIC                            )                            insertSendData(unsentFiles)                            if (!sendingFileInProgress) sendUnsentFiles()                        }                        groupDao.updateGroupMemberOnlineName(userName,userNumber)                    }                }            }        }    }    fun processGroupHomeProfilesList(profiles: JsonArray) {        CoroutineScope(Dispatchers.IO).launch {            statusAndProfileMutex.withLock {                profiles.forEach { jsonElement ->                    if (!jsonElement.isJsonObject) return@forEach                    val profile = jsonElement.asJsonObject                    val userNumber = profile.get(JsonKeys.GROUP_ID)                        ?.takeUnless { it.isJsonNull }                        ?.asString ?: return@forEach                    val newProfileTime = profile.get(JsonKeys.TIME_STAMP)                        ?.takeUnless { it.isJsonNull }                        ?.asLong ?: 0L                    val profilePass = profile.get(JsonKeys.DATA)                        ?.takeUnless { it.isJsonNull }                        ?.asString ?: ""                    DLog.i("🔄 Processing $userNumber")                    val group = groupDao.getGroupById(userNumber)                    if (group != null) {                        if (newProfileTime != group.imageTime && newProfileTime > 0) {                            DLog.i("🆕 New profile image for $userNumber")                            groupDao.updateImageTimeByNumber(userNumber, newProfileTime)                            // Send request for profile image                            val unsentFiles = UnsentFiles(                                messageId = createMessageID(),                                receiver = userNumber,                                data = profilePass,                                dataType = FileDataType.GET_PROFILE_PIC,                                isGroup = true                            )                            insertSendData(unsentFiles)                            if (!sendingFileInProgress) sendUnsentFiles()                        }                    } else {                        DLog.i("⚠️ User not found in upbhogta table, skipping update: $userNumber")                    }                }            }        }    }    fun loginDootawas() {        CoroutineScope(Dispatchers.IO).launch {            DLog.i("LOGIN DAKIYA")//            DLog.i("Login credentials retrieved: username=$userNameKhud. Proceeding with login...")            loginRequest(userNumberKhud.firstOrNull(), userSamabhashKhud.firstOrNull())        }    }    private var dataTypeAck: DataType? = null    private var messageIDWork: String? = null    private var ackAwaiter: CompletableDeferred<Boolean>? = null    private suspend fun waitForResponse(): Boolean {        ackAwaiter = CompletableDeferred()        return withTimeoutOrNull(5000.milliseconds) {            ackAwaiter?.await()        } == true    }    fun notifyResponseReceived(ackMessageId: String) {        if (ackMessageId == messageIDWork && ackAwaiter?.isActive == true) {            DLog.i("✅ notifyAckReceived called for $ackMessageId")            ackAwaiter?.complete(true)        }    }    fun notifyResponseReceivedWithoutID() {        ackAwaiter?.complete(true)    }    fun addToMessageSentUsage(bytes: Int, isMobileData: Boolean) {        coroutineScope.launch {            val key = if (isMobileData) SettingPrefKeys.DATA_USAGE_MOBILE_MESSAGE_SENT else                SettingPrefKeys.DATA_USAGE_WIFI_MESSAGE_SENT            dataUsageMutex.withLock {                settingStore.edit { prefs ->                    val current = prefs[key] ?: 0                    prefs[key] = current + bytes                }            }        }    }    suspend fun requestLiveLocationRoute(        sandeshId: String,        originLat: Double,        originLng: Double,        destinationLat: Double,        destinationLng: Double    ){        // 🚫 Validate token first        if (sessionToken.isNullOrBlank()) {            DLog.e("Session token is null or empty")            isParmaan = false            SocketManager.forceReconnect()            return;        }        val jsonObject = JsonObject().apply {            addProperty(JsonKeys.DATA_TYPE, DataType.LIVE_LOCATION_ROUTE.value)            addProperty(JsonKeys.MESSAGE_ID, sandeshId)            addProperty(JsonKeys.ORIGIN_LATITUDE, originLat)            addProperty(JsonKeys.ORIGIN_LONGITUDE, originLng)            addProperty(JsonKeys.DESTINATION_LATITUDE, destinationLat)            addProperty(JsonKeys.DESTINATION_LONGITUDE, destinationLng)            addProperty(JsonKeys.USER_NUMBER, userNumberKhud.firstOrNull())            addProperty(JsonKeys.SAMABHASH_TOKEN, sessionToken)        }        val sent = SocketManager.send(jsonObject.toString())    }    // Keyed by "receiver:messageId" — counts how many times writeJsonToSession has    // been asked to send the SAME message to the SAME receiver. Past the threshold,    // we stop actually sending (likely a retry loop caused by something upstream)    // and just report success so the caller doesn't keep spinning.    // NOTE: this map grows unbounded per unique (receiver, messageId) pair and is    // only cleared on a successful send below — if you have long-lived messageIds    // that legitimately never succeed, this can leak memory over a long session.    // Worth revisiting with a TTL or periodic sweep if that turns out to matter.    private val duplicateSendCounts = java.util.concurrent.ConcurrentHashMap<String, java.util.concurrent.atomic.AtomicInteger>()    private val duplicateSendThreshold = 10    private suspend fun writeJsonToSession(jsonObject: JsonObject, overrideParmaan: Boolean = false): Boolean {        val caller = Throwable().stackTrace.firstOrNull {            it.className != this::class.java.name ||                    !it.methodName.startsWith("writeJsonToSession")        }        DLog.i("writeJsonToSession called by: $caller")        var dedupeKey: String? = null        if (!overrideParmaan) {            if (!isParmaan) {                DLog.i("Parmaan is False")                SocketManager.forceReconnect()                return false            }// 🚫 Validate token first            if (sessionToken.isNullOrBlank()) {                DLog.e("Session token is null or empty")                isParmaan = false                SocketManager.forceReconnect()                return false            }// 🚫 Validate tokenTime            if (tokenTime <= 0L) {                DLog.e("Token time is invalid: $tokenTime")                isParmaan = false                SocketManager.forceReconnect()                return false            }// ⏰ Token expiry check            val currentTime = System.currentTimeMillis()            val isExpired = currentTime - tokenTime > 14 * 60 * 1000L            if (isExpired) {                DLog.i("Session token expired")                isParmaan = false                SocketManager.forceReconnect()                return false            }            val messageId = jsonObject.get(JsonKeys.MESSAGE_ID)?.asString            val receiver = jsonObject.get(JsonKeys.RECEIVER)?.asString            if (!messageId.isNullOrBlank() && !receiver.isNullOrBlank()) {                dedupeKey = "$receiver:$messageId"                val attempts = duplicateSendCounts                    .computeIfAbsent(dedupeKey) { java.util.concurrent.atomic.AtomicInteger(0) }                    .incrementAndGet()                if (attempts > duplicateSendThreshold) {                    DLog.i("writeJsonToSession: $dedupeKey called $attempts times — short-circuiting, returning true")                    return true                }            }            // ✅ Attach token            jsonObject.addProperty(JsonKeys.SAMABHASH_TOKEN, sessionToken)        }        val message = jsonObject.toString()        val messageSizeInBytes = message.toByteArray(Charsets.UTF_8).size        if (messageSizeInBytes > 4096) {            DLog.e("Message too large: $messageSizeInBytes bytes")        }        // 🔥 SEND VIA SOCKET MANAGER        val sent = SocketManager.send(message)        if (!sent) {            DLog.i("Socket not ready → send failed")            return false        }        DLog.i("Write to Session: $jsonObject")        // 🔥 Wait for response (your existing logic)        return waitForResponse().also { result ->            if (!result) {                DLog.i("wait false → resetting session : $jsonObject")                isParmaan = false                // 🔥 reconnect cleanly                SocketManager.forceReconnect()            } else {                DLog.i("wait true")                addToMessageSentUsage(messageSizeInBytes, isOnMobileData)            }        }    }    fun createOrderID(        amount: Int,        orderType: PurchaseOrderType = PurchaseOrderType.OTHER    ) {        CoroutineScope(Dispatchers.IO).launch {            val orderJsonObject = JsonObject().apply {                addProperty(JsonKeys.DATA_TYPE, DataType.CREATE_ORDER_ID.value)                addProperty(JsonKeys.AMOUNT, amount)                addProperty(JsonKeys.CURRENCY, "INR")                addProperty(JsonKeys.TIME_STAMP, System.currentTimeMillis())                addProperty(JsonKeys.USER_NUMBER, userNumberKhud.firstOrNull())                addProperty(JsonKeys.ORDER_TYPE, orderType.value)            }            writeJsonToSessionNoLogin(orderJsonObject)        }    }    fun writeJsonToSessionNoLogin(jsonObject: JsonObject): Boolean {        return try {                val messageString = jsonObject.toString()                val messageSizeInBytes = messageString.toByteArray(Charsets.UTF_8).size                if (messageSizeInBytes > 4096) {                    DLog.i("Message too large to send (no login): $messageSizeInBytes bytes")                }                val sent = SocketManager.send(messageString)                DLog.i("Write to Session (No Login): $jsonObject")                if (sent) {                    addToMessageSentUsage(messageSizeInBytes, isOnMobileData)                    true                } else {                    DLog.i("❌ WebSocket.send() failed (connection likely closed)")                    false                }        } catch (e: Exception) {            DLog.i("❌ Exception while writing to WebSocket (No Login): ${e.message}")            false        }    }    fun rejectCall(user: String) {        val ackJson = JsonObject().apply {            addProperty(JsonKeys.DATA_TYPE, DataType.CALL_DATA.value)            addProperty(JsonKeys.CALL_DATA_TYPE, CallDataType.REJECTED.value)            addProperty(JsonKeys.RECEIVER, user)            addProperty(JsonKeys.MESSAGE_ID, createMessageID())            addProperty(JsonKeys.SANDESH, "ACK DATA")            addProperty(JsonKeys.PROFILE_ID, "")        }//        writeJsonToSessionCall(ackJson)    }    suspend fun sendCallData(callData: CallData) {        val jsonObject = Gson().toJsonTree(callData).asJsonObject        writeJsonToSessionCall(jsonObject)    }    private suspend fun writeJsonToSessionCall(jsonObject: JsonObject) {        try {            val target = jsonObject.get(JsonKeys.TARGET)?.asString ?: return            // Receiver: CallData already carries the flag stored from the invite,            // so keep it. Caller: nothing in CallData, so read it from the DB.            val existing = jsonObject.get(JsonKeys.REVEAL_SENDER_NUMBER)            if (existing == null || existing.isJsonNull) {                val revealSender = upbhogtaDao.getRevealSender(target) ?: false                jsonObject.addProperty(JsonKeys.REVEAL_SENDER_NUMBER, revealSender)            }            jsonObject.addProperty(JsonKeys.SAMABHASH_TOKEN, sessionToken)            jsonObject.addProperty(JsonKeys.DATA_TYPE, DataType.CALL_DATA.value)            val messageString = jsonObject.toString()            val messageSizeInBytes = messageString.toByteArray(Charsets.UTF_8).size            if (messageSizeInBytes > 4096) {                DLog.i("Call data too large: $messageSizeInBytes bytes")            }            if (SocketManager.send(messageString)) {                addToMessageSentUsage(messageSizeInBytes, isOnMobileData)            } else {                DLog.i("WebSocket.send() failed (connection likely closed)")            }        } catch (e: Exception) {            DLog.i("Exception while writing call data: ${e.message}")        }    }    private fun createMessageID(): String {        return UUID.randomUUID().toString()    }    fun generateRSAKeyPair(alias: String) {        val keyGen =            KeyPairGenerator.getInstance(KeyProperties.KEY_ALGORITHM_RSA, "AndroidKeyStore")        val spec = KeyGenParameterSpec.Builder(            alias,            KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT        ).setKeySize(2048)            .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_RSA_PKCS1)            .build()        keyGen.initialize(spec)        keyGen.generateKeyPair()    }    fun generateRSAKeyPairIfNotExists(alias: String) {        val keyStore = KeyStore.getInstance("AndroidKeyStore").apply { load(null) }        if (keyStore.containsAlias(alias)) {            DLog.i("🔑 Key already exists for alias: $alias")            return // Do not generate again        }        val keyGen =            KeyPairGenerator.getInstance(KeyProperties.KEY_ALGORITHM_RSA, "AndroidKeyStore")        val spec = KeyGenParameterSpec.Builder(            alias,            KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT        ).setKeySize(2048)            .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_RSA_PKCS1)            .build()        keyGen.initialize(spec)        keyGen.generateKeyPair()        DLog.i("✅ New RSA key pair generated for alias: $alias")    }    fun generateGroupKeyIfNotExists(groupId: String) {        val alias = "dootawas_group_key_$groupId"        val keyStore = KeyStore.getInstance("AndroidKeyStore").apply { load(null) }        if (keyStore.containsAlias(alias)) {            DLog.i("✅ Group key already exists for alias: $alias")            return        }        val keyGen =            KeyPairGenerator.getInstance(KeyProperties.KEY_ALGORITHM_RSA, "AndroidKeyStore")        val spec = KeyGenParameterSpec.Builder(            alias,            KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT        ).setKeySize(2048)            .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_RSA_PKCS1)            .build()        keyGen.initialize(spec)        keyGen.generateKeyPair()        DLog.i("✅ New RSA key pair generated for group alias: $alias")    }    fun askKey(userNumber: String) {        coroutineScope.launch {            writeMessageMutex.withLock {                val unsentSandesh = UnsentSandesh(                    messId = createMessageID(),                    receiver = userNumber,                    message = "any",                    dataType = DataType.ASK_KEY                )                DLog.i("Sending KEY: $unsentSandesh")                insertUnsentData(unsentSandesh)                sendUnsentMessages(false)            }        }    }    fun isValidPublicKey(pubKeyBase64: String?): Boolean {        if (pubKeyBase64.isNullOrBlank()) return false        return try {            // Use Android Base64 decode if on Android            val keyBytes = Base64.decode(pubKeyBase64, Base64.DEFAULT)            val keySpec = X509EncodedKeySpec(keyBytes)            val keyFactory = KeyFactory.getInstance("RSA")            val publicKey = keyFactory.generatePublic(keySpec)            // Optional: confirm algorithm is RSA            publicKey.algorithm.equals("RSA", ignoreCase = true)        } catch (e: IllegalArgumentException) {            DLog.i("❌ Invalid Base64 input: ${e.message}")            false        } catch (e: InvalidKeySpecException) {            DLog.i("❌ Invalid key spec: ${e.message}")            false        } catch (e: NoSuchAlgorithmException) {            DLog.i("❌ RSA algorithm not available: ${e.message}")            false        } catch (e: Exception) {            DLog.i("❌ Unknown error validating public key: ${e.message}")            false        }    }    suspend fun decryptGroupJsonObject(        encryptedJson: JsonObject    ): JsonObject {        return try {            val protocolVersion = encryptedJson                .get(DootawasMessage.GROUP_CRYPTO_PROTOCOL_VERSION)                ?.asInt                ?: throw IllegalArgumentException("Missing group crypto protocol version")            val groupId = encryptedJson                .get(JsonKeys.GROUP_ID)                ?.asString                ?: throw IllegalArgumentException("Missing group ID")            val epoch = encryptedJson                .get(DootawasMessage.GROUP_EPOCH)                ?.asLong                ?: throw IllegalArgumentException("Missing group epoch")            val senderId = encryptedJson                .get(DootawasMessage.GROUP_SENDER_ID)                ?.asString                ?: throw IllegalArgumentException("Missing group sender ID")            val senderDeviceId = encryptedJson                .get(DootawasMessage.GROUP_SENDER_DEVICE_ID)                ?.asString                ?: throw IllegalArgumentException("Missing group sender device ID")            val messageId = encryptedJson                .get(JsonKeys.MESSAGE_ID)                ?.asString                ?: throw IllegalArgumentException("Missing message ID")            val messageNumber = encryptedJson                .get(DootawasMessage.GROUP_MESSAGE_NUMBER)                ?.asLong                ?: throw IllegalArgumentException("Missing group message number")            val nonceBase64 = encryptedJson                .get(DootawasMessage.GROUP_NONCE)                ?.asString                ?: throw IllegalArgumentException("Missing group nonce")            val ciphertextBase64 = encryptedJson                .get(JsonKeys.SANDESH)                ?.asString                ?: throw IllegalArgumentException("Missing encrypted group message")            val message = GroupMessage(                protocolVersion = protocolVersion,                groupId = groupId,                epoch = epoch,                senderId = senderId,                senderDeviceId = senderDeviceId,                messageId = messageId,                messageNumber = messageNumber,                nonce = Base64.decode(nonceBase64, Base64.NO_WRAP),                ciphertext = Base64.decode(ciphertextBase64, Base64.NO_WRAP)            )            val decryptedJsonString = groupCryptoManager.receiveMessage(                groupId = groupId,                message = message            )            val parsed = JsonParser.parseString(decryptedJsonString)            if (!parsed.isJsonObject) {                DLog.e("DECRYPT GROUP FAILED: Decrypted payload is not a JSON object")                JsonObject().apply {                    addProperty(                        "error",                        "Invalid JSON object after group decryption"                    )                }            } else {                DLog.i("DECRYPT GROUP PASSED messageId=$messageId groupId=$groupId")                parsed.asJsonObject            }        } catch (e: Exception) {            DLog.e("Group decryption failed", e)            JsonObject().apply {                addProperty(                    "error",                    "Group decryption failed: ${e.message ?: "Unknown error"}"                )            }        }    }    /**     * Decrypts an incoming Signal message (X3DH or PQXDH/Kyber).     * Uses only Gson — no kotlinx.serialization.     */    private fun shouldSkipMessage(messageId: String): Boolean {        val count = (decryptFailures[messageId] ?: 0) + 1        decryptFailures[messageId] = count        return count >= 5    }    private val decryptFailures = ConcurrentHashMap<String, Int>()    suspend fun decryptJsonObject(        senderNumber: String,        messageId: String,        encryptedJson: JsonObject,    ): JsonObject = withContext(Dispatchers.IO) {        try {            val address = SignalProtocolAddress(senderNumber, 1)            val sessionCipher = SessionCipher(roomSignalStore, address)            val ciphertextBase64 = encryptedJson.get(DootawasMessage.CIPHER_MESSAGE)?.asString                    ?: return@withContext errorJson("Missing ciphertext")            val ciphertextBytes = Base64.decode(ciphertextBase64, Base64.NO_WRAP)            val cipherMessageType = encryptedJson.get(DootawasMessage.CIPHER_MESSAGE_TYPE)?.asString                    ?: return@withContext errorJson("Missing cipher message type")            val message = when (cipherMessageType) {                    DootawasMessage.CIPHER_TYPE_PREKEY -> PreKeySignalMessage(ciphertextBytes)                    DootawasMessage.CIPHER_TYPE_WHISPER -> SignalMessage(ciphertextBytes)                    DootawasMessage.CIPHER_TYPE_UNKNOWN -> return@withContext errorJson("Unknown cipher message type")                    else -> return@withContext errorJson("Invalid cipher message type")                }            val plaintextBytes = when (message) {                    is PreKeySignalMessage -> sessionCipher.decrypt(message)                    is SignalMessage -> sessionCipher.decrypt(message)                    else -> return@withContext errorJson("Unsupported cipher message")                }            val decryptedString = String(plaintextBytes, Charsets.UTF_8)            // Parse with Gson instead of kotlinx.serialization            val parsedJson = gson.fromJson(decryptedString, JsonObject::class.java)            DLog.i("Decryption SUCCESS • PQXDH: ${roomSignalStore.loadSession(address).sessionVersion >= 4}")            DLog.i(decryptedString)            parsedJson        } catch (e: DuplicateMessageException) {            DLog.i("Duplicate message from $senderNumber")            gson.toJsonTree(mapOf("duplicate" to true)).asJsonObject        } catch (e: NoSessionException) {            DLog.i("NoSessionException from $senderNumber")            if (shouldSkipMessage(messageId)) {                errorJson("SKIP")            } else {                errorJson("ASK_KEY")            }        } catch (e: UntrustedIdentityException) {            DLog.i("UntrustedIdentityException from $senderNumber")            val msgType = encryptedJson.get(DootawasMessage.CIPHER_MESSAGE_TYPE)?.asString            val msgBytes = encryptedJson.get(DootawasMessage.CIPHER_MESSAGE)?.asString                ?.let { Base64.decode(it, Base64.NO_WRAP) }            val newIdentity: IdentityKey? = when {                msgType == DootawasMessage.CIPHER_TYPE_PREKEY && msgBytes != null -> {                    try {                        PreKeySignalMessage(msgBytes).identityKey                    } catch (parseErr: Exception) {                        DLog.e("Failed to parse identity key from PreKeySignalMessage", parseErr)                        null                    }                }                else -> e.untrustedIdentity            }            if (newIdentity == null) {                if (shouldSkipMessage(messageId)) {                    return@withContext errorJson("SKIP")                }                return@withContext errorJson("ASK_KEY")            }            val address = SignalProtocolAddress(senderNumber, 1)            try {                roomSignalStore.acceptNewIdentityAndResetSession(                    address = address,                    identityKey = newIdentity                )                DLog.i("New identity accepted and old session deleted for $senderNumber")                return@withContext decryptJsonObject(                    senderNumber = senderNumber,                    messageId = messageId,                    encryptedJson = encryptedJson                )            } catch (resetException: Exception) {                DLog.e("Failed to accept new identity/reset session: ${resetException::class.simpleName}: ${resetException.message}")                if (shouldSkipMessage(messageId)) {                    return@withContext errorJson("SKIP")                }                return@withContext errorJson("ASK_KEY")            }        } catch (e: InvalidMessageException) {            DLog.e("❌ InvalidMessageException from $senderNumber: ${e.message}")            if (shouldSkipMessage(messageId)) {                errorJson("SKIP")            } else {                errorJson("ASK_KEY")            }        } catch (e: InvalidKeyException) {            DLog.e("❌ InvalidKeyException from $senderNumber: ${e.message}")            if (shouldSkipMessage(messageId)) errorJson("SKIP") else errorJson("ASK_KEY")        } catch (e: LegacyMessageException) {            DLog.e("❌ LegacyMessageException from $senderNumber")            errorJson("SKIP") // correct — legacy protocol, resending won't fix it        } catch (e: Exception) {            DLog.e("❌ UNKNOWN ${e::class.java.simpleName} from $senderNumber: ${e.message}")            e.printStackTrace()            if (shouldSkipMessage(messageId)) errorJson("SKIP") else errorJson("ASK_KEY")        }    }    private fun errorJson(message: String): JsonObject {        DLog.i("DECRYPT ERROR -> $message")        return JsonObject().apply {            addProperty("error", message)        }    }    fun encryptJsonObject(        receiverNumber: String,        json: JsonObject    ): JsonObject {        val address = SignalProtocolAddress(receiverNumber, 1)        val sessionCipher = SessionCipher(roomSignalStore, address)        val messageBytes =            json.toString().toByteArray(Charsets.UTF_8)        val encryptedMessage =            sessionCipher.encrypt(messageBytes)        val ciphertext =            Base64.encodeToString(                encryptedMessage.serialize(),                Base64.NO_WRAP            )        val type =            when (encryptedMessage.type) {                CiphertextMessage.PREKEY_TYPE -> DootawasMessage.CIPHER_TYPE_PREKEY                CiphertextMessage.WHISPER_TYPE -> DootawasMessage.CIPHER_TYPE_WHISPER                else -> DootawasMessage.CIPHER_TYPE_UNKNOWN            }        return JsonObject().apply {            addProperty(JsonKeys.RECEIVER, receiverNumber)            addProperty(DootawasMessage.CIPHER_MESSAGE_TYPE, type)            addProperty(DootawasMessage.CIPHER_MESSAGE, ciphertext)        }    }    fun typingMessage(userName: String?) {        coroutineScope.launch {            // Check if typing indicators are enabled            val isTypingEnabled = settingFlow(SettingPrefKeys.CHAT_MESSAGE_TYPING_INDICATORS, false)                .first() // suspends until first value is available            if (!isTypingEnabled) {                DLog.i("✋ Typing indicators are disabled. Skipping send.")                return@launch            }            DLog.i("SEND WRITE EXEC TO TYPING MESSAGE")            val typing = JsonObject().apply {                addProperty(JsonKeys.DATA_TYPE, DataType.TYPING.value)                addProperty(JsonKeys.RECEIVER, userName)            }            writeJsonToSessionNoLogin(typing)        }    }    private suspend fun loginRequest(username: String?, password: String?) {        if (username.isNullOrBlank() || password.isNullOrBlank() || eKey.isNullOrBlank()) {            DLog.i("Missing credentials or key, register")            sessionIdReq()            return        }        // Encrypt both username and password using public key        val encryptedUsername = encryptRSA(username, eKey!!)        val encryptedPassword = encryptRSA(password, eKey!!)        DLog.i("Encrypted username: $encryptedUsername")        DLog.i("Encrypted password: $encryptedPassword")        dataTypeAck = DataType.LOGIN        val loginRequest = JsonObject().apply {            addProperty(JsonKeys.USER_NUMBER, encryptedUsername)            addProperty(JsonKeys.PASSWORD, encryptedPassword)            addProperty(JsonKeys.DATA_TYPE, DataType.LOGIN.value)        }        if (encryptedPassword!=password){            writeJsonToSession(loginRequest,true)        }    }    // 🔒 RSA encryption helper    private fun encryptRSA(plainText: String, base64PublicKey: String): String {        val keyBytes = Base64.decode(base64PublicKey, Base64.DEFAULT)        val keySpec = X509EncodedKeySpec(keyBytes)        val keyFactory = KeyFactory.getInstance("RSA")        val publicKey = keyFactory.generatePublic(keySpec)        val cipher = Cipher.getInstance("RSA/ECB/PKCS1Padding")        cipher.init(Cipher.ENCRYPT_MODE, publicKey)        val encryptedBytes = cipher.doFinal(plainText.toByteArray(Charsets.UTF_8))        return Base64.encodeToString(encryptedBytes, Base64.NO_WRAP)    }    fun sendToken(token: String?) {        coroutineScope.launch {            DLog.i("token request")            val msgId: String = createMessageID()            val unsentSandesh = UnsentSandesh(                messId = msgId,                receiver = "null",                message = token,                dataType = DataType.FCM_TOKEN            )            insertUnsentData(unsentSandesh)            sendUnsentMessages(false)        }    }    private fun sessionIdReq() {        coroutineScope.launch {            registerStatus = RegisterStatus()            DLog.i("sent register Req")            dataTypeAck = DataType.ASK_REGISTER_KEY            val askRegisterKey = JsonObject() // Kotlin can infer that this is of type JsonObject            askRegisterKey.addProperty(JsonKeys.DATA_TYPE, DataType.ASK_REGISTER_KEY.value)            writeJsonToSession(askRegisterKey,true)        }    }    /**     * we can skip this method but its only for save space caus a lot of calling this method     * Persists a delivery confirmation to the local database and triggers a message sync.     * * This method ensures reliability by creating an [UnsentSandesh] record before     * attempting transmission. If the network is unavailable, the message remains     * in the local store for future retry attempts.     *     * @param messageId The unique identifier of the message to be confirmed.     * @param receiver The recipient's unique ID or destination address.     * @param messageB The raw message content or payload.     * @param dataType The classification of the data being sent (e.g., TEXT, IMAGE).     * @param time The timestamp of the event; defaults to system current time if null.     * @param isGroupZ Set to true if the confirmation is destined for a group chat.     */    private suspend fun sendDeliveryConfirmation(        messageId: String,        receiver: String,        messageB: String,        dataType: DataType,        time: String? = null,        isGroupZ: Boolean = false,        sendSpringDelivery: Boolean = false,    ) {        val finalTime = time ?: Instant.now().toEpochMilli().toString()        val sandeshJson = runCatching {            JsonParser.parseString(messageB).asJsonObject        }.getOrElse { JsonObject() }        sandeshJson.remove(JsonKeys.MESSAGE_ID)        val revealSender = if (isGroupZ) {            groupDao.getRevealSender(receiver) ?: false        } else {            upbhogtaDao.getRevealSender(receiver) ?: false        }        sandeshJson.addProperty(JsonKeys.REVEAL_SENDER_NUMBER,revealSender)        val sender = userNumberKhud.firstOrNull()        if (sender.isNullOrBlank()) {            return        }        val json = JsonObject()        // 🔹 REQUIRED IN ALL TYPES        json.addProperty(JsonKeys.SENDER, sender)        json.addProperty(JsonKeys.RECEIVER, receiver)        json.addProperty(JsonKeys.MESSAGE_ID, messageId)        json.addProperty(JsonKeys.DATA_TYPE, dataType.value)        json.addProperty(JsonKeys.TIME_STAMP, finalTime)        json.addProperty(JsonKeys.IS_LOGIN, true)        json.add(JsonKeys.SANDESH, sandeshJson)        // 🔹 CONDITIONAL KEYS (STRICT MATCH)        when (dataType) {            DataType.SEEN_STATUS ->{                json.addProperty(JsonKeys.IS_GROUP, isGroupZ)            }            DataType.DELIVERY_CONFIRMATION -> {                json.addProperty(JsonKeys.IS_GROUP, isGroupZ)            }            DataType.SEEN_DELIVERED,            DataType.DELIVERY_DELIVERED,            DataType.MALFUNCTION_JSON -> {                // 🚫 DO NOT ADD IS_GROUP            }            else -> {                // Optional: log unexpected type                DLog.e("Unknown DataType: $dataType")            }        }        if (sendSpringDelivery){            val token = userDataStore.data.first()[PrefKeys.DELIVERY_TOKEN]            if (token == null) {                DLog.i("TOKEN NULL → stopping all sending immediately")                getDeliveryToken()                return            }            // Step 3: insert token into JSON            json.addProperty(JsonKeys.SAMABHASH_TOKEN, token)            val (success, _) = sendDeliveryReceiptSuspend(json.toString())            if (success) {                deleteUnsentData(                    messageId,                    dataType,                    receiver                )            }        }else{            // 🔥 VALIDATION (same as yours)            if (!isParmaan) {                DLog.i("Parmaan is False")                SocketManager.forceReconnect()                return            }            if (sessionToken.isNullOrBlank()) {                DLog.e("Session token is null or empty")                isParmaan = false                SocketManager.forceReconnect()                return            }            if (tokenTime <= 0L) {                DLog.e("Token time is invalid: $tokenTime")                isParmaan = false                SocketManager.forceReconnect()                return            }            val isExpired = System.currentTimeMillis() - tokenTime > 14 * 60 * 1000L            if (isExpired) {                DLog.i("Session token expired")                isParmaan = false                SocketManager.forceReconnect()                return            }            // ✅ REQUIRED for ALL            json.addProperty(JsonKeys.SAMABHASH_TOKEN, sessionToken)            SocketManager.send(json.toString())        }    }    suspend fun sendDeliveryReceiptSuspend(jsonBody: String): Pair<Boolean, String> {        return suspendCancellableCoroutine { cont ->            val call = ReceiptSender.send(jsonBody) { success, message ->                if (cont.isActive) {                    cont.resume(success to message)                }            }            cont.invokeOnCancellation {                call.cancel()            }        }    }    //region sendMessage    private var times: Int = 0    private var times2: Int = 0    private suspend fun isReceiverSelf(receiver: String?): Boolean {        if (receiver.isNullOrBlank()) return false        val khudNumber = userNumberKhud.firstOrNull()        val khudUserNameId = userNameIdKhud.firstOrNull()        val isSelfNumber = !khudNumber.isNullOrBlank() && receiver == khudNumber        val isSelfUserNameId = !khudUserNameId.isNullOrBlank() && receiver == khudUserNameId        return isSelfNumber || isSelfUserNameId    }    private fun isUuid(value: String): Boolean {        return try {            UUID.fromString(value)            true        } catch (e: IllegalArgumentException) {            false        }    }    fun sendUnsentMessages(onlyDataStatus: Boolean) {        val trace = Throwable().stackTrace        val caller = trace.getOrNull(1)   // 0 = this method, 1 = caller        coroutineScope.launch {            delay(50.milliseconds)            if (!sendMessageMutex.tryLock()) {                DLog.i("⛔ sendUnsentMessages already running — skipping")                return@launch            }            DLog.i("✅ sendUnsentMessages LOCK ACQUIRED")            DLog.i("int Times called $times")            times++            times2++            if (!isParmaan) {                while (true) {                    DLog.i("SENDING SPRING B")                    val unsentSandeshA =                        unsentSandeshDao.getEarliestUnsentByTypes(                            listOf(                                DataType.DELIVERY_CONFIRMATION,                                DataType.SEEN_STATUS                            )                        ) ?: break                    DLog.i("sending via spring")                    DLog.i("Sending DeliveryConfirmation")                    DLog.i("TO : " + unsentSandeshA.receiver)                    DLog.i("ID : " + unsentSandeshA.messId)                    DLog.i("Time : " + unsentSandeshA.time)                    val deliveryConfirmation =                        JsonObject()                    deliveryConfirmation.addProperty(                        JsonKeys.SENDER, userNumberKhud                            .firstOrNull()                    )                    deliveryConfirmation.addProperty(                        JsonKeys.RECEIVER,                        unsentSandeshA.receiver                    )                    deliveryConfirmation.addProperty(                        JsonKeys.MESSAGE_ID,                        unsentSandeshA.messId                    )                    deliveryConfirmation.addProperty(                        JsonKeys.DATA_TYPE,                        unsentSandeshA.dataType.value                    ) // Assuming DataType is an enum or class                    deliveryConfirmation.addProperty(                        JsonKeys.TIME_STAMP,                        unsentSandeshA.time                    )                    val sandeshJson = JsonParser.parseString(unsentSandeshA.message).asJsonObject                    sandeshJson.remove(JsonKeys.MESSAGE_ID)                    deliveryConfirmation.add(JsonKeys.SANDESH, sandeshJson)                    deliveryConfirmation.addProperty(JsonKeys.IS_GROUP, unsentSandeshA.isGroup)                    deliveryConfirmation.addProperty(JsonKeys.IS_LOGIN, false)                    DLog.i("sending this spring $deliveryConfirmation")                    val token = userDataStore.data.first()[PrefKeys.DELIVERY_TOKEN]                    if (token == null) {                        DLog.i("TOKEN NULL → stopping all sending immediately")                        getDeliveryToken()                        sendMessageMutex.unlock()                        return@launch               // ✅ exits ENTIRE function, skips 2nd loop                    }                    // Step 3: insert token into JSON                    deliveryConfirmation.addProperty(JsonKeys.SAMABHASH_TOKEN, token)                    val (success, _) = sendDeliveryReceiptSuspend(deliveryConfirmation.toString())                    if (success) {                        deleteUnsentData(                            unsentSandeshA.messId,                            unsentSandeshA.dataType,                            unsentSandeshA.receiver                        )                    } else {                        DLog.i("SEND FAILED → HARD STOP")//                        getDeliveryToken()                        delay(1000.milliseconds)                        sendMessageMutex.unlock()                        return@launch               // ✅ full exit, NO next loop                    }                    delay(50.milliseconds)                }                //delay(1000L) // Delay for 2 seconds                val unsentSandesh: UnsentSandesh? = unsentSandeshDao.getEarliestInsertedMessage()                if (unsentSandesh != null) {                    DLog.i("THERE MORE DATA TO SEND A $unsentSandesh")                    if (reason != ConnectReason.Registration) {//                            connection(ConnectReason.SendDataOnly)                    }                }                sendMessageMutex.unlock()                return@launch            }            try {                while (isParmaan) {                    val unsentSandesh: UnsentSandesh? =                        unsentSandeshDao.getEarliestInsertedMessage()                    var sent: Boolean                    if (unsentSandesh != null) {                        DLog.i("unsent MessageA " + unsentSandesh.message + " DATA TYPE " + unsentSandesh.dataType)                        if (unsentSandesh.dataType == DataType.MESSAGE                        ) {                            DLog.i("Sending Message To: " + unsentSandesh.receiver + " : Message Id : " + unsentSandesh.messId + " : Message : " + unsentSandesh.message)                            val sandeshEdit: JsonObject = JsonParser.parseString(unsentSandesh.message).asJsonObject                            sandeshEdit.addProperty(JsonKeys.TIME_STAMP, unsentSandesh.time)                            val jsonMessage = JsonObject()                            jsonMessage.addProperty(JsonKeys.RECEIVER, unsentSandesh.receiver)                            jsonMessage.addProperty(JsonKeys.MESSAGE_ID, unsentSandesh.messId)                            jsonMessage.addProperty(JsonKeys.IS_GROUP, unsentSandesh.isGroup)                            jsonMessage.addProperty(JsonKeys.DATA_TYPE, DataType.MESSAGE.value)                            DLog.i("Sending DATA TO WEBSOCKET")                            if (!unsentSandesh.isGroup) {                                val sandeshType = sandeshEdit.get(DootawasMessage.SANDESH_TYPE)?.asInt                                val forceRevealSender = sandeshType in setOf(                                    SandeshType.CREATE_GROUP.value,                                    SandeshType.GROUP_KEY_SETUP.value,                                    SandeshType.GROUP_KEY_REQUEST.value,                                    SandeshType.GROUP_KEY_RESPONSE.value,                                    SandeshType.EPOCH_COMMIT.value                                )                                jsonMessage.addProperty(JsonKeys.REVEAL_SENDER_NUMBER, if (forceRevealSender) true else upbhogtaDao.getRevealSender(unsentSandesh.receiver))                                val receiver = unsentSandesh.receiver                                val hasSession = hasSecureSession(                                    roomSignalStore,                                    receiver                                )                                if (!hasSession) {                                    logDebugSafe(                                        level = "DEBUG",                                        tag = "isSessionResetTriggered",                                        message = "Triggered ",                                        msgId = unsentSandesh.messId,                                        userId = unsentSandesh.receiver                                    )                                    DLog.i("⚠️ No session found for $receiver — requesting key bundle from server...")                                    dataTypeAck = DataType.ASK_KEY                                    messageIDWork = unsentSandesh.messId                                    if (isReceiverSelf(unsentSandesh.receiver)) {                                        sent = true                                        DLog.i("Skipping write to session because receiver is self: ${unsentSandesh.receiver}")                                    } else {                                        val jsonMessageA = JsonObject().apply {                                            addProperty(                                                JsonKeys.DATA_TYPE,                                                DataType.ASK_KEY.value                                            )                                            addProperty(                                                JsonKeys.RECEIVER,                                                unsentSandesh.receiver                                            )                                            addProperty(                                                JsonKeys.MESSAGE_ID,                                                unsentSandesh.messId                                            )                                        }                                        sent = writeJsonToSession(jsonMessageA)                                    }                                    if (sent) {                                        val hasSession =                                            hasSecureSession(roomSignalStore, receiver)                                        if (!hasSession) {                                            DLog.i("the bitch is still null")                                            unsentSandeshDao.markMessageOnHold(                                                messageId = unsentSandesh.messId,                                                receiver = unsentSandesh.receiver                                            )                                        }                                        continue                                    } else {                                        DLog.i("Breaking")                                        break // Stop sending if a message fails to send                                    }                                }                                try {                                    // 1. Safely check if the key exists and matches your ledger condition                                    if (sandeshEdit.has(DootawasMessage.LEDGER_TYPE)) {                                        var ledgerType = sandeshEdit.get(DootawasMessage.LEDGER_TYPE).asInt                                        val ledgerTypeUnchanged = sandeshEdit.get(DootawasMessage.LEDGER_TYPE).asInt                                        var finalAmount = if (sandeshEdit.has(DootawasMessage.LEDGER_AMOUNT)) {                                            sandeshEdit.get(DootawasMessage.LEDGER_AMOUNT).asDouble                                        } else {                                            0.0                                        }                                        // --- SYSTEM DYNAMIC BALANCE ADJUSTMENT FOR TYPE 0 (BILL) ---                                        if (ledgerType == 0 && sandeshEdit.has("ledgerData")) {                                            try {                                                val ledgerData = sandeshEdit.getAsJsonObject("ledgerData")                                                if (ledgerData != null && ledgerData.has("amountPaid")) {                                                    val amountPaid = ledgerData.get("amountPaid").asDouble                                                    DLog.i("📊 Sender Core Ledger: Original Amount = $finalAmount, Amount Paid = $amountPaid")                                                    // Net calculation: Bill Total (e.g. 2000) - Amount Paid (e.g. 2070) = -70                                                    val pendingAmount = finalAmount - amountPaid                                                    when {                                                        pendingAmount > 0.0 -> {                                                            // Scenario A: Underpaid balance remaining                                                            finalAmount = pendingAmount                                                            ledgerType = 1 // CREDIT                                                            DLog.i("📉 Underpayment calculated. Remaining pending debt: $finalAmount. Setting Type to CREDIT (1).")                                                        }                                                        pendingAmount == 0.0 -> {                                                            // Scenario B: Exact match payment                                                            finalAmount = 0.0                                                            ledgerType = 0 // Keep as BILL total but with zero balance                                                            DLog.i("✅ Clean Settlement. Exact payment match made. Balance cleared to 0.0.")                                                        }                                                        else -> {                                                            // Scenario C: Overpayment! (e.g., paid 70 extra)                                                            finalAmount = abs(pendingAmount)                                                            ledgerType = 2 // DEBIT - Direction flips completely because they are now owed 70 back                                                            DLog.w("🔺 Overpayment Detected at Sender Pipeline! Extra amount paid: $finalAmount. Converting to DEBIT (2).")                                                        }                                                    }                                                    // Sync these changes back into the sandeshEdit payload so local storage matches perfectly                                                    sandeshEdit.addProperty(DootawasMessage.LEDGER_AMOUNT, finalAmount)                                                    sandeshEdit.addProperty(DootawasMessage.LEDGER_TYPE, ledgerTypeUnchanged)                                                    DLog.i("💾 Sender state synchronized locally. Final Amount: $finalAmount, Type Value: $ledgerType")                                                }                                            } catch (e: Exception) {                                            }                                        }                                        // --- END OF ADJUSTMENT LAYER ---                                        // 2. Extract and append unencrypted fields to the main payload so the server can see them                                        jsonMessage.addProperty(DootawasMessage.LEDGER_AMOUNT, finalAmount)                                        jsonMessage.addProperty(DootawasMessage.LEDGER_TYPE, ledgerType)                                        jsonMessage.addProperty(JsonKeys.DATA_TYPE, DataType.LEDGER.value)                                        // Encrypt the adjusted payload structure safely                                        jsonMessage.add(JsonKeys.SANDESH, encryptJsonObject(receiver, sandeshEdit))                                        // Skip encryption settings for structural ACK IDs                                        if (ledgerType != 4 && ledgerType != 5) {                                            jsonMessage.addProperty(DootawasMessage.ORIGINAL_MESSAGE_ID, unsentSandesh.messId)                                        } else {                                            jsonMessage.addProperty(DootawasMessage.ORIGINAL_MESSAGE_ID, sandeshEdit.get(DootawasMessage.ORIGINAL_MESSAGE_ID).asString)                                        }                                    } else {                                        // Regular non-ledger messages are always encrypted straight into the payload box                                        jsonMessage.add(JsonKeys.SANDESH, encryptJsonObject(receiver, sandeshEdit))                                    }                                } catch (e: Exception) {                                    DLog.e(                                        "❌ Encryption failed for messageId=${unsentSandesh.messId} ",                                        e                                    )                                    val address = SignalProtocolAddress(receiver, 1)                                    roomSignalStore.deleteSession(address)                                    unsentSandeshDao.markMessageOnHold(                                        messageId = unsentSandesh.messId,                                        receiver = receiver                                    )                                }                            } else {                                val groupId = unsentSandesh.receiver                                if (groupId.isNotBlank()) {                                    try {                                        val revealSender = groupDao.getRevealSender(unsentSandesh.receiver) ?: false                                        jsonMessage.addProperty(                                            JsonKeys.REVEAL_SENDER_NUMBER,                                            true // todo change it later on setup of  username in group message                                        )                                        val plaintext = sandeshEdit.toString().toByteArray(Charsets.UTF_8)                                        val messageNumber = unsentSandesh.time.toLongOrNull()                                            ?: throw IllegalArgumentException(                                                "Invalid message time/messageNumber: ${unsentSandesh.time}"                                            )                                        val encryptedMessage = groupCryptoManager.encryptSendMessage(                                            groupId = groupId,                                            plaintext = plaintext,                                            messageId = unsentSandesh.messId,                                            messageNumber = messageNumber                                        )                                        val sandeshJson = JsonObject().apply {                                            addProperty(                                                DootawasMessage.GROUP_CRYPTO_PROTOCOL_VERSION,                                                encryptedMessage.protocolVersion                                            )                                            addProperty(                                                JsonKeys.GROUP_ID,                                                encryptedMessage.groupId                                            )                                            addProperty(                                                DootawasMessage.GROUP_EPOCH,                                                encryptedMessage.epoch                                            )                                            addProperty(                                                DootawasMessage.GROUP_SENDER_ID,                                                encryptedMessage.senderId                                            )                                            addProperty(                                                DootawasMessage.GROUP_SENDER_DEVICE_ID,                                                encryptedMessage.senderDeviceId                                            )                                            addProperty(                                                JsonKeys.MESSAGE_ID,                                                encryptedMessage.messageId                                            )                                            addProperty(                                                DootawasMessage.GROUP_MESSAGE_NUMBER,                                                encryptedMessage.messageNumber                                            )                                            addProperty(                                                DootawasMessage.GROUP_NONCE,                                                Base64.encodeToString(                                                    encryptedMessage.nonce,                                                    Base64.NO_WRAP                                                )                                            )                                            addProperty(                                                JsonKeys.SANDESH,                                                Base64.encodeToString(                                                    encryptedMessage.ciphertext,                                                    Base64.NO_WRAP                                                )                                            )                                        }                                        // Put the complete group crypto envelope inside outer "sandesh".                                        jsonMessage.add(                                            JsonKeys.SANDESH,                                            sandeshJson                                        )                                    } catch (e: Exception) {                                        DLog.e(                                            "Encryption failed for