sId,                                        unsentSandesh.dataType,                                        unsentSandesh.receiver                                    )                                    continue                                }                            }                            dataTypeAck = DataType.MESSAGE                            messageIDWork = unsentSandesh.messId                            timePrekshit = -1                            if (isReceiverSelf(unsentSandesh.receiver)) {                                sent = true                                DLog.i("Skipping write to session because receiver is self: ${unsentSandesh.receiver}")                            }else{                                sent = writeJsonToSession(jsonMessage)                            }                            if (sent) {                                DLog.i("Sent Success")                                markAsSent(                                    unsentSandesh.messId,                                    unsentSandesh.dataType,                                    unsentSandesh.receiver                                )                                if (timePrekshit != -1L) {                                    DLog.i("timePrekshit has been updated!")                                    if (unsentSandesh.isGroup) {                                        val groupId =                                            sandeshEdit.get(JsonKeys.GROUP_ID)?.asString.orEmpty()                                        updateGroupSandeshStithiTime(                                            groupId,                                            unsentSandesh                                                .messId,                                            SandeshStithi.PREKSHIT,                                            "",                                            timePrekshit, true                                        )                                    } else {                                        updateSandeshStithiTime(                                            unsentSandesh.receiver,                                            unsentSandesh.messId,                                            SandeshStithi.PREKSHIT,                                            timePrekshit, true                                        )                                    }                                } else {                                    DLog.i("timePrekshit is still -1")                                }                            } else {                                DLog.i("Breaking")                                continue // Stop sending if a message fails to send                            }                        } else if (unsentSandesh.dataType == DataType.ASK_AGAIN) {                            DLog.i("Sending Message To: " + unsentSandesh.receiver + " : Message Id : " + unsentSandesh.messId + " : Message : " + unsentSandesh.message)                            val sandeshEdit: JsonObject =                                JsonParser.parseString(unsentSandesh.message).asJsonObject                            sandeshEdit.addProperty(JsonKeys.TIME_STAMP, unsentSandesh.time)//                                sandeshEdit.addProperty(JsonKeys.IS_GROUP,false)                            val revealSenderNumber = sandeshEdit.get(JsonKeys.REVEAL_RECEIVER_NUMBER)?.asBoolean ?: true                            sandeshEdit.remove(JsonKeys.REVEAL_RECEIVER_NUMBER)                            val jsonMessage = JsonObject()                            jsonMessage.add(JsonKeys.SANDESH, sandeshEdit)                            jsonMessage.addProperty(JsonKeys.RECEIVER, unsentSandesh.receiver)                            jsonMessage.addProperty(JsonKeys.MESSAGE_ID, unsentSandesh.messId)                            jsonMessage.addProperty(JsonKeys.DATA_TYPE, DataType.MESSAGE.value)                            jsonMessage.addProperty(JsonKeys.IS_GROUP, unsentSandesh.isGroup)                            jsonMessage.addProperty(JsonKeys.REVEAL_SENDER_NUMBER, revealSenderNumber)                            DLog.i("Sending DATA TO WEBSOCKET")                            dataTypeAck = DataType.MESSAGE                            messageIDWork = unsentSandesh.messId                            sent = writeJsonToSession(jsonMessage)                            if (sent) {                                DLog.i("Sent Success")                                deleteUnsentData(                                    unsentSandesh.messId,                                    unsentSandesh.dataType,                                    unsentSandesh.receiver                                )                            } else {                                DLog.i("Breaking")                                continue // Stop sending if a message fails to send                            }                        } else if (unsentSandesh.dataType == DataType.PROFILE_UPDATE) {                            DLog.i("sending setProfile time" + unsentSandesh.time)                            dataTypeAck = DataType.PROFILE_UPDATE                            messageIDWork = unsentSandesh.messId                            val profileUpdate = JsonObject()                            profileUpdate.addProperty(                                JsonKeys.USER_NUMBER,                                userNumberKhud.firstOrNull()                            )                            profileUpdate.addProperty(JsonKeys.MESSAGE_ID, unsentSandesh.messId)                            profileUpdate.addProperty(JsonKeys.DATA, unsentSandesh.message)                            profileUpdate.addProperty(                                JsonKeys.DATA_TYPE,                                DataType.PROFILE_UPDATE.value                            )                            profileUpdate.