        }    }    private val lastProfileCheck = mutableMapOf<String, Long>()    fun checkSingleProfile(userNumber: String) {        if (userNumber.isBlank()) {            DLog.i("Invalid userNumber: cannot be empty or blank")            return        }        val now = System.currentTimeMillis()        val lastCheck = lastProfileCheck[userNumber]        if (lastCheck != null && now - lastCheck < 60_000L) {            DLog.i("Skipping checkProfile for $userNumber - called again within 1 minute")            return        }        lastProfileCheck[userNumber] = now        DLog.i("OKAY THIS REQ IS CALLED")        coroutineScope.launch {            writeMessageMutex.withLock {                val existing = unsentSandeshDao.getUnsentSandeshByReceiverAndType(                    receiver = userNumber,                    dataType = DataType.ASK_SINGLE_PROFILE_STATUS                )                if (existing != null) {                    DLog.i("UnsentSandesh already exists for user $userNumber and type ${DataType.ASK_SINGLE_PROFILE_STATUS}")                    return@launch                }                val unsentSandesh = UnsentSandesh(                    messId = createMessageID(),                    receiver = userNumber,                    message = "many",                    dataType = DataType.ASK_SINGLE_PROFILE_STATUS                )                insertUnsentData(unsentSandesh)                if (userNumber == "+919999912345" ){                    val unsentSandeshQuickTips = UnsentSandesh(                        messId = createMessageID(),                        receiver = "+919999912345",                        message = "quickTips",                        dataType = DataType.GET_QUICK_TIPS_DATA                    )                    insertUnsentData(unsentSandeshQuickTips)                }                sendUnsentMessages(false)            }        }    }    //endregion    //region HOME SCREEN    fun checkVisibleProfiles(userNumbers: List<String>) {        if (userNumbers.isEmpty()) return        coroutineScope.launch {            universalMutex.withLock {                val jsonArray = JsonArray().apply {                    userNumbers.distinct().forEach { add(it) }                }                val existing = unsentSandeshDao.getUnsentSandeshByReceiverAndType(                    receiver = "checkHomeUsers",                    dataType = DataType.HOME_PROFILE_STATUS                )                if (existing != null) return@launch                val unsent = UnsentSandesh(                    messId = createMessageID(),                    receiver = "checkHomeUsers",                    message = jsonArray.toString(),                    dataType = DataType.HOME_PROFILE_STATUS                )                insertUnsentData(unsent)                sendUnsentMessages(false)            }        }    }    fun checkVisibleGroupMembers(userNumbers: List<String>) {        if (userNumbers.isEmpty()) return        coroutineScope.launch {            universalMutex.withLock {                val jsonArray = JsonArray().apply {                    userNumbers.distinct().forEach { add(it) }                }                //todo wtf is that why not use insert unsent data directly and why we need a seperate group memeber profile checker?                val existing = unsentSandeshDao.getUnsentSandeshByReceiverAndType(                    receiver = "checkHomeUsers",                    dataType = DataType.GROUP_MEMBER_PROFILE                )                if (existing != null) return@launch                val unsent = UnsentSandesh(                    messId = createMessageID(),                    receiver = "checkHomeUsers",                    message = jsonArray.toString(),                    dataType = DataType.GROUP_MEMBER_PROFILE                )                insertUnsentData(unsent)                sendUnsentMessages(false)            }        }    }    fun checkVisibleGroupProfiles(userNumbers: List<String>) {        if (userNumbers.isEmpty()) return        coroutineScope.launch {            universalMutex.withLock {                val jsonArray = JsonArray().apply {                    userNumbers.distinct().forEach { add(it) }                }                val existing = unsentSandeshDao.getUnsentSandeshByReceiverAndType(                    receiver = "checkHomeUsers",                    dataType = DataType.GROUP_HOME_PROFILE                )                if (existing != null) return@launch                val unsent = UnsentSandesh(                    messId = createMessageID(),                    receiver = "checkHomeUsers",                    message = jsonArray.toString(),                    dataType = DataType.GROUP_HOME_PROFILE                )                insertUnsentData(unsent)                sendUnsentMessages(false)            }        }    }    //endregion    private suspend fun generateContactsJson(): List<JsonObject>? {        val userContactDao = dootawasDatabase.contactDao()        val allContacts = userContactDao.getAllContacts().first()        if (allContacts.isEmpty()) {            DLog.i("❌ No contacts found. Skipping JSON generation.")            return null        }        val phoneUtil = PhoneNumberUtil.getInstance()        val defaultRegion = "IN" // fallback region for numbers without country code        // Instead of {receiver: number}, just a list of numbers        val validNumbers = mutableListOf<String>()        for (contact in allContacts) {            val rawNumber = contact.number.trim()            try {                val numberProto = if (rawNumber.startsWith("+")) {                    phoneUtil.parse(rawNumber, null)                } else {                    phoneUtil.parse(rawNumber, defaultRegion)                }                if (phoneUtil.isValidNumber(numberProto)) {                    val e164 = phoneUtil.format(numberProto, PhoneNumberUtil.PhoneNumberFormat.E164)                    validNumbers.add(e164)                    DLog.i("✅ Valid contact: ${contact.name} → $e164")                } else {                    DLog.i("⚠️ Invalid number skipped: ${contact.name} → $rawNumber")                }            } catch (e: NumberParseException) {                DLog.i("❌ Parse error for number '${contact.number}': ${e.message}")            }        }        if (validNumbers.isEmpty()) {            DLog.i("❌ No valid contacts to send.")            return null        }        // 🔹 Split into chunks of ~4KB        val chunkedJsonList = mutableListOf<JsonObject>()        val tempList = mutableListOf<String>()        var currentSize = 0        for (number in validNumbers) {            val numberSize = number.toByteArray(Charsets.UTF_8).size + 3 // quotes + comma approx            if (currentSize + numberSize > 4000 && tempList.isNotEmpty()) {                // flush current chunk                val jsonChunk = JsonObject().apply {                    addProperty(JsonKeys.DATA_TYPE, DataType.CHECK_USER_EXISTENCE.value)                    add(JsonKeys.LIST, JsonArray().apply { tempList.forEach { add(it) } })                }                chunkedJsonList.add(jsonChunk)                tempList.clear()                currentSize = 0            }            tempList.add(number)            currentSize += numberSize        }        // flush remaining        if (tempList.isNotEmpty()) {            val jsonChunk = JsonObject().apply {                addProperty(JsonKeys.DATA_TYPE, DataType.CHECK_USER_EXISTENCE.value)                add(JsonKeys.LIST, JsonArray().apply { tempList.forEach { add(it) } })            }            chunkedJsonList.add(jsonChunk)        }        DLog.i("✅ Final Chunks Prepared: ${chunkedJsonList.size}")        return chunkedJsonList    }    private val _contactResultFlow =        MutableSharedFlow<CheckedContact>()    val contactResultFlow =        _contactResultFlow.asSharedFlow()    fun sendCheckUser(phone: String) {        coroutineScope.launch {            val unsentSandesh = UnsentSandesh(                messId = createMessageID(),                receiver = phone,                message = "manyContact",                dataType = DataType.CHECK_USER_EXISTENCE_QR            )            insertUnsentData(unsentSandesh)            sendUnsentMessages(false)        }    }    //    private  @NonNull BlockUser getBlockUser(UnsentData unsentData) {    //        BlockUser blockUser;    //                                  Instant instant = Instant.now();    ////                                // Convert Instant to milliseconds    ////                                long epochMillis = instant.toEpochMilli();    ////                                String msgId = String.valueOf(epochMillis);    ////                                updateSandeshStithi(unsentData.getReceiver(),SandeshStithi.PREKSHIT,unsentData.getMess_id(),msgId);    //        Stop sending if a message fails to send    //        if (Objects.equals(unsentData.getMessage(), "true")) {    //            blockUser = new BlockUser(true, unsentData.getReceiver());    //        }else{    //            blockUser = new BlockUser(false, unsentData.getReceiver());    //        }    //        return blockUser;    //    }    private fun retrieveDocument(filePath: String?): File? {        DLog.i("PICKING FILE $filePath")        if (filePath == null){            return  null        }        val file = File(filePath)        return if (file.exists()) file else null // ✅ Return only if the file exists    }    fun getFileFromUri(uri: Uri): File? {        return try {            val inputStream = context.contentResolver.openInputStream(uri) ?: return null            val tempFile = File.createTempFile("upload_", ".jpg", context.cacheDir)   