rName,messageId);    //                UnsentData unsentData = new UnsentData(messageId,userName, docType, DataType.DOCUMENTS , 1,  null);    //                insertUnsentData(unsentData);    //                if (!sendingFileInProgress) {    //                    sendUnsentFiles();    //                }    //                if (!sendingInProgress) {    //                    sendUnsentMessages(false);    //                }    //            }    //    //            @Override    //            public void onUploadFailed(String errorMessage) {    //    //            }    //    //            @Override    //            public void onProgress(int progressPercentage) {    //    //            }    //        });    //    //    }    fun updateBlockedUserLocally(userNumber: String, isBlock: Boolean) {        coroutineScope.launch {            settingStore.edit { prefs ->                val current =                    prefs[SettingPrefKeys.SERVER_BLOCKED_USERS] ?: emptySet()                val updated =                    if (isBlock) current + userNumber                    else current - userNumber                prefs[SettingPrefKeys.SERVER_BLOCKED_USERS] = updated                DLog.i("🔐 Updated local blocklist = $updated")            }        }    }    fun blockOrUnblockUser(userNameC: String, isBlock: Boolean) {        coroutineScope.launch {            universalMutex.withLock {                val blockString: String = if (isBlock) "true" else "false"                val unsentSandesh = UnsentSandesh(                    messId = createMessageID(),                    receiver = userNameC,                    message = blockString,                    dataType = DataType.BLOCK                )                insertUnsentData(unsentSandesh, false)                sendUnsentMessages(false)                // 🔥 Immediately update local DataStore                upbhogtaDao.updateBlockedStatus(userNameC, isBlock)                updateBlockedUserLocally(userNameC, isBlock)            }        }    }    // Function to add a message if it's not already being processed    fun addMessage(username: String, messageId: String): Boolean {        val key = UserMessageKey(username, messageId)        if (!messagesBeingProcessed.contains(key)) {            messagesBeingProcessed.add(key)            DLog.i("Message ID $messageId from user $username is now being processed.")            return true        } else {            DLog.i("Message ID $messageId from user $username is already being processed.")            return false        }    }    // Function to remove a message after processing is done    fun removeMessage(username: String, messageId: String) {        val key = UserMessageKey(username, messageId)        if (messagesBeingProcessed.remove(key)) {            DLog.i("Message ID $messageId from user $username has been processed and removed.")        } else {            DLog.i("Message ID $messageId from user $username was not found in the processing list.")        }    }    // HashSet to store the composite keys of messages being processed    private val messagesBeingProcessed: MutableSet<UserMessageKey> = HashSet()    private fun getProfile(        username: String,        messageID: String,        profilePass: String,        isGroup: Boolean    ): Int {        return try {            val response = runBlocking {                requestProfileDownloadUrl(                    messageID,                    username,                    isGroup                )            }            if (!response.dataBoolean) {                return 503            }            downloadAndExtractProfileZip(                response.downloadUrl,                username,                profilePass,                isGroup            )            200        } catch (e: Exception) {            Log.e("ProfileDL", "Exception getting profile URL", e)            503        }    }    fun deleteProfile(        isGroup: Boolean,        groupId: String? = null    ): Int {        val userToken = getValidFileToken() ?: return 401        val api = RetrofitClient.instance.create(ApiService::class.java)        val call = if (isGroup) {            api.deleteGroupProfile(userToken, groupId ?: return 400)        } else {            api.deleteProfile(userToken)        }        return try {            val response = call.execute()            if (!response.isSuccessful) {                Log.e("ProfileDelete", "Delete failed: ${response.code()}")                return response.code()            }            200        } catch (e: Exception) {            Log.e("ProfileDelete", "Network error deleting profile", e)            503        }    }    private fun downloadAndExtractProfileZip(        signedUrl: String,        username: String,        profilePass: String?,        isGroup: Boolean    ) {        CoroutineScope(Dispatchers.IO).launch {            try {                if (profilePass.isNullOrEmpty()) {                    Log.w("ProfileDL", "Profile hidden by privacy settings. Skipping download for $username")                    return@launch                }                val request = Request.Builder()                    .url(signedUrl)                    .get()                    .build()                RetrofitClient.okHttpClient.newCall(request).execute().use { response ->                    if (!response.isSuccessful) {                        Log.e("ProfileDL", "ZIP download failed: HTTP ${response.code}")                        return@launch                    }                    val peekBytes = response.peekBody(10).bytes()                    if (peekBytes.size < 2 ||                        peekBytes[0] != 'P'.code.toByte() ||                        peekBytes[1] != 'K'.code.toByte()                    ) {                        Log.e("ProfileDL", "Server did not return a ZIP. Dumping response:")                        Log.e("ProfileDL", response.body.string())                        return@launch                    }                    val privateDir = File(context.filesDir, "profiles").apply { mkdirs() }                    val timeStamp = SimpleDateFormat(                        "yyyyMMdd_HHmmss",                        Locale.getDefault()                    ).format(Date())                    val zipFile = File(privateDir, "${username}_${timeStamp}.zip")                    val extractDir = File(privateDir, "${username}_${timeStamp}")                    response.body.byteStream().use { input ->                        FileOutputStream(zipFile).use { output ->                            input.copyTo(output)                        }                    }                    if (zipFile.length() < 50) {                        Log.e("ProfileDL", "ZIP too small → likely invalid.")                        return@launch                    }                    extractProfileZip(                        zipFile,                        extractDir,                        profilePass,                        username,                        isGroup                    )                }            } catch (e: Exception) {                Log.e("ProfileDL", "Failed to download/extract profile", e)            }        }    }    private suspend fun extractProfileZip(        zipFile: File,        extractDir: File,        profilePass: String,        username: String,        isGroup: Boolean    ) {        try {            if (zipFile.length() < 22) {                throw IllegalArgumentException("ZIP too small")            }            // Ensure extraction directory exists            if (extractDir.exists()) {                if (!extractDir.isDirectory) {                    throw IllegalStateException("Extract path is not directory")                }            } else {                val created = extractDir.mkdirs()                if (!created) {                    throw IllegalStateException(                        "Failed creating dir: ${extractDir.absolutePath}"                    )                }            }            // ZIP magic bytes check            val header = ByteArray(4)            FileInputStream(zipFile).use { it.read(header) }            val magic = header.joinToString(" ") { "%02x".format(it) }            if (!magic.startsWith("50 4b 03 04")) {                throw IllegalArgumentException("Invalid ZIP header")            }            val zip = ZipFile(zipFile)            if (zip.isEncrypted) {                zip.setPassword(profilePass.toCharArray())            }            zip.extractAll(extractDir.absolutePath)            zipFile.delete()            val extractedFile = extractDir                .listFiles()                ?.firstOrNull { it.isFile }            if (extractedFile != null) {                withContext(Dispatchers.Main) {                    if (isGroup) {                        replaceGroupUri(username, extractedFile.absolutePath)                    } else {                        replaceUri(username, extractedFile.absolutePath)                    }                }            } else {                Log.e("ProfileDL", "No extracted file found")            }        } catch (e: Exception) {            Log.e("ProfileDL", "Extraction failed for $username", e)        }    }    private fun replaceUri(userName: String, newImagePath: String?) {        CoroutineScope(Dispatchers.IO).launch {            // Get old path            val oldUrl = contactDao.getImageUrlByNumber(userName)            // 🔹 Delete old image file if exists            oldUrl?.takeIf { it.isNotBlank() }?.let { oldPath ->                val oldFile = File(oldPath)                if (oldFile.exists()) {                    DLog.i("🗑 DELETED OLD IMAGE")                    oldFile.delete()                }            }            // 🔹 If self user, update local DataStore            if (userNumberKhud.firstOrNull().toString() == userName) {                DLog.i("👤 Updating Self Profile")                userDataStore.edit { prefs ->                    if (newImagePath.isNullOrBlank()) {                        prefs.remove(PrefKeys.PROFILE_IMAGE)                    } else {                        prefs[PrefKeys.PROFILE_IMAGE] = newImagePath                    }                }            }            // 🔹 Update DB with nullable value            contactDao.updateImageUrlByNumber(newImagePath ?: "", userName)            upbhogtaDao.updatePhotoUrlByNumber(newImagePath ?: "", userName)            groupDao.updatePhotoUrlByNumber(newImagePath ?: "", userName)        }    }    private fun replaceGroupUri(userName: String, newImagePath: String) {        CoroutineScope(Dispatchers.IO).launch {            //todo dont u think you should clean file from upbhogta and group too??            val oldUrl = groupDao.getImageUrlByGroupId(userName)            oldUrl?.takeIf { it.isNotEmpty() }?.let { oldPath ->                val oldFile = File(oldPath)                if (oldFile.exists()) {                    DLog.i("DELETED OLD IMAGE")                    oldFile.delete()                }            }            groupDao.updateImageUrlByGroupId(newImagePath, userName)        }    }    fun generateUuidAndStrongPassword(): Pair<String, String> {        val uuid = UUID.randomUUID().toString()        val chars =            """ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()-_+[]{}"""        val passwordLength = 32        val password = (1..passwordLength)            .map { chars.random() }            .joinToString("")        return Pair(uuid, password)    }    val gson = Gson()    fun compressWithZip4j(inputFile: File, outputZip: File, password: String? = null) {        val zipFile = if (password != null)            ZipFile(outputZip, password.toCharArray())        else            ZipFile(outputZip)        val parameters = ZipParameters().apply {            isEncryptFiles = password != null            encryptionMethod = EncryptionMethod.ZIP_STANDARD // or AES if you prefer        }        zipFile.addFile(inputFile, parameters)    }    /**     * Uploads a profile picture directly to Cloudflare R2 using a presigned URL.     *     * @param fileQ The profile image file.     * @param fileNameQ User phone or group ID.     * @param pass Zip encryption password.     * @param isGroup True if uploading a group profile.     * @return HTTP status code or 503 on failure.     */    private fun uploadProfileInternal(        fileQ: File,        fileNameQ: String,        pass: String,        isGroup: Boolean    ): Int {        var response: Response? = null        var compressedFile: File? = null        return try {            // Compress + encrypt profile            compressedFile = File(fileQ.parent, "compressed_${fileQ.name}.zip")            compressWithZip4j(fileQ, compressedFile, password = pass)            // Ask server for upload URL            val uploadResponse = runBlocking {                requestProfileUploadUrl(                    messageId = UUID.randomUUID().toString(),                    receiver = if (isGroup) fileNameQ else null,                    pass = pass,                    isGroup = isGroup                )            }            if (!uploadResponse.dataBoolean) {                DLog.e("Profile upload URL request failed.")                return 503            }            val progressRequestBody = ProgressRequestBody(                compressedFile.asRequestBody("application/zip".toMediaType())            ) { progress ->                DLog.i("Profile Upload: $progress%")            }            val request = Request.Builder()                .url(uploadResponse.uploadUrl)                .put(progressRequestBody)                .build()            response = OkHttpClient()                .newCall(request)                .execute()            if (response.isSuccessful) {                DLog.i("✅ Profile uploaded successfully.")                response.code            } else {                DLog.e("❌ Profile upload failed. HTTP ${response.code}")                response.code            }        } catch (e: IOException) {            Log.e(                "UploadProfile",                "Error uploading profile.",                e            )            503        } finally {            response?.close()            compressedFile                ?.takeIf { it.exists() }                ?.delete()        }    }    fun createOkHttpClient(): OkHttpClient {        return OkHttpClient.Builder()            .connectTimeout(20, TimeUnit.SECONDS)   // Connection timeout            .writeTimeout(120, TimeUnit.SECONDS)    // Upload/write timeout            .readTimeout(120, TimeUnit.SECONDS)     // Download/read timeout            .retryOnConnectionFailure(true)         // Retry on transient network failures            .connectionPool(ConnectionPool(10, 5, TimeUnit.MINUTES)) // Reuse connections            .build()    }    private fun initializeRetrofit() {        if (retrofit == null) {            DLog.i("Initializing Retrofit...")            try {                val client: OkHttpClient = createOkHttpClient()                val baseUrl = BuildConfig.                BASE_HOST + BuildConfig.API_PREFIX                // Create Retrofit instance                this.retrofit = Retrofit.Builder()                    .baseUrl(baseUrl) // Make sure URL ends with /                    .client(client)                    .addConverterFactory(GsonConverterFactory.create())                    .build()                DLog.i("Retrofit initialized successfully.")            } catch (e: Exception) {                DLog.i("Error during Retrofit initialization: ${e.message}")                e.printStackTrace()            }        } else {            DLog.i("Retrofit is already initialized, reusing instance.")        }    }    suspend fun saveFileToken(token: String) {        val now = System.currentTimeMillis()        fileToken = token        tokenTime = now        context.userDataStore.edit { prefs ->            prefs[PrefKeys.FILE_TOKEN] = token            prefs[PrefKeys.FILE_TOKEN_TIME] = now        }    }    private fun sendUnsentFiles() {        // 1. Check the flag immediately        if (sendingFileInProgress) {            DLog.i("Worker is already running and looping")            return        }        sendingFileInProgress = true        coroutineScope.launch {            try {                DLog.i("Starting persistent file sender loop...")                while (isParmaan) {                    // Use the Mutex only for the sensitive DB/Token work                    sendFileMutex.withLock {                        val unsentFilesDao = dootawasDatabase.unsentFilesDao()                        if (unsentFilesDao.isAnyDataPresent()) {                            DLog.i("Data found! Processing...")                            processAfterToken()                        } else {                            // We don't return here anymore, just log and move to delay                            DLog.i("No files to send right now")                        }                    }                    DLog.i("Sleeping for 3 seconds...")                    delay(3000.milliseconds)                }            } catch (e: Exception) {                DLog.e("Coroutine crashed: ${e.message}")            } finally {                // 2. This is the only place we reset the flag                // It runs if isParmaan becomes false OR if the loop crashes                sendingFileInProgress = false                DLog.i("Worker stopped. Flag reset.")            }        }    }    suspend fun getDeliveryToken() {        DLog.i("INSERTING GET FILE")        val unsentSandesh = UnsentSandesh(            messId = createMessageID(),            receiver = userNumberKhud.firstOrNull().toString(),            message = "getDliveryToken",            dataType = DataType.GET_DELIVERY_TOKEN        )        insertUnsentData(unsentSandesh)        sendingFileInProgress = false        sendUnsentMessages(false)    }    suspend fun saveDeliveryToken(token: String) {        val currentTime = System.currentTimeMillis() // store time in millis        userDataStore.edit { prefs ->            prefs[PrefKeys.DELIVERY_TOKEN] = token            prefs[PrefKeys.DELIVERY_TOKEN_TIME] = currentTime        }    }    suspend fun checkAndHandleDeliveryToken() {        val prefs = userDataStore.data.first()        val token = prefs[PrefKeys.DELIVERY_TOKEN]        val savedTime = prefs[PrefKeys.DELIVERY_TOKEN_TIME]        // If no token stored → fetch new token        if (token == null || savedTime == null) {            getDeliveryToken()            return        }        val now = System.currentTimeMillis()        val diffDays = (now - savedTime) / DAY_MILLIS        when {            diffDays >= TOKEN_VALIDITY_DAYS -> {                // Token expired → refresh token                getDeliveryToken()            }            diffDays >= TOKEN_WARNING_DAYS -> {                // About to expire → refresh token proactively                getDeliveryToken()            }            else -> {                // Token is valid → do nothing            }        }    }    fun compressStringToBytes(data: String): ByteArray {        val outputStream = ByteArrayOutputStream()        GZIPOutputStream(outputStream).use { gzip ->            gzip.write(data.toByteArray(Charsets.UTF_8))        }        return outputStream.toByteArray()    }    private suspend fun processAfterToken() {      