messageId, receiver)                                        removeMessage(receiver, unsentData.messageId)                                        DLog.i("SOMETHING WENT WRONG")                                    }                                }                                FileDataType.LOCATION,                                FileDataType.REPLY_LOCATION -> {                                    DLog.i("PRINT LOCATION DATA $unsentData")                                    val locationData: JsonObject =                                        JsonParser.parseString(unsentData.data).asJsonObject                                    val jsonString = locationData.toString()                                    val byteSize = jsonString.toByteArray(Charsets.UTF_8).size                                    DLog.i("JSON byte size: 1 $byteSize")                                    val receiversJson = if (unsentData.isGroup) {                                        val members =                                            groupDao.getAllMemberNumbersInGroup(receiver)                                        Gson().toJson(members) // already a list                                    } else {                                        Gson().toJson(listOf(receiver)) // wrap in list                                    }                                    val uriString = locationData.get(DootawasMessage.ORIGINAL_URI).asString                                    if (!uriString.isNullOrBlank()) {                                        val (uuidG, password) = generateUuidAndStrongPassword()                                        DLog.i("Generated UUID: $uuidG")                                        DLog.i("Generated Strong Password: $password")                                        UploadScheduler.startUpload(                                            context,                                            UploadData(                                                filePaths = listOf(uriString),   // ✅ wrap into list                                                uuid = uuidG,                                                receiversJson = receiversJson,                                                password = password,                                                isGroup = unsentData.isGroup,                                                receiver = receiver,                                                messageId = unsentData.messageId,                                                dataType = unsentData.dataType,                                                mainJson = unsentData.data,                                            )                                        )                                    } else {                                        deleteSendData(unsentData.messageId, receiver)                                        removeMessage(receiver, unsentData.messageId)                                        DLog.i("SOMETHING WENT WRONG")                                    }                                }                                FileDataType.PROFILE_UPDATE -> {                                    DLog.i("NOW WE WILL UPLOAD PROFILE ${unsentData.data}")                                    val doc: File? = getFileFromUri(unsentData.data.toUri())                                    if (doc != null) {                                        // Perform operations with the file                                        DLog.i("NOW SENDING IT $messageId")                                        val (uuidG, password) = generateUuidAndStrongPassword()                                        val upload = uploadProfileInternal(                                            doc,                                            receiver,                                            password,                                            unsentData.isGroup                                        )      