ge(receiver, unsentData.messageId)                                        DLog.i("SOMETHING WENT WRONG")                                    }                                }                                FileDataType.VIDEO,                                FileDataType.REPLY_VIDEO -> {                                    val videoData = JsonParser.parseString(unsentData.data).asJsonObject                                    DLog.i("Processing video for $videoData")                                    val receiversJson = if (unsentData.isGroup) {                                        val members = groupDao.getAllMemberNumbersInGroup(receiver)                                        Gson().toJson(members)                                    } else {                                        Gson().toJson(listOf(receiver))                                    }                                    val dataArray = videoData.getAsJsonArray(DootawasMessage.ALL_DATA)                                    if (dataArray != null) {                                        val total = dataArray.size()                                        val filePaths = mutableListOf<String>()                                        var progressReset = false                                        try {                                            for (i in 0 until total) {                                                val obj = dataArray[i].asJsonObject                                                val orig = obj.get(DootawasMessage.ORIGINAL_URI)?.asString                                                if (orig.isNullOrBlank()) continue                                                val dup = obj.get(DootawasMessage.DUPLICATE_URI)?.asString                                                val reusable = !dup.isNullOrBlank() &&                                                        (!dup.startsWith("/") || File(dup).exists())                                                val path = if (reusable) {                                                    dup.orEmpty()                                                } else {                                                    if (!progressReset) {                                                        progressReset = true                                                        resetCompressionProgress(unsentData.isGroup, unsentData.messageId, receiver)                                                    }                                                    val out = smartCompressVideo(                                                        context = context,                                                        inputPathOrUri = orig,                                                        isGroup = unsentData.isGroup,                                                        messageId = unsentData.messageId,                                                        receiver = unsentData.receiver,                                                        index = i,                                                        count = total                                                    )                                                    obj.addProperty(DootawasMessage.DUPLICATE_URI, out)                                                    obj.addProperty("video_transformed", out != orig)                                                    // save after each video so a retry reuses finished ones                                                    insertSendData(unsentData.copy(data = videoData.toString()))                                                    out                                                }                                                filePaths += path                                            }                                        } catch (e: CancellationException) {                                            throw e   // keep finished duplicates, the retry will reuse them                                        } catch (e: Exception) {                                            DLog.e("Multi video transform failed: ${e.message}")                                            // delete every compressed duplicate (never the original)                                            for (el in dataArray) {                                                val o = el.asJsonObject                                                val orig = o.get(DootawasMessage.ORIGINAL_URI)?.asString                                                val dup = o.get(DootawasMessage.DUPLICATE_URI)?.asString                                                if (!dup.isNullOrBlank() && dup != orig && dup.startsWith("/")) File(dup).delete()                                            }                                            deleteSendData(unsentData.messageId, receiver)                                            removeMessage(receiver, unsentData.messageId)                                            return@launch                                        }                                        if (filePaths.isEmpty()) {                                            DLog.i("No valid videos to send")                                            deleteSendData(unsentData.messageId, receiver)                                            removeMessage(receiver, unsentData.messageId)                                            return@launch                                        }                                        // downloadSize must match what is actually uploaded                                        if (filePaths.all { it.startsWith("/") }) {                                            videoData.addProperty(DootawasMessage.DOWNLOAD_SIZE, filePaths.sumOf { File(it).length() })                                        }                                        val finalJson = videoData.toString()                                        insertSendData(unsent