                         removeMessage(receiver, unsentData.messageId)                                        DLog.i("SOMETHING WENT WRONG")                                        DLog.i("FILE IS NULL")                                    }                                }                                FileDataType.DELETE_PROFILE -> {                                    DLog.i("user: ${unsentData.receiver}")                                    val responseCode = deleteProfile(                                        unsentData.isGroup,                                        unsentData.data,                                    )                                    when (responseCode) {                                        in 200..299 -> {                                            DLog.i("✅ Profile downloaded successfully")                                            deleteSendData(                                                unsentData.messageId,                                                unsentData.receiver                                            )                                            removeMessage(                                                unsentData.receiver,                                                unsentData.messageId                                            )                                        }                                        in listOf(502, 503, 504, 429) -> {                                            DLog.i("⚠️ Temporary error ($responseCode), will retry automatically...")                                            // You can enqueue this for retry or leave it pending                                            removeMessage(                                                receiver,                                                unsentData.messageId                                            )                                        }                                        401 -> {                                            DLog.i("🔑 Token expired — refreshing...")//                                                invalidateTokenCache()                                        }                                        else -> {                                            DLog.i("❌ Permanent failure ($responseCode)")                                            deleteSendData(                                                unsentData.messageId,                                                unsentData.receiver                                            )                                            removeMessage(                                                unsentData.receiver,                                                unsentData.messageId                                            )                                        }                                    }                                }                                FileDataType.UNKNOWN -> {                                    deleteSendData(unsentData.messageId, receiver)                                    removeMessage(receiver, unsentData.messageId)                                    DLog.i("SOMETHING WENT WRONG")                                    DLog.i("FILE IS NULL")                                }                                FileDataType.STORY -> {                                    val storyData = JsonParser                                        .parseString(unsentData.data)                                        .asJsonObject                                    val storyId = storyData.get("storyId")?.asString                                    val localPath = storyData.get("localPath")?.asString                                    if (storyId.isNullOrBlank() || localPath.isNullOrBlank()) {                                        DLog.e("STORY: Missing storyId or localPath")                                        deleteSendData(unsentData.messageId, receiver)                                        return@launch                                    }                                    val storyRequest = JsonObject().apply {                                        addProperty(                                            JsonKeys.FILE_TOKEN_TYPE,                                            FileDataTypeToken.STORY_UPLOAD_REQUEST.value                                        )                                        addProperty(                                            JsonKeys.MESSAGE_ID,                                            storyId                                        )                                    }                                    val (uuidG, password) = generateUuidAndStrongPassword()                                    DLog.i("STORY: Starting upload storyId=$storyId")                                    DLog.i("STORY: localPath=$localPath")                                    UploadScheduler.startUpload(                                        context,                                        UploadData(                                            filePaths = listOf(localPath),                                            uuid = storyId,                                            receiversJson = Gson().toJson(listOf(receiver)),                                            password = password,                                            isGroup = false,                                            receiver = receiver,                                            messageId = storyId,                                            dataType = FileDataType.STORY,                                            mainJson = unsentData.data                                        )                                    )                                }                                FileDataType.CONTACT -> TODO()                                FileDataType.REPLY_MESSAGE -> TODO()                                FileDataType.REPLY_CONTACT -> TODO()                                FileDataType.GROUP_ACTION -> TODO()                            }                        } catch (e: Exception) {                            Log.e("UnsentFiles", "Error in unsent files: ${e.message}", e)                            deleteSendData(unsentData.messageId, receiver)                        }                    }                }            }        }    }    fun formatFileSize(sizeInBytes: Long): String {        val kb = sizeInBytes / 1024        val mb = kb / 1024        return when {            mb > 0 -> "$mb MB"            kb > 0 -> "$kb KB"            else -> "$sizeInBytes Bytes"        }    }    @Throws(IOException::class)    private fun extractFrameFromVideo(videoFile: File): Bitmap? {        val retriever = MediaMetadataRetriever()        try {            // Set the data source (the video file)            retriever.setDataSource(videoFile.absolutePath)            // Extract the frame at 1 second (1 second = 1,000,000 microseconds)            val timeUs: Long = 1000000 // 1 second in microseconds            return retriever.getFrameAtTime(timeUs, MediaMetadataRetriever.OPTION_CLOSEST_SYNC)        } catch (e: Exception) {            e.printStackTrace()            return null        } finally {            retriever.release() // Release the retriever after use        }    }    // Helper function    private fun Bitmap.toWebPByteArray(quality: Int = 30): ByteArray {        ByteArrayOutputStream().use { stream ->            compress(Bitmap.CompressFormat.WEBP, quality, stream)            return stream.toByteArray()        }    }    private fun bitmapToWebPBase64(bitmap: Bitmap, quality: Int = 30): String =        Base64.encodeToString(bitmap.toWebPByteArray(quality), Base64.NO_WRAP)    private fun processBlurredPreview(doc: File, isVideo: Boolean): String? {        var originalBitmap: Bitmap? = null        var downSampledBitmap: Bitmap? = null        var croppedBitmap: Bitmap? = null        var base64String: String? = null        try {            originalBitmap = if (isVideo) extractFrameFromVideo(doc)            else BitmapFactory.decodeFile(doc.absolutePath)            if (originalBitmap == null) {                Log.e("ProcessBlur", "❌ Failed to decode bitmap from file.")                return null            }            val width = originalBitmap.width            val height = originalBitmap.height            downSampledBitmap = if (width > 400 || height > 400) {                val targetSize = 210                val downSampleFactor =                    (max(width.toDouble(), height.toDouble()) / targetSize).toInt()                downSampleBitmap(originalBitmap, downSampleFactor)            } else originalBitmap            val downW = downSampledBitmap.width            val downH = downSampledBitmap.height            // ADD THIS BLOCK TO PRINT SIZE IN KB            val webpBytesA = downSampledBitmap.toWebPByteArray(quality = 30)            val sizeInKBB = webpBytesA.size / 1024.0            croppedBitmap = when {                downH > downW * 1.33f -> {                    val desiredHeight = (downW * 1.33f).toInt()                    val cropY = (downH - desiredHeight) / 2                    Bitmap.createBitmap(downSampledBitmap, 0, cropY, downW, desiredHeight)                }                downH < downW * 1.5f -> {                    val desiredWidth = (downH / 1.5f).toInt()                    val cropX = (downW - desiredWidth) / 2                    Bitmap.createBitmap(downSampledBitmap, cropX, 0, desiredWidth, downH)                }                else -> downSampledBitmap            }            val croppedW = croppedBitmap.width            val croppedH = croppedBitmap.height            val mutableCroppedBitmap = croppedBitmap.copy(Bitmap.Config.ARGB_8888, true)            // === With blur ===            val blurredBitmap = blurBitmapA(mutableCroppedBitmap, 10f)            val base64WithBlur = blurredBitmap?.let { compressBitmapToBase64(it) }            val withBlurSize = base64WithBlur?.toByteArray(Charsets.UTF_8)?.size ?: 0            // Choose which version to return            base64String = base64WithBlur        } catch (e: OutOfMemoryError) {            Log.e("ProcessBlur", "OutOfMemoryError: ${e.message}")        } catch (e: Exception) {            Log.e("ProcessBlur", "Error: ${e.message}")        } finally {            originalBitmap?.recycle()            if (downSampledBitmap !== originalBitmap) downSampledBitmap?.recycle()            if (croppedBitmap !== downSampledBitmap && croppedBitmap !== originalBitmap) croppedBitmap?.recycle()        }        return base64String    }    private fun blurBitmapA(inputBitmap: Bitmap, radius: Float): Bitmap? {        return if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {            blurBitmapWithHardwareRenderer(inputBitmap, radius)        } else {            blurBitmap(inputBitmap) // Your previous Stack Blur method        }    }    private fun blurBitmap(bitmap: Bitmap): Bitmap {        val outputBitmap: Bitmap = Bitmap.createBitmap(bitmap)        // Create a RenderScript object        val renderScript: RenderScript = RenderScript.create(context)        // Allocate memory for Renderscript to work with        val input: Allocation = Allocation.createFromBitmap(renderScript, bitmap)        val output: Allocation = Allocation.createFromBitmap(renderScript, outputBitmap)        // Load the script to blur the image        val blur: ScriptIntrinsicBlur =            ScriptIntrinsicBlur.create(renderScript, Element.U8_4(renderScript))        blur.setInput(input)        // Set the blur radius (0 < radius <= 25)        blur.setRadius(17f)        // Perform the Renderscript blur        blur.forEach(output)        // Copy the output bitmap back into the original bitmap        output.copyTo(outputBitmap)        // Destroy the Renderscript instance to free up resources        renderScript.destroy()        return outputBitmap    }    @RequiresApi(Build.VERSION_CODES.S) // API 31 (Android 12)    fun blurBitmapWithHardwareRenderer(inputBitmap: Bitmap, radius: Float): Bitmap? {        // Ensure we're on Android 12+; otherwise, return null or fallback (caller should check)        // Step 1: Set up ImageReader for output        val imageReader = ImageReader.newInstance(            inputBitmap.width,            inputBitmap.height,            PixelFormat.RGBA_8888,            1, // Single output image            HardwareBuffer.USAGE_GPU_SAMPLED_IMAGE or HardwareBuffer.USAGE_GPU_COLOR_OUTPUT        )        // Step 2: Configure RenderNode and HardwareRenderer        val renderNode = RenderNode("BlurEffect")        val hardwareRenderer = HardwareRenderer().apply {            setSurface(imageReader.surface)            setContentRoot(renderNode)        }        renderNode.setPosition(0, 0, imageReader.width, imageReader.height)        // Step 3: Apply blur effect        val blurRenderEffect = RenderEffect.createBlurEffect(            radius.coerceIn(0f, 25f), // Cap radius at 25 for consistency with older APIs            radius.coerceIn(0f, 25f),            Shader.TileMode.MIRROR // Mirror edges for smooth boundaries        )        renderNode.setRenderEffect(blurRenderEffect)        // Step 4: Draw the bitmap with blur        val renderCanvas = renderNode.beginRecording()        renderCanvas.drawBitmap(inputBitmap, 0f, 0f, null)        renderNode.endRecording()        // Step 5: Render and sync        hardwareRenderer.createRenderRequest()            .setWaitForPresent(true)            .syncAndDraw()        // Step 6: Extract the blurred Bitmap from HardwareBuffer        return try {            val image = imageReader.acquireNextImage()                ?: throw RuntimeException("Failed to acquire image from ImageReader")            val hardwareBuffer = image.hardwareBuffer                ?: throw RuntimeException("No HardwareBuffer available")            val blurredBitmap = Bitmap.wrapHardwareBuffer(hardwareBuffer, null)                ?: throw RuntimeException("Failed to create Bitmap from HardwareBuffer")            // Step 7: Clean up resources            hardwareBuffer.close()            image.close()            imageReader.close()            renderNode.discardDisplayList()            hardwareRenderer.destroy()            blurredBitmap        } catch (e: Exception) {            e.printStackTrace()            null        }    }    // Method to calculate the size of a bitmap in bytes    private fun getBitmapSize(bitmap: Bitmap): Int {        val byteArrayOutputStream: ByteArrayOutputStream = ByteArrayOutputStream()        bitmap.compress(Bitmap.CompressFormat.PNG, 100, byteArrayOutputStream)        return byteArrayOutputStream.toByteArray().size // Return size in bytes    }    // DownSample the Bitmap    private fun downSampleBitmap(bitmap: Bitmap, sampleSize: Int): Bitmap {        val width: Int = bitmap.width        val height: Int = bitmap.height        // Calculate the new dimensions        val newWidth: Int = width / sampleSize        val newHeight: Int = height / sampleSize        // Use createScaledBitmap for faster resizing        return bitmap.scale(newWidth, newHeight) // 'true' for filtering for better quality    }    private fun compressBitmapToBase64(bitmap: Bitmap): String? {        return if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {            DLog.i("Using WebP_LOSSY (API 30+)")            compressBitmapToBase64API30(bitmap)        } else {            DLog.i("Using classic WebP (API <30)")            compressBitmapToBase64Legacy(bitmap)        }    }    // ✅ Modern Compression (API 30+)    @RequiresApi(Build.VERSION_CODES.R)    fun compressBitmapToBase64API30(bitmap: Bitmap): String? {        return compressBitmapToBase64Original(bitmap, Bitmap.CompressFormat.WEBP_LOSSY)    }    // ✅ Legacy Compression (API <30)    private fun compressBitmapToBase64Legacy(bitmap: Bitmap): String? {        return compressBitmapToBase64Original(            bitmap,            Bitmap.CompressFormat.JPEG        ) // 🔥 Use JPEG instead of WEBP    }    private fun compressBitmapToBase64Original(        bitmap: Bitmap,        format: Bitmap.CompressFormat    ): String? {        val byteArrayOutputStream = ByteArrayOutputStream()        var quality = 100  // Start at max quality        // Binary search bounds        var maxQuality = 100        var bestByteArray: ByteArray? = null        var lastDecrease = 0        while (0 <= maxQuality) {            byteArrayOutputStream.reset()            // ✅ Ensure quality is always within 0-100 range            quality = quality.coerceIn(0, 100)            bitmap.compress(format, quality, byteArrayOutputStream)            val byteArray = byteArrayOutputStream.toByteArray()            if (byteArray.size <= MAX_SIZE_IN_BYTES) {                // ✅ Found a valid compressed image, store it as best candidate                bestByteArray = byteArray                // ✅ Try increasing quality to get closer to MAX_SIZE_IN_BYTES                val adaptiveIncrease = max((lastDecrease / 2).toDouble(), 1.0).toInt()                val higherQuality = (quality + adaptiveIncrease).coerceIn(0, 100)                byteArrayOutputStream.reset()                bitmap.compress(format, higherQuality, byteArrayOutputStream)                val higherQualityByteArray = byteArrayOutputStream.toByteArray()                if (higherQualityByteArray.size <= MAX_SIZE_IN_BYTES) {                    // ✅ If higher quality still fits, use it                    bestByteArray = higherQualityByteArray                } else {                    // ✅ If higher quality is too large, keep previous best                }                break            } else {                // ❌ Too large, reduce quality using binary search                maxQuality = quality - 1                val newQuality = (0 + maxQuality) / 2                // Calculate last decrease step                lastDecrease = quality - newQuality                quality = newQuality            }            DLog.i("Compression in progress. Quality: $quality, Size: ${byteArray.size} bytes.")        }        if (bestByteArray != null) {            val base64Str = Base64.encodeToString(bestByteArray, Base64.DEFAULT)            DLog.i("✅ Raw compressed image byte array size: ${bestByteArray.size} bytes.")            DLog.i("✅ Base64 encoded string size: ${base64Str.toByteArray(Charsets.UTF_8).size} bytes.")            return base64Str        }        DLog.i("Image could not be compressed to under $MAX_SIZE_IN_BYTES bytes.")        return null    }//    private fun compressBitmapToBase64Original(bitmap: Bitmap, format: Bitmap.CompressFormat): String? {//        val byteArrayOutputStream: ByteArrayOutputStream = ByteArrayOutputStream()//        var quality: Int = 100 // Start with maximum quality////        // Binary search bounds//        val minQuality: Int = 0//        var maxQuality: Int = 100////        // To store the best (smallest) compressed version found//        var bestByteArray: ByteArray? = null//////        // To store the last reduction value (for adaptive increase)//        var lastDecrease: Int = 0////        // Compress the image until it's under the specified size//        while (minQuality <= maxQuality) {//            byteArrayOutputStream.reset() // Reset the output stream//            bitmap.compress(format, quality, byteArrayOutputStream)//            val byteArray: ByteArray = byteArrayOutputStream.toByteArray()////            if (byteArray.size <= MAX_SIZE_IN_BYTES) {//                // Store this as the best candidate so far//                bestByteArray =