null) {//            DLog.i("final image size " + bestByteArray.size)//            // If we found a good candidate, return it as Base64//            return Base64.encodeToString(bestByteArray, Base64.DEFAULT)//        }////        // If compression failed, log the final size//        DLog.i("Image could not be compressed to under $MAX_SIZE_IN_BYTES bytes.")//        return null // Return null if the compression couldn't meet the size limit//    }    /**todo we already have a method [getUserNameFromAll] we can use it but for online name we must put something in front of username*/    suspend fun getNameByNumberFromContactOnly(number: String?): String {        val userContact = number?.let { contactDao.getUserContactByNumber(it) }        return userContact?.name ?: ""    }    private fun formatPhoneNumber(phoneNumber: String): String {        // Remove all non-numeric characters (e.g., spaces, dashes, parentheses)        var formattedPhoneNumber = phoneNumber.replace("\\D".toRegex(), "")        // If the number starts with "91", it's already the desired country code        if (formattedPhoneNumber.startsWith("91")) {            formattedPhoneNumber = formattedPhoneNumber.substring(2) // Remove the "91"        } else if (formattedPhoneNumber.startsWith("0")) {            // If it starts with a leading 0, remove the 0            formattedPhoneNumber = formattedPhoneNumber.substring(1)        }        // If the number doesn't have exactly 10 digits after cleaning, it's invalid        if (formattedPhoneNumber.length != 10) {            return "" // Invalid phone number        }        // Prepend "91-" to the phone number and return        return "91-$formattedPhoneNumber"    }    suspend fun deleteSendData(messageId: String, receiver: String) {        unsentFilesDao.deleteByMessageIdAndSender(messageId, receiver)    }    private suspend fun deleteUnsentData(messId: String?, chunk: DataType?, receiver: String?) {        if (messId != null && chunk != null && receiver != null) {            unsentSandeshDao.deleteByMessIdAndSender(messId, chunk, receiver)            //unsentSandeshDao.deleteOldestSentMessagesOverLimit()        }    }    private suspend fun markAsSent(messId: String?, chunk: DataType?, receiver: String?) {        if (messId != null && chunk != null && receiver != null) {            val rowsUpdated = unsentSandeshDao.markAsSent(messId, chunk, receiver)            unsentSandeshDao.deleteOldestSentMessagesOverLimit()            // Optional: Log how many are left (for extra insight)            val totalSentCount = unsentSandeshDao.countSentMessages()        } else {            Log.w(                "deleteUnsentData",                "Skipping deletion: One or more parameters are null (messId=$messId, chunk=$chunk, receiver=$receiver)"            )        }    }    suspend fun insertUnsentData(        unsentSandesh: UnsentSandesh,        checkAlready: Boolean = true    ) {        try {            insertUnsentSandeshMutex.withLock {                if (checkAlready) {                    val existing = unsentSandeshDao.findSimilarUnsentSandesh(                        receiver = unsentSandesh.receiver,                        message = unsentSandesh.message ?: "",                        dataType = unsentSandesh.dataType                    )                    if (existing != null) {                        DLog.i("⚠️ Similar unsentSandesh already exists, skipping insert: $existing")                        return                    }                }                DLog.i("ADDING TO UNSENT")                unsentSandeshDao.insert(unsentSandesh)            }        } catch (e: Exception) {            e.printStackTrace()            Log.e(ContentValues.TAG, "❌ Error inserting unsentSandesh: ${e.message}")        }    }    private fun insertSendData(unsentFiles: UnsentFiles) {        unsentFilesDao.insert(unsentFiles)    }    private suspend fun getSandeshStithiTime(        userNumber: String,        sandeshId: String,        stithi: SandeshStithi    ): String {        // Try to fetch the existing JSON from DB        val existingJson = sandeshStatusDao.getStatusJson(userNumber, sandeshId)            ?: // No JSON found — just return current time            return System.currentTimeMillis().toString()        // Parse to JSON object safely        val jsonObject = try {            Gson().fromJson(existingJson, JsonObject::class.java)        } catch (e: Exception) {            // If malformed JSON, fallback to now            return System.currentTimeMillis().toString()        }        // Return stored time if found, else current time        return jsonObject.get(stithi.value.toString())?.asString            ?: System.currentTimeMillis().toString()    }    private fun setup() {        CoroutineScope(Dispatchers.IO).launch {            val start = System.currentTimeMillis()            val prefs = userDataStore.data.first()            val end = System.currentTimeMillis()            val audioAttributes = AudioAttributes.Builder()                .setUsage(AudioAttributes.USAGE_NOTIFICATION)                .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)                .build()            soundPool = SoundPool.Builder()                .setMaxStreams(1)                .setAudioAttributes(audioAttributes)                .build()            soundId = soundPool.load(context, R.raw.dootawas_noti, 1)            soundPool.setOnLoadCompleteListener { _, _, _ ->                isLoaded = true            }        }    }    // ───────────────────────────────────────────────────────────    // Always Read These Dynamically From DataStore    // ───────────────────────────────────────────────────────────    suspend fun shouldPlayNotificationSound(): Boolean {        return settingStore.data            .map { it[SettingPrefKeys.MESSAGE_SOUND] != false }            .first()    }    //    suspend fun getNotificationTone(): String? {//        return settingStore.data//            .map { it[SettingPrefKeys.NOTIFICATION_TONE] }//            .firstOrNull()//    }////    suspend fun isVibrationEnabled(): Boolean {//        return settingStore.data//            .map { it[SettingPrefKeys.NOTIFICATION_VIBRATE] ?: true }//            .first()//    }//    private lateinit var soundPool: SoundPool    private var soundId: Int = 0    private var isLoaded = false    private var lastPlayedTime: Long = 0  // Track last play timestamp    fun vibrateDevice() {        val vibrator = context.getSystemService(VIBRATOR_SERVICE) as Vibrator        vibrator.vibrate(VibrationEffect.createOneShot(100, VibrationEffect.DEFAULT_AMPLITUDE))    }    private fun playReceivedSound() {        val currentTime = SystemClock.elapsedRealtime()        if (isLoaded && (currentTime - lastPlayedTime >= 500)) {            soundPool.play(soundId, 1f, 1f, 1, 0, 1f)            lastPlayedTime = currentTime        }    }    private suspend fun insertSandeshWithCheck(        sandesh: Sandesh,        messagePass: String,        notiOn: Boolean,        storageType: Int,        yourAreRevealedToSender: Boolean    ) {        DLog.i("Saving Received Message To DataBase")        val sandeshDao: SandeshDao = dootawasDatabase.sandeshDao()        // Check if the message already exists        val existingSandesh: Sandesh? =            sandeshDao.getSandeshByIdAndUser(sandesh.sandeshId, sandesh.userNumber)        if (existingSandesh == null) {            val instant: Instant = Instant.now()            val epochMillis: Long = instant.toEpochMilli()            val newTime: String = epochMillis.toString()            if (yourAreRevealedToSender) {                val revealSender = upbhogtaDao.getRevealSender(sandesh.userNumber)                if (revealSender == false) {                    upbhogtaDao.updateRevealSender(sandesh.userNumber, true)                }            }            val deletedIds = recentDeletedMessageIds.first() // Suspends until data is loaded, no flag needed            if (deletedIds.contains(sandesh.sandeshId)) {                DLog.i("Duplicate message → skip")                return            }            val duration = upbhogtaDao.getAutoDisappearDuration(sandesh.userNumber)            val messageToSave = if (duration != 0) "new message" else messagePass            upbhogtaDao.incrementUnreadByUserNumber(sandesh.userNumber)            checkAndInsertUser(sandesh.userNumber, messageToSave, sandesh.sandeshId,isRsn = yourAreRevealedToSender)            sandeshDao.insertMessage(sandesh)            val playSound2 = shouldPlayMessageSound(sandesh.userNumber, false)            updateSandeshStithiTime(                sandesh.userNumber,                sandesh.sandeshId,                SandeshStithi.SAMARPIT,                newTime.toLong()            )            if (notiOn) {                    if (playSound2) {                        notifier.showMessage(                            sandesh.userNumber,                            messageToSave,                            sandesh.sandeshId,                            wakeScreen = true                        )                    }                    DLog.i("SENDING SPRING A")            } else {                val vibrate = shouldVibrateOnMessage()                if (vibrate) {                    vibrateDevice()                }                if (playSound2) {                    if (sandesh.userNumber != activeScreenUser) {                        notifier.showMessage(                            sandesh.userNumber,                            messageToSave,                            sandesh.sandeshId,                            countInBadge = false                        )                    } else {                        playReceivedSound()                    }                }            }            val confirmationJson = JSONObject().apply {                put(JsonKeys.SENT_DATA_TYPE, 0)                put(JsonKeys.DATA, sandesh.time)                put(JsonKeys.STORAGE_TYPE, storageType)                put(JsonKeys.MESSAGE_ID, sandesh.sandeshId)            }            sendDeliveryConfirmation(                sandesh.sandeshId,                sandesh.userNumber,                confirmationJson.toString(),                DataType.DELIVERY_CONFIRMATION,                newTime, sendSpringDelivery = notiOn            )        } else {            DLog.i("Message Already Exist")            val confirmationJson = JSONObject().apply {                put(JsonKeys.SENT_DATA_TYPE, 0)                put(JsonKeys.DATA, sandesh.time)                put(JsonKeys.STORAGE_TYPE, storageType)                put(JsonKeys.MESSAGE_ID, sandesh.sandeshId)            }            try {                sendDeliveryConfirmation(                    sandesh.sandeshId,                    sandesh.userNumber,                    confirmationJson.toString(),                    DataType.DELIVERY_CONFIRMATION,                    getSandeshStithiTime(                        sandesh.userNumber,                        sandesh.sandeshId,                        SandeshStithi.SAMARPIT                    ),sendSpringDelivery = notiOn                )                DLog.i(("Duplicate record found. Message ID: " + sandesh.sandeshId + ", Sender: " + sandesh.userNumber + " : Message " + sandesh.samagri))            } catch (e: JSONException) {                throw RuntimeException(e)            }        }    }    private suspend fun insertGroupWithCheck(        groupSandesh: GroupSandesh, messagePass: String,        notiOn: Boolean, storageType: Int    ) {        // Check if the message already exists        DLog.i("${groupSandesh.groupId} ${groupSandesh.userNumber} ${groupSandesh.sandeshId}")        val existingSandesh: GroupSandesh? = groupDao.getGroupSandeshByIdAndUser(            groupSandesh.sandeshId,            groupSandesh.groupId,            groupSandesh.userNumber        )        if (existingSandesh == null) {            val instant: Instant = Instant.now()            val epochMillis: Long = instant.toEpochMilli()            val newTime: String = epochMillis.toString()            val confirmationJson = JSONObject().apply {                put(JsonKeys.SENT_DATA_TYPE, 0)                put(JsonKeys.DATA, groupSandesh.time)                put(JsonKeys.GROUP_ID, groupSandesh.groupId)                put(JsonKeys.STORAGE_TYPE, storageType)                put(JsonKeys.MESSAGE_ID, groupSandesh.sandeshId)            }            sendDeliveryConfirmation(                groupSandesh.sandeshId,                groupSandesh.userNumber,                confirmationJson.toString(), // ✅ send full JSON                DataType.DELIVERY_CONFIRMATION,                getSandeshStithiTime(groupSandesh.userNumber, groupSandesh.sandeshId, SandeshStithi.SAMARPIT),                true,notiOn            )            val unsentSandeshA = UnsentSandesh(                messId = groupSandesh.sandeshId,                receiver = groupSandesh.userNumber,                message = confirmationJson.toString(),                dataType = DataType.DELIVERY_CONFIRMATION,                isGroup = true,                time = newTime            )//            insertUnsentData(unsentSandeshA, false)            sendUnsentMessages(false)            val deletedIds = recentDeletedMessageIds.first() // Suspends until data is loaded, no flag needed            if (deletedIds.contains(groupSandesh.sandeshId)) {                DLog.i("Duplicate message → skip")                return            }            groupDao.incrementUnreadByUserNumber(groupSandesh.groupId)            groupDao.insertMessage(groupSandesh)            checkAndInsertGroup(groupSandesh.groupId, messagePass, groupSandesh.sandeshId)            val playSound2 = shouldPlayMessageSound(groupSandesh.groupId, true)            if (!notiOn) {                val vibrate = shouldVibrateOnMessage()                if (vibrate) {                    vibrateDevice()                }                if (playSound2) {                    if (groupSandesh.userNumber != activeScreenUser) {                        playReceivedSound()                        val groupName = groupDao.getGroupNameByGroupId(groupSandesh.groupId) ?: ""                        notifier.showGroupMessage(                            groupSandesh.groupId,                            groupName,                            groupSandesh.userNumber,                            messagePass,                            groupSandesh.sandeshId,                        )                    }                }            } else {                if (playSound2) {                    val groupName = groupDao.getGroupNameByGroupId(groupSandesh.groupId) ?: ""                    notifier.showGroupMessage(                        groupSandesh.groupId,                        groupName,                        groupSandesh.userNumber,                        messagePass,                        groupSandesh.sandeshId,                        wakeScreen = true                    )                }                    sendUnsentMessages(true)                }            updateSandeshStithiTime(                groupSandesh.userNumber,                groupSandesh.sandeshId,                SandeshStithi.SAMARPIT,                newTime.toLong()            )        } else {            try {                val confirmationJson = JSONObject().apply {                    put(JsonKeys.SENT_DATA_TYPE, 0)                    put(JsonKeys.GROUP_ID, groupSandesh.groupId)                    put(JsonKeys.DATA, groupSandesh.time)                    put(JsonKeys.STORAGE_TYPE, storageType)                    put(JsonKeys.MESSAGE_ID, groupSandesh.sandeshId)                }//                val unsentSandeshA = UnsentSandesh(//                    messId = groupSandesh.sandeshId,//                    receiver = groupSandesh.userNumber,//                    message = confirmationJson.toString(),//                    dataType = DataType.DELIVERY_CONFIRMATION,//                    isGroup = true,//                    //todo if data is already inserted we should get its new time from db//                    // also do it for sandesh//                )//                insertUnsentData(unsentSandeshA, false)                        sendDeliveryConfirmation(                            groupSandesh.sandeshId,                            groupSandesh.userNumber,                            confirmationJson.toString(), // ✅ send full JSON                            DataType.DELIVERY_CONFIRMATION,                            getSandeshStithiTime(groupSandesh.userNumber, groupSandesh.sandeshId, SandeshStithi.SAMARPIT),                            true,notiOn                        )                sendUnsentMessages(false)                DLog.i(("Duplicate record found. Message ID: " + groupSandesh.sandeshId + ", Sender: " + groupSandesh.userNumber + " : Message " + groupSandesh.samagri))            } catch (e: JSONException) {                throw RuntimeException(e)            }        }    }    @SuppressLint("InvalidWakeLockTag")    private fun wakeApp() {        val pm = context.getSystemService(Context.POWER_SERVICE) as PowerManager        val screenIsOn = pm.isInteractive        DLog.i("wakeApp $screenIsOn")        if (!screenIsOn) {            val wakeLockTag = "${context.packageName}:WAKELOCK"            val wakeLock = pm.newWakeLock(                PowerManager.PARTIAL_WAKE_LOCK,                wakeLockTag            )            try {                wakeLock.acquire(10 * 60 * 1000L) // Keep CPU on for 10 minutes max            } catch (e: Exception) {                e.printStackTrace()            }            // Release early to avoid holding too long            Handler(Looper.getMainLooper()).postDelayed({                if (wakeLock.isHeld) wakeLock.release()            }, 1000L) // Release after 1 second        }    }    @SuppressLint("UseKtx")    fun createNotificationChannels() {        val notificationManager = context.getSystemService(NotificationManager::class.java)        if (notificationManager == null) {            Log.w("NotificationChannel", "NotificationManager is null")            return        }        val channels = mutableListOf<NotificationChannel>()        // 🔥 DEFAULT CHANNEL (required for FCM fallback)        val defaultChannel = NotificationChannel(            "default_channel",            "General Notifications",            NotificationManager.IMPORTANCE_HIGH        ).apply {            description = "Default notifications"            enableVibration(true)        }        channels += defaultChannel        // 🔥 Incoming Call (Sound handled manually)        val incomingCallSound = NotificationChannel(            "incoming_call_sound_channel",            "Incoming Calls (Sound)",            NotificationManager.IMPORTANCE_HIGH        ).apply {            description = "Call alerts with ringtone"            setSound(null, null)            enableVibration(true)        }        channels += incomingCallSound        // 🔥 Message Notification (default system sound)        val messageSound = NotificationChannel(            "message_sound_channel",            "Messages (Sound)",            NotificationManager.IMPORTANCE_HIGH        ).apply {            description = "Messages with default sound"            val attrs = AudioAttributes.Builder()                .setUsage(AudioAttributes.USAGE_NOTIFICATION)                .build()            setSound(Settings.System.DEFAULT_NOTIFICATION_URI, attrs)            enableVibration(true)        }        channels += messageSound        // 🔥 Incoming Call (Vibrate only)        val incomingCallVibrate = NotificationChannel(            "incoming_call_vibrate_channel",            "Incoming Calls (Vibrate)",            NotificationManager.IMPORTANCE_HIGH        ).apply {            setSound(null, null)            enableVibration(true)            vibrationPattern = longArrayOf(0, 200, 200, 300)        }        channels += incomingCallVibrate        // 🔥 Message (Vibrate only)        val messageVibrate = NotificationChannel(            "message_vibrate_channel",            "Messages (Vibrate)",            NotificationManager.IMPORTANCE_HIGH        ).apply {            setSound(null, null)            enableVibration(true)            vibrationPattern = longArrayOf(0, 150, 150, 200)        }        channels += messageVibrate        // 🔥 Incoming Call (Silent)        val incomingCallSilent = NotificationChannel(            "incoming_call_silent_channel",            "Incoming Calls (Silent)",            NotificationManager.IMPORTANCE_HIGH        ).apply {            setSound(null, null)            enableVibration(false)        }        channels += incomingCallSilent        // 🔥 Message (Silent)        val messageSilent = NotificationChannel(            "message_silent_channel",            "Messages (Silent)",            NotificationManager.IMPORTANCE_HIGH        ).apply {            setSound(null, null)            enableVibration(false)        }        channels += messageSilent        // 🔥 Create all channels at once        // 🔥 Active Call Timer (silent, ongoing)        val callTimer = NotificationChannel(            "call_timer_channel",            "Active Call Timer",            NotificationManager.IMPORTANCE_DEFAULT        ).apply {            description = "Shows call duration during an active call"            setSound(null, null)            enableVibration(false)        }        channels += callTimer        // 🔥 Live Location (silent, background updates)        val liveLocation = NotificationChannel(            "live_location_channel",            "Live Location",            NotificationManager.IMPORTANCE_LOW        ).apply {            description = "Shows ongoing live location sharing updates"            setSound(null, null)            enableVibration(false)            setShowBadge(false)        }        channels += liveLocation        notificationManager.createNotificationChannels(channels)    }    fun startVibrate(context: Context) {        val vibrator = context.getSystemService(VIBRATOR_SERVICE) as? Vibrator        vibrator?.vibrate(VibrationEffect.createOneShot(500, VibrationEffect.DEFAULT_AMPLITUDE))    }    fun notificationReply(userNumber: String, replyMessage: String) {        coroutineScope.launch {            writeMessageMutex.withLock {                val duration = upbhogtaDao.getAutoDisappearDuration(userNumber)                DLog.i("NOTI NOTI CALLED")                // Normal message                val message = JsonObject().apply {                    addProperty(DootawasMessage.PAATH, replyMessage)                    addProperty(DootawasMessage.IS_LINK, false)                    addProperty(DootawasMessage.DISAPPEAR_DURATION,duration)                }                val newSandesh = Sandesh(                    sandeshId = createMessageID(),                    userNumber = userNumber,                    samagri = message.toString(),                    isSelf = true, // ✅ Always true for self-messages                    time = Instant.now().toEpochMilli(), // ✅ Instant-based timestamp                    sandeshType = SandeshType.MESSAGE.value,                    sandeshStithi = SandeshStithi.LIKHIT                )                message.addProperty(DootawasMessage.SANDESH_TYPE, SandeshType.MESSAGE.value)                val unsentSandesh = UnsentSandesh(                    messId = newSandesh.sandeshId,                    receiver = userNumber,                    message = message.toString(),                    dataType = DataType.MESSAGE                )                sandeshDao.insertMessage(newSandesh)                checkAndInsertUser(userNumber, replyMessage, newSandesh.sandeshId)                sendMessage(unsentSandesh)                syncMessagesInBackground()                notifier.addReply(userNumber, replyMessage, newSandesh.sandeshId)            }        }    }    fun syncMessagesInBackground(){        if (!isParmaan) {            reason = ConnectReason.SendDataOnly            SocketManager.setAppActive(true)        }    }    /** true = messages pending, false = none, null = couldn't check (no network, timeout, bad response) */    suspend fun isMessagePending(): Boolean? {        if (isParmaan) return false        activeScreenUser = ""                       // kept from your original function        val token = userDataStore.data.first()[PrefKeys.DELIVERY_TOKEN]        if (token == null) {            DLog.i("Pending check skipped → token null")            return false        }        val json = JsonObject().apply {            addProperty(JsonKeys.SAMABHASH_TOKEN, token)            addProperty(JsonKeys.DATA_TYPE, DataType.IS_MESSAGE_PENDING.value)        }        return withTimeoutOrNull(15_000L.milliseconds) {            suspendCancellableCoroutine<Boolean?> { cont ->                ReceiptSender.send(json.toString()) { success, message ->                    if (!cont.isActive) return@send       // callback fired twice or after timeout                    if (!success) {                        cont.resume(null)                        return@send                    }                    try {                        val response = JsonParser.parseString(message).asJsonObject                        cont.resume(response.get(JsonKeys.DATA_BOOLEAN)?.asBoolean ?: false)                    } catch (e: Exception) {                        DLog.e("Pending check parse error", e)                        cont.resume(null)                    }                }            }        }   // timeout → null    }    /** Old entry point, so existing callers keep working. */    fun checkPendingMessages() {        coroutineScope.launch {            if (isMessagePending() == true) SocketManager.setAppActive(true)        }    }//    private val messagingStyleMap = mutableMapOf<String, NotificationCompat.MessagingStyle>()    fun removeUserFromNotification(sender: String) {        notifier.clearConversation(sender)        notifier.clearMissedCallNotification(sender)//        DLog.i("REMOVING USE FROM NOTI $sender $messagingStyleMap")//        val notificationId = sender.hashCode()//        NotificationManagerCompat.from(context).cancel(notificationId)//        messagingStyleMap.remove(sender)    }    @WorkerThread    private fun showAddedToGroupNotification(sender: String, groupName: String) {        val audioManager = context.getSystemService(AUDIO_SERVICE) as AudioManager        val channelId = when (audioManager.ringerMode) {            AudioManager.RINGER_MODE_NORMAL -> "message_sound_channel"            AudioManager.RINGER_MODE_VIBRATE -> "message_vibrate_channel"            else -> "message_silent_channel"        }        // Create intent to open app when clicked        val mainIntent = Intent(context, MainActivity::class.java).apply {            flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK        }        val mainPendingIntent = PendingIntent.getActivity(            context,            0,            mainIntent,            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE        )        val builder = NotificationCompat.Builder(context, channelId)            .setSmallIcon(R.mipmap.ic_launcher)            .setContentTitle("Added to group")            .setContentText("$sender added you to $groupName")            .setPriority(NotificationCompat.PRIORITY_HIGH)            .setCategory(NotificationCompat.CATEGORY_SOCIAL)            .setContentIntent(mainPendingIntent)            .setAutoCancel(true)        val notificationManager = NotificationManagerCompat.from(context)        if (ActivityCompat.checkSelfPermission(context, Manifest.permission.POST_NOTIFICATIONS) !=            PackageManager.PERMISSION_GRANTED        ) {            return        }        notificationManager.notify(groupName.hashCode(), builder.build())    }    private fun bold(text: String): CharSequence {        return SpannableString(text).apply {            setSpan(                StyleSpan(Typeface.BOLD),                0,                text.length,                Spannable.SPAN_EXCLUSIVE_EXCLUSIVE            )        }    }    private fun currentChannelId(): String {        val am = context.getSystemService(Context.AUDIO_SERVICE) as AudioManager        return when (am.ringerMode) {            AudioManager.RINGER_MODE_NORMAL -> "message_sound_channel"            AudioManager.RINGER_MODE_VIBRATE -> "message_vibrate_channel"            else -> "message_silent_channel"        }    }//    suspend fun addReplyToNotification(//        sender: String,//        replyText: String,//        messageId: String//    ) {//        val notificationManager = NotificationManagerCompat.from(context)//        if (!notificationManager.areNotificationsEnabled()) return////        val displayName = upbhogtaDao.getUserNameByNumber(sender)//            ?.takeIf { it.isNotBlank() } ?: sender////        val messagingStyle = NotificationStore.messagingStyleMap[sender] ?: return////        messagingStyle.addMessage(//            NotificationCompat.MessagingStyle.Message(//                bold(replyText),//                System.currentTimeMillis(),//                createYouPerson()      // must use the same key/name as the original userPerson//            )//        )