curityException) {//            DLog.e("Notification permission missing: $e")//        }//    }//    // ✅ Always create a NEW Person for "You"//    private suspend fun createYouPerson(): Person {//        val myProfileUrl = profileImagePathFlow.firstOrNull()//        val myProfileBitmap = loadProfileBitmapFromUrl(myProfileUrl)////        val roundMyBitmap = myProfileBitmap?.let { makeBitmapRound(it) }////        return Person.Builder()//            .setName("You")//            .apply {//                if (roundMyBitmap != null) {//                    setIcon(IconCompat.createWithBitmap(roundMyBitmap))//                } else {//                    setIcon(IconCompat.createWithResource(context, R.drawable.ic_person_thematic))//                }//            }//            .build()//    }    fun resolveDisplayName(        onlineName: String?,        contactName: String?,        fallback: String    ): String {        return when {            !onlineName.isNullOrBlank() -> onlineName            !contactName.isNullOrBlank() -> contactName            else -> fallback        }    }    suspend fun createCallUpbhogta(userNumber: String): CallUpbhogta {        val user = upbhogtaDao.getUserByNumber(userNumber)        val displayName = resolveDisplayName(            onlineName = user?.onlineName,            contactName = user?.contactName,            fallback = userNumber        )        return CallUpbhogta(            userNumber = userNumber,            userName = displayName,            profileImageUrl = getUserProfileImageUrlFromAll(userNumber),            status = user?.status,            isBlocked = user?.isBlocked ?: false,            isOnline = false        )    }    suspend fun getUserNameFromAll(userNumber: String): String {        // 3️⃣ Local contacts        val contactName = contactDao.getUserNameByNumber(userNumber)        if (!contactName.isNullOrBlank()) {            return contactName        }        // 1️⃣ Upbhogta online name        val onlineName = upbhogtaDao.getUserOnlineNameByNumber(userNumber)        if (!onlineName.isNullOrBlank()) {            return onlineName        }        // 4️⃣ Group (fallback – optional)        val groupName = groupDao.getUserOnlineNameByNumber(userNumber)        if (!groupName.isNullOrBlank()) {            return groupName        }        // 5️⃣ Final fallback        return userNumber    }    suspend fun getUserProfileImageUrlFromAll(userNumber: String): String? {        val upbhogtaUrl = upbhogtaDao.getImageUrlByNumber(userNumber)        if (!upbhogtaUrl.isNullOrBlank()) {            return upbhogtaUrl        }        val contactUrl = contactDao.getImageUrlByNumber(userNumber)        if (!contactUrl.isNullOrBlank()) {            return contactUrl        }        val groupUrl = groupDao.getImageUrlByNumber(userNumber)        if (!groupUrl.isNullOrBlank()) {            return groupUrl        }        return null    }////    @WorkerThread//    fun showFallbackNotification(sender: String, text: String) {//        val notificationManager = NotificationManagerCompat.from(context)//        if (!notificationManager.areNotificationsEnabled()) return////        val mainIntent = Intent(context, MainActivity::class.java).apply {//            flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP//            data = "app://chat/$sender".toUri()//            putExtra("open_chat_user", sender)//        }////        val pendingIntent = PendingIntent.getActivity(//            context,//            sender.hashCode(),//            mainIntent,//            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE//        )////        val builder = NotificationCompat.Builder(context, "message_silent_channel")//            .setSmallIcon(R.mipmap.ic_launcher_background)//            .setContentTitle(text)//            .setContentText("Open app to sync")//            .s