er(            context,            "live_location_channel"        )            .setSmallIcon(R.mipmap.ic_launcher_foreground)            .setContentTitle(sender)            .setContentText(text)            .setCategory(NotificationCompat.CATEGORY_SERVICE)            .setPriority(NotificationCompat.PRIORITY_LOW)            .setVisibility(NotificationCompat.VISIBILITY_PRIVATE)            .setOnlyAlertOnce(true)            .setOngoing(true)            .setSilent(true)            .setContentIntent(openIntent)        NotificationManagerCompat            .from(context)            .notify(notificationId, builder.build())    }    fun showPlaceholderNotification(sender: String) {        notifier.showPlaceholder(sender = sender)    }    fun showFallbackNotification(target: String) {        notifier.showFallback(target)    }//    @WorkerThread//    private suspend fun showMessageNotification(//        sender: String,//        message: String,//        messageId: String,//        timestamp: Long = System.currentTimeMillis()//    ) {//        val notificationManager = NotificationManagerCompat.from(context)//        // Bail out early, before doing any network/DB work//        if (!notificationManager.areNotificationsEnabled()) return////        val displayName = upbhogtaDao.getUserNameByNumber(sender)//            ?.takeIf { it.isNotBlank() } ?: sender//        val profileBitmap = withContext(Dispatchers.IO) {//            loadProfileBitmapFromUrl(upbhogtaDao.getImageUrlByNumber(sender))//        }?.let { makeBitmapRound(it) }////        val icon = profileBitmap?.let { IconCompat.createWithBitmap(it) }//            ?: IconCompat.createWithResource(context, R.drawable.ic_person_thematic)////        val notificationId = sender.hashCode()////        // Person needs a stable key so Android can group/identify the conversation//        val userPerson = Person.Builder().setName("You").setKey("me").build()//        val senderPerson = Pe