                 .allowHardware(false) // ✅ REQUIRED for notifications                    .build()                val result = (loader.execute(request) as? SuccessResult)?.drawable                (result as? BitmapDrawable)?.bitmap            } catch (e: Exception) {                null            }        }    }    fun processFirebaseMessage(jsonMessage: JsonObject) {        coroutineScope.launch {            messageReceivedMutex.withLock {                try {                    handleInternalMessage(jsonMessage, true)                } catch (e: Exception) {                    Log.e("Knotx NOTI CRASHED", e.toString())                    handleMalformedJsonDelivery(jsonMessage.toString(), e)                }            }        }    }    suspend fun checkAndInsertUser(        userNumber: String,        lastMessage: String,        messageId: String,        isSelf: Boolean = false,        isRsn: Boolean = false    ) {        val exists = upbhogtaDao.doesUserExist(userNumber) > 0        val trimmedMessage = if (lastMessage.length > 30) {            lastMessage.take(30) + "..."        } else {            lastMessage        }        if (exists) {            upbhogtaDao.updateLastMessageAndId(                userNumber,                trimmedMessage,                System.currentTimeMillis(),                messageId,                SandeshStithi.LIKHIT            )        } else {            DLog.i("INSERTING NEW USER $userNumber $exists")            val upbhogta = Upbhogta(                contactName = getNameByNumberFromContactOnly(userNumber),                userNumber = userNumber,                photoUrl = null,                lastMessage = lastMessage,                lastOnline = System.currentTimeMillis(),                totalUnread = if (isSelf) 0 else 1,                status = null,                encryptionKey = null,                isBlocked = false,                isPinned = false,            