     if (!isLink) return@launch                val fullText = samagri.get(DootawasMessage.PAATH)?.asString ?: return@launch                // 🔥 Extract first URL directly here                val pattern = Pattern.compile(                    "(https?://[\\w-]+(\\.[\\w-]+)+(:\\d+)?(/[\\w-./?%&=]*)?)|(www\\.[a-zA-Z0-9\\-]+\\.[a-zA-Z]{2,})"                )                val matcher = pattern.matcher(fullText)                if (!matcher.find()) return@launch                var url = matcher.group()                if (url.startsWith("www")) {                    url = "http://$url"                }                val preview = fetchLinkPreview(url) ?: return@launch                val localImagePath = preview.imageUrl?.let {                    downloadAndSaveImage(it)                }                preview.title?.let {                    samagri.addProperty(DootawasMessage.LINK_TITLE, it)                }                localImagePath?.let {                    samagri.addProperty(DootawasMessage.LINK_URI, it)                }                if (isGroup && groupId != null) {                    groupDao.updateSamagri(                        sandeshId = msgId,                        samagri = samagri.toString(),                        groupId = groupId                    )                } else {                    sandeshDao.updateSamagri(                        sandeshId = msgId,                        samagri = samagri.toString()                    )                }            } catch (e: Exception) {                e.printStackTrace()            }        }    }    fun storeReaction(        msgId: String,        reaction: String?, // null = remove        isGroup: Boolean,        groupIdOrUser: String,        whoIsReacting: String // "self" or "other"    ) {        coroutineScope.launch {            try {                // 1️⃣ Get existing message                val existingMessage = if (isGroup) {                    groupDao.getGroupSandeshByIdAndGroupId(msgId, groupIdOrUser)                } else {                    sandeshDao.getSandeshByIdAndUser(msgId, groupIdOrUser)                } ?: return@launch                val samagriString = when (existingMessage) {                    is Sandesh -> existingMessage.samagri                    is GroupSandesh -> existingMessage.samagri                    else -> return@launch                }                val json = JsonParser                    .parseString(samagriString)                    .asJsonObject                // 2️⃣ Get or create reactions object                val reactions = if (json.has("reactions") &&                    json.get("reactions").isJsonObject                ) {                    json.getAsJsonObject("reactions")                } else {                    JsonObject().also {                        json.add("reactions", it)                    }                }                // 3️⃣ Update / Remove reaction                if (reaction.isNullOrBlank()) {                    reactions.remove(whoIsReacting)                } else {                    reactions.addProperty(whoIsReacting, reaction)                }                // 4️⃣ Clean up if reactions empty                if (reactions.entrySet().isEmpty()) {                    json.remove("reactions")                }                // 5️⃣ Update DB                if (isGroup) {                    groupDao.updateSamagri(                        sandeshId = msgId,                        samagri = json.toString(),                        groupId = groupIdOrUser                    )                } else {                    sandeshDao.updateSamagri(                        sandeshId = msgId,                        samagri = json.toString()                    )                }            } catch (e: Exception) {                e.printStackTrace()            }        }    }    private suspend fun downloadAndSaveImage(imageUrl: String): String? {        return withContext(Dispatchers.IO) {            try {                val url = URL(imageUrl)                val connection = url.openConnection()                connection.connect()                val input = connection.getInputStream()                val fileName = "preview_${System.currentTimeMillis()}.webp"                val file = File(                    context.filesDir,                    "link_previews/$fileName"                )                file.parentFile?.mkdirs()                file.outputStream().use { output ->                    input.copyTo(output)                }                file.toURI().toString()            } catch (e: Exception) {                null            }        }    }    fun updateLastUpdatedToTop(targetUserNumber: String) {//        val usersDao: UsersDao = DootawasDatabase.usersDao()//        val userList: List<Users> = usersDao.allUsersOrderedBySerial//        // Find the target user and its current serial//        // Set the target user's serial to 1//        for (user: Users in userList) {//            if (user.getNumber() == targetUserNumber) {//                user.serial = 1//                break//            }//        }////        // Update the serial values for other users in continuous series//        var serialCounter = 2//        for (user: Users in userList) {//            if (user.getNumber() != targetUserNumber) {//                user.serial = serialCounter++//            }//        }////        // Update the database with the modified users//        for (user: Users in userList) {//            usersDao.updateUserSerial(user.getNumber(), user.serial)//        }    }    //    public  void changeStatus( String username, String statusTOChange){    //        databaseWriteExecutor.execute(() -> {    //            if (DootawasDatabase == null) {    //                DootawasDatabase = DootawasData