mpat.checkSelfPermission(                    context,                    Manifest.permission.READ_CONTACTS                ) == PackageManager.PERMISSION_GRANTED            ) {                val contactList = mutableListOf<Contact>()                val uri: Uri = ContactsContract.CommonDataKinds.Phone.CONTENT_URI                val cursor: Cursor? = context.contentResolver.query(uri, null, null, null, null)                val khudNumber = userNumberKhud.firstOrNull()                DLog.i("KHUD KA NUMBER $khudNumber")                cursor?.use {                    while (it.moveToNext()) {                        val nameIndex =                            it.getColumnIndex(ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME)                        val phoneIndex =                            it.getColumnIndex(ContactsContract.CommonDataKinds.Phone.NUMBER)                        val name = if (nameIndex != -1) it.getString(nameIndex) else null                        val phoneNumber = if (phoneIndex != -1) it.getString(phoneIndex) else null                        if (!name.isNullOrBlank() && !phoneNumber.isNullOrBlank()) {                            val formattedPhoneNumber =                                normalizePhoneNumber(phoneNumber, getDefaultRegion())                            if (!formattedPhoneNumber.isNullOrEmpty()) {                                var finalName = name                                if (formattedPhoneNumber == khudNumber) {                                    finalName += " (you)"                                }                                DLog.i("GOT CONTACT: $finalName phone: $formattedPhoneNumber")                                contactList.add(                                    Contact(                                        name = finalName,                                        number = formattedPhoneNumber                                    )                                )                            }                        }                    }                }                // ✅ Remove duplicates from `contactList` (before database check)                val uniqueContacts = contactList.distinctBy { it.name to it.number }                // ✅ Sort contacts by name                uniqueContacts.sortedBy { it.name.lowercase() }                val database = getDatabase(context)                val contactDao = database.contactDao()                // ✅ Fetch existing contacts from database                val existingContacts = contactDao.getAllContacts().first()                // ✅ Create a HashSet for fast lookup                val existingNumbers = existingContacts.map { it.number }.toHashSet()                val existingNames = existingContacts.map { it.name }.toHashSet()                // 1. Filter only new contacts                val filteredNewContacts = uniqueContacts.filter { contact ->                    !(existingNumbers.contains(contact.number) && existingNames.contains(contact.name))                }                // 2. Sort by name (case-insensitive)                val sortedNewContacts = filteredNewContacts.sortedBy { it.name.lowercase() }                // 3. Assign a random color to each contact                val newContacts = sortedNewContacts.map { contact ->                    contact.apply {                        backgroundColor = RandomColorGenerator.getRandomColor()                    }                }                // 4. Insert into DB and log                if (newContacts.isNotEmpty()) {                    DLog.i("New contact(s) found: ${newContacts.size}")                    newContacts.forEach {                        DLog.i("New Contact → Name: ${it.name}, Number: ${it.number}, Color: ${it.backgroundColor}")                    }                    contactDao.insertAll(newContacts)//                    DLog.i("Contacts inserted successfully.")                } else {                    DLog.i("No new contacts to insert.")                }                DLog.i("WE NEED TO CONFIRM THIS?? $updateToo")                if (updateToo) {                    sendAllContactUpdateReq()                }            }        }    }    fun showIncomingVoipCall(callerName: String, isVideoCall: Boolean, userId: String) {        val intent = Intent(context, CallActivity2::class.java).apply {            putExtra("userNumber", userId)            putExtra("video", isVideoCall)            putExtra("outgoing", false)            addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)            addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP)            addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP)            addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT)        }        DLog.i("Starting Call Activity")        context.startActivity(intent)    }    suspend fun waitUntilParmaanTrueOrEndCall() {        withContext(Dispatchers.IO) {            val success = withTimeoutOrNull(10_000.milliseconds) {                while (!isParmaan) {                    delay(200.milliseconds)                }                true            }        }    }    suspend fun showIncomingCallA(        callerName: String?,        isVideoCall: Boolean?,        userId: String?,        roomId: String?    ) {        if (roomId == null){            return        }        if (isCallAlreadyEnded(roomId)) {            return        }        SocketManager.setAppActive(true)        // Step 1: Always check POST_NOTIFICATIONS permission (Android 13+)        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {            if (ContextCompat.checkSelfPermission(                    context,                    Manifest.permission.POST_NOTIFICATIONS                ) != PackageManager.PERMISSION_GRANTED            ) {                Log.w("VOIP", "POST_NOTIFICATIONS not granted - cannot show call notification")                // Optional: Request permission if possible, or fallback to silent                return  // Or show toast/log, but don't proceed            }        }        val telecomManager = context.getSystemService(TELECOM_SERVICE) as? TelecomManager            ?: return        val phoneAccountHandle = PhoneAccountHandle(            ComponentName(context, ConnectionDootaws::class.java),            "DootawasVoIPAccount"        )        // Prepare extras for Telecom        val incomingExtras = Bundle().apply {            putString("CALLER_NAME", callerName ?: "Unknown")            putString("ROOM_ID", roomId)            putBoolean("IS_VIDEO_CALL", isVideoCall == true)            putString("USER_ID", userId ?: "")        }        val extras = Bundle().apply {            putParcelable(TelecomManager.EXTRA_INCOMING_CALL_EXTRAS, incomingExtras)        }        // Try Telecom first — it works reliably for both locked & unlocked        try {            // Check if permitted (optional but good practice)            if (!telecomManager.isIncomingCallPermitted(phoneAccountHandle)) {                Log.w(                    "VOIP",                    "Incoming call not permitted - check PhoneAccount registration knotx"                )//                return                // 7. Telecom / Manual Connection — THE SAFE WAY                ConnectionDootaws.currentConnection?.let { conn ->                    if (conn.state == Connection.STATE_RINGING) {                        conn.onReject()                    } else {                        conn.onDisconnect()                    }                }            }            telecomManager.addNewIncomingCall(phoneAccountHandle, extras)//            telecomManager.placeCall(uri,extras)            waitUntilParmaanTrueOrEndCall()            val json = JsonObject().apply {                addProperty(JsonKeys.DATA_TYPE, DataType.CALL_DATA.value)                addProperty(JsonKeys.CALL_DATA_TYPE, CallDataType.CALL_REACHED_SUCCESSFULLY.value)                addProperty(JsonKeys.RECEIVER, userId)                addProperty(JsonKeys.MESSAGE_ID, createMessageID())                addProperty(JsonKeys.PROFILE_ID, roomId)                addProperty(JsonKeys.SANDESH, "")            }//            writeJsonToSessionCall(json)            return  // Success! No need for custom service        } catch (e: Exception) {            Log.e("VOIP", "Telecom addNewIncomingCall failed - fallback to legacy", e)        }    }    suspend fun createCallSession(        receiver: String,        roomId: String,        callDataType: CallDataType,        outcome: CallResult = CallResult.NO_ANSWER    ) {        DLog.i("CREATING ROOM ID $roomId")        val session = CallSession(            sender = userNumberKhud.firstOrNull().toString(), // assuming this is non-null            receiver = receiver,            startTime = System.currentTimeMillis(), // ✅ UTC-safe            callDataType = callDataType,            outcome = outcome,            roomId = roomId,            duration = 0        )        callSessionDao.insertCall(session)    }    fun updateCallDuration(roomId: String, duration: Long) {        coroutineScope.launch {            DLog.i("Updating call time $roomId $duration")            callSessionDao.updateCallDuration(roomId, duration)        }    }    suspend fun updateCallOutcome(        roomId: String,        outcome: CallResult,        userNumber: String?,        isVideoCall: Boolean,        isOutGoing: Boolean,    ) {        try {            DLog.i(                "☎️ updateCallOutcome roomId=$roomId outcome=$outcome user=$userNumber video=$isVideoCall outgoing=$isOutGoing"            )            callSessionDao.updateCallOutcome(roomId, outcome)            if (outcome == CallResult.MISSED && userNumber != null) {                val data = JsonObject().apply {                    addProperty("roomId", roomId)                    addProperty("outcome", outcome.value)                    addProperty("isVideoCall", isVideoCall)                    addProperty("isOutgoing", isOutGoing)                }                insertUniversalMessage(                    type = "call",                    data = data,                    userNumber = userNumber                )                if (!isOutGoing) {                    notifier.showMissedCallNotification(                        userId = userNumber,                        userName = userNumber,                        isVideoCall = isVideoCall                    )                }            }            DLog.i("✅ Call outcome updated to: $outcome for room: $roomId")        } catch (e: Exception) {            DLog.i("❌ Failed to update call outcome: ${e.message}")        }    }    private val userUpdateStatus: MutableMap<String, Boolean> = HashMap()    private val updateMutex = Mutex()    private var updateJob: Job? = null    // Queue contact updates and process them in batches    fun addItemToUpdate(userId: String) {        coroutineScope.launch {            updateMutex.withLock {                // Ignore users already queued or processed                if (userUpdateStatus.containsKey(userId)) {                    return@withLock                }                userUpdateStatus[userId] = false                // Start only one processing job                if (updateJob?.isActive != true) {                    updateJob = coroutineScope.launch {                        while (true) {                            // Collect contacts for 3 seconds                            delay(3000.milliseconds)                            val pendingUsers = updateMutex.withLock {                                val pending = userUpdateStatus                                    .filterValues { !it }                                    .keys                                    .toList()                                if (pending.isEmpty()) {                                    updateJob = null                                    return@withLock null                                }                                // Mark as processed before sending                                pending.forEach {                                    userUpdateStatus[it] = true                                }                                pending                            }                            // No more pending users                            if (pendingUsers == null) {                                break                            }                            val request = JsonObject().apply {                                addProperty(                                    JsonKeys.DATA_TYPE,                                    DataType.CONTACT_PROFILE_STATUS.value                                )                                add(                                    JsonKeys.LIST,                                    JsonArray().apply {                                        pendingUsers.forEach { number ->                                            add(                                                JsonObject().apply {                                                    addProperty(                                                        JsonKeys.RECEIVER,                                                        number                                                    )                                                }                                            )                                        }                                    }                                )                                addProperty(                                    JsonKeys.SAMABHASH_TOKEN,                                    sessionToken                                )                            }                            DLog.i("CONTACT UPDATE REQUEST: $request")                            SocketManager.send(request.toString())                        }                    }                }            }        }    }    fun updateWallPaper(        uri: Uri?,        userNumberOrGroupId: String,        groupPassed: Boolean    ) {        coroutineScope.launch(Dispatchers.IO) {            if (groupPassed) {                groupDao.updateWallpaper(                    groupId = userNumberOrGroupId,                    wallpaperImage = uri?.toString()                )            } else {                upbhogtaDao.updateWallpaper(                    userNumber = userNumberOrGroupId,                    wallpaperImage = uri?.toString()                )            }        }    }    fun setupMediaDirectories() {        val baseDir = File(            Environment.getExternalStorageDirectory(),            "Android/media/${context.packageName}/Knotx/Media"        )        val folders = listOf(            "Images",            "Videos",            "Audio",            "Documents",            "Location",            "Cropped"        )        folders.forEach { folder ->            try {                val dir = File(baseDir, folder)                if (!dir.exists()) {                    dir.mkdirs()                }                val noMedia = File(dir, ".nomedia")                if (!noMedia.exists()) {                    noMedia.createNewFile()                }            } catch (e: Exception) {                Log.e("MediaSetup", "Failed for $folder", e)            }        }    }//    fun updateCallSessionOutcomeAndDuration(//        callSessionId: Long,//        newOutcome: Int,//        newDuration: Long//    ) {//        coroutineScope.launch(Dispatchers.IO) {//            val callSessionDao = dootawasDatabase.callSessionDao()//            val callSession = callSessionDao.getCallById(callSessionId)////            callSession?.let {//                it.outcome = CallOutcome.fromValue(newO