 drawableId: Int,        storageType: MediaCategory = MediaCategory.PROFILE    ): SavedMedia? = withContext(Dispatchers.IO) {        try {            // 1. Extract drawable as a Bitmap            val drawable = ContextCompat.getDrawable(context, drawableId) ?: return@withContext null            val bitmap = drawable.toBitmap(width = 512, height = 512, config = Bitmap.Config.ARGB_8888)            // 2. Write to a temporary file in cache            val tempFile = File(context.cacheDir, "temp_drawable_${System.currentTimeMillis()}.jpg")            tempFile.outputStream().use { out ->                bitmap.compress(Bitmap.CompressFormat.JPEG, 90, out)            }            // 3. Get Uri from temporary file            val sourceUri = Uri.fromFile(tempFile)            // 4. Pass through your custom storage function            val savedMedia = saveMediaToAppStorageNext(                context = context,                sourceUri = sourceUri,                storageType = storageType,                visibility = MediaVisibility.PRIVATE            )            // 5. Clean up temporary cache file            if (tempFile.exists()) {                tempFile.delete()            }            savedMedia        } catch (e: Exception) {            e.printStackTrace()            null        }    }    fun createAndAddQuickTipsContact() {        CoroutineScope(Dispatchers.IO).launch {            val existing = upbhogtaDao.getUserByNumber(QUICK_TIPS_NUMBER)            if (existing != null) return@launch            // Store the drawable using your storage infrastructure            val savedMedia = saveDrawableAsMedia(                context = context,                drawableId = R.drawable.ic_quick_tips2,                storageType = MediaCategory.PROFILE            )            val upbhogta = Upbhogta(                contactName = QUICK_TIPS_NAME,                userNumber = QUICK_TIPS_NUMBER,                photoUrl = savedMedia?.local