al ivSpec = IvParameterSpec(ivBytes)        // Step 4️⃣ Encrypt group private key with AES        val cipherAES = Cipher.getInstance("AES/CBC/PKCS5Padding")        cipherAES.init(Cipher.ENCRYPT_MODE, aesKey, ivSpec)        val encryptedGroupPrivateKeyBytes = cipherAES.doFinal(groupPrivateKeyBytes)        // Step 5️⃣ Encrypt AES key with RSA public key        val cipherRSA = Cipher.getInstance("RSA/ECB/PKCS1Padding")        cipherRSA.init(Cipher.ENCRYPT_MODE, personalPublicKey)        val encryptedAesKeyBytes = cipherRSA.doFinal(aesKeyBytes)        // Step 6️⃣ Encode to Base64        val encryptedGroupPrivateKeyBase64 =            Base64.encodeToString(encryptedGroupPrivateKeyBytes, Base64.NO_WRAP)        val ivBase64 = Base64.encodeToString(ivBytes, Base64.NO_WRAP)        val encryptedAesKeyBase64 = Base64.encodeToString(encryptedAesKeyBytes, Base64.NO_WRAP)        DLog.i("✅ Group private key encrypted with hybrid approach")        return Triple(encryptedGroupPrivateKeyBase64, ivBase64, encryptedAesKeyBase64)    }    fun decryptGroupPrivateKeyHybrid(        encryptedAesKey: ByteArray,        iv: ByteArray,        encryptedHybridKey: ByteArray,        personalPrivateKeyAlias: String    ): ByteArray? {        return try {            // 1️⃣ Load private key from Keystore            val keyStore = KeyStore.getInstance("AndroidKeyStore")            keyStore.load(null)            val privateKey = keyStore.getKey(personalPrivateKeyAlias, null) as? PrivateKey                ?: return null            // 2️⃣ Decrypt AES "session" key using RSA private key            val rsaCipher = Cipher.getInstance("RSA/ECB/PKCS1Padding")            rsaCipher.init(Cipher.DECRYPT_MODE, privateKey)            val sessionKeyBytes = rsaCipher.doFinal(encryptedHybridKey)            // 3️⃣ Use decrypted session key to decrypt the actual AES key            val secretKeySpec = SecretKeySpec(sessionKeyBytes, "AES")            val aesCipher = Cipher.getInstance("AES/CBC/PKCS5Padding")            aesCipher.init(Cipher.DECRYPT_MODE, secretKeySpec, IvParameterSpec(iv))            aesCipher.doFinal(encryptedAesKey)        } catch (e: Exception) {            DLog.i("❌ decryptGroupPrivateKeyHybrid error: ${e.message}")            null        }    }    /**     * Decrypts AES group key from stored JSON.     *     * @param combinedEncryptedJson The JSON string stored in DB (GroupEntity.encryptedAesKey).     * @param personalPrivateKeyAlias The Keystore alias you used (e.g., "senghol_user_key").     * @return AES SecretKey if success, null if failed.     */    fun getGroupAesKeyFromCombinedJson(        combinedEncryptedJson: String?,        personalPrivateKeyAlias: String = "senghol_user_key"    ): SecretKey? {        try {            if (combinedEncryptedJson.isNullOrEmpty()) {                DLog.i("❌ JSON is null or empty.")                return null            }            // Parse JSON            val json = JsonParser.parseString(combinedEncryptedJson).asJsonObject            val encryptedAesKeyBase64 = json.get("encryptedAesKey")?.asString ?: return null            val ivBase64 = json.get("iv")?.asString ?: return null            val encryptedHybridKeyBase64 = json.get("encryptedHybridKey")?.asString ?: return null            // Convert base64 fields to bytes            val encryptedAesKeyBytes = Base64.decode(encryptedAesKeyBase64, Base64.DEFAULT)            val ivBytes = Base64.decode(ivBase64, Base64.DEFAULT)            val encryptedHybridKeyBytes = Base64.decode(encryptedHybridKeyBase64, Base64.DEFAULT)            // Decrypt using your hybrid helper            val aesKeyBytes = decryptGroupPrivateKeyHybrid(                encryptedAesKeyBytes,                ivBytes,                encryptedHybridKeyBytes,                personalPrivateKeyAlias            )            if (aesKeyBytes == null) {                DLog.i("❌ Failed to decrypt AES key bytes.")                return null            }            // Convert to SecretKey            return SecretKeySpec(aesKeyBytes, 0, aesKeyBytes.size, "AES")        } catch (e: Exception) {            DLog.i("❌ Exception while decrypting AES key: ${e.message}")            return null        }    }    fun generateUserColors(): UserColors {        val hue = Random.nextFloat() * 360f        // Dark-background variant: high saturation, high value = vivid & bright        val darkModeColor = Color.HSVToColor(floatArrayOf(hue, 0.25f, 0.95f))        // Light-background variant: same hue, high saturation, lower value = solid & readable, not washed out        val lightModeColor = Color.HSVToColor(floatArrayOf(hue, 0.95f, 0.45f))        return UserColors(            darkModeColor = darkModeColor,            lightModeColor = lightModeColor        )    }    fun createGroup(        groupName: String,        groupDescription: String,        revealNumber: Boolean    ) {        CoroutineScope(Dispatchers.IO).launch {            try {                val groupId = createMessageID()                val myNumber = userNumberKhud.firstOrNull()                    ?: throw IllegalStateException("Local user number not available")                val myUserNameId = userNameIdKhud.firstOrNull()                    ?: throw IllegalStateException("Local user ID not available")                val myMemberInstanceId = if (revealNumber) {                    myUserNameId                } else {                    myNumber                }                val createdAt = getCurrentTimeMillis()                // =========================================================================                // 1. CREATE GROUP                // =========================================================================                val groupEntity = GroupEntity(                    groupId = groupId,                    groupName = groupName,                    groupDescription = groupDescription,                    groupImageUrl = "",                    createdBy = myMemberInstanceId,                    createdAt = createdAt,                    isMuted = false,                    lastMessageId = "",                    sandeshStithi = SandeshStithi.LIKHIT,                    backgroundColor = RandomColorGenerator.getRandomColor(),                    // ===== GROUP E2EE STATE =====                    currentEpoch = 0L,                    currentCommitHash = null,                    rosterVersion = 0L,                    groupCryptoProtocolVersion = 1                )                groupDao.insertGroupEntity(groupEntity)                DLog.i("Group entity created: $groupId")                // =========================================================================                // 2. ADD CREATOR AS FIRST MEMBER                // =========================================================================                val colors = generateUserColors()                val selfMemberEntity = GroupMemberEntity(                    groupId = groupId,                    userNumber = myMemberInstanceId,                    contactName = getNameByNumberFromContactOnly(myNumber),                    userDarkColor = colors.darkModeColor,                    userLightColor = colors.lightModeColor,                    joinedAt = createdAt,                    canMessage = true,                    canUpdateProfile = true,                    canModifyMembers = true,                    canStartCall = true,                    isSwami = true,                    profileUrl = "",                    publicKey = "",                    // ===== GROUP E2EE IDENTITY =====                    memberInstanceId = myMemberInstanceId,                    deviceId = "1",                    leafIndex = 0,                    keyGeneration = 1L,                    x25519PublicKey = ByteArray(0),                    mlKemPublicKey = ByteArray(0),                    ed25519PublicKey = ByteArray(0),                    isCryptoActive = true                )                groupDao.insertMember(selfMemberEntity)                DLog.i(                    "Added creator as group member: " +                            "number=$myNumber memberInstanceId=$myMemberInstanceId"                )                // =========================================================================                // 3. CREATE INITIAL GROUP EPOCH                // =========================================================================                groupCryptoManager.createInitialEpoch(groupId)                DLog.i("Initial group epoch created: groupId=$groupId")                // =========================================================================                // 4. CREATE GROUP CREATION MESSAGE                // =========================================================================                val jsonObject = JsonObject().apply {                    addProperty(JsonKeys.GROUP_ID, groupEntity.groupId)                    addProperty(JsonKeys.GROUP_NAME, groupEntity.groupName)                    addProperty(JsonKeys.GROUP_DEC, groupEntity.groupDescription)                    addProperty(DootawasMessage.SANDESH_TYPE, GroupSandeshType.ACTION_CREATE_GROUP.value)                }                val unsentSandesh = UnsentSandesh(                    messId = createMessageID(),                    receiver = "createGroup",                    message = jsonObject.toString(),                    dataType = DataType.GROUP_ACTION                )                insertUnsentData(unsentSandesh)                DLog.i(                    "Group creation queued: " +                            "groupId=$groupId messageId=${unsentSandesh.messId}"                )                // =========================================================================                // 5. SEND CREATION REQUEST                // =========================================================================                sendUnsentMessages(false)            } catch (e: Exception) {                DLog.e("Failed to create group", e)            }        }    }    fun submitOtp(otpSubmitJson: JsonObject) {        CoroutineScope(Dispatchers.IO).launch {            try {                // 1️⃣ Extract phone number from JSON                val phoneNumber = otpSubmitJson.get(JsonKeys.USER_NUMBER)?.asString                    ?: throw IllegalArgumentException("Missing user_number in JSON")                // 2️⃣ Generate the user’s key bundle using KeyRegistrationManager                val publicJson = roomSignalStore.generateInitialBundle(phoneNumber)                // 3️⃣ Combine OTP + encrypted data + Signal keys into one JSON                val gson = Gson()                val signalBundle = gson.fromJson(publicJson, JsonObject::class.java)                val finalJson = JsonObject().apply {                    add(JsonKeys.DATA, otpSubmitJson)                    add(JsonKeys.SIGNAL_DATA, signalBundle)                    addProperty(JsonKeys.DATA_TYPE, DataType.SUBMIT_OTP.value)                }                // 4️⃣ Convert to string and print/log the size                val jsonString = gson.toJson(finalJson)                val byteSize = jsonString.toByteArray(StandardCharsets.UTF_8).size                // 5️⃣ Optionally, persist session or write JSON to local file                writeJsonToSessionNoLogin(finalJson)            } catch (e: Exception) {                Log.e("E2EE", "Error in submitOtp: ${e.message}", e)            }        }    }    fun updateContactState(number: String, isAdded: Boolean) {        CoroutineScope(Dispatchers.IO).launch {            val state = if (isAdded) ContactButtonState.ADDED else ContactButtonState.ADD            contactDao.updateContactStateByNumber(number, state)        }    }    fun clearChatOfUser(userNumber: String) {        CoroutineScope(Dispatchers.IO).launch {            sandeshDao.clearChatByNumber(userNumber)            upbhogtaDao.updateLastMessageAndId(                userNumber,                "",                0,                "",                SandeshStithi.LIKHIT            )        }    }    //endregion    //region Settings    suspend fun shouldVibrateOnMessage(): Boolean {        val audioManager = context.getSystemService(AUDIO_SERVICE) as AudioManager        val isVibrateMode = audioManager.ringerMode == AudioManager.RINGER_MODE_VIBRATE        if (isVibrateMode) {            return true        }        if (audioManager.ringerMode == AudioManager.RINGER_MODE_NORMAL) {            val prefs = settingStore.data                .catch { if (it is IOException) emit(emptyPreferences()) }                .first()            val appVibrationEnabled = prefs[SettingPrefKeys.MESSAGE_VIBRATION] == true            return appVibrationEnabled        }        return false    }    suspend fun shouldPlayMessageSound(        userNumber: String,        isGroup: Boolean    ): Boolean {        var result = false        val timeTaken = measureTimeMillis {            // 1. Check if user is muted            val isMuted =                if (isGroup) groupDao.isGroupMuted(userNumber) == true                else upbhogtaDao.isMuted(userNumber) == true            if (isMuted) {                result = false                return@measureTimeMillis // skip rest            }            // 2. Check internal and external notification settings            val internalOk = canPlaySoundAppLevel()            result = internalOk        }        return result    }    fun canPlaySoundSystemLevel(): Boolean {        val audioManager = context.getSystemService(AUDIO_SERVICE) as AudioManager        val isRingerNormal = audioManager.ringerMode == AudioManager.RINGER_MODE_NORMAL        val isVolumeAudible = audioManager.getStreamVolume(AudioManager.STREAM_NOTIFICATION) > 0        return isRingerNormal && isVolumeAudible    }    suspend fun canPlaySoundAppLevel(): Boolean {        val prefs = settingStore.data            .catch { if (it is IOException) emit(emptyPreferences()) }            .first()        val notificationsEnabled = prefs[SettingPrefKeys.NOTIFICATION_ENABLE_ALL] != false        val messagesEnabled = prefs[SettingPrefKeys.NOTIFICATION_NEW_MESSAGES] != false        val dndEnabled = prefs[SettingPrefKeys.NOTIFICATION_DND_ENABLE] == true        // Optional: parse custom DND hours string if needed        val isInDndHours =            false // TODO: Handle parsing of NOTIFICATION_DND_CUSTOM_HOURS if required        return notificationsEnabled &&                messagesEnabled &&                !(dndEnabled && isInDndHours)    }    //endregion    //region SandeshScreen    fun sendMessage(unsentSandesh: UnsentSandesh) {        coroutineScope.launch {            writeMessageMutex.withLock {                DLog.i("Sending message: $unsentSandesh") // Placeholder action                insertUnsentData(unsentSandesh, false)                DLog.i(" HELP ME 6")                sendUnsentMessages(false)            }        }    }    fun sendLocation(unsentData: UnsentFiles) {        coroutineScope.launch(Dispatchers.IO) {            insertSendData(unsentData)            if (!sendingFileInProgress) {                sendUnsentFiles()            }        }    }    fun sendImage(unsentData: UnsentFiles) {        coroutineScope.launch(Dispatchers.IO) {            try {                // ✅ No JSON mutation needed anymore                insertSendData(unsentData)                if (!sendingFileInProgress) {                    sendUnsentFiles()                }            } catch (e: Exception) {                DLog.i("Error in sendImage: ${e.message}")            }        }    }//    fun sendImage(unsentData: 