   }    }    fun calculateBitrate(meta: VideoMeta, targetMB: Int): Int {        val durationSec = meta.durationMs / 1000.0        val targetBytes = targetMB * 1024 * 1024        val bitrate = (targetBytes * 8 / durationSec).toInt()        return bitrate.coerceIn(            800_000,   // minimum            8_000_000  // maximum        )    }    fun getFileSizeMB(        context: Context,        pathOrUri: String    ): Long {        return try {            val size = if (pathOrUri.startsWith("/")) {                File(pathOrUri).length()            } else {                val fd = context.contentResolver                    .openFileDescriptor(                        pathOrUri.toUri(),                        "r"                    )                val uriSize = fd?.statSize ?: 0                fd?.close()                uriSize            }            size / (1024 * 1024)        } catch (e: Exception) {            e.printStackTrace()            0L        }    }    fun uriToFile(context: Context, uri: Uri): File {        if (uri.scheme == "file") {            return File(uri.path!!)        }        val file = File(context.cacheDir, "video_${System.currentTimeMillis()}.mp4")        context.contentResolver.openInputStream(uri)?.use { input ->            file.outputStream().use { output ->                input.copyTo(output)            }        }        return file    }    fun pathOrUriToPlayableUri(        context: Context,        pathOrUri: String    ): Uri {        return if (pathOrUri.startsWith("/")) {            FileProvider.getUriForFile(                context,                "${context.packageName}.provider",                File(pathOrUri)            )        } else {            pathOrUri.toUri()        }    }    private val compressGate = kotlinx.coroutines.sync.Semaphore(1)    suspend fun resetCompressionProgress(isGroup: Boolean, messageId: String, receiver: String) {        val mutex = SamagriUpdateLock.getMutexForId(messageId)        mutex.withLock {            if (isGroup) {                val s = groupDao.getGroupSandeshByIdAndGroupId(messageId, receiver) ?: return                val json = JsonParser.parseString(s.samagri).asJsonObject                run {                    json.addProperty(DootawasMessage.DOWNLOAD_PERCENT, -1)                    groupDao.updateSamagri(messageId, json.toString(), receiver)                }            } else {                val s = sandeshDao.getSandeshByIdAndUser(messageId, receiver) ?: return                val json = JsonParser.parseString(s.samagri).asJsonObject                run {                    json.addProperty(DootawasMessage.DOWNLOAD_PERCENT, -1)                    sandeshDao.updateSamagri(messageId, json.toString())                }            }        }    }    @OptIn(UnstableApi::class)    suspend fun smartCompressVideo(        context: Context,        inputPathOrUri: String,        isGroup: Boolean,        messageId: String,        receiver: String,        targetSizeMB: Int = 18,        index: Int = 0,        count: Int = 1    ): String = compressGate.withPermit {        val sizeMB = withContext(Dispatchers.IO) { getFileSizeMB(context, inputPathOrUri) }        if (sizeMB <= targetSizeMB) return@withPermit inputPathOrUri        val meta = withContext(Dispatchers.IO) { getVideoMeta(context, inputPathOrUri) }        val targetHeight = chooseTargetHeight(meta)        val bitrate = calculateBitrate(meta, targetSizeMB)        val out = withContext(Dispatchers.IO) { newPrivateMediaFile(context, MediaCategory.VIDEO) }        var ok = false        try {            coroutineScope {                // one serial writer, so progress writes can't reorder                val ch = Channel<Int>(Channel.CONFLATED)                val writer = launch(Dispatchers.IO) {                    for (p in ch) updateCompressionProgress(isGroup, messageId, receiver, p)                }                try {                    var lastSent = 0                    runTransformer(context, inputPathOrUri, out, targetHeight, bitrate) { p ->                        if (p - lastSent >= 5 || p == 100) {                            lastSent = p                            ch.trySend((index * 100 + p) / count)                        }                    }                    ch.trySend(((index + 1) * 100) / count)                } finally {                    ch.close()                }                writer.join()            }            ok = true            out.absolutePath        } finally {            if (!ok) out.delete()   // failed or cancelled: remove the partial file        }    }    @OptIn(UnstableApi::class)    private suspend fun runTransformer(        context: Context,        input: String,        output: File,        targetHeight: Int,        bitrate: Int,        onProgress: (Int) -> Unit    ) = withContext(Dispatchers.Main) {        suspendCancellableCoroutine<Unit> { cont ->            val handler = Handler(Looper.getMainLooper())            val composition = Composition.Builder(                listOf(EditedMediaItemSequence.Builder(EditedMediaItem.Builder(MediaItem.fromUri(input)).build()).build())            )                .setEffects(Effects(emptyList(), listOf(Presentation.createForHeight(targetHeight))))                .setHdrMode(Composition.HDR_MODE_TONE_MAP_HDR_TO_SDR_USING_MEDIACODEC)                .build()            val transformer = Transformer.Builder(context)                .setEncoderFactory(                    DefaultEncoderFactory.Builder(context)                        .setEnableFallback(true)                        .setRequestedVideoEncoderSettings(VideoEncoderSettings.Builder().setBitrate(bitrate).build())                        .build()                )                .build()            val holder = ProgressHolder()            val poll = object : Runnable {                override fun run() {                    if (transformer.getProgress(holder) == Transformer.PROGRESS_STATE_AVAILABLE) onProgress(holder.progress)                    handler.postDelayed(this, 500)                }            }            transformer.addListener(object : Transformer.Listener {                override fun onCompleted(composition: Composition, result: ExportResult) {                    handler.removeCallbacks(poll)                    if (cont.isActive) cont.resume(Unit)                }                override fun onError(composition: Composition, result: ExportResult, e: ExportException) {                    handler.removeCallbacks(poll)                    if (cont.isActive) cont.resumeWithException(e)                }            })            cont.invokeOnCancellation {                handler.post { handler.removeCallbacks(poll); transformer.cancel() }            }            if (cont.isActive) {                transformer.start(composition, output.absolutePath)                handler.post(poll)            }        }    }    /** Creates an empty, uniquely named file in the private media folder (never visible to gallery or other apps). */    fun newPrivateMediaFile(        context: Context,        category: MediaCategory,        extension: String = category.defaultExtension    ): File {        val dir = File(context.filesDir, category.folder).apply { mkdirs() }        File(dir, ".nomedia").let { if (!it.exists()) it.createNewFile() }        return File.createTempFile("${category.prefix}_", ".$extension", dir)    }    suspend fun updateCompressionProgress(        isGroup: Boolean,        messageId: String,        receiver: String,        progress: Int,    ) {        val tag = "CompressProgress"        val mutex = SamagriUpdateLock.getMutexForId(messageId)        mutex.withLock {            val newProgress = -progress            DLog.i("$tag [$messageId] incoming=$progress -> stored value would be $newProgress (group=$isGroup)")            try {                if (isGroup) {                    val sandesh = groupDao.getGroupSandeshByIdAndGroupId(messageId, receiver)                    if (sandesh == null) {                        DLog.e("$tag [$messageId] group row NOT FOUND (receiver=$receiver), update skipped")                        return                    }                    val json = JsonParser.parseString(sandesh.samagri).asJsonObject                    val hadKey = json.has(DootawasMessage.DOWNLOAD_PERCENT)                    val current = json.get(DootawasMessage.DOWNLOAD_PERCENT)?.asInt ?: 0                    if (newProgress < current) {                        json.addProperty(DootawasMessage.DOWNLOAD_PERCENT, newProgress)                        groupDao.updateSamagri(messageId, json.toString(), receiver)                        DLog.i("$tag [$messageId] WRITTEN group: $current -> $newProgress (keyExisted=$hadKey)")                    } else {                        DLog.i("$tag [$messageId] REJECTED group: new=$newProgress is not below current=$current (keyExisted=$hadKey)")                    }                } else {                    val sandesh = sandeshDao.getSandeshByIdAndUser(messageId, receiver)                    if (sandesh == null) {                        DLog.e("$tag [$messageId] row NOT FOUND (receiver=$receiver), update skipped")                        return                    }                    val json = JsonParser.parseString(sandesh.samagri).asJsonObject                    val hadKey = json.has(DootawasMessage.DOWNLOAD_PERCENT)                    val current = json.get(DootawasMessage.DOWNLOAD_PERCENT)?.asInt ?: 0                    if (newProgress < current) {                        json.addProperty(DootawasMessage.DOWNLOAD_PERCENT, newProgress)                        sandeshDao.updateSamagri(messageId, json.toString())                        DLog.i("$tag [$messageId] WRITTEN: $current -> $newProgress (keyExisted=$hadKey)")                    } else {                        DLog.i("$tag [$messageId] REJECTED: new=$newProgress is not below current=$current (keyExisted=$hadKey)")                    }                }            } catch (e: kotlinx.coroutines.CancellationException) {                throw e            } catch (e: Exception) {                DLog.e("$tag [$messageId] update FAILED: ${e.message}")            }        }    }    @OptIn(UnstableApi::class)    suspend fun transformVideoInBackground(        context: Context,        inputUri: Uri,        targetHeight: Int = 720 // default medium    ): File = suspendCancellableCoroutine { cont ->        val fileName = "transformed_${System.currentTimeMillis()}.mp4"        val outputFile = File(context.filesDir, fileName)        val mediaItem = MediaItem.fromUri(inputUri)        val editedMediaItem = EditedMediaItem.Builder(mediaItem)            .setFlattenForSlowMotion(true)            .build()        val sequence = EditedMediaItemSequence.Builder(editedMediaItem)            .setIsLooping(false)            .build()        val effects = Effects(            emptyList(),            listOf(Presentation.createForHeight(targetHeight))        )        val composition = Composition.Builder(listOf(sequence))            .setEffects(effects)            .setHdrMode(Composition.HDR_MODE_KEEP_HDR)            .build()        val transformer = Transformer.Builder(context)            .addListener(object : Transformer.Listener {                override fun onCompleted(composition: Composition, result: ExportResult) {                    val sizeInMB = outputFile.length() / (1024 * 1024)                    DLog.i("✅ Transcode complete: ${outputFile.absolutePath}")                    DLog.i("📦 Size: $sizeInMB MB")                    cont.resume(outputFile) { cause, _, _ -> }                }                override fun onError(                    composition: Composition,                    result: ExportResult,                    exception: ExportException                ) {                    DLog.i("❌ Transcode failed: ${exception.message}")                    cont.resumeWithException(exception)                }            })            .build()        Handler(Looper.getMainLooper()).post {            transformer.start(composition, outputFile.absolutePath)        }    }    fun sendVideo(unsentData: UnsentFiles) {        coroutineScope.launch(Dispatchers.IO) {            insertSendData(unsentData)            if (!sendingFileInProgress) {                sendUnsentFiles()            }        }    }    fun sendStory(unsentData: UnsentFiles) {        coroutineScope.launch(Dispatchers.IO) {            insertSendData(unsentData)            if (!sendingFileInProgress) {                sendUnsentFiles()            }        }    }    fun sendAudio(unsentFile: UnsentFiles) {        coroutineScope.launch {            writeMessageMutex.withLock {                DLog.i("SENDING AUDIO $unsentFile")                insertSendData(unsentFile)                if (!sendingFileInProgress) {                    sendUnsentFiles()                }            }        }    }    fun ensureNoMediaDocuments(context: Context) {        val dir = File(            Environment.getExternalStorageDirectory(),            "Android/media/${context.packageName}/Knotx/Media/Documents"        )        if (!dir.exists()) dir.mkdirs()        val noMedia = File(dir, ".nomedia")        if (!noMedia.exists()) {            noMedia.createNewFile()        }    }    fun saveDocumentToAppMedia(        context: Context,        sourceUri: Uri,        fileName: String? = null    ): Uri? {        ensureNoMediaDocuments(context)        val resolver = context.contentResolver        val name = fileName ?: "DOC_${System.currentTimeMillis()}"        val mimeType = resolver.getType(sourceUri) ?: "application/octet-stream"        val contentValues = ContentValues().apply {            put(MediaStore.Files.FileColumns.DISPLAY_NAME, name)            put(MediaStore.Files.FileColumns.MIME_TYPE, mimeType)            put(                MediaStore.Files.FileColumns.RELATIVE_PATH,                "Android/media/${context.packageName}/Knotx/Media/Documents"            )            put(MediaStore.Files.FileColumns.IS_PENDING, 1)        }        val collection =            MediaStore.Files.getContentUri(MediaStore.VOLUME_EXTERNAL_PRIMARY)        val newUri = resolver.insert(collection, contentValues) ?: return null        return try {            val inputStream = when (sourceUri.scheme) {                "content" -> resolver.openInputStream(sourceUri)                "file", null -> sourceUri.path?.let { File(it).inputStream() }                else -> resolver.openInputStream(sourceUri)            } ?: throw Exception("Unable to open input stream")            resolver.openOutputStream(newUri)?.use { output ->                inputStream.use { input ->                    input.copyTo(output)                }            }            // ✅ Mark complete            contentValues.clear()            contentValues.put(MediaStore.Files.FileColumns.IS_PENDING, 0)            resolver.update(newUri, contentValues, null, null)            newUri        } catch (e: Exception) {            resolver.delete(newUri, null, null)            e.printStackTrace()            null        }    }    fun sendDocument(unsentFile: UnsentFiles) {        coroutineScope.launch {            writeMessageMutex.withLock {                insertSendData(unsentFile)                if (!sendingFileInProgress) {                    sendUnsentFiles()                }            }        }    }    fun sendDelete(unsentSandesh: UnsentSandesh) {        coroutineScope.launch {            writeMessageMutex.withLock {                DLog.i("Sending message: $unsentSandesh") // Placeholder action                insertUnsentData(unsentSandesh, false)                DLog.i(" HELP ME 6")                sendUnsentMessages(false)                // Wait 50ms before allowing the next execution                delay(50.milliseconds)            }        }    }    fun deleteUserListMessage(        deleteSandeshList: List<String>,        receiverId: String,        skipSelfCheck: Boolean = false    ) {        coroutineScope.launch(Dispatchers.IO) {            sandeshDeleter.deleteMessages(                sandeshIds = deleteSandeshList,                userNumber = receiverId,                skipSelfCheck = skipSelfCheck            )            unsentFilesDao.deleteUserListMessage(deleteSandeshList, receiverId)            unsentSandeshDao.deleteUserListMessage(deleteSandeshList, receiverId)            deleteSandeshList.forEach { messageId ->                upbhogtaDao.resetLastMessageByMessageId(                    messageId = messageId,                    number = receiverId,                    deletedText = "Message Deleted"                )            }        }    }    fun deleteGroupListMessage(        deleteSandeshList: List<String>,        groupId: String,        ownerNumber: String,        skipOwnerCheck: Boolean = false    ) {        coroutineScope.launch(Dispatchers.IO) {            unsentFilesDao.deleteUserListMessage(deleteSandeshList, groupId)            unsentSandeshDao.deleteUserListMessage(deleteSandeshList, groupId)            groupDao.deleteMessages(                messageIds = deleteSandeshList,                groupId = groupId,                ownerNumber = ownerNumber,                skipOwnerCheck = skipOwnerCheck            )            deleteSandeshList.forEach { messageId ->                groupDao.resetLastMessageByMessageId(                    messageId = messageId,                    group = groupId                )            }        }    }    fun showToastForHttpCode(context: Context, code: Int) {        val message = when (code) {            200 -> "✅ File retrieved successfully."            201 -> "✅ File uploaded successfully."            202 -> "⏳ Upload accepted. Processing..."            204 -> "✅ Action completed. No content returned."            400 -> "❌ Bad request. Please try again."            401 -> "🔒 Unauthorized. Login required."            403 -> "🚫 Forbidden. Access denied."            404 -> "❌ File not found. It may have been deleted or moved."            405 -> "⚠️ Method not allowed."            409 -> "⚠️ Conflict: File may already exist."            413 -> "🚫 File too large to upload."            415 -> "⚠️ Unsupported file type."            429 -> "⏱ Too many requests. Please slow down."            500 -> "💥 Internal server error. Contact support if this continues."            501 -> "❌ Not implemented."            502 -> "⚠️ Bad gateway."            503 -> "⚠️ Server busy. Try later."            504 -> "⏱ Server timeout. Try again."            else -> "❓ Unknown response: $code"        }        // Run toast on UI thread        Handler(Looper.getMainLooper()).post {            Toast.makeText(context, message, Toast.LENGTH_SHORT).show()        }    }    suspend fun generateAndSaveThumbnail(        message: JsonObject,        sandeshId: String    ): String? {        return withContext(Dispatchers.IO) {            try {                val originalUriString =                    message.get(DootawasMessage.ORIGINAL_URI)                        ?.asString                if (originalUriString.isNullOrBlank()) {                    DLog.i("❌ No ORIGINAL_URI found in message")                    return@withContext null                }                val videoUri =                    originalUriString.toUri()                // ------------------------------------------------                // Generate thumbnail                // ------------------------------------------------                val retriever =                    MediaMetadataRetriever()                retriever.setDataSource(                    context,                    videoUri                )                val bitmap =                    retriever.getFrameAtTime(                        1_000_000 // 1 second                    )                retriever.release()                if (bitmap == null) {                    DLog.i(                        "❌ Could not retrieve frame from video"                    )                    return@withContext null                }                // ------------------------------------------------                // Temporary cache file                // ------------------------------------------------                val tempPreviewFile =                    File.createTempFile(                        "video_preview_temp",                        ".webp",                        context.cacheDir                    )                val format =                    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {                        Bitmap.CompressFormat.WEBP_LOSSLESS                    } else {                        Bitmap.CompressFormat.WEBP                    }                FileOutputStream(tempPreviewFile).use { outputStream ->                    if (                        !bitmap.compress(                            format,                            100,                            outputStream                        )                    ) {                        DLog.i(                            "❌ Failed to save preview image"                        )                        bitmap.recycle()                        tempPreviewFile.delete()                        return@withContext null                    }                }                bitmap.recycle()                // ------------------------------------------------                // Save using unified storage system                // ------------------------------------------------                val savedMedia =                    saveMediaToAppStorageNext(                        context = context,                        sourceUri = tempPreviewFile.toUri(),                        storageType = MediaCategory.PREVIEW,                        visibility = MediaVisibility.PRIVATE,                        overrideMimeType = "image/webp"                    )                tempPreviewFile.delete()                if (savedMedia == null) {                    DLog.i("❌ Failed to save preview")                    return@withContext null                }                DLog.i(                    "✅ Preview saved at: ${savedMedia.localPath}"                )                return@withContext savedMedia.localPath            } catch (e: Exception) {                e.printStackTrace()                return@withContext null            }        }    }    suspend fun generateAndSaveThumbnailInternal(        message: JsonObject,        sandeshId: String,        userNumber: String    ) {        try {            val allData = message                .getAsJsonArray(DootawasMessage.ALL_DATA)            if (allData == null || allData.size() == 0) {                DLog.i("❌ No ALL_DATA found")                return            }            val previewUris = JsonArray()            val maxPreviewCount = minOf(4, allData.size())            for (i in 0 until maxPreviewCount) {                try {                    val mediaObject =                        allData[i].asJsonObject                    val originalPath =                        mediaObject.get(                            DootawasMessage.ORIGINAL_URI                        )?.asString                    if (originalPath.isNullOrBlank()) {                        continue                    }                    val retriever =                        MediaMetadataRetriever()                    retriever.setDataSource(originalPath)                    val bitmap =                        retriever.getFrameAtTime(                            -1,                            MediaMetadataRetriever.OPTION_CLOSEST_SYNC                        )                    retriever.release()                    if (bitmap == null) {                        DLog.i("❌ Could not generate thumbnail")                        continue                    }                    val tempPreviewFile =                        File.createTempFile(                            "preview_temp",                            ".jpg",                            context.cacheDir                        )                    FileOutputStream(tempPreviewFile).use {                        bitmap.compress(                            Bitmap.CompressFormat.JPEG,                            85,                            it                        )                    }                    bitmap.recycle()                    val savedMedia =                        saveMediaToAppStorageNext(                            context = context,                            sourceUri = tempPreviewFile.toUri(),                            storageType = MediaCategory.PREVIEW,                            visibility = MediaVisibility.PRIVATE,                            overrideMimeType = "image/jpeg"                        )                    tempPreviewFile.delete()                    if (savedMedia == null) {                        DLog.i("❌ Failed to save preview")                        continue                    }                    previewUris.add(savedMedia.localPath)                    DLog.i(                        "✅ Preview saved at: ${savedMedia.localPath}"                    )                } catch (e: Exception) {                    e.printStackTrace()                }            }                    val sandesh =                        sandeshDao.getSandeshByIdAndUser(                            sandeshId,                            userNumber                        )                    if (sandesh == null) {                        DLog.i(                            "❌ Sandesh not found in DB"                        )                        return                    }                    val samagriJson =                        runCatching {                            JsonParser.parseString(                                sandesh.samagri                            ).asJsonObject                        }.getOrNull()                            ?: JsonObject()                    samagriJson.add(                        DootawasMessage.IMAGE_PREVIEW,                        previewUris                    )                    sandeshDao.updateSamagri(                        sandeshId,                        samagriJson.toString()                    )                    DLog.i(                        "✅ Preview URIs updated in DB"                    )        } catch (e: Exception) {            e.printStackTrace()        }    }    suspend fun generateAndSaveThumbnailInternalGroup(        message: JsonObject,        sandeshId: String,        groupId: String    ) {        try {            val allData = message                .getAsJsonArray(DootawasMessage.ALL_DATA)            if (allData == null || allData.size() == 0) {                DLog.i("❌ No ALL_DATA found")                return            }            val previewUris = JsonArray()            val maxPreviewCount = minOf(4, allData.size())            for (i in 0 until maxPreviewCount) {                try {                    val mediaObject =                        allData[i].asJsonObject                    val originalPath =                        mediaObject.get(                            DootawasMessage.ORIGINAL_URI                        )?.asString                    if (originalPath.isNullOrBlank()) {                        continue                    }                    val retriever =                        MediaMetadataRetriever()                    retriever.setDataSource(originalPath)                    val bitmap =                        retriever.getFrameAtTime(                            -1,                            MediaMetadataRetriever.OPTION_CLOSEST_SYNC                        )                    retriever.release()                    if (bitmap == null) {                        DLog.i("❌ Could not generate thumbnail")                        continue                    }                    val tempPreviewFile =                        File.createTempFile(                            "preview_temp",                            ".jpg",                            context.cacheDir                        )                    FileOutputStream(tempPreviewFile).use {                        bitmap.compress(                            Bitmap.CompressFormat.JPEG,                            85,                            it                        )                    }                    bitmap.recycle()                    val savedMedia =                        saveMediaToAppStorageNext(                            context = context,                            sourceUri = tempPreviewFile.toUri(),                            storageType = MediaCategory.PREVIEW,                            visibility = MediaVisibility.PRIVATE,                            overrideMimeType = "image/jpeg"                        )                    tempPreviewFile.delete()                    if (savedMedia == null) {                        DLog.i("❌ Failed to save preview")                        continue                    }                    previewUris.add(savedMedia.localPath)                    DLog.i(                        "✅ Preview saved at: ${savedMedia.localPath}"                    )                } catch (e: Exception) {                    e.printStackTrace()                }            }            val mutex =                SamagriUpdateLock.getMutexForId(                    sandeshId                )                    val sandesh =                        groupDao.getGroupSandeshByIdAndGroupId(                            sandeshId,                            groupId                        )                    if (sandesh == null) {                        DLog.i(                            "❌ Sandesh not found in DB"                        )                        return                    }                    val samagriJson =                        runCatching {                            JsonParser.parseString(                                sandesh.samagri                            ).asJsonObject                        }.getOrNull()                            ?: JsonObject()                    samagriJson.add(                        DootawasMessage.IMAGE_PREVIEW,                        previewUris                    )                    groupDao.updateSamagri(                        sandeshId,                        samagriJson.toString(),                        groupId                    )                    DLog.i(                        "✅ Preview URIs updated in DB"                    )        } catch (e: Exception) {            e.printStackTrace()        }    }    fun downloadFileGroup(sandeshId: String, groupId: String) {        DLog.i("⬇️ DOWNLOADING FILE for Sandesh ID: $sandeshId $groupId")        coroutineScope.launch(Dispatchers.IO) {            try {                val sandesh = groupDao.getGroupSandeshByIdAndGroupId(sandeshId, groupId)                if (sandesh == null) {                    DLog.i("❌ Sandesh not found for ID: $sandeshId and GroupId: $groupId")                    return@launch                }                when (sandesh.sandeshType) {                    SandeshType.IMAGE.value,                    SandeshType.REPLY_IMAGE.value -> {                        downloadMultiMediaFilesGroup(sandesh, groupId, MediaCategory.IMAGE)                    }                    SandeshType.VIDEO.value,                    SandeshType.REPLY_VIDEO.value -> {                        downloadMultiMediaFilesGroup(sandesh, groupId, MediaCategory.VIDEO)                    }                    else -> {                        downloadSingleFileGroup(sandesh, groupId)                    }                }            } catch (e: Exception) {                Log.e("DownloadFileGroup", "💥 Error: ${e.message}")            }        }    }    fun downloadMultiMediaFilesGroup(        sandesh: GroupSandesh,        groupId: String,        mediaCategory: MediaCategory    ) {        DLog.i("⬇️ DOWNLOADING ${mediaCategory.name} FILES for Group Sandesh: $sandesh")        val isVideo = mediaCategory == MediaCategory.VIDEO        coroutineScope.launch(Dispatchers.IO) {            try {                val jsonObject = JsonParser.parseString(sandesh.samagri).asJsonObject                val password = jsonObject.get(DootawasMessage.FILE_PASS).asString                val uuid = jsonObject.get(DootawasMessage.FILE_ID).asString                val sender = sandesh.userNumber                val saveToGallery = settingFlow(                    SettingPrefKeys.CHAT_MEDIA_SAVE_TO_GALLERY,                    false                ).first() && sandesh.sandeshType !in setOf(                    SandeshType.LOCATION.value,                    SandeshType.REPLY_LOCATION.value                )                val apiLevel = Build.VERSION.SDK_INT                // -------------------------                // 📂 1️⃣ Prepare download folder                // -------------------------                val dirName = if (isVideo) "Videos" else "Images"                val galleryLegacyDir =                    if (isVideo) Environment.DIRECTORY_MOVIES else Environment.DIRECTORY_PICTURES                val downloadDir = when {                    saveToGallery && apiLevel >= Build.VERSION_CODES.Q ->                        File(context.getExternalFilesDir(null), "Gallery").apply { mkdirs() }                    saveToGallery ->                        File(                            Environment.getExternalStoragePublicDirectory(galleryLegacyDir),                            "Knotx"                        ).apply { mkdirs() }                    else -> File(context.getExternalFilesDir(null), dirName).apply { mkdirs() }                }                val currentDate =                    SimpleDateFormat("yyyyMMdd_HHmmss", Locale.getDefault()).format(Date())                val encryptedZipFile = File(downloadDir, "$currentDate.zip")                updateGroupDownloadPercent(groupId, 1, sandesh.sandeshId)                // -------------------------                // 🔗 2️⃣ Fetch Signed URL                // -------------------------                val downloadResponse = requestDownloadUrl(                    sender = sender,                    messageId = uuid                )                if (!downloadResponse.success) {                    DLog.i("❌ Failed to get download URL: ${downloadResponse.message}")                    updateGroupDownloadPercent(groupId, 0, sandesh.sandeshId)                    return@launch                }                val signedUrl = downloadResponse.downloadUrl                if (signedUrl.isNullOrBlank()) {                    DLog.i("❌ Download URL empty")                    updateGroupDownloadPercent(groupId, 0, sandesh.sandeshId)                    return@launch                }                // -------------------------                // ⬇️ 3️⃣ Download ZIP                // -------------------------                val request = Request.Builder().url(signedUrl).build()                val client = OkHttpClient()                val httpResponse = client.newCall(request).execute()                if (!httpResponse.isSuccessful) {                    DLog.i("❌ Failed to download zip")                    updateGroupDownloadPercent(groupId, 0, sandesh.sandeshId)                    return@launch                }                val body = httpResponse.body                val contentLength = body.contentLength()                body.byteStream().use { input ->                    encryptedZipFile.outputStream().use { output ->                        val buffer = ByteArray(DEFAULT_BUFFER_SIZE)                        var bytesRead: Int                        var totalBytes = 0L                        var lastProgress = 0                        while (input.read(buffer).also { bytesRead = it } != -1) {                            output.write(buffer, 0, bytesRead)                            totalBytes += bytesRead                            val progress = minOf(((totalBytes * 100) / contentLength).toInt(), 99)                            if (progress - lastProgress >= 10) {                                lastProgress = progress                                updateGroupDownloadPercent(groupId, progress, sandesh.sandeshId)                            }                        }                    }                }                DLog.i("✅ ZIP downloaded: ${encryptedZipFile.absolutePath}")                // -------------------------                // 🔓 4️⃣ Decrypt & Extract                // -------------------------                val zipFile = ZipFile(encryptedZipFile, password.toCharArray())                zipFile.extractAll(downloadDir.absolutePath)                // -------------------------                // 📂 5️⃣ Collect ALL files                // -------------------------                val extractedFiles = zipFile.fileHeaders.mapNotNull { header ->                    val file = File(downloadDir, header.fileName)                    if (file.exists()) file else null                }                // -------------------------                // 🔄 6️⃣ Rename files                // -------------------------                val renameSuffix = if (isVideo) "vid" else "img"                val finalFiles = extractedFiles.mapIndexed { index, file ->                    val newFile =                        File(downloadDir, "${currentDate}_${renameSuffix}_${index}.${file.extension}")                    file.renameTo(newFile)                    newFile                }                DLog.i("${if (isVideo) "🎬" else "📸"} Extracted ${finalFiles.size} ${mediaCategory.name.lowercase()}s")                // -------------------------                // 💾 7️⃣ Save to MediaStore                // -------------------------                val mimePrefix = if (isVideo) "video/" else "image/"                val mimeFallback = if (isVideo) "video/mp4" else "image/jpeg"                val oldArray = jsonObject.getAsJsonArray(DootawasMessage.ALL_DATA)                val resolvedMedia = mutableListOf<Pair<String, String>>() // path + mime                val visibility = if (saveToGallery) MediaVisibility.PUBLIC else MediaVisibility.PRIVATE                finalFiles.forEachIndexed { index, file ->                    val senderMime = if (oldArray != null && index < oldArray.size()) {                        oldArray[index].asJsonObject.get(DootawasMessage.MIME_TYPE)?.asString                    } else null                    val fileMime = senderMime?.takeIf { it.startsWith(mimePrefix) }                        ?: getMimeTypeFromFile(file).takeIf { it.startsWith(mimePrefix) }                        ?: mimeFallback                    val savedMedia = saveMediaToAppStorageNext(                        context = context,                        sourceUri = file.toUri(),                        storageType = mediaCategory,                        visibility = visibility,                        overrideMimeType = fileMime                    )                    val resolvedPath = savedMedia?.localPath ?: file.absolutePath                    val resolvedMime = savedMedia?.mimeType ?: fileMime                    resolvedMedia.add(Pair(resolvedPath, resolvedMime))                }                // -------------------------                // 🧾 8️⃣ Update DB (with mutex)                // -------------------------                val mutex = SamagriUpdateLock.getMutexForId(sandesh.sandeshId)                mutex.withLock {                    val updated =                        groupDao.getGroupSandeshByIdAndGroupId(sandesh.sandeshId, groupId)                    if (updated != null) {                        val json = JsonParser.parseString(updated.samagri).asJsonObject                        // ALL_DATA → media paths                        val dataArray = JsonArray()                        resolvedMedia.forEach { (path, mime) ->                            dataArray.add(JsonObject().apply {                                addProperty(DootawasMessage.ORIGINAL_URI, path)                                addProperty(DootawasMessage.MIME_TYPE, mime)                            })                        }                        json.add(DootawasMessage.ALL_DATA, dataArray)                        json.addProperty(                            DootawasMessage.DOWNLOAD_PERCENT,                            100                        )                        groupDao.updateSamagri(                            sandesh.sandeshId,                            json.toString(),                            groupId                        )                        if (isVideo) {                            generateAndSaveThumbnailInternalGroup(                                json,                                sandesh.sandeshId,                                groupId                            )                        }                    }                }            } catch (e: Exception) {                updateGroupDownloadPercent(groupId, 0, sandesh.sandeshId)                Log.e("DownloadMultiMediaFilesGroup", "💥 Error: ${e.message}")            } finally {                cleanOldZipFiles()            }        }    }    fun downloadSingleFileGroup(sandesh: GroupSandesh, groupId: String) {        DLog.i("⬇️ DOWNLOADING FILE for Sandesh ID: ${sandesh.sandeshId}")        coroutineScope.launch(Dispatchers.IO) {            try {                val jsonObject = JsonParser.parseString(sandesh.samagri).asJsonObject                val password = jsonObject.get(DootawasMessage.FILE_PASS).asString                val uuid = jsonObject.get(DootawasMessage.FILE_ID).asString                val sender = sandesh.userNumber                val mimeType = jsonObject.get("mimeType").asString                val fileExtension = getFileExtension(mimeType)                val category = getFileCategory(mimeType)                val apiLevel = Build.VERSION.SDK_INT                val saveToGallery = settingFlow(                    SettingPrefKeys.CHAT_MEDIA_SAVE_TO_GALLERY,                    false                ).first() && sandesh.sandeshType !in setOf(                    SandeshType.LOCATION.value,                    SandeshType.REPLY_LOCATION.value                )                // -------------------------                // 📂 1️⃣ Prepare download folder                // -------------------------                val downloadDir = when {                    saveToGallery && apiLevel >= Build.VERSION_CODES.Q &&                            category in listOf("image", "video", "audio") ->                        File(context.getExternalFilesDir(null), "Gallery").apply { mkdirs() }                    saveToGallery && category in listOf("image", "video", "audio") -> {                        val base = when (category) {                            "image" -> Environment.DIRECTORY_PICTURES                            "video" -> Environment.DIRECTORY_MOVIES                            "audio" -> Environment.DIRECTORY_MUSIC                            else -> Environment.DIRECTORY_DOWNLOADS                        }                        File(Environment.getExternalStoragePublicDirectory(base), "Knotx")                            .apply { mkdirs() }                    }                    else -> File(context.getExternalFilesDir(null), "Documents").apply { mkdirs() }                }                val currentDate = SimpleDateFormat("yyyyMMdd_HHmmss", Locale.getDefault()).format(Date())                val encryptedZipFile = File(downloadDir, "$currentDate.zip")                updateGroupDownloadPercent(groupId, 1, sandesh.sandeshId)                // -------------------------                // 🔗 2️⃣ Fetch Signed URL                // -------------------------                val downloadResponse = requestDownloadUrl(                    sender = sender,                    messageId = uuid                )                if (!downloadResponse.success) {                    DLog.i("❌ Failed to get download URL: ${downloadResponse.message}")                    updateGroupDownloadPercent(groupId, 0, sandesh.sandeshId)                    return@launch                }                val signedUrl = downloadResponse.downloadUrl                if (signedUrl.isNullOrBlank()) {                    DLog.i("❌ Download URL empty")                    updateGroupDownloadPercent(groupId, 0, sandesh.sandeshId)                    return@launch                }                // -------------------------                // ⬇️ 3️⃣ Download ZIP                // -------------------------                val request = Request.Builder().url(signedUrl).build()                val client = OkHttpClient()                val httpResponse = client.newCall(request).execute()                if (!httpResponse.isSuccessful) {                    DLog.i("❌ Failed to download file")                    updateGroupDownloadPercent(groupId, 0, sandesh.sandeshId)                    return@launch                }                val body = httpResponse.body                val contentLength = body.contentLength()                body.byteStream().use { input ->                    encryptedZipFile.outputStream().use { output ->                        val buffer = ByteArray(DEFAULT_BUFFER_SIZE)                        var bytesRead: Int                        var totalBytes = 0L                        var lastProgress = 0                        while (input.read(buffer).also { bytesRead = it } != -1) {                            output.write(buffer, 0, bytesRead)                            totalBytes += bytesRead                            val progress = minOf(((totalBytes * 100) / contentLength).toInt(), 99)                            if (progress - lastProgress >= 10) {                                lastProgress = progress                                updateGroupDownloadPercent(groupId, progress, sandesh.sandeshId)                            }                        }                    }                }                DLog.i("✅ ZIP saved: ${encryptedZipFile.absolutePath}")                // -------------------------                // 4️⃣ Decrypt & Extract                // -------------------------                try {                    val zipFile = ZipFile(encryptedZipFile, password.toCharArray())                    zipFile.extractAll(downloadDir.absolutePath)                    val extractedFile = File(downloadDir, zipFile.fileHeaders[0].fileName)                    val finalFile = File(downloadDir, "$currentDate$fileExtension")                    if (extractedFile.exists()) extractedFile.renameTo(finalFile)                    DLog.i("✅ Final file: ${finalFile.absolutePath}")                    // -------------------------                    // 5️⃣ Save via saveMediaToAppStorage                    // -------------------------                    val fileCategory = when (category) {                        "image" -> MediaCategory.IMAGE                        "video" -> MediaCategory.VIDEO                        "audio" -> MediaCategory.AUDIO                        else -> MediaCategory.DOCUMENT                    }                    val visibility = if (saveToGallery) MediaVisibility.PUBLIC else MediaVisibility.PRIVATE                    val savedMedia = saveMediaToAppStorageNext(                        context = context,                        sourceUri = finalFile.toUri(),                        storageType = fileCategory,                        visibility = visibility,                        overrideMimeType = mimeType                    )                    val resolvedPath =                        savedMedia?.localPath ?: finalFile.absolutePath                    val resolvedMime =                        savedMedia?.mimeType ?: mimeType                    // -------------------------                    // 6️⃣ Update DB (with mutex)                    // -------------------------                    val mutex = SamagriUpdateLock.getMutexForId(sandesh.sandeshId)                    mutex.withLock {                        val updated = groupDao.getGroupSandeshByIdAndGroupId(sandesh.sandeshId, groupId)                        if (updated != null) {                            val json = JsonParser.parseString(updated.samagri).asJsonObject                            json.addProperty(DootawasMessage.ORIGINAL_URI, resolvedPath)                            json.addProperty(DootawasMessage.DOWNLOAD_PERCENT, 100)                            json.addProperty(DootawasMessage.MIME_TYPE, resolvedMime)                            if (sandesh.sandeshType == SandeshType.VIDEO.value ||                                sandesh.sandeshType == SandeshType.REPLY_VIDEO.value                            ) {                                val previewUri = generateAndSaveThumbnail(json, sandesh.sandeshId)                                if (previewUri != null) json.addProperty(                                    DootawasMessage.DUPLICATE_URI,                                    previewUri                                )                            } else if (sandesh.sandeshType == SandeshType.DOCUMENT.value ||                                sandesh.sandeshType == SandeshType.REPLY_DOCUMENT.value                            ) {                                val previewUri = saveFirstPageAsImage(context, finalFile.toUri())                                if (previewUri != null) json.addProperty(                                    DootawasMessage.DUPLICATE_URI,                                    previewUri.toString()                                )                            }                            groupDao.updateSamagri(sandesh.sandeshId, json.toString(), groupId)                        }                    }                } catch (ze: ZipException) {                    ze.printStackTrace()                    DLog.i("❌ ZIP extraction failed: ${ze.message}")                } catch (ex: Exception) {                    ex.printStackTrace()                    DLog.i("❌ Unexpected error during extraction: ${ex.message}")                }            } catch (e: Exception) {                Log.e("DownloadSingleFileGroup", "💥 Error: ${e.message}")                updateGroupDownloadPercent(groupId, 0, sandesh.sandeshId)            } finally {                cleanOldZipFiles()            }        }    }    fun cleanOldZipFiles(maxAgeHours: Long = 24) {        val dirs = listOf(            File(context.getExternalFilesDir(null), "Gallery"),            File(context.getExternalFilesDir(null), "Documents")        )        val now = System.currentTimeMillis()        var totalDeletedCount = 0        dirs.forEach { tempDir ->            if (!tempDir.exists()) {                tempDir.mkdirs()                DLog.i("✅ Created temp directory: ${tempDir.absolutePath}")                return@forEach            }            var deletedCount = 0            tempDir.listFiles()?.forEach { file ->                if (file.extension == "zip") {                    val ageHours = (now - file.lastModified()) / (1000 * 60 * 60)                    if (ageHours >= maxAgeHours) {                        if (file.delete()) {                            deletedCount++                            DLog.i("🗑 Deleted old ZIP: ${file.name} (age: ${ageHours}h)")                        } else {                            DLog.i("⚠️ Failed to delete: ${file.name}")                        }                    }                }            }            totalDeletedCount += deletedCount            DLog.i("✅ Cleanup done for ${tempDir.name}. Deleted $deletedCount old ZIP files.")        }        DLog.i("✅ Total cleanup complete. Deleted $totalDeletedCount old ZIP files from all directories.")    }    private val downloadSemaphore = Semaphore(3)    fun downloadFile(sandeshId: String, userNumber: String) {        coroutineScope.launch(Dispatchers.IO) {            downloadSemaphore.withPermit {                try {                    val sandesh = sandeshDao.getSandeshByIdAndUser(sandeshId, userNumber)                        ?: return@withPermit                    when (sandesh.sandeshType) {                        SandeshType.IMAGE.value,                        SandeshType.REPLY_IMAGE.value ->                            downloadMultiMediaFiles(sandesh, userNumber, MediaCategory.IMAGE)                        SandeshType.VIDEO.value,                        SandeshType.REPLY_VIDEO.value ->                            downloadMultiMediaFiles(sandesh, userNumber, MediaCategory.VIDEO)                        else -> downloadSingleFile(sandesh, userNumber)                    }                } catch (e: CancellationException) {                    throw e                } catch (e: Exception) {                    Log.e("DownloadFile", "Download failed: $sandeshId", e)                }            }        }    }    fun getMimeTypeFromFile(file: File): String {        return MimeTypeMap.getSingleton()            .getMimeTypeFromExtension(file.extension.lowercase())            ?: "application/octet-stream"    }    suspend fun downloadMultiMediaFiles(        sandesh: Sandesh,        userNumber: String,        mediaCategory: MediaCategory    ) {        DLog.i("⬇️ DOWNLOADING ${mediaCategory.name} FILES for Sandesh: $sandesh")        val isVideo = mediaCategory == MediaCategory.VIDEO        try {            val jsonObject = JsonParser.parseString(sandesh.samagri).asJsonObject            val password = jsonObject.get(DootawasMessage.FILE_PASS).asString            val uuid = jsonObject.get(DootawasMessage.FILE_ID).asString            val sender = sandesh.userNumber            val saveToGallery = settingFlow(                SettingPrefKeys.CHAT_MEDIA_SAVE_TO_GALLERY,                false            ).first() && sandesh.sandeshType !in setOf(                SandeshType.LOCATION.value,                SandeshType.REPLY_LOCATION.value            )            val apiLevel = Build.VERSION.SDK_INT            // -------------------------            // 📂 1️⃣ Prepare download folder            // -------------------------            val dirName = if (isVideo) "Videos" else "Images"            val galleryLegacyDir =                if (isVideo) Environment.DIRECTORY_MOVIES else Environment.DIRECTORY_PICTURES            val downloadDir = when {                saveToGallery && apiLevel >= Build.VERSION_CODES.Q ->                    File(context.getExternalFilesDir(null), "Gallery").apply { mkdirs() }                saveToGallery ->                    File(                        Environment.getExternalStoragePublicDirectory(galleryLegacyDir),                        "Knotx"                    ).apply { mkdirs() }                else -> File(context.getExternalFilesDir(null), dirName).apply { mkdirs() }            }            val currentDate =                SimpleDateFormat("yyyyMMdd_HHmmss", Locale.getDefault()).format(Date())            val encryptedZipFile = File(downloadDir, "$currentDate.zip")            updateDownloadPercent(userNumber, 1, sandesh.sandeshId)            // -------------------------            // 🔗 2️⃣ Fetch Signed URL            // -------------------------// -------------------------// 🔗 2️⃣ Fetch Signed URL// -------------------------            val downloadResponse = requestDownloadUrl(                sender = sender,                messageId = uuid            )            if (!downloadResponse.success) {                DLog.i("❌ Failed to get download URL: ${downloadResponse.message}")                updateDownloadPercent(userNumber, 0, sandesh.sandeshId)                return            }            val signedUrl = downloadResponse.downloadUrl            if (signedUrl.isNullOrBlank()) {                DLog.i("❌ Download URL empty")                updateDownloadPercent(userNumber, 0, sandesh.sandeshId)                return            }            // -------------------------            // ⬇️ 3️⃣ Download ZIP            // -------------------------            val request = Request.Builder().url(signedUrl).build()            val client = OkHttpClient()            val response = client.newCall(request).execute()            DLog.i("HTTP ${response.code}")            DLog.i("Message: ${response.message}")            if (!response.isSuccessful) {                DLog.i("Body: ${response.body?.string()}")                updateDownloadPercent(userNumber, 0, sandesh.sandeshId)                return            }            val body = response.body            val contentLength = body.contentLength()            body.byteStream().use { input ->                encryptedZipFile.outputStream().use { output ->                    val buffer = ByteArray(DEFAULT_BUFFER_SIZE)                    var bytesRead: Int                    var totalBytes = 0L                    var lastProgress = 0                    while (input.read(buffer).also { bytesRead = it } != -1) {                        output.write(buffer, 0, bytesRead)                        totalBytes += bytesRead                        val progress = minOf(((totalBytes * 100) / contentLength).toInt(), 99)                        if (progress - lastProgress >= 10) {                            lastProgress = progress                            updateDownloadPercent(userNumber, progress, sandesh.sandeshId)                        }                    }                }            }            DLog.i("✅ ZIP downloaded: ${encryptedZipFile.absolutePath}")            // -------------------------            // 🔓 4️⃣ Decrypt & Extract            // -------------------------            val zipFile = ZipFile(encryptedZipFile, password.toCharArray())            zipFile.extractAll(downloadDir.absolutePath)            // -------------------------            // 📂 5️⃣ Collect ALL files            // -------------------------            val extractedFiles = zipFile.fileHeaders.mapNotNull { header ->                val file = File(downloadDir, header.fileName)                if (file.exists()) file else null            }            // -------------------------            // 🔄 6️⃣ Rename files            // -------------------------            val renameSuffix = if (isVideo) "vid" else "img"            val finalFiles = extractedFiles.mapIndexed { index, file ->                val newFile = File(                    downloadDir,                    "${currentDate}_${renameSuffix}_${index}.${file.extension}"                )                file.renameTo(newFile)                newFile            }            DLog.i("${if (isVideo) "🎬" else "📸"} Extracted ${finalFiles.size} ${mediaCategory.name.lowercase()}s")            // -------------------------            // 💾 7️⃣ Save to MediaStore            // -------------------------            val mimePrefix = if (isVideo) "video/" else "image/"            val mimeFallback = if (isVideo) "video/mp4" else "image/jpeg"            val oldArray = jsonObject.getAsJsonArray(DootawasMessage.ALL_DATA)            val resolvedMedia = mutableListOf<Pair<String, String>>()   // path + mime            val visibility = if (saveToGallery) {                val duration = upbhogtaDao.getAutoDisappearDuration(userNumber) ?: 0                if (duration != 0) MediaVisibility.PRIVATE else MediaVisibility.PUBLIC            } else {                MediaVisibility.PRIVATE            }            finalFiles.forEachIndexed { index, file ->                val senderMime = if (oldArray != null && index < oldArray.size()) {                    oldArray[index].asJsonObject.get(DootawasMessage.MIME_TYPE)?.asString                } else null                val fileMime = senderMime?.takeIf { it.startsWith(mimePrefix) }                    ?: getMimeTypeFromFile(file).takeIf { it.startsWith(mimePrefix) }                    ?: mimeFallback                val savedMedia = saveMediaToAppStorageNext(                    context = context,                    sourceUri = file.toUri(),                    storageType = mediaCategory,                    visibility = visibility,                    overrideMimeType = fileMime                )                val resolvedPath = savedMedia?.localPath ?: file.absolutePath                val resolvedMime = savedMedia?.mimeType ?: fileMime                resolvedMedia.add(Pair(resolvedPath, resolvedMime))            }            // -------------------------            // 🧾 8️⃣ Update DB (with mutex)            // -------------------------            CoroutineScope(Dispatchers.IO).launch {                val mutex = SamagriUpdateLock.getMutexForId(sandesh.sandeshId)                mutex.withLock {                    val updated =                        sandeshDao.getSandeshByIdAndUser(sandesh.sandeshId, userNumber)                    if (updated != null) {                        val json = JsonParser.parseString(updated.samagri).asJsonObject                        // ALL_DATA → media paths                        val dataArray = JsonArray()                        resolvedMedia.forEach { (path, mime) ->                            dataArray.add(JsonObject().apply {                                addProperty(DootawasMessage.ORIGINAL_URI, path)                                addProperty(DootawasMessage.MIME_TYPE, mime)                            })                        }                        json.add(DootawasMessage.ALL_DATA, dataArray)                        // IMAGE_PREVIEW → thumbnails (videos only)                        json.addProperty(DootawasMessage.DOWNLOAD_PERCENT, 100)                        sandeshDao.updateSamagri(sandesh.sandeshId, json.toString())                        if (isVideo) {                            generateAndSaveThumbnailInternal(                                json,                                sandesh.sandeshId,                                userNumber                            )                        }                    }                }            }        } catch (e: Exception) {            Log.e("DownloadMultiMediaFiles", "💥 Error", e)            updateDownloadPercent(userNumber, 0, sandesh.sandeshId)        } finally {            cleanOldZipFiles()        }    }    suspend fun downloadSingleFile(sandesh: Sandesh, userNumber: String) {        DLog.i("⬇️ DOWNLOADING FILE for Sandesh ID: ${sandesh.sandeshId}")            try {                val jsonObject = JsonParser.parseString(sandesh.samagri).asJsonObject                val password = jsonObject.get(DootawasMessage.FILE_PASS).asString                val uuid = jsonObject.get(DootawasMessage.FILE_ID).asString                val sender = sandesh.userNumber                val mimeType = jsonObject.get("mimeType").asString                val fileExtension = getFileExtension(mimeType)                val category = getFileCategory(mimeType)                val saveToGallery =                    settingFlow(SettingPrefKeys.CHAT_MEDIA_SAVE_TO_GALLERY, false).first()                val apiLevel = Build.VERSION.SDK_INT                // -------------------------                // 1️⃣ Prepare download folder                // -------------------------                val downloadDir = when {                    saveToGallery && apiLevel >= Build.VERSION_CODES.Q &&                            category in listOf("image", "video", "audio") ->                        File(context.getExternalFilesDir(null), "Gallery").apply { mkdirs() }                    saveToGallery && category in listOf("image", "video", "audio") -> {                        val base = when (category) {                            "image" -> Environment.DIRECTORY_PICTURES                            "video" -> Environment.DIRECTORY_MOVIES                            "audio" -> Environment.DIRECTORY_MUSIC                            else -> Environment.DIRECTORY_DOWNLOADS                        }                        File(Environment.getExternalStoragePublicDirectory(base), "Knotx")                            .apply { mkdirs() }                    }                    else -> File(context.getExternalFilesDir(null), "Documents").apply { mkdirs() }                }                val currentDate =                    SimpleDateFormat("yyyyMMdd_HHmmss", Locale.getDefault()).format(Date())                val encryptedZipFile = File(downloadDir, "$currentDate.zip")                updateDownloadPercent(userNumber, 1, sandesh.sandeshId)                // -------------------------                // 2️⃣ Fetch Signed URL                // -------------------------// -------------------------// 2️⃣ Fetch Signed URL// -------------------------                val downloadResponse = requestDownloadUrl(                    sender = sender,                    messageId = uuid                )                if (!downloadResponse.success) {                    DLog.i("❌ Failed to get download URL: ${downloadResponse.message}")                    updateDownloadPercent(userNumber, 0, sandesh.sandeshId)                    return                }                val signedUrl = downloadResponse.downloadUrl                DLog.i("🔗 Signed URL received: $signedUrl")                if (signedUrl.isNullOrBlank()) {                    DLog.i("❌ Download URL empty")                    updateDownloadPercent(userNumber, 0, sandesh.sandeshId)                    return                }                // -------------------------                // 3️⃣ Download ZIP via OkHttp                // -------------------------                val request = Request.Builder().url(signedUrl).build()                val client = OkHttpClient()                val httpResponse = client.newCall(request).execute()                if (!httpResponse.isSuccessful) {                    DLog.i("❌ Failed to download file")                    updateDownloadPercent(userNumber, 0, sandesh.sandeshId)                    return                }                val body = httpResponse.body                val contentLength = body.contentLength()                DLog.i("📦 ZIP size from S3 = $contentLength bytes")                body.byteStream().use { input ->                    encryptedZipFile.outputStream().use { output ->                        val buffer = ByteArray(DEFAULT_BUFFER_SIZE)                        var bytesRead: Int                        var totalBytes = 0L                        var lastProgress = 0                        while (input.read(buffer).also { bytesRead = it } != -1) {                            output.write(buffer, 0, bytesRead)                            totalBytes += bytesRead                            val progress = minOf(((totalBytes * 100) / contentLength).toInt(), 99)                            if (progress - lastProgress >= 10) {                                lastProgress = progress                                updateDownloadPercent(userNumber, progress, sandesh.sandeshId)                            }                        }                    }                }                DLog.i("✅ ZIP saved: ${encryptedZipFile.absolutePath}")                // -------------------------                // 4️⃣ Decrypt & Extract ZIP                // -------------------------                val zipFile = ZipFile(encryptedZipFile, password.toCharArray())                zipFile.extractAll(downloadDir.absolutePath)                val extractedFile = File(downloadDir, zipFile.fileHeaders[0].fileName)                val finalFile = File(downloadDir, "$currentDate$fileExtension")                if (extractedFile.exists()) extractedFile.renameTo(finalFile)                DLog.i("✅ Final File: ${finalFile.absolutePath}")                // -------------------------                // 5️⃣ Save via saveMediaToAppStorage                // -------------------------                val fileCategory = when (category) {                    "image" -> MediaCategory.IMAGE                    "video" -> MediaCategory.VIDEO                    "audio" -> MediaCategory.AUDIO                    else -> MediaCategory.DOCUMENT                }                val visibility = if (saveToGallery) {                    val duration = upbhogtaDao.getAutoDisappearDuration(userNumber) ?: 0                    if (duration != 0) MediaVisibility.PRIVATE else MediaVisibility.PUBLIC                } else {                    MediaVisibility.PRIVATE                }                val savedMedia = saveMediaToAppStorageNext(                    context = context,                    sourceUri = finalFile.toUri(),                    storageType = fileCategory,                    visibility = visibility,                    overrideMimeType = mimeType                )                val resolvedPath =                    savedMedia?.localPath ?: finalFile.absolutePath                val resolvedMime =                    savedMedia?.mimeType ?: mimeType                // -------------------------                // 6️⃣ Update local DB                // -------------------------                CoroutineScope(Dispatchers.IO).launch {                    val mutex = SamagriUpdateLock.getMutexForId(sandesh.sandeshId)                    mutex.withLock {                        val updated = sandeshDao.getSandeshByIdAndUser(sandesh.sandeshId, userNumber)                        if (updated != null) {                            val json = JsonParser.parseString(updated.samagri).asJsonObject                            json.addProperty(DootawasMessage.ORIGINAL_URI, resolvedPath)                            json.addProperty(DootawasMessage.DOWNLOAD_PERCENT, 100)                            json.addProperty(DootawasMessage.MIME_TYPE, resolvedMime)                            if (sandesh.sandeshType == SandeshType.VIDEO.value ||                                sandesh.sandeshType == SandeshType.REPLY_VIDEO.value                            ) {                                val previewUri = generateAndSaveThumbnail(json, sandesh.sandeshId)                                if (previewUri != null) json.addProperty(                                    DootawasMessage.DUPLICATE_URI,                                    previewUri                                )                            } else if (sandesh.sandeshType == SandeshType.DOCUMENT.value ||                                sandesh.sandeshType == SandeshType.REPLY_DOCUMENT.value                            ) {                                val previewUri = saveFirstPageAsImage(context, finalFile.toUri())                                if (previewUri != null) json.addProperty(                                    DootawasMessage.DUPLICATE_URI,                                    previewUri.toString()                                )                            }                            sandeshDao.updateSamagri(sandesh.sandeshId, json.toString())                        }                    }                }            } catch (e: Exception) {                updateDownloadPercent(userNumber, 0, sandesh.sandeshId)                Log.e("DownloadFile", "💥 Error: ${e.message}")            } finally {                cleanOldZipFiles()            }    }    private fun getFileCategory(mimeType: String): String {        return when {            mimeType.startsWith("image/") -> "image"            mimeType.startsWith("video/") -> "video"            mimeType.startsWith("audio/") -> "audio"            mimeType == "application/pdf" -> "document"            mimeType == "application/msword" ||                    mimeType == "application/vnd.openxmlformats-officedocument.wordprocessingml.document" ||                    mimeType == "application/vnd.ms-excel" ||                    mimeType == "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" ||                    mimeType == "application/vnd.ms-powerpoint" ||                    mimeType == "application/vnd.openxmlformats-officedocument.presentationml.presentation" -> "document"            mimeType.startsWith("text/") -> "document"            else -> "unknown"        }    }    fun saveFirstPageAsImage(        context: Context,        docUri: Uri    ): Uri? {        return try {            val fileDescriptor =                context.contentResolver.openFileDescriptor(                    docUri,                    "r"                ) ?: return null            val pdfRenderer =                PdfRenderer(fileDescriptor)            if (pdfRenderer.pageCount == 0) {                pdfRenderer.close()                fileDescriptor.close()                return null            }            val page =                pdfRenderer.openPage(0)            val bitmap = createBitmap(page.width, page.height)            page.render(                bitmap,                null,                null,                PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY            )            page.close()            pdfRenderer.close()            fileDescriptor.close()            // ------------------------------------------------            // Temporary cache file            // ------------------------------------------------            val tempPreviewFile = File.createTempFile(                "pdf_preview_temp",                ".png",                context.cacheDir            )            FileOutputStream(tempPreviewFile).use { out ->                bitmap.compress(                    Bitmap.CompressFormat.PNG,                    100,                    out                )            }            bitmap.recycle()            // ------------------------------------------------            // Save using unified storage system            // ------------------------------------------------            val savedMedia =                saveMediaToAppStorageNext(                    context = context,                    sourceUri = tempPreviewFile.toUri(),                    storageType = MediaCategory.PREVIEW,                    visibility = MediaVisibility.PRIVATE,                    overrideMimeType = "image/png"                )            tempPreviewFile.delete()            savedMedia?.localPath?.toUri()        } catch (e: Exception) {            e.printStackTrace()            null        }    }    private fun getFileExtension(mimeType: String): String {        return when (mimeType) {            "image/jpeg" -> ".jpg"            "image/png" -> ".png"            "image/gif" -> ".gif"            "image/webp" -> ".webp"            "video/mp4" -> ".mp4"            "audio/mpeg" -> ".mp3"            "application/pdf" -> ".pdf"            "application/msword" -> ".doc"            "application/vnd.openxmlformats-officedocument.wordprocessingml.document" -> ".docx"            "application/vnd.ms-excel" -> ".xls"            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" -> ".xlsx"            "application/vnd.ms-powerpoint" -> ".ppt"            "application/vnd.openxmlformats-officedocument.presentationml.presentation" -> ".pptx"            "text/plain" -> ".txt"            else -> ".bin" // Default binary extension        }    }    /**     * Updates the download percent in the database     */    fun updateDownloadPercent(userNumber: String, percent: Int, sandeshId: String) {        CoroutineScope(Dispatchers.IO).launch {            val mutex = SamagriUpdateLock                .getMutexForId(sandeshId)            mutex.withLock {                val sandesh = sandeshDao.getSandeshByIdAndUser(sandeshId, userNumber)                if (sandesh != null) {                    val jsonObject = JsonParser.parseString(sandesh.samagri).asJsonObject                    jsonObject.addProperty(DootawasMessage.DOWNLOAD_PERCENT, percent)                    sandeshDao.updateSamagri(sandeshId, jsonObject.toString())                    DLog.i("📊 Updated Download Percent: $percent% for sandeshId=$sandeshId")                } else {                    DLog.i("⚠️ Sandesh not found for ID=$sandeshId and user=$userNumber")                }            }        }    }    fun updateGroupDownloadPercent(groupId: String, percent: Int, sandeshId: String) {        CoroutineScope(Dispatchers.IO).launch {            val mutex = SamagriUpdateLock                .getMutexForId(sandeshId)            mutex.withLock {                val sandesh = groupDao.getGroupSandeshByIdAndGroupId(sandeshId, groupId)                if (sandesh != null) {                    val jsonObject = JsonParser.parseString(sandesh.samagri).asJsonObject                    jsonObject.addProperty(DootawasMessage.DOWNLOAD_PERCENT, percent)                    groupDao.updateSamagri(                        sandeshId,                        jsonObject.toString(),                        groupId                    ) // ✅ Save updated JSON                    DLog.i("📊 Updated Download Percent: $sandeshId%")                } else {                    DLog.i("⚠️ Sandesh not found for ID=$sandeshId and user=$groupId")                }            }        }    }    private val scheduledDisappearJobs = mutableMapOf<String, Job>()    private fun scheduleDisappearForBatch(        userNumber: String,        sandeshIds: List<String>,        seenTime: Long    ) {        coroutineScope.launch {            val sandeshList = sandeshDao.getSandeshesByIdsAndUser(                sandeshIds,                userNumber            )            sandeshList.forEach { sandesh ->                val diD = try {                    JsonParser.parseString(sandesh.samagri)                        .asJsonObject                        .get(DootawasMessage.DISAPPEAR_DURATION)                        ?.asInt ?: 0                } catch (e: Exception) {                    0                }                if (diD <= 0) return@forEach                if (scheduledDisappearJobs.containsKey(sandesh.sandeshId)) {                    return@forEach                }                val elapsedSeconds =                    (Instant.now().toEpochMilli() - seenTime) / 1000                val remainingSeconds = diD - elapsedSeconds                val job = coroutineScope.launch {                    if (remainingSeconds > 0) {                        delay((remainingSeconds * 1000).milliseconds)                    }                    sandeshDeleter.deleteMessages(                        sandeshIds = listOf(sandesh.sandeshId),                        userNumber = userNumber,                        skipSelfCheck = true                    )                    upbhogtaDao.resetLastMessageByMessageId(                        messageId = sandesh.sandeshId,                        deletedText = "Message Cleared",                        number = userNumber                    )                    scheduledDisappearJobs.remove(sandesh.sandeshId)                }                scheduledDisappearJobs[sandesh.sandeshId] = job            }        }    }    suspend fun cleanupExpiredDisappearingMessages(userNumber: String) {        val now = Instant.now().toEpochMilli()        val dhristMessages = sandeshDao.getAllMessagesByStithi(SandeshStithi.DHRIST, userNumber)        dhristMessages.forEach { sandesh ->            val diD = try {                JsonParser.parseString(sandesh.samagri).asJsonObject                    .get(DootawasMessage.DISAPPEAR_DURATION)?.asInt ?: 0            } catch (e: Exception) {                0            }            if (diD <= 0) return@forEach            val statusJson = sandeshStatusDao.getStatusJson(sandesh.userNumber, sandesh.sandeshId)            val seenTime = try {                Gson().fromJson(statusJson, JsonObject::class.java)                    ?.get(SandeshStithi.DHRIST.value.toString())?.asLong            } catch (e: Exception) {                null            } ?: sandesh.time            val expiryTime = seenTime + (diD * 1000L)            if (now >= expiryTime) {                // already past expiry ? delete immediately                sandeshDeleter.deleteMessages(                    sandeshIds = listOf(sandesh.sandeshId),                    userNumber = userNumber,                    skipSelfCheck = true                )                upbhogtaDao.resetLastMessageByMessageId(                    messageId = sandesh.sandeshId,                    deletedText = "Message Cleared",                    number = userNumber                )            } else {                // not expired yet ? reschedule a timer for the remaining time                // so it still gets deleted on time even without another app restart                if (!scheduledDisappearJobs.containsKey(sandesh.sandeshId)) {                    val remainingMs = expiryTime - now                    val job = coroutineScope.launch {                        delay(remainingMs.milliseconds)                        sandeshDeleter.deleteMessages(                            sandeshIds = listOf(sandesh.sandeshId),                            userNumber = userNumber,                            skipSelfCheck = true                        )                        upbhogtaDao.resetLastMessageByMessageId(                            messageId = sandesh.sandeshId,                            deletedText = "Message Cleared",                            number = userNumber                        )                        scheduledDisappearJobs.remove(sandesh.sandeshId)                    }                    scheduledDisappearJobs[sandesh.sandeshId] = job                }            }        }    }    fun sendDhrist(userNumber: String, isStatusOnly: Boolean = false) {        coroutineScope.launch {            updateStithi.withLock {//                if (!isStatusOnly && activeScreenUser != userNumber) return@withLock                resetUnread(userNumber, true)                val unreadIds = sandeshDao.getUnreadUserMessageIds(userNumber)                if (unreadIds.isEmpty()) return@launch                val time = Instant.now().toEpochMilli().toString()                val idsArray = JsonArray()                unreadIds.forEach { id ->                    idsArray.add(id)                    updateSandeshStithiTimePass(userNumber, id, SandeshStithi.DHRIST, time.toLong())                }                scheduleDisappearForBatch(userNumber, unreadIds, time.toLong()) // 👈 one call, batch handles the rest                val sandeshDelivery = JsonObject()                sandeshDelivery.addProperty(JsonKeys.STORAGE_TYPE, 0)                sandeshDelivery.add(DootawasMessage.ORIGINAL_MESSAGE_ID, idsArray)                sandeshDelivery.add(DootawasMessage.ORIGINAL_MESSAGE_ID, idsArray)                val revealSender = upbhogtaDao.getRevealSender(userNumber) ?: false                sandeshDelivery.addProperty(JsonKeys.REVEAL_SENDER_NUMBER,revealSender)                DLog.i("UNREAD IS RESET")                val unsentSandesh = UnsentSandesh(                    messId = createMessageID(),                    receiver = userNumber,                    message = sandeshDelivery.toString(),                    dataType = DataType.SEEN_STATUS,                    time = time,                    isGroup = false                )                DLog.i("Sending message: $unsentSandesh") // Placeholder action                val isReadReceiptEnabled = settingFlow(                    SettingPrefKeys.CHAT_MESSAGE_READ_RECEIPTS,                    default = true                ).first()                val duration = upbhogtaDao.getAutoDisappearDuration(userNumber)                if (duration != 0 || isReadReceiptEnabled) {                    DLog.i("❌ Read receipts Enabled")                    unsentSandeshDao.insert(unsentSandesh)                }                if (isStatusOnly){                    sendDeliveryConfirmation(unsentSandesh.messId,userNumber,sandeshDelivery.toString(),                        DataType.SEEN_STATUS,time, isGroupZ = false, sendSpringDelivery = true                    )                }                DLog.i(" HELP ME 6")                sendUnsentMessages(isStatusOnly)                delay(70.milliseconds)                // ✅ Reset unread AFTER sending                resetUnread(userNumber, false)            }        }    }    fun sendGroupDhrist(groupId: String, isStatusOnly: Boolean = false) {        coroutineScope.launch {            updateStithi.withLock {//                if (!isStatusOnly && activeScreenUser != groupId) return@withLock                val myUserNumber = userNumberKhud.first()                    ?: return@launch                // ✅ Get messages WITH sender                val unreadMessages = groupDao.getUnreadGroupMessagesForUser(groupId)                DLog.i("UNREAD IS RESET $unreadMessages")                if (unreadMessages.isEmpty()) return@launch                delay(70.milliseconds)                val time = Instant.now().toEpochMilli().toString()                // ✅ GROUP BY ORIGINAL SENDER                val groupedBySender = unreadMessages.groupBy { it.userNumber }                val isReadReceiptEnabled = settingFlow(                    SettingPrefKeys.CHAT_MESSAGE_READ_RECEIPTS,                    default = true                ).first()                groupedBySender.forEach { (originalSender, messages) ->                    val idsArray = JsonArray()                    messages.forEach { msg ->                        idsArray.add(msg.sandeshId)                        // ✅ LOCAL UPDATE                        updateGroupSandeshStithiTimePass(                            groupId = groupId,                            sandeshId = msg.sandeshId,                            stithi = SandeshStithi.DHRIST,                            memberUserNumber = myUserNumber,                            time = time.toLong(),                            true                        )                    }                    val sandeshDelivery = JsonObject()                    sandeshDelivery.addProperty(JsonKeys.GROUP_ID, groupId)                    sandeshDelivery.addProperty(JsonKeys.STORAGE_TYPE, 0)                    sandeshDelivery.add(                        DootawasMessage.ORIGINAL_MESSAGE_ID,                        idsArray                    )                    val revealSender = groupDao.getRevealSender(groupId) ?: false                    sandeshDelivery.addProperty(JsonKeys.REVEAL_SENDER_NUMBER,revealSender)                    val unsentSandesh = UnsentSandesh(                        messId = createMessageID(),                        receiver = originalSender, // ✅ FIXED                        message = sandeshDelivery.toString(),                        dataType = DataType.SEEN_STATUS,                        time = time,                        isGroup = true                    )                    DLog.i("Sending SEEN to $originalSender -> $idsArray")                    if (isReadReceiptEnabled) {                        unsentSandeshDao.insert(unsentSandesh)                    }                    DLog.i(" HELP ME 6")                    if (isStatusOnly){                        sendDeliveryConfirmation(unsentSandesh.messId,originalSender,sandeshDelivery.toString(),                            DataType.SEEN_STATUS,time,false, sendSpringDelivery = true                        )                    }                }                // ✅ Send all queued messages                sendUnsentMessages(isStatusOnly)                delay(70.milliseconds)                // ✅ Reset unread AFTER sending                resetUnread(groupId, true)            }        }    }    suspend fun resetUnread(id: String, isGroup: Boolean){        if (isGroup){            groupDao.resetUnread(id)        }else{            upbhogtaDao.resetUnread(id)        }    }    //endregion    fun updateServerContacts(payload: JsonObject) {        coroutineScope.launch {            writeMessageMutex.withLock {                val unsentSandesh = UnsentSandesh(                    messId = createMessageID(),                    receiver = "update-contacts",   // server route / handler key                    message = payload.toString(),   // 🔥 Gson JSON as String                    dataType = DataType.UPDATE_SERVER_CONTACTS,                    isGroup = false                )                // 📦 store locally (offline-safe)                insertUnsentData(unsentSandesh)                // 🚀 trigger sender if idle                sendUnsentMessages(false)            }        }    }    fun buildPrivacyPayload(        type: PrivacyType,        value: Int    ): JsonObject {        return JsonObject().apply {            addProperty(JsonKeys.PRIVACY_TYPE, type.name)            addProperty(JsonKeys.DATA, value)        }    }    fun updateServerPrivacySetting(        privacyType: PrivacyType,        value: Int    ) {        coroutineScope.launch {            writeMessageMutex.withLock {                val payload = buildPrivacyPayload(privacyType, value)                val unsentSandesh = UnsentSandesh(                    messId = createMessageID(),                    receiver = "privacy-update",                    message = payload.toString(),                    dataType = DataType.UPDATE_PRIVACY_SETTING,                    isGroup = false                )                insertUnsentData(unsentSandesh)                sendUnsentMessages(false)            }        }    }    //region DataStore//    private val _profileImagePathFlow = MutableStateFlow<String?>(null)//    val profileImagePathFlow: StateFlow<String?> = _profileImagePathFlow    private val _isPasscodeEnabledFlow = MutableStateFlow(false)    val isPasscodeEnabledFlow: StateFlow<Boolean> = _isPasscodeEnabledFlow    private val flowCache = mutableMapOf<Preferences.Key<*>, StateFlow<*>>()    @Suppress("UNCHECKED_CAST")    suspend fun <T> settingFlow(key: Preferences.Key<T>, default: T): StateFlow<T> {        // Return from cache if already initialized        flowCache[key]?.let {            return it as StateFlow<T>        }        // Get the initial value from DataStore        val initialValue = try {            settingStore.data.first()[key] ?: default        } catch (e: Exception) {            default        }        // Create the flow        val stateFlow = settingStore.data            .map { prefs ->                prefs[key] ?: default            }            .stateIn(                coroutineScope,                SharingStarted.Eagerly,                initialValue            )        // Cache it        flowCache[key] = stateFlow        return stateFlow    }    fun updateStringSetSetting(        key: Preferences.Key<Set<String>>,        newValue: Set<String>    ) {        coroutineScope.launch {            settingStore.edit { prefs ->                prefs[key] = newValue            }        }    }    private val _selectedAppIcon = MutableStateFlow("default")    val selectedAppIcon: StateFlow<String> = _selectedAppIcon    fun loadAppIcon() {        coroutineScope.launch {            val prefs = settingStore.data.first()            _selectedAppIcon.value = prefs[PrefKeys.APP_ICON] ?: "default"        }    }    fun saveAppIcon(context: Context, icon: String) {        val selectedIcon = if (icon in setOf("default", "green", "cyan", "blue", "slate", "orange")) icon else "default"        AppIconManager.changeAppIcon(context, selectedIcon)        coroutineScope.launch {            settingStore.edit { prefs -> prefs[PrefKeys.APP_ICON] = selectedIcon }            _selectedAppIcon.value = selectedIcon        }    }    val settingsFlow: StateFlow<Map<Preferences.Key<*>, Any?>> =        settingStore.data            .map { prefs -> prefs.asMap() }            .stateIn(coroutineScope, SharingStarted.WhileSubscribed(5000), emptyMap())    @Suppress("UNCHECKED_CAST")    fun <T> observeSetting(        key: Preferences.Key<T>,        default: T    ): StateFlow<T> {        // return cached flow if already exists        flowCache[key]?.let {            return it as StateFlow<T>        }        val stateFlow = settingStore.data            .map { prefs -> prefs[key] ?: default }            .stateIn(                coroutineScope,                SharingStarted.Eagerly,                default            )        flowCache[key] = stateFlow        return stateFlow    }    @Suppress("UNCHECKED_CAST")    fun <T> getCachedSettingFlow(        key: Preferences.Key<T>,        default: T    ): StateFlow<T> {        val stateFlow = MutableStateFlow<T?>(null)        coroutineScope.launch {            val initial = settingStore.data.map { prefs -> prefs[key] as? T ?: default }.first()            stateFlow.value = initial            // Keep updating in background            settingStore.data.map { prefs -> prefs[key] as? T ?: default }                .collect { stateFlow.value = it }        }        return stateFlow.map { it ?: default }            .stateIn(coroutineScope, SharingStarted.Eagerly, default)    }    fun saveThemeBundle(bundle: StoredThemeBundle) {        coroutineScope.launch {            val json = gson.toJson(bundle)            settingStore.edit {                it[PrefKeys.DOOTAWAS_THEME] = json            }            // 🔥 update memory instantly (no reload needed)            _themeBundle.value = bundle        }    }    private val _themeBundle = MutableStateFlow<StoredThemeBundle?>(null)    val themeBundle: StateFlow<StoredThemeBundle?> = _themeBundle    fun loadTheme() {        coroutineScope.launch {            val prefs = settingStore.data.first()            val json = prefs[PrefKeys.DOOTAWAS_THEME]            val bundle = if (json != null) {                gson.fromJson(json, StoredThemeBundle::class.java)            } else {                StoredThemeBundle(                    light = LightDootawasColors.toStored(),                    dark = DarkDootawasColors.toStored()                )            }            _themeBundle.value = bundle        }    }    fun updateSingleColor(        isDark: Boolean,        borderMode: BorderMode,        useModernStyle: Boolean, // 👈 1. Added layout configuration flag parameter        update: (DootawasColors) -> DootawasColors    ) {        coroutineScope.launch {            val bundle = _themeBundle.value ?: return@launch            val current = if (isDark) {                bundle.dark.toCompose()            } else {                bundle.light.toCompose()            }            // apply change            val updatedTheme = update(current)            // 2. Build the updated bundle configuration including layout style selection flags cleanly            val updatedBundle = if (isDark) {                bundle.copy(                    dark = updatedTheme.toStored(),                    borderMode = borderMode.ordinal,                    useModernStyle = useModernStyle                )            } else {                bundle.copy(                    light = updatedTheme.toStored(),                    borderMode = borderMode.ordinal,                    useModernStyle = useModernStyle                )            }            // save to DataStore            settingStore.edit { preferences ->                preferences[PrefKeys.DOOTAWAS_THEME] = gson.toJson(updatedBundle)            }            // memory state update to trigger observers instantly            _themeBundle.value = updatedBundle        }    }    fun resetTheme() {        coroutineScope.launch {            settingStore.edit { prefs ->                prefs.remove(PrefKeys.DOOTAWAS_THEME) // ✅ only this key            }            // reload default theme into memory            loadTheme()        }    }    // GROUP THEME    private val _groupThemeBundle = MutableStateFlow<StoredGroupThemeBundle?>(null)    val groupThemeBundle: StateFlow<StoredGroupThemeBundle?> = _groupThemeBundle    fun saveGroupThemeBundle(bundle: StoredGroupThemeBundle) {        coroutineScope.launch {            val json = gson.toJson(bundle)            settingStore.edit {                it[PrefKeys.DOOTAWAS_GROUP_THEME] = json            }            _groupThemeBundle.value = bundle // update memory instantly        }    }    fun loadGroupTheme() {        coroutineScope.launch {            val prefs = settingStore.data.first()            val json = prefs[PrefKeys.DOOTAWAS_GROUP_THEME]            val bundle = runCatching {                if (json != null) gson.fromJson(json, StoredGroupThemeBundle::class.java) else null            }.getOrNull() ?: defaultGroupBundle() // nothing set (or corrupt) -> defaults            _groupThemeBundle.value = bundle        }    }    fun updateGroupColor(        isDark: Boolean,        borderMode: BorderMode,        useModernStyle: Boolean,        transform: (GroupDootawasColors) -> GroupDootawasColors    ) {        val b = _groupThemeBundle.value ?: defaultGroupBundle()        saveGroupThemeBundle(            b.copy(                light = if (!isDark) transform(b.light.toCompose()).toStored() else b.light,                dark = if (isDark) transform(b.dark.toCompose()).toStored() else b.dark,                borderMode = borderMode.ordinal,                useModernStyle = useModernStyle            )        )    }    fun resetGroupTheme() = saveGroupThemeBundle(defaultGroupBundle())    // In your Knotx class - add flow + setter    val swipeTutorialShown: Flow<Boolean> = userDataStore.data        .map { prefs -> prefs[SettingPrefKeys.SWIPE_TUTORIAL_SHOWN] ?: false }    suspend fun markSwipeTutorialShown() {        userDataStore.edit { prefs ->            prefs[SettingPrefKeys.SWIPE_TUTORIAL_SHOWN] = true        }    }    private val _sosContactsFlow = MutableStateFlow<List<SosContact>>(emptyList())    val sosContactsFlow: StateFlow<List<SosContact>> = _sosContactsFlow.asStateFlow()    // Call from wherever your SOS-contact-pick