                    }                )            }            json.remove(DootawasMessage.ORIGINAL_URI)            json.remove(DootawasMessage.MIME_TYPE)            if (isVideo) {                val preview =                    json.get(DootawasMessage.DUPLICATE_URI)?.asString                val previewArray = JsonArray()                if (!preview.isNullOrBlank()) {                    previewArray.add(preview)                }                json.remove(DootawasMessage.DUPLICATE_URI)                json.remove(DootawasMessage.BLUR_URI)                json.add(                    DootawasMessage.IMAGE_PREVIEW,                    previewArray                )            }            json.addProperty(                DootawasMessage.DATA_COUNT,                1            )            json.add(                DootawasMessage.ALL_DATA,                dataArray            )            return true        }        sandeshDao.getAllSandesh().forEach { sandesh ->            try {                val isImage =                    sandesh.sandeshType == SandeshType.IMAGE.value ||                            sandesh.sandeshType == SandeshType.REPLY_IMAGE.value                val isVideo =                    sandesh.sandeshType == SandeshType.VIDEO.value ||                            sandesh.sandeshType == SandeshType.REPLY_VIDEO.value                if (!isImage && !isVideo) return@forEach                val json =                    JsonParser.parseString(                        sandesh.samagri                    ).asJsonObject                if (migrate(json, isVideo)) {                    sandeshDao.updateSamagri(                        sandeshId = sandesh.sandeshId,                        userNumber = sandesh.userNumber,                        samagri = json.toString()                    )                }            } catch (e: Exception) {                DLog.i("❌ Failed single migration: ${e.message}")            }        }        groupDao.getAllGroupSandesh().forEach { sandesh ->            try {                val isImage =                    sandesh.sandeshType == SandeshType.IMAGE.value ||                            sandesh.sandeshType == SandeshType.REPLY_IMAGE.value                val isVideo =                    sandesh.sandeshType == SandeshType.VIDEO.value ||                            sandesh.sandeshType == SandeshType.REPLY_VIDEO.value                if (!isImage && !isVideo) return@forEach                val json =                    JsonParser.parseString(                        sandesh.samagri                    ).asJsonObject                if (migrate(json, isVideo)) {                    groupDao.updateSamagri(                        sandeshId = sandesh.sandeshId,                        groupId = sandesh.groupId,                        samagri = json.toString()                    )                }            } catch (e: Exception) {                DLog.i("❌ Failed group migration: ${e.message}")            }        }        DLog.i("✅ firstTimeRunAfterUpdate completed")    }    suspend fun getIsRegistered(): Boolean {        return userDataStore.data.map { it[PrefKeys.IS_REGISTERED] == true }.first()    }    suspend fun setUserRegistered(isRegistered: Boolean) {        userDataStore.edit { it[PrefKeys.IS_REGISTERED] = isRegistered }    }    suspend fun updateUserName(newName: String) {            userDataStore.edit { it[PrefKeys.USER_NAME] = newName }            updateUserName()    }    suspend fun updateAbout(newAbout: String) {            userDataStore.edit { it[PrefKeys.USER_ABOUT] = newAbout }            updateUserBio()    }    suspend fun incrementNotificationCount(): Int {        var newValue = 0        userDataStore.edit { prefs ->            val current = prefs[NOTIFICATION_COUNT] ?: 0            newValue = current + 1            prefs[NOTIFICATION_COUNT] = newValue        }