le image request...")//                unsentFilesDao.deleteAndInsert(unsentData)                DLog.i("✅ Profile image update queued successfully.")                if (!sendingFileInProgress) {                    sendUnsentFiles()                }                val unsentSandesh = UnsentSandesh(                    messId = createMessageID(),                    receiver = "remove-profile",                    message = "path",                    dataType = DataType.DELETE_PROFILE,                    isGroup = false                )                insertUnsentData(unsentSandesh, false)                sendUnsentMessages(false)            }        }    }    fun setGroupProfileImage(path: String, groupId: String) {        coroutineScope.launch {            val unsentData = UnsentFiles(                messageId = createMessageID(),                receiver = groupId,                data = path,                dataType = FileDataType.PROFILE_UPDATE,                isGroup = true            )            DLog.i("🖼️ Updating group profile image request...")            // Replace any existing pending profile update for this group            unsentFilesDao.deleteAndInsert(unsentData)            DLog.i("✅ Group profile image update queued successfully.")            if (!sendingFileInProgress) {                sendUnsentFiles()            }        }    }    fun scheduleBackupWork(        context: Context, frequencyDays: Long, accountName: String, isMedia:        Boolean    ) {        val inputData = workDataOf(            "account_name" to accountName,            "include_media" to isMedia // Or pull this from your settings if needed        )        val workRequest = PeriodicWorkRequestBuilder<BackupWorker>(            frequencyDays, TimeUnit.DAYS        ).setConstraints(            Constraints.Builder()                .setRequiredNetworkType(NetworkType.CONNECTED)                .setRequiresCharging(true)                .build()        ).setInputData(inputData)            .build()        WorkManager.getInstance(context).enqueueUniquePeriodicWork(            "DriveBackupWork",            ExistingPeriodicWorkPolicy.UPDATE,            workRequest        )    }    fun startBackupNow(context: Context, accountName: String, includeMedia: Boolean) {        val inputData = workDataOf(            "account_name" to accountName,            "include_media" to includeMedia        )        val workRequest = OneTimeWorkRequestBuilder<BackupWorker>()            .setInputData(inputData)            .build()        WorkManager.getInstance(context).enqueue(workRequest)    }    fun startBackupNow(context: Context, includeMedia: Boolean) {        coroutineScope.launch(Dispatchers.IO) {            try {                val key = SettingPrefKeys.BACKUP_DIRECTORY_URI                val folderUriString = settingFlow(key, "").first()                val folderUri = folderUriString.toUri()                val timestamp = System.currentTimeMillis()                val formatted = SimpleDateFormat("yyyy_MM_dd_HH_mm_ss", Locale.getDefault()).format(                    Date(timestamp)                )                val fileName = "backup_$formatted.zip"                // Generate backup bytes (replace with real zip)                val backupBytes = createBackupArchiveBytes(context, includeMedia)                writeBackupToUri(context, folderUri, fileName, backupBytes)                updateLongSetting(SettingPrefKeys.LAST_BACKUP_TIME, timestamp)            } catch (e: Exception) {                Log.e("Backup", "Backup failed", e)            }        }    }    fun writeBackupToUri(context: Context, folderUri: Uri, fileName: String, bytes: ByteArray) {        val doc = DocumentFile.fromTreeUri(context, folderUri)            ?: throw IllegalStateException("Invalid backup folder")        val newFile = doc.createFile("application/zip", fileName)            ?: throw IllegalStateException("Failed to create file")        context.contentResolver.openOutputStream(newFile.uri)?.use { it.write(bytes) }    }    private fun createBackupArchiveBytes(context: Context, includeMedia: Boolean): ByteArray {        return "dummy-backup-data".toByteArray() // TODO build real zip    }    fun startRestore(context: Context, fileUri: Uri) {        coroutineScope.launch(Dispatchers.IO) {            try {                val tempFile = File(context.cacheDir, "restore.zip")                context.contentResolver.openInputStream(fileUri)?.use { input ->                    tempFile.outputStream().use { output ->                        input.copyTo(output)                    }                }                restoreArchive(context, tempFile)            } catch (e: Exception) {                Log.e("Restore", "Restore failed", e)            }        }    }    private fun restoreArchive(context: Context, backupFile: File) {        val tempDir = File(context.cacheDir, "restore_temp").apply { mkdirs() }        unzip(backupFile, tempDir)        // Restore DB        val restoredDb = File(tempDir, "messages.db")        val destDb = File(context.filesDir, "messages.db")        if (restoredDb.exists()) {            destDb.delete()            restoredDb.copyTo(destDb)        }        // Restore media folder        val mediaFolder = File(tempDir, "media")        val destMediaFolder = File(context.filesDir, "media")        if (mediaFolder.exists()) {            destMediaFolder.deleteRecursively()            mediaFolder.copyRecursively(target = destMediaFolder, overwrite = true)        }        tempDir.deleteRecursively()    }    fun unzip(zipFile: File, targetDir: File) {        targetDir.mkdirs()        ZipInputStream(zipFile.inputStream()).use { zis ->            var entry = zis.nextEntry            while (entry != null) {                val outFile = File(targetDir, entry.name)                if (entry.isDirectory) {                    outFile.mkdirs()                } else {                    outFile.outputStream().use { fos ->                        zis.copyTo(fos)                    }                }                zis.closeEntry()                entry = zis.nextEntry            }        }    }    fun cancelBackupWork(context: Context) {        WorkManager.getInstance(context).cancelUniqueWork("DriveBackupWork")    }    suspend fun updatePermissions(permissionsJson: JsonObject, user: String) {        val unsentSandesh = UnsentSandesh(            messId = UUID.randomUUID().toString(),            receiver = user,            message = permissionsJson.toString(),            dataType = DataType.PERMISSION_UPDATE,        )        insertUnsentData(unsentSandesh);        sendUnsentMessages(false)    }    suspend fun getSelfProfile() {        checkSingleProfile(userNumberKhud.firstOrNull().toString())    }    //endregion    //todo solve this    object SamagriUpdateLock {        private val mutexMap = mutableMapOf<String, Mutex>()        fun getMutexForId(id: String): Mutex {            return mutexMap.getOrPut(id) { Mutex() }        }    }    fun getVideoMeta(        context: Context,        pathOrUri: String    ): VideoMeta {        val retriever = MediaMetadataRetriever()        try {            if (pathOrUri.startsWith("/")) {                retriever.setDataSource(pathOrUri)            } else {                retriever.setDataSource(                    context,                    pathOrUri.toUri()                )            }            val width =                retriever.extractMetadata(                    MediaMetadataRetriever.METADATA_KEY_VIDEO_WIDTH                )?.toInt() ?: 0            val height =                retriever.extractMetadata(                    MediaMetadataRetriever.METADATA_KEY_VIDEO_HEIGHT                )?.toInt() ?: 0            val duration =                retriever.extractMetadata(                    MediaMetadataRetriever.METADATA_KEY_DURATION                )?.toLong() ?: 0            return VideoMeta(                width,                height,                duration            )        } finally {            retriever.release()        }    }    //region GROUP_KEY_HANDLING    fun generateAesKeyGroup(): AESKeyGroup {        val key = ByteArray(32)        SecureRandom().nextBytes(key)        return AESKeyGroup(            id = UUID.randomUUID().toString(),            aesKey = Base64.encodeToString(key, Base64.NO_WRAP),            createdAt = System.currentTimeMillis()        )    }    fun ensureLocalStorageKey() {        val ks = KeyStore.getInstance("AndroidKeyStore")        ks.load(null)        if (ks.containsAlias(KEY_ALIAS)) {            val key = ks.getKey(KEY_ALIAS, null)            if (key is SecretKey) {                return            }            // Wrong type (RSA), delete it            ks.deleteEntry(KEY_ALIAS)        }        val keyGenerator = KeyGenerator.getInstance(            KeyProperties.KEY_ALGORITHM_AES,            "AndroidKeyStore"        )        val spec = KeyGenParameterSpec.Builder(            KEY_ALIAS,            KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT        )            .setBlockModes(KeyProperties.BLOCK_MODE_GCM)            .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)            .build()        keyGenerator.init(spec)        keyGenerator.generateKey()    }    suspend fun requestGroupKey(        groupId: String,        receiver: String    ) {        val selfNumber = userNumberKhud.firstOrNull() ?: return //todo this could be user name or number        val selfMember = groupDao.getAGroupMemberByNumber(groupId, selfNumber) ?: return        val json = JsonObject().apply {            addProperty(DootawasMessage.SANDESH_TYPE, SandeshType.REQUEST_DISAPPEARING.value)            addProperty(JsonKeys.GROUP_ID, groupId)            // Pass fresh identity public keys from selfMember entity            addProperty("x25519PublicKey", Base64.encodeToString(selfMember.x25519PublicKey, Base64.NO_WRAP))            addProperty("mlKemPublicKey", Base64.encodeToString(selfMember.mlKemPublicKey, Base64.NO_WRAP))        }        val sandeshId = createMessageID()        val unsentSandesh = UnsentSandesh(            messId = sandeshId,            receiver = receiver,            message = json.toString(),            dataType = DataType.MESSAGE        )        sendMessage(unsentSandesh)    }    suspend fun requeueGroupUnsentMessages(groupId: String) {        val messages = groupDao.getLikhitGroupMessages(groupId)        if (messages.isEmpty()) {            DLog.i("No LIKHIT messages to requeue for group $groupId")            return        }        messages.forEach { msg ->           unsentSandeshDao.markDataSentFalse(                messId = msg.sandeshId,                receiver = groupId            )        }        DLog.i("Requeued ${messages.size} messages for group $groupId")    }        fun addDummyContact() {            coroutineScope.launch {                val dummyContacts = listOf(                    Contact(                        name = "Test_User1",                        number = "1111111111",                        isInstalled = true,                        backgroundColor = RandomColorGenerator.getRandomColor()                    ),                    Contact(                        name = "TestUser2",                        number = "2222222222",                        isInstalled = true,                        backgroundColor = RandomColorGenerator.getRandomColor()                    )                )                contactDao.insertAll(dummyContacts)            }        }    suspend fun getAllTransactionsOnce(): List<TransactionEntity> {        return transactionDao.getAllTransactions()    }    suspend fun requestIntegrityToken(): String? =        suspendCancellableCoroutine { cont ->            val integrityManager = IntegrityManagerFactory.create(context)            val nonce = UUID.randomUUID().toString()            val request = IntegrityTokenRequest.builder()                .setNonce(nonce)                .setCloudProjectNumber(YOUR_CLOUD_PROJECT_NUMBER)                .build()            integrityManager.requestIntegrityToken(request)                .addOnSuccessListener { response ->                    cont.resume(response.token(), null)                }                .addOnFailureListener { e ->                    DLog.e("Integrity API failed", e)                    cont.resume(null, null)                }        }    fun addNewScannerContact(phone: String) {        coroutineScope.launch {            val contactDb = contactDao.getUserContactByNumber(phone)            val contact = ContactUiItem(                number = contactDb?.number ?: phone,                name = contactDb?.name ?: "",                imageUrl = contactDb?.imageUrl,                isInstalled = true,                buttonState = ContactButtonState.ADD,                backgroundColor = RandomColorGenerator.getRandomColor()            )            val newState = when (contact.buttonState) {                ContactButtonState.INVITE -> ContactButtonState.INVITED                ContactButtonState.ADD -> ContactButtonState.ADDED                else -> return@launch            }            addContactToUpbhogta(contact)            contactDao.updateContactStateByNumber(contact.number, newState)        }    }    fun stopLiveLocationSharing(        context: Context,        sandeshId: String,        targetId: String,        isGroup: Boolean    ) {        coroutineScope.launch {            val samagri =                if (isGroup) {                    groupDao                        .getGroupSandeshByIdAndGroupId(                            sandeshId,                            targetId                        )?.samagri                } else {                    sandeshDao                        .getSandeshByIdAndUser(                            sandeshId,                            targetId                        )?.samagri                } ?: return@launch            val jsonObject = try {                JsonParser.parseString(                    samagri                ).asJsonObject            } catch (e: Exception) {                return@launch            }            jsonObject.addProperty(                DootawasMessage.IS_STOPPED,                true            )            if (isGroup) {                groupDao.updateSamagri(                    sandeshId = sandeshId,                    groupId = targetId,                    samagri = jsonObject.toString()                )            } else {                sandeshDao.updateSamagri(                    sandeshId = sandeshId,                    userNumber = targetId,                    samagri = jsonObject.toString()                )            }            LiveLocationService.removeLiveLocation(                context = context,                sandeshId = sandeshId            )            val liveLocationUpdate = JsonObject().apply {                addProperty(DootawasMessage.ORIGINAL_MESSAGE_ID, sandeshId)                addProperty(DootawasMessage.LATITUDE, 0.0)                addProperty(DootawasMessage.LONGITUDE, 0.0)                addProperty(DootawasMessage.IS_STOPPED, true)                addProperty(DootawasMessage.SANDESH_TYPE,SandeshType.LIVE_LOCATION_UPDATE.value)                if (isGroup){                    addProperty(JsonKeys.GROUP_ID, targetId)                }            }            val unsentSandesh = UnsentSandesh(                messId = createMessageID(),                receiver = targetId,                message = liveLocationUpdate.toString(),                dataType = DataType.MESSAGE,                isGroup = isGroup            )            sendMessage(unsentSandesh)        }    }    suspend fun updateUserTheme(        userNumber: String,        json: String    ) {        upbhogtaDao.updateUserColors(            userNumber = userNumber,            colorsJson = json        )    }    //endregion    fun startBackup(        context: Context,        accountName: String,        includeMedia: Boolean,        retentionCount: Int,        mediaRetentionMonths: Int,        onSuccess: () -> Unit,        onFailure: () -> Unit    ) {        coroutineScope.launch(Dispatchers.IO) {            val success = BackupManager.startBackup(                context, accountName, includeMedia, retentionCount, mediaRetentionMonths            )            withContext(Dispatchers.Main) {                if (success) onSuccess() else onFailure()            }        }    }    fun prepareForRestore() {        // Stop socket        SocketManager.setAppActive(false)        // Close DB        dootawasDatabase.close()    }    suspend fun afterRestoreCleanup() {        try {            // ------------------------------------------------            // Clear broken restored profile paths            // ------------------------------------------------            upbhogtaDao.clearAllProfilePictures()            // ------------------------------------------------            // Restore contact profile pictures            // ------------------------------------------------            val contacts =                contactDao.getAllContactPhotos()            contacts.forEach { contact ->                upbhogtaDao.updatePhotoUrlByNumber(                    number = contact.number,                    newUrl = contact.imageUrl                )            }            sandeshDao.markAllMessagesAsViewed()            groupDao.markAllGroupMessagesAsViewed()            groupDao.cle