erveListData(userNumber: String): Flow<List<HomeViewModel.ListItem>> =        sandeshDao.observeLists(userNumber).map { rows ->            rows.mapNotNull { row ->                runCatching {                    gson.fromJson(row.samagri, ListData::class.java)                }.getOrNull()?.let { listData ->                    HomeViewModel.ListItem(                        sandeshId = row.sandeshId,                        userNumber = row.userNumber,                        listData = listData                    )                }            }        }    fun resetUserNameIdCheck(candidate: String) {        checkJob?.cancel()        latestCandidate = candidate // claims this slot so any earlier in-flight response gets discarded        _userNameIdCheckState.value = UserNameIdCheckState.Idle    }    fun setUserNameIdInvalid(reason: String, candidate: String) {        checkJob?.cancel()        latestCandidate = candidate        _userNameIdCheckState.value = UserNameIdCheckState.Invalid(reason)    }    // keyed by messId so multiple in-flight checks (fast typing) don't cross-wire responses    private val pendingUsernameChecks = ConcurrentHashMap<String, CompletableDeferred<Boolean>>()    private var latestCandidate: String? = null // 👈 NEW    fun checkUserNameIdAvailability(candidate: String) {        val normalized = if (candidate.startsWith("@")) candidate else "@$candidate"        val validationError = validateUserNameId(normalized)        if (validationError != null) {            _userNameIdCheckState.value = UserNameIdCheckState.Invalid(validationError)            return        }        latestCandidate = normalized // 👈 record what's actually being asked about right now        checkJob?.cancel()        checkJob = coroutineScope.launch {            _userNameIdCheckState.value = UserNameIdCheckState.Checking            val messId = createMessageID()            val deferred = CompletableDeferred<Boolean>()            pendingUsernameChecks[messId] = deferred            try {                sendMessage(                    UnsentSandesh(                        messId = messId,                        receiver = normalized,                        message = "userName",                        dataType = DataType.CHECK_USERNAME_ID                    )                )                val isAvailable = withTimeout(8_000L) { deferred.await() }                // 👈 guard: only apply this result if no newer candidate has been typed since                if (latestCandidate != normalized) {                    DLog.i("🚫 Discarding stale result for $normalized — latest is $latestCandidate")                    return@launch                }                _userNameIdCheckState.value = if (isAvailable) {                    UserNameIdCheckState.Available                } else {                    UserNameIdCheckState.Taken                }            } catch (e: TimeoutCancellationException) {                if (latestCandidate == normalized) {                    _userNameIdCheckState.value = UserNameIdCheckState.Error("Server took too long to respond")                }            } catch (e: Exception) {                if (latestCandidate == normalized) {                    _userNameIdCheckState.value = UserNameIdCheckState.Error(e.message ?: "Check failed")                }            } finally {                pendingUsernameChecks.remove(messId)            }        }    }    private val pendingUsernameUpdates = ConcurrentHashMap<String, CompletableDeferred<UpdateUserNameIdResult>>()    fun updateUserName(){        sendMessage(            UnsentSandesh(                messId = createMessageID(),                receiver = "updateUserName",                message = "userName",                dataType = DataType.UPDATE_USERNAME            )        )    }    fun updateUserBio(){        sendMessage(            UnsentSandesh(                messId = createMessageID(),                receiver = "updateUserBio",                message = "userBio",                dataType = DataType.UPDATE_USER_BIO            )        )    }    suspend fun setUserNameIdLocalOnly(value: String) { //for testing only        userDataStore.edit {            it[PrefKeys.USER_NAME_ID] = value        }    }    suspend fun updateUserNameId(newUserNameId: String): Boolean {        val normalized = if (newUserNameId.startsWith("@")) newUserNameId else "@$newUserNameId"        val messId = createMessageID()        val deferred = CompletableDeferred<UpdateUserNameIdResult>()        pendingUsernameUpdates[messId] = deferred        return try {            sendMessage(                UnsentSandesh(                    messId = messId,                    receiver = normalized,                    message = "userName",                    dataType = DataType.UPDATE_USERNAME_ID                )            )            val result = withTimeout(8_000L.milliseconds) { deferred.await() }            when (result) {                is UpdateUserNameIdResult.Success -> {                    userDataStore.edit {                        it[PrefKeys.USER_NAME_ID] = normalized                        it[PrefKeys.USER_NAME_ID_UPDATE_TIME] = System.currentTimeMillis()                    }                    _userNameIdCheckState.value = UserNameIdCheckState.Idle                    true                }                is UpdateUserNameIdResult.Taken -> {                    _userNameIdCheckState.value = UserNameIdCheckState.Taken                    false                }                is UpdateUserNameIdResult.CooldownActive -> {                    _userNameIdCheckState.value = UserNameIdCheckState.Error("You can't change your username yet")                    false                }                is UpdateUserNameIdResult.Failed -> {                    _userNameIdCheckState.value = UserNameIdCheckState.Error(result.reason)                    false                }            }        } catch (e: TimeoutCancellationException) {            _userNameIdCheckState.value = UserNameIdCheckState.Error("Server took too long to respond")            false        } catch (e: Exception) {            _userNameIdCheckState.value = UserNameIdCheckState.Error(e.message ?: "Update failed")            false        } finally {            pendingUsernameUpdates.remove(messId)        }    }    private fun validateUserNameId(id: String): String? {        val body = id.removePrefix("@")        return when {            body.isBlank() -> "Username can't be empty"            body.length < 3 -> "Must be at least 3 characters"            body.length > 20 -> "Must be under 20 characters"            !body.matches(Regex("^[a-zA-Z0-9_]+$")) -> "Only letters, numbers, and underscores"            body.first().isDigit() -> "Can't start with a number"            else -> null        }    }    init {        loadTheme()        loadGroupTheme()        observeSocket()        setup()        loadAppIcon()        coroutineScope.launch {            DLog.i("don't Delete them")            val key = SettingPrefKeys.CHAT_CHAT_FONT_SIZE            val flow1 = settingFlow(key, 14)            DLog.i(flow1.toString())        }        coroutineScope.launch {            settingStore.data.map {                it[SettingPrefKeys.ACCOUNT_SECURITY_PASSCODE] != null            }.collect { _isPasscodeEnabledFlow.value = it }        }        coroutineScope.launch {            settingStore.data                .map { prefs -> prefs[SettingPrefKeys.SOS_CONTACT_NUMBERS] ?: emptySet() }                .distinctUntilChanged() // don't re-resolve names on unrelated DataStore writes                .map { numbers ->                    // resolve all numbers -> names in parallel, not one-by-one                    coroutineScope {                        numbers.map { number ->                       